#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define THRESHOLD 1000000 // Memory threshold (adjust as needed)

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node *next;
} Node;

void log_error(const char *message) {
    // Implement logging mechanism here using existing logging system.
}

Node* create_node(Record data) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failure");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert(int key, int value, Node **head, long *offsets, int *keys) {
    long current_offset = 0;
    int i;

    for (i = 0; i < keys && keys[i] != key; ++i) {
        current_offset += offsets[i + 1] - offsets[i];
    }

    if (i == keys_len) { // Key not found, insert at the end
        Node *new_node = create_node((Record){value});
        if (!new_node) return;

        (*head)->next = new_node;
        offsets[keys_len + 1] = current_offset + sizeof(Node);
        keys[keys_len + 1] = key;
        ++keys_len;
    } else { // Key found, insert the value and adjust offsets
        Node *new_node = create_node((Record){value});
        if (!new_node) return;

        Node *temp = (*head);
        for (int j = 0; j < i; ++j) {
            temp = temp->next;
        }

        new_node->next = temp->next;
        temp->next = new_node;

        offsets[i + 1] = current_offset + sizeof(Node);
    }

    if (current_offset + sizeof(Node) > THRESHOLD) { // Memory capping
        log_error("Memory usage exceeded threshold");
        // Implement memory deallocation and pruning strategy here.
    }
}

void delete(int key, Node **head, long *offsets, int *keys) {
    int i;

    for (i = 0; i < keys_len && keys[i] != key; ++i) {}

    if (i == keys_len) return; // Key not found

    Node *temp = (*head);
    if (i > 0) {
        for (int j = 0; j < i; ++j) {
            temp = temp->next;
        }
    }

    Node *node_to_delete = temp->next;
    if (!node_to_delete) return; // Sanity check

    temp->next = node_to_delete->next;
    free(node_to_delete);

    offsets[i + 1] -= sizeof(Node);
}
