struct keyword_search {
    regex_t regex;
    bool search;
};

int main(int argc, char **argv) {
    struct keyword_search kw_search = { .regex = { 0 } };
    const char *const short_options = "i:o::f:k:h";
    const char *const long_options = "input=,output=,format,file,keyword,help";
    int option_index;
    bool help = false;
    char *input_files[MAX_FILES] = { 0 };
    char *output_file = NULL;
    char format = 't'; // text by default
