        fprintf(stderr, "\t-o, --output=FILE         Output file (or stdout if omitted)\n");
        fprintf(stderr, "\t-f, --format=FORMAT       Output format: t for text or c for csv\n");
        fprintf(stderr, "\t-k, --keyword=KEYWORD      Search keyword within files\n");
        fprintf(stderr, "\t-h, --help                 Show this help message\n");
        return 0;
    }

    // Initialize regex for searching
    regcomp(&kw_search.regex, (keyword ? keyword : ""), REG_EXTENDED | REG_ICASE);
    kw_search.search = bool(keyword != NULL);

    int num_files = optind;
    struct line lines[num_files];
    struct stat file_stats[num_files];
    FILE **file_ptrs = malloc(sizeof(FILE *) * num_files);
    for (int i = 0; i < num_files; ++i) {
        file_ptrs[i] = fopen(input_files[i], "r");
        if (!file_ptrs[i]) {
            perror("Error opening file");
            return 1;
        }
        if (fstat(fileno(file_ptrs[i]), &file_stats[i]) < 0) {
            perror("Error getting file statistics");
            return 1;
        }
    }

    struct line *line_iter = lines;
    for (int i = 0; i < num_files; ++i) {
        char buffer[BUF_SIZE];
        size_t bytes_read = 0;
        while ((bytes_read = fread(buffer, 1, BUF_SIZE, file_ptrs[i])) > 0) {
            for (char *c = buffer; c < buffer + bytes_read; ++c) {
                if (*c == '\n') {
                    line_iter->line_num += 1;
                    line_iter->file = input_files[i];
                    if (kw_search.search && regmatch(&kw_search.regex, c, NULL)) {
                        line_iter++;
                    }
                }
            }
        }
        fclose(file_ptrs[i]);
    }

    free(file_ptrs);

    // Sort the lines by file name and then by line number
    qsort(lines, num_files, sizeof(struct line), line_compare);

    // Print or write results based on format option
    if (format == 't') {
        for (struct line *line = lines; line < lines + num_files; ++line) {
            printf("%s:%" PRIuMAX": %s\n", line->file, line->line_num, line->file ? line->file : "<stdin>");
        }
    } else if (format == 'c') {
        // Implement CSV output here...
    }

    return 0;
}

int line_compare(const void *a, const void *b) {
    struct line *line1 = a;
    struct line *line2 = b;

    int cmp = strcmp(line1->file, line2->file);
    if (!cmp) {
        return line1->line_num - line2->line_num;
    } else {
        return cmp;
    }
}
