#include <arpa/inet.h>
#include <netdb.h>
#include <resolv.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

typedef struct {
    size_t hostname_len;
    u_char* hostname;
    // Add other necessary fields here
} packet_t;

int dns_resolve(const char* hostname, u_char** ip_addr) {
    struct hostent *he = gethostbyname(hostname);
    if (he == NULL) return 1;
    *ip_addr = malloc(he->h_length);
    memcpy(*ip_addr, he->h_addr, he->h_length);
    return 0;
}

void print_packet(const packet_t* pkt) {
    printf("%.*s ", pkt->hostname_len, pkt->hostname);
    // Add other fields to be printed here
}

int main() {
    int sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    char buf[4096];

    while (1) {
        ssize_t n = recv(sockfd, buf, sizeof(buf), 0);
        if (n <= 0) break;

        packet_t* pkt = malloc(sizeof(packet_t));
        pkt->hostname_len = strnlen(buf, n);
        pkt->hostname = malloc(pkt->hostname_len + 1);
        memcpy(pkt->hostname, buf, pkt->hostname_len);
        pkt->hostname[pkt->hostname_len] = '\0';

        u_char ip_addr[sizeof(struct in_addr)];
        int err = dns_resolve(pkt->hostname, ip_addr);
        if (err) {
            free(pkt->hostname);
            free(pkt);
            continue;
        }

        struct in_addr addr;
        memcpy(&addr, ip_addr, sizeof(struct in_addr));
        print_packet(pkt);
        printf("%s\n", inet_ntoa(addr));
        float avg = (pkt->fields[n - 2] + pkt->fields[n - 1]) / 2.0f;
        printf("Average: %.2f\n", avg);

        free(pkt->hostname);
        free(pkt);
    }

    close(sockfd);
    return 0;
}
