int num_modules = 0;

void load_module(const char* libname) {
    void *handle = dlopen(libname, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        return;
    }

    const char* hashes_sym = strcat(libname, "_get_hashes");
    get_hashes_func get_hashes = (get_hashes_func) dlsym(handle, hashes_sym);
    if (get_hashes) {
        crypt_module* mod = malloc(sizeof(struct crypt_module));
        mod->name = libname;
        mod->hashes = get_hashes;
        mod->ciphers = NULL; // Assume no ciphers for now

        crypt_modules[num_modules++] = mod;
    }
}

void load_all_modules() {
