3. Delete Semaphore Function:
```c
void delete_semaphore(const char* id) {
    // synchronized access to semaphores collection
    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(id, semaphores[i]->id) == 0) {
            for (int j = i + 1; j < num_semaphores; ++j) {
                semaphores[j - 1] = semaphores[j];
            }
            free(semaphores[--num_semaphores]);
            break;
        }
    }
}
