        void log(const std::string& message) {
            // Implement logging for each level using spdlog
            if (getLevel() >= Level) {
                sync_lock.lock();
                outputBuffer += timeStamp + " [" + getLevelName(Level) + "] " + message + "\n";
                sync_condition.notify_one();
                sync_lock.unlock();
