['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Net.NetworkInformation;
using System.Threading;
using System.Threading.Tasks;
using System.Timers;

public class HttpRequestBatcher
{
    private readonly List<Tuple<Uri, HttpRequestMessage>> _queue = new List<Tuple<Uri, HttpRequestMessage>>();
    private readonly SemaphoreSlim _semaphore;
    private readonly Dictionary<Uri, RequestMetadata> _metadata = new Dictionary<Uri, RequestMetadata>();
    private readonly TimeSpan _timeout;
    private readonly int _maxConcurrency;
    private readonly string _preferredInterface;
    private readonly HttpClient _httpClient;
    private readonly Timer _retryTimer;
    private int _currentRetryAttempt;
    private readonly int _maxRetries;

    public HttpRequestBatcher(TimeSpan timeout, int maxConcurrency, string preferredInterface, HttpClient httpClient, int maxRetries = 3)
    {
        _timeout = timeout;
        _maxConcurrency = maxConcurrency;
        _preferredInterface = preferredInterface;
        _httpClient = httpClient;
        _maxRetries = maxRetries;

        _semaphore = new SemaphoreSlim(_maxConcurrency);
        _retryTimer = new Timer(TimeSpan.FromSeconds(1).TotalMilliseconds) { AutoReset = true };
        _retryTimer.Elapsed += OnRetryTimerElapsed;
    }

    public async Task<IList<KeyValuePair<Uri, (HttpResponseMessage Response, RequestMetadata Metadata)>>> SendRequestsAsync(IEnumerable<Uri> urls, IEnumerable<HttpRequestMessage> requests)
    {
        var tasks = new List<Task<Tuple<Uri, HttpResponseMessage>>>();

        foreach (var (url, request) in urls.Zip(requests, (a, b) => (a, b)))
        {
            if (_metadata.ContainsKey(url))
                _metadata[url].EnqueueRequest(request);
            else
                _metadata[url] = new RequestMetadata();

            tasks.Add(_semaphore.WaitAsync()
                   .ContinueWith(async token =>
                   {
                       try
                       {
                           var networkInterface = GetPreferredNetworkInterface(_preferredInterface);

                           _metadata[url].CurrentNetworkInterface = networkInterface;
                           _metadata[url].LastActivityTime = DateTime.UtcNow;

                           using (var handler = new HttpClientHandler() { AutomaticDecompression = DecompressionMethods.Deflate | DecompressionMethods.Gzip })
                           using (var client = new HttpClient(handler))
                           {
                               var requestWithNetworkSettings = new HttpRequestMessage(request.Method, url)
                               {
                                   Headers = request.Headers,
                                   Content = request.Content
                               };

                               var response = await client.SendAsync(requestWithNetworkSettings);
                               return Tuple.Create(url, response);
                           }
                       }
                       catch (Exception ex)
                       {
                           _metadata[url].Error = ex;
                           OnRetryTimerElapsed(this, EventArgs.Empty);
                           throw;
                       }
                   }));
        }

        await Task.WhenAll(tasks);

        var results = new List<KeyValuePair<Uri, (HttpResponseMessage Response, RequestMetadata Metadata)>>();

        foreach (var (url, response) in tasks.Select(t => t.Result))
        {
            _metadata[url].CurrentNetworkInterface = null;
            results.Add(new KeyValuePair<Uri, (HttpResponseMessage Response, RequestMetadata Metadata)>(url, (response, _metadata[url])));
        }

        return results;
    }

    private NetworkInterface GetPreferredNetworkInterface(string preferredInterface)
    {
        if (string.IsNullOrEmpty(preferredInterface))
            return null;

        var allInterfaces = NetworkInterface.GetAllNetworkInterfaces();

        return allInterfaces.FirstOrDefault(i => i.Name.Equals(preferredInterface, StringComparison.OrdinalIgnoreCase));
    }

    private void OnRetryTimerElapsed(object sender, EventArgs e)
    {
        if (_currentRetryAttempt >= _maxRetries) return;

        var tasksToComplete = _metadata.Values
            .Where(m => m.HasError && m.LastActivityTime + _timeout > DateTime.UtcNow)
            .Select(m => _semaphore.Release())
            .ToList();

        Task.WaitAll(tasksToComplete);
        _currentRetryAttempt++;
    }
}

public class RequestMetadata
{
    public Uri Uri { get; set; }
    public NetworkInterface CurrentNetworkInterface { get; private set; }
    public DateTime LastActivityTime { get; private set; }
    public Exception Error { get; private set; }
    public Queue<HttpRequestMessage> RequestQueue { get; private set; } = new Queue<HttpRequestMessage>();

    public bool HasError => Error != null;

    public void EnqueueRequest(HttpRequestMessage request)
    {
        RequestQueue.Enqueue(request);
    }
}
```
This code defines a `HttpRequestBatcher` class that takes care of asynchronously sending HTTP requests with custom priority and handling network disconnections gracefully by retrying the requests up to a specified limit. It also ensures that no more than the specified number of concurrent requests are active at any given time.']

