    {
        _weatherService = weatherService;
        _trafficService = trafficService;
        _settingsManager = settingsManager;
        _billboards = new ConcurrentDictionary<int, IBillboard>();
    }

    public async Task UpdateAsync()
    {
        var weatherData = await _weatherService.GetWeatherDataAsync();
        var trafficData = await _trafficService.GetTrafficDataAsync();

        ProcessWeatherData(weatherData);
        ProcessTrafficData(trafficData);

        // Update billboards based on processed data and settings.
    }

    private void ProcessWeatherData(WeatherData weatherData)
    {
        // Handle discrepancies in data formats using adapter patterns if needed.
        var adjustedBrightness = _settingsManager.GetAdjustedBrightness(weatherData);

        foreach (var billboard in _billboards)
        {
            billboard.Value.SetBrightness(adjustedBrightness);
        }
    }

    private void ProcessTrafficData(TrafficData trafficData)
    {
        // Handle discrepancies in data formats using adapter patterns if needed.
        var adjustedContrast = _settingsManager.GetAdjustedContrast(trafficData);

        foreach (var billboard in _billboards)
        {
            billboard.Value.SetContrast(adjustedContrast);
        }
    }
}
