    var nodes = doc.SelectNodes($"/*/*[name()='{elementName}']");

    if (nodes == null || nodes.Count == 0)
    {
        Debug.WriteLine($"Warning: No element '{elementName}' found.");
        return;
    }

    if (nodes.Count > 1)
