['```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

public class StateLoader {
    private static final String CACHE_ROOT = "theme_cache";
    private static final Map<String, File> THEME_CACHE = new HashMap<>();

    public static <T> T loadState(Class<T> clazz, String fileName) throws IOException, ClassNotFoundException {
        File file = new File(fileName);
        if (!file.exists()) {
            throw new IllegalArgumentException("File not found: " + fileName);
        }

        try (FileInputStream fis = new FileInputStream(file)) {
            ObjectInputStream ois = new ObjectInputStream(fis);
            T state = clazz.cast(ois.readObject());
            ois.close();
            return state;
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Invalid class: " + clazz.getName(), e);
        }
    }

    public static JSONArray loadThemes() throws IOException, JSONException {
        File themesFile = new File(CACHE_ROOT, "themes.json");
        if (!themesFile.exists()) {
            throw new IllegalArgumentException("Default theme directory not found: " + CACHE_ROOT);
        }

        return new JSONArray(new String(Files.readAllBytes(themesFile.toPath())));
    }

    public static Optional<Bitmap> getTheme(int themeId) {
        File themeFile = THEME_CACHE.computeIfAbsent(String.valueOf(themeId), id -> new File(CACHE_ROOT, id + ".png"));

        if (!themeFile.exists()) {
            return Optional.empty();
        }

        // Assuming you have a Bitmap class and the method to load Bitmap from file
        return Optional.of(loadBitmapFromFile(themeFile));
    }
}
```

In this code, I have created a StateLoader utility that can dynamically load state objects from files in Java. It uses an existing ObjectInputStream to deserialize the object stored in a file and handles potential ClassCastExceptions. For managing themes, it loads a JSONArray containing theme IDs and file names, checks for their existence, and retrieves the Bitmap using a separate method (`loadBitmapFromFile()`) assuming you have defined it.

Please note that this code is an example, and some adjustments might be required based on your specific requirements and available libraries. It does not include error handling for potential parsing errors or theme caching management when recycling theme bitmaps. Additionally, I haven't integrated with any state management framework as it wasn't specified in the task description.

The code also assumes that you are using a JSON library to handle JSON files and have a Bitmap class and corresponding method to load Bitmap from file.']

