void refreshDialogFields(std::forward_list<std::string> fieldNames, int resourceId, const std::string& url) {
    std::vector<std::string> specificFields = {"field1", "field2", "field3"}; // Define your specific fields to refresh here
    std::map<std::string, std::atomic_bool> requests;

    for (const auto& fieldName : fieldNames) {
        if (std::find(specificFields.begin(), specificFields.end(), fieldName) != specificFields.end()) {
            std::unique_ptr<CURL, decltype(&curl_easy_cleanup)> curlPtr(curl_easy_init(), curl_easy_cleanup);
            if (curl_easy_setopt(curlPtr.get(), CURLOPT_URL, API_ENDPOINT + "?resourceId=" + std::to_string(resourceId) + "&fieldName=" + fieldName) != CURLE_OK) {
                std::cerr << "Failed to set URL" << std::endl;
                continue;
            }

            curl_easy_setopt(curlPtr.get(), CURLOPT_WRITEFUNCTION, WriteCallback);
            requests[fieldName] = { true };

            int maxTries = 3;
            while (requests[fieldName]) {
                if (curl_easy_perform(curlPtr.get()) == CURLE_OK) {
                    auto respCode = curl_easy_getinfo(curlPtr.get(), CURLINFO_RESPONSE_CODE);
                    if (respCode == 200) {
