                        requests[fieldName] = false;
                    } else {
                        std::cerr << "Failed to get response with code: " << respCode << std::endl;
                    }
                } else {
                    int errNum = curl_easy_getinfo(curlPtr.get(), CURLINFO_LASTERR);
                    if (maxTries > 0) {
                        maxTries--;
                        std::this_thread::sleep_for(std::chrono::milliseconds(std::pow(2, maxTries)));
                    } else {
                        requests[fieldName] = false;
                        std::cerr << "Max retries exceeded" << std::endl;
                    }
                }
            }
