```java
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.handler.codec.http.HttpClientCodec;
import io.netty.handler.retry.BackoffHandler;
import io.netty.util.AttributeKey;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class MultiConnManager {
    private final Map<String, ConnectionHandler> connections = new ConcurrentHashMap<>();
    private final ScheduledExecutorService executor = Executors.newScheduledThreadPool(10);
    private final EDS externalDataStore;

    public MultiConnManager(EDS externalDataStore) {
        this.externalDataStore = externalDataStore;
    }

    public void connect(String host, int port, Runnable onConnected) {
        ConnectionHandler handler = new ConnectionHandler(host, port, this);
        connections.putIfAbsent(handler.getId(), handler);
        Bootstrap bootstrap = new Bootstrap();
        bootstrap.group(NioEventLoopGroup.therapistThreadPoolSizeFromAvailableProcessors())
                .channel(NioSocketChannel.class)
                .handler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) throws Exception {
                        ch.pipeline().addLast(new HttpClientCodec());
                        ch.pipeline().addLast(handler);
                    }
                })
                .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 100)
                .option(ChannelOption.SO_KEEPALIVE, true)
                .option(ChannelOption.TCP_NODELAY, true)
                .option(ChannelOption.RETRY_ON_FAILURE, true)
                .handler(new BackoffHandler(100, 500, TimeUnit.MILLISECONDS))
                .attr(AttributeKey.valueOf("id"), handler.getId());
        ChannelFuture future = bootstrap.connect(host, port).sync();
        future.addListener((ChannelFutureListener) future1 -> {
            if (future1.isSuccess()) {
                onConnected.run();
            } else {
                // Handle connection failure and perform retry logic based on EDS authentication and status updates
            }
        });
    }

    // Implement other methods for sending messages, closing connections, etc.

    private class ConnectionHandler extends SimpleChannelInboundHandler<Object> {
        private final String id;
        // Constructor, handle methods, etc.
    }
}
```

