    }

    private void startOrStopServices(int difference) {
        if (difference > 0) {
            for (int i = 0; i < difference; i++) {
                String serviceName = getNextServiceToStart();
                ActorRef newInstance = system.actorOf(Props.create(DataStreamProcessor.class, serviceName), serviceName);
