<?php

class ApiUpdater {
    private $cache;
    private $apis = [];
    private $concurrencyLimit = 10;
    private $statusMessages = [
        200 => 'Operation successful',
        400 => 'Invalid parameters',
        401 => 'Unauthorized',
        403 => 'Forbidden',
        404 => 'Not found',
        409 => 'Conflict (rate limiting or data consistency issue)',
        500 => 'Internal server error',
        // Add more custom status messages as needed
    ];

    public function __construct($cache) {
        $this->cache = $cache;
    }

    public function addApi($apiUrl, $method, $params = []) {
        $this->apis[] = (object)[
            'url' => $apiUrl,
            'method' => $method,
            'params' => $params
        ];
    }

    public function updateProfiles() {
        // Retrieve user profiles from your database or other data source
        $userProfiles = getUserProfiles();

        // Process concurrently up to the concurrencyLimit
        $profileGroups = array_chunk($userProfiles, $this->concurrencyLimit);

        foreach ($profileGroups as $group) {
            go(function () use ($group) {
                global $this;

                // Simulate delay or real API calls
                sleep(1);

                foreach ($group as $userProfile) {
                    $success = false;
                    $attempts = 0;

                    do {
                        try {
                            // Get the next available API from the cache or fetch a new one if needed
                            $api = $this->getAvailableApi();

                            // Call the external API with provided user profile data
                            $response = call_user_func_array($api['method'], array_merge([$api['url']], $api['params'] + [$userProfile]));

                            if ($response->getStatusCode() == 200) {
                                // Update the cache to reflect successful update
                                $this->cache->updateUserProfile($userProfile);

                                $success = true;
                                break;
                            } else {
                                $errorCode = $response->getStatusCode();
                                if (!array_key_exists($errorCode, $this->statusMessages)) {
                                    $errorCode = 500; // Fallback to internal server error for unknown error codes
                                }
                            }
                        } catch (Exception $e) {
                            if ($attempts >= 3) {
                                throw new Exception('Rate limiting or server timeout reached');
                            }
                        }

                        // Increment attempts counter and sleep to avoid overloading the APIs
                        usleep(1000 * $attempts);
                        $attempts++;
                    } while (!$success);
                }
            });
        }

        // Wait for all concurrent requests to finish before returning the overall status message
        foreach (gen_async() as $task) {
            $task->wait();
        }

        return 'Operation completed';
    }

    private function getAvailableApi() {
        if (!$this->cache->has('available_apis')) {
            // Fetch all available APIs and store in cache with a TTL of 5 minutes (300 seconds)
            $apis = array_map(function ($api) {
                return [
                    'url' => $api['url'],
                    'last_checked' => time()
                ];
            }, $this->apis);

            usort($apis, function ($a, $b) {
                return strtotime($b['last_checked']) - strtotime($a['last_checked']);
            });

            $this->cache->store('available_apis', $apis, 300);
        }

        // Get the first available API from the cache that hasn't been checked in the last 5 minutes
        $api = reset($this->cache->get('available_apis'));

        if (time() - $api['last_checked'] > 300) {
            // If the chosen API was not available, remove it from the cache and get a new one
            array_shift($this->cache->get('available_apis'));
            $this->getAvailableApi();
        }

        return current($this->apis);
    }
}
