const fs = require('fs');
const https = require('https');
const url = require('url');
const zlib = require('zlib');

let cache = {};

async function fetchAndSaveCertificate(oauthRequest) {
  const { host, path, headers } = url.parse(oauthRequest.certificateUrl);
  let cachedResponse;

  if (cache[host]) {
    cachedResponse = cache[host][path];
  } else {
    try {
      const response = await https.get(oauthRequest.certificateUrl, { headers });
      cachedResponse = response;

      // Cache the response for future requests
      if (!cache[host]) {
        cache[host] = {};
      }
      cache[host][path] = response;
    } catch (error) {
      console.error(`Error fetching certificate: ${error}`);
      return null;
    }
  }

  let privateKeyBuffer = Buffer.from('');
  let certificateBuffer = Buffer.from('');
  let currentVersion = 'unknown';

  for (const chunk of cachedResponse) {
    if (chunk.key === 'private_key') {
      privateKeyBuffer = Buffer.concat([privateKeyBuffer, chunk.value]);
    } else if (chunk.key === 'certificate') {
      certificateBuffer = Buffer.concat([certificateBuffer, chunk.value]);
    } else if (chunk.key === 'version') {
      currentVersion = chunk.value;
    }
  }

  let combinedBuffer;

  // Handle gzip compression
  if (cachedResponse.headers['content-encoding'] === 'gzip') {
    combinedBuffer = zlib.gunzipSync(certificateBuffer);
  } else {
    combinedBuffer = certificateBuffer;
  }

  // Validate the certificate against a trusted root
  try {
    const caRootCertificate = fs.readFileSync('path/to/ca_root_certificate');
    const chainAndPrivateKey = {
      key: privateKeyBuffer,
      cert: combinedBuffer,
      ca: [caRootCertificate],
    };

    const options = {
      // Adjust this based on the CA service endpoint requirements
      requestCert: true,
      rejectUnauthorized: false,
    };

    const verifiedChainAndPrivateKey = await new Promise((resolve, reject) => {
      const agent = new https.Agent(options);
      const req = https.request({
        host,
        path,
        headers,
        method: 'GET',
      }, (verifiedRes) => {
        resolve({ chain: verifiedRes._server.sslHandshakeInfo.localCertificateChain, key: privateKeyBuffer });
      });
      req.on('error', reject);
      req.on('upgrade', () => {
        req.write(combinedBuffer);
        req.end();
      });
      agent.once('request', (innerReq) => {
        innerReq.on('data', (chunk) => req.write(chunk));
      });
      req.pipe(agent);
    });

    if (!verifiedChainAndPrivateKey) {
      console.error(`Certificate could not be verified`);
      return null;
    }

    combinedBuffer = Buffer.concat([verifiedChainAndPrivateKey.key, combinedBuffer]);
  } catch (error) {
    console.error(`Error validating certificate: ${error}`);
    return null;
  }

  fs.writeFileSync(`certificate_${currentVersion}.pem`, combinedBuffer);

  return combinedBuffer;
}
```"]

