class Attack {
public:
    enum class Type { FIRST, SECOND, THIRD, FOURTH };
    static const std::array<std::chrono::seconds, 4> cooldowns = { std::chrono::seconds(5), std::chrono::seconds(7), std::chrono::seconds(8), std::chrono::seconds(12) };

    Type type;
    std::chrono::steady_clock::time_point lastUsed;
};

class GameCharacter {
public:
    void performAttack(Attack::Type type, std::function<void()> onCompleteCallback) {
        std::unique_lock<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        auto elapsed = now - lastAttacks[type];
        if (elapsed < cooldowns[static_cast<int>(type)]) {
            auto remaining = cooldowns[static_cast<int>(type)] - elapsed;
            attackQueue.push([this, type, onCompleteCallback, remaining]() mutable {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait_for(lock, remaining);
                performAttack(type, onCompleteCallback);
            });
            return;
        }
        lastAttacks[type] = now;
        attackOnThread = std::thread([this, type, onCompleteCallback]() mutable {
            performAttackInternal(type, onCompleteCallback);
            cv.notify_one();
        });
    }

private:
    void performAttackInternal(Attack::Type type, std::function<void()> onCompleteCallback) {
        // Implement the attack logic here
        onCompleteCallback();
    }

    std::array<std::chrono::steady_clock::time_point, 4> lastAttacks = {};
    std::array<Attack::Type, 10> attackHistory = {};
    std::queue<std::function<void()>> attackQueue;
    std::atomic_thread_id attackOnThreadId = {0};
    std::mutex mtx;
    std::condition_variable cv;
    // Other class members and methods...
};
