using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Text;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private float minFloatValue;
    private float maxFloatValue;
    private int minIntValue;
    private int maxIntValue;

    private Vector2d vector2D;
    private Vector3d vector3D;

    private Dictionary<(float, float), (Color, float)> colorDist;
    private int[] valueDist;

    private Random _random;

    public RandomValueGenerator()
    {
        _random = new System.Random();
        Reset();
    }

    public void Reset()
    {
        minFloatValue = float.MaxValue;
        maxFloatValue = float.MinValue;
        minIntValue = int.MaxValue;
        maxIntValue = int.MinValue;
        vector2D = default(Vector2d);
        vector3D = default(Vector3d);

        colorDist = new Dictionary<(float, float), (Color, float)>();
        valueDist = null;
    }

    public RandomValueGenerator WithRange(float min, float max)
    {
        Reset();
        minFloatValue = min;
        maxFloatValue = max;
        return this;
    }

    public RandomValueGenerator WithIntRange(int min, int max)
    {
        Reset();
        minIntValue = min;
        maxIntValue = max;
        return this;
    }

    public float NextFloat() => _random.NextSingle(minFloatValue, maxFloatValue + 1e-6);

    public int NextInt() => _random.Next(minIntValue, maxIntValue + 1);

    public Vector2d NextVector2D()
    {
        if (vector2D == default) vector2D = new Vector2d((NextFloat(), NextFloat()));
        return vector2D;
    }

    public Vector3d NextVector3D()
    {
        if (vector3D == default) vector3D = new Vector3d(NextVector2D(), NextFloat());
        return vector3D;
    }

    public Color NextColor(Dictionary<(float, float), (Color, float)> distribution = null)
    {
        if (distribution == null)
            distribution = colorDist;

        var distPair = distribution.OrderBy(x => x.Key.Item1 - x.Key.Item2).FirstOrDefault();
        if (!distPair.Equals(default))
            return distPair.Value;

        return Color.White;
    }

    public int NextColorIndex(Dictionary<int, float> distribution)
    {
        if (valueDist == null || valueDist.Length != distribution.Count)
        {
            valueDist = distribution.Select((x, i) => i).ToArray();
        }

        var index = _random.Next(0, valueDist.Length);
        return valueDist[index];
    }

    public override string ToString() => $"[{minIntValue},{maxIntValue}:{minFloatValue},{maxFloatValue}]";
}
```

