[' Here is a simplified C++11 library design, using `std::map` for setting storage, `std::mutex` for concurrent access, `boost::property_tree` for parsing config from various sources, and custom exception classes for error handling.

```cpp
#include <iostream>
#include <fstream>
#include <map>
#include <string>
#include <vector>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <mutex>

class ConfigSource {
public:
    virtual ~ConfigSource() {}
    virtual boost::property_tree::ptree load() const = 0;
};

struct FileSource : public ConfigSource {
    explicit FileSource(const std::string& file) : _file(file) {}
    boost::property_tree::ptree load() const override {
        boost::property_tree::ptree tree;
        try {
            std::ifstream ifs(this->_file);
            boost::property_tree::read_json(ifs, tree);
        } catch (const std::exception& e) {
            std::cerr << "Error reading file: " << this->_file << ", error: " << e.what() << '\n';
        }
        return tree;
    }

private:
    const std::string _file;
};

struct EnvironmentSource : public ConfigSource {
public:
    boost::property_tree::ptree load() const override {
        boost::property_tree::ptree tree;
        try {
            auto it = std::getenv("CONFIG");
            if (it == nullptr) {
                return tree;
            }
            boost::property_tree::read_json(std::string(*it), tree);
        } catch (const std::exception& e) {
            std::cerr << "Error reading environment variable: CONFIG, error: " << e.what() << '\n';
        }
        return tree;
    }
};

struct CommandLineSource : public ConfigSource {
public:
    explicit CommandLineSource(int argc, char* argv[]) : _argc(argc), _argv(argv) {}
    boost::property_tree::ptree load() const override {
        if (_argc <= 1) {
            return {};
        }
        try {
            boost::property_tree::read_json(std::string(*(_argv + 1)), *this->_config);
        } catch (const std::exception& e) {
            std::cerr << "Error reading command line arguments, error: " << e.what() << '\n';
        }
        return *this->_config;
    }

private:
    int _argc;
    const char** _argv;
    boost::property_tree::ptree* _config = new boost::property_tree::ptree();
};

class ConfigLoader {
public:
    explicit ConfigLoader(const std::vector<ConfigSource*>& sources) : _sources(sources) {}

    void load() {
        for (auto& source : this->_sources) {
            auto tree = source->load();
            if (!tree.empty()) {
                std::unique_lock<std::mutex> lock(this->_mutex);
                _config.insert(std::make_pair(tree.get_child("source").get_value<std::string>(), tree));
            }
        }
    }

private:
    std::map<std::string, boost::property_tree::ptree> _config;
    std::vector<ConfigSource*> _sources;
    mutable std::mutex _mutex;
};

class ConfigManager {
public:
    explicit ConfigManager(const ConfigLoader& loader) : _loader(loader), _current("file") {}

    void setCurrentSource(const std::string& sourceName) {
        if (_sources.find(sourceName) == _sources.end()) {
            throw InvalidSourceException{sourceName};
        }
        _current = sourceName;
    }

    template<typename T>
    const T* getSetting(const std::string& key, const T& defaultValue) {
        auto it = this->_config[_current].get<T>(key);
        if (it == nullptr) {
            return &defaultValue;
        }
        return it;
    }

private:
    const ConfigLoader& _loader;
    std::string _current;
    const auto _sources = this->_loader._config;
};

class InvalidSourceException : public std::runtime_error {
public:
    explicit InvalidSourceException(const std::string& source) : std::runtime_error("Invalid source: " + source) {}
};
```

This library allows you to create a configuration manager instance, load settings from multiple sources, and access them with the getSetting() function. You can switch between sources dynamically using setCurrentSource().

You may need to customize the ConfigSource classes for your specific use case or include additional features like error handling for missing keys or invalid values, logging mechanisms, etc. Additionally, consider implementing caching strategies to optimize performance and resource consumption when iterating or modifying configuration settings.']

