// Cache structure
typedef struct {
    void *data;
    size_t size;
    pthread_mutex_t lock;
} CacheEntry;

typedef struct {
    CacheEntry **cache;
    size_t cacheSize;
    size_t numEntries;
    sem_t sem; // Semaphore for synchronizing access to the cache
} Cache;

Cache *create_cache(size_t cacheSize) {
    Cache *cache = malloc(sizeof(Cache));
    cache->cache = calloc(cacheSize, sizeof(CacheEntry*));
    cache->cacheSize = cacheSize;
    cache->numEntries = 0;
    sem_init(&cache->sem, 0, cacheSize);
    return cache;
}

void put_in_cache(Cache *cache, const char *key, void *data, size_t size) {
    unsigned long index = hash(key) % cache->cacheSize;
    pthread_mutex_lock(&cache->cache[index]->lock);
    while (cache->cache[index] && strcmp(key, cache->cache[index]->data)) {
        index = (index + 1) % cache->cacheSize;
    }
    if (!cache->cache[index]) {
        cache->cache[index] = malloc(sizeof(CacheEntry));
        memcpy(cache->cache[index], calloc(1, sizeof(CacheEntry)), sizeof(CacheEntry));
    }
    cache->cache[index]->data = data;
    cache->cache[index]->size = size;
    pthread_mutex_unlock(&cache->cache[index]->lock);
}

void *get_from_cache(Cache *cache, const char *key) {
    unsigned long index = hash(key) % cache->cacheSize;
    pthread_mutex_lock(&cache->sem);
    while (cache->cache[index] && strcmp(key, cache->cache[index]->data)) {
        index = (index + 1) % cache->cacheSize;
    }
