#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libtiff/tiff.h>
#include <openssl/md5.h>

typedef struct {
    int width, height;
    short bits_per_sample;
    short samples_per_pixel;
    int extra_samples_count;
    unsigned char *extra_samples;
    unsigned char *md5_hash;
} TiffReport;

TiffReport* parseAndHashTiff(const char *file_path) {
    TIFF *tif = TIFFOpen(file_path, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file: %s\n", file_path);
        return NULL;
    }

    // Handle different bit depths
    switch (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE)) {
        case 1:
        case 8:
        case 16:
        case 32:
            break;
        default:
            fprintf(stderr, "Error: Unsupported bit depth: %d\n", TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE));
            TIFClose(tif);
            return NULL;
    }

    // Extract metadata and validate image structure
    int width = TIFFGetField(tif, TIFFTAG_IMAGEWIDTH);
    int height = TIFFGetField(tif, TIFFTAG_IMAGELENGTH);
    short samples_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    if (samples_per_pixel != 1 && samples_per_pixel != 3 && samples_per_pixel != 4) {
        fprintf(stderr, "Error: Unsupported number of samples per pixel\n");
        TIFClose(tif);
        return NULL;
    }

    int extra_samples_count = TIFFGetFieldCount(tif) - 3; // Account for width, height, and bits per sample fields

    // Allocate memory for extra samples if necessary
    if (extra_samples_count > 0) {
        TiffReport->extra_samples = malloc(TIFFDirectory_ItemsPerStrip(tif) * extra_samples_count);
        if (!TiffReport->extra_samples) {
            fprintf(stderr, "Error: Out of memory\n");
            TIFClose(tif);
            return NULL;
        }
    }

    // Read and store extra samples if present
    if (TIFFReadDirectory(tif) == 0) {
        fprintf(stderr, "Error: Failed to read directory\n");
        TIFClose(tif);
        return NULL;
    }

    for (int i = 3; i < extra_samples_count + 3; i++) {
        if (!TIFFGetField(tif, i)) break; // Reached the end of metadata fields

        int field_type = TIFFFieldDesc(i)->fType;
        switch (field_type) {
            case TIFF_SHORT:
            case TIFF_LONG:
                if (extra_samples_count > 0) TiffReport->extra_samples[TIFFDirectory_ItemsPerStrip(tif) * (i - 3)] = TIFFGetField(tif, i);
                break;
            default:
                fprintf(stderr, "Error: Unsupported metadata field type: %d\n", field_type);
                TIFClose(tif);
                return NULL;
        }
    }

    TiffReport *report = malloc(sizeof(TiffReport));
    if (!report) {
        fprintf(stderr, "Error: Out of memory\n");
        TIFClose(tif);
        return NULL;
    }

    report->width = width;
    report->height = height;
    report->bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    report->samples_per_pixel = samples_per_pixel;
    report->extra_samples_count = extra_samples_count;
    report->extra_samples = (extra_samples_count > 0) ? TiffReport->extra_samples : NULL;

    // Compute MD5 hash of file content
    unsigned char *buffer = malloc(TIFFDirectory_ItemsPerStrip(tif));
    if (!buffer) {
        fprintf(stderr, "Error: Out of memory\n");
        TIFClose(tif);
        free(report);
        return NULL;
    }

    unsigned char *hash_data = malloc((MD5_DIGEST_LENGTH + 1) * sizeof(unsigned char));
    if (!hash_data) {
        fprintf(stderr, "Error: Out of memory\n");
        free(buffer);
        TIFClose(tif);
        free(report);
        return NULL;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);

    TIFFSetByteOrder(tif, LITTLE_ENDIAN); // Ensure consistency for hashing large files

    size_t bytes_read = 0;
    while (TIFFReadScanline(tif, buffer, 0) == size_t(TIFFDirectory_ItemsPerStrip(tif))) {
        MD5_Update(&ctx, buffer, TIFFDirectory_ItemsPerStrip(tif));
        bytes_read += TIFFDirectory_ItemsPerStrip(tif);
    }

    if (bytes_read != TIFFDirectory_RowCount(tif) * TIFFDirectory_ItemsPerStrip(tif)) {
        fprintf(stderr, "Error: Incomplete file\n");
        free(buffer);
        MD5_Clean(&ctx);
        free(hash_data);
        TIFClose(tif);
        free(report);
        return NULL;
    }

    MD5_Final(hash_data, &ctx);
    report->md5_hash = hash_data;

    // Close file and cleanup resources
    free(buffer);
    TIFClose(tif);

    return report;
}
```

This implementation assumes the availability of `libtiff` and `OpenSSL` libraries. It handles various bit depths, validates image structure, computes MD5 hash, and returns a custom struct containing extracted metadata and computed hash. The code considers potential issues with large files by reading scanlines instead of loading the entire file into memory. Error handling has been added for better user experience.']

