#include <string.h>
#include <ctype.h>

char* modify_filename(const char *input) {
    size_t len = strlen(input);
    size_t dir_len = 0;
    size_t file_len = 0;
    size_t ext_len = 0;
    const char *ptr = input;

    // Find the last slash to separate the directory path, filename and extension
    for (; *ptr != '\0'; ++ptr) {
        if (*ptr == '/') {
            dir_len += file_len + ext_len + 1;
            file_len = ext_len = 0;
        } else if (*ptr == '.') {
            ext_len = len - (ptr - input);
        } else {
            ++file_len;
        }
    }
    dir_len += file_len + ext_len;

    // Allocate memory for the modified filename
    char *modified = malloc(dir_len + 10); // Add some extra space to avoid buffer overflows
    size_t index = 0;

    ptr = input;

    // Copy the directory path
    for (; *ptr != '\0' && *ptr != '/'; ++ptr, ++index) {
        modified[index] = *ptr;
    }

    // If there is no extension, set it to ".new"
    if (!*ptr || *ptr == '/') {
        ptr++;
        while (*ptr != '\0') {
            modified[index++] = *ptr++;
        }
        modified[index] = '.';
        index++;
        modified[index++] = 'n';
        modified[index++] = 'e';
        modified[index++] = '\0';
    } else {
        // Move to the next character after the last dot (or end of the string)
        for (; *ptr != '\0' && *ptr != '/'; ++ptr) {
            if (*ptr == '.') {
                ptr++;
                break;
            }
        }

        // Copy the filename up to the last dot or end of the string
        for (; ptr > input && *(ptr - 1) != '/'; --ptr, ++index) {
            modified[index] = *ptr;
        }
        ext_len = len - (ptr - input);

        // Calculate the number of digits in the filename and add "_even" or "_odd" as appropriate
        size_t num_digits = 0;
        for (const char *q = modified; *q != '\0'; ++q) {
            if (isdigit(*q)) {
                ++num_digits;
            }
        }
        char digit_suffix[3] = "";
        if (num_digits % 2 == 1) {
            strcpy(digit_suffix, "_odd");
        } else {
            strcpy(digit_suffix, "_even");
        }

        // Append the calculated number of digits followed by ".new" to the extension
        snprintf(modified + index, 10 - (len - dir_len), "%zu.new%s", num_digits, digit_suffix);
    }

    return modified;
}
