```cpp
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <string>
#include <mutex>
#include <map>
#include <fstream>
#include <png.h>
#include <thread>

std::mutex cipher_mutex;
std::mutex theme_mutex;

// Global state for AES-256-CBC ciphers and theme cache
std::map<std::string, EVP_CIPHER_CTX*> cipher_contexts;
std::map<std::string, png_structrp> theme_cache;

const std::string default_theme_dir = "/path/to/default/theme";

void cleanup_cipher(const std::string& password) {
    std::unique_lock<std::mutex> lock(cipher_mutex);

    if (auto cipher_ctx_it = cipher_contexts.find(password); cipher_ctx_it != cipher_contexts.end()) {
        EVP_CIPHER_CTX_free(cipher_ctx_it->second);
        cipher_contexts.erase(cipher_ctx_it);
    }
}

EVP_CIPHER_CTX* initialize_cipher(const std::string& password) {
    // Generate IV uniquely each time
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));

    // HMAC-based Key Derivation Function (HKDF) for deriving encryption key
    const uint8_t salt[] = "AES-256-CBC";
    size_t key_len;
    unsigned char *derived_key = HKDF(EVP_sha384(), salt, sizeof(salt), password.c_str(), password.length(), iv, sizeof(iv), &key_len);

    EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, derived_key, iv);
    EVP_CIPHER_CTX_set_padding(cipher_ctx, 1);
    EVP_CIPER_CTX_ctrl(cipher_ctx, TVF_ENCRYPT_PKCS7_PADDING, 0, NULL);

    {
        std::unique_lock<std::mutex> lock(cipher_mutex);
        cipher_contexts[password] = cipher_ctx;
    }

    return cipher_ctx;
}

void recycle_theme(const std::string& theme_id) {
    std::unique_lock<std::mutex> lock(theme_mutex);

    if (auto theme_it = theme_cache.find(theme_id); theme_it != theme_cache.end()) {
        png_destroy_read_struct(&theme_it->second, nullptr, nullptr);
        theme_cache.erase(theme_it);
    }
}

png_structrp get_theme(const std::string& theme_id) {
    std::unique_lock<std::mutex> lock(theme_mutex);

    if (auto theme_it = theme_cache.find(theme_id); theme_it != theme_cache.end()) {
        return theme_it->second;
    }

    const std::string cache_root = get_theme_dir(); // Implement the function to retrieve the default theme directory
    std::stringstream ss;
    ss << cache_root << "/" << theme_id << ".png";
    std::ifstream png_file(ss.str(), std::ios::binary);

    if (png_file.is_open()) {
        png_structrp theme = png_create_read_struct(PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
        png_bytep buffer;
        size_t length;

        png_file.seekg(0, std::ios::end);
        length = png_file.tellg();
        png_file.seekg(0);

        buffer = static_cast<png_bytep>(std::malloc(length));
        png_file.read(reinterpret_cast<char*>(buffer), length);
        png_decode(theme, &buffer[0], length);

        recycle_theme(theme_id);
        theme_cache[theme_id] = theme;

        return theme;
    }

    return nullptr;
}
```

This implementation includes a thread-safe cipher initialization and cleanup function, as well as a robust theme caching mechanism. The provided code snippet is intended to serve as a starting point for further customization and optimization based on your specific use case and requirements.']

