#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>

#define MAX_TIMEOUT 10 /* seconds */

typedef struct {
    char *cmd;
    pid_t pid;
    time_t start_time;
} Command;

void sigint_handler(int signum) {
    for (size_t i = 0; i < num_commands; ++i) {
        if (WIFSIGNALED(WEXITSTATUS(kill(command[i].pid, 0)))) {
            kill(command[i].pid, SIGTERM);
        } else {
            kill(command[i].pid, SIGINT);
        }
    }
}

int execute_command(const char *cmd, unsigned int timeout) {
    Command command = { cmd, 0, time(NULL) };
    pid_t child_pid = fork();

    if (child_pid == -1) {
        perror("fork");
        return 0;
    } else if (!child_pid) {
        execl(cmd, cmd, NULL);
        perror("execl");
        _exit(EXIT_FAILURE);
    }

    command.pid = child_pid;
    command.start_time += timeout;

    signal(SIGINT, sigint_handler);

    while (1) {
        if (timeout == 0 || time(NULL) < command.start_time) {
            continue;
        }

        int status;
        if (waitpid(command.pid, &status, WNOHANG) > 0) {
            break;
        }

        double elapsed = difftime(time(NULL), command.start_time);
        if (elapsed >= MAX_TIMEOUT) {
            kill(command.pid, SIGTERM);
            return 0;
        }
    }

    if (WIFSIGNALED(WEXITSTATUS(status))) {
        perror("Child process terminated by signal");
        return 0;
    } else {
        printf("[%s] Executed successfully in %.2fs\n", command.cmd, difftime(time(NULL), command.start_time));
        return 1;
    }
}
