        {
            _webHostBuilder = webHostBuilder;
            _logger = logger;
        }

        public async Task<IWebHost?> AddAndManageWebsiteAsync(string websiteDirectoryPath)
        {
            if (!Directory.Exists(websiteDirectoryPath))
            {
                _logger.LogError($"The specified directory does not exist: {websiteDirectoryPath}");
                return null;
            }

            var webConfigPath = Path.Combine(websiteDirectoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                _logger.LogError($"The specified directory does not contain a web.config file: {websiteDirectoryPath}");
                return null;
            }

            try
            {
                FileSecurity security = Directory.GetAccessControl(websiteDirectoryPath);
                if (!IsAppropriatePermissions(security))
                {
                    _logger.LogError($"Insufficient permissions on the specified directory: {websiteDirectoryPath}");
                    return null;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to check permissions on the specified directory: {ex.Message}", ex);
                return null;
            }

            try
            {
                using var cancellationTokenSource = new CancellationTokenSource();
                var host = _webHostBuilder
                    .UseContentRoot(websiteDirectoryPath)
                    .ConfigureLogging((hostingContext, loggingBuilder) =>
                    {
                        loggingBuilder.AddFilter("Microsoft", LogLevel.Warning);
                        loggingBuilder.AddConsole();
                    })
                    .UseUrls($"http://localhost:5000")
                    .Build();

                host.Start(cancellationTokenSource.Token);
                cancellationTokenSource.Token.ThrowIfCancellationRequested();

                await Task.Delay(TimeSpan.FromSeconds(10), cancellationTokenSource.Token); // Allow some time for external dependencies to initialize

                try
                {
                    var httpClient = new HttpClient();
                    // Check if the website is accessible, e.g., by sending a GET request to its root URL and checking the response status code
                    var response = await httpClient.GetAsync("http://localhost:5000", cancellationTokenSource.Token);
                    response.EnsureSuccessStatusCode();
                }
                catch (Exception ex)
                {
                    _logger.LogError($"Failed to access the running website: {ex.Message}", ex);
                    host.StopAsync(cancellationTokenSource.Token);
                    cancellationTokenSource.Cancel();
                    return null;
                }

                // Add your code here for handling any other dependencies, such as database connectivity or network services

                return host;
            }
            catch (Exception ex)
            {
                _logger.LogError($"Failed to start the website: {ex.Message}", ex);
                return null;
            }
        }

        private bool IsAppropriatePermissions(FileSecurity security)
        {
            var accessRule = new FileSystemAccessRule("Everyone", FileSystemRights.FullControl, AccessControlType.Allow);
            var inheritableAce = new InheritanceOnlyAce(accessRule);
            var ace = new Ace(inheritableAce);

            security.GetAccessRules(true, true, typeof(NTAccount)).ToList().ForEach(rule =>
            {
                if (ace.IsSimilarAccessRule(rule))
                    return;

                _logger.LogWarning($"Inappropriate permissions detected on the specified directory: {security.GetPath()}");
            });

            security.AddAccessRule(ace);
            return true;
        }
    }
}
```

