#include <set>
#include <mutex>

// Predefined roles as a set
std::set<std::string> authorized_roles = {"admin", "editor", "viewer"};

// Session store with weak ordering policy (for csrf_token caching)
class SessionStore {
public:
    std::mutex m;
    std::map<std::string, std::string> sessions;

    bool validateCSRFToken(const std::string& session_id, const std::string& token) {
        std::unique_lock<std::mutex> lock(m);
        auto it = sessions.find(session_id);
        if (it != sessions.end() && it->second == token)
            return true;
        return false;
    }
};

bool processUserSession(const char* payload) {
    json_t *root, *session_id, *expiration_time, *user_role, *csrf_token = json_object();
    time_t current_time, expiration;
    bool is_valid = true;

    root = json_loads(payload, 0, NULL);
    if (!root) {
        // Handle JSON parsing errors
        return false;
    }

    session_id = json_object_get(root, "session_id");
    expiration_time = json_object_get(root, "expiration_time");
    user_role = json_object_get(root, "user_role");

    if (!json_is_string(session_id) || json_string_length(session_id) == 0) {
        // Handle missing or invalid session_id
        is_valid = false;
    }

    if (!json_is_integer(expiration_time)) {
        // Handle missing or invalid expiration_time
        is_valid = false;
    } else {
        current_time = time(NULL);
        expiration = json_integer_value(expiration_time) + current_time;
        if (expiration <= current_time) {
            // Handle expired session
            is_valid = false;
        }
    }

    if (!json_is_string(user_role)) {
        // Handle missing user_role
        is_valid = false;
    } else {
        auto it = authorized_roles.find(json_string_value(user_role));
        if (it == authorized_roles.end()) {
            // Handle unauthorized role
            is_valid = false;
        }
    }

    if (json_object_has_member(root, "csrf_token")) {
        csrf_token = json_object_get(root, "csrf_token");
        if (!SessionStore::validateCSRFToken("session_id", json_string_value(csrf_token))) {
            // Handle invalid or missing csrf_token
            is_valid = false;
        }
    }

    json_decref(root);
    return is_valid;
}
```

