    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_integers(int* num, FILE* file) {
    fscanf(file, "%d", num);
    return fgetc(file) == EOF ? 1 : 0;
}

void randomize() {
    srand(time(NULL));
}

NFAPI_CRC_INDICATION_PDU_T* process_input(FILE* file) {
    int num = 0, count = 0;
    read_integers(&num, file);
    while (read_integers(&num, file)) {
        count++;
        randomize();
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }
        for (int i = 0; i < count - 1; i++) {
            data[i].RX_UE_INFORMATION_TAG = i + 1;
            data[i].RNTI = num;
            data[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        }
        data[count - 1].RX_UE_INFORMATION_TAG = count;
        data[count - 1].RNTI = num;
        data[count - 1].CRC_INDICATION_REL8_TAG = rand() % 2;
        free(data + 1); // Free memory for the unused elements (excluding first element)
        data--; // Adjust pointer to point to the first element
        return data;
    }
    return NULL; // Return null if there's only one integer in the input
}
