['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    uint32_t rnti;
    uint16_t harq_pid;
    uint8_t  RX_CQI_TAG;
    uint8_t  PHY_RX_SRS_TAG;
    uint16_t srs_id;
} LTE_PHY_RX_CQI_MEASUREMENT_T;

#define MAX_RNTIS 1000
sem_t rnti_cache_mutex;
pthread_mutex_t srs_id_mutex;
static unsigned int used_rntis[MAX_RNTIS];
static uint32_t next_srs_id = 0;

void init_cache() {
    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        used_rntis[i] = 0;
    }
}

unsigned int get_next_unique_rnti() {
    sem_wait(&rnti_cache_mutex);
    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        if (!used_rntis[i]) {
            used_rntis[i] = 1;
            sem_post(&rnti_cache_mutex);
            return i;
        }
    }
    sem_post(&rnti_cache_mutex);
    // If we reach here, all RNTIs are in use. Return a new one with the smallest index.
    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        if (!used_rntis[i]) {
            return i;
        }
    }
}

void lock_srs_id() {
    pthread_mutex_lock(&srs_id_mutex);
}

void unlock_srs_id() {
    pthread_mutex_unlock(&srs_id_mutex);
}

uint16_t get_next_srs_id() {
    uint16_t temp = next_srs_id;
    next_srs_id += 1;
    return temp % (1 << 14); // Limit the SRS ID to a valid range.
}

void log_init_info(int count, int skipped) {
    printf("Initialized %d measurements, with %d skipped due to constraints.\n", count, skipped);
}

LTE_PHY_RX_CQI_MEASUREMENT_T* initialize_measurements(size_t num_measurements, float srs_probability) {
    LTE_PHY_RX_CQI_MEASUREMENT_T* measurements = (LTE_PHY_RX_CQI_MEASUREMENT_T*)malloc(num_measurements * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!measurements) {
        perror("Failed to allocate memory for measurements");
        return NULL;
    }

    size_t counter = 0;
    while (counter < num_measurements && counter < MAX_RNTIS) {
        LTE_PHY_RX_CQI_MEASUREMENT_T* current_measurement = &measurements[counter];

        lock_srs_id();
        current_measurement->rnti = get_next_unique_rnti();
        current_measurement->harq_pid = rand() % 16; // Generate a valid harq pid.
        current_measurement->RX_CQI_TAG = rand() % 32 + 1; // Generate a valid RX CQI tag.
        if (rand() < srs_probability * RAND_MAX) {
            current_measurement->PHY_RX_SRS_TAG = 1;
            current_measurement->srs_id = get_next_srs_id();
        } else {
            current_measurement->PHY_RX_SRS_TAG = 0;
        }
        unlock_srs_id();

        counter++;
    }

    if (counter < num_measurements) {
        free(measurements);
        log_init_info(counter, num_measurements - counter);
        return NULL;
    }

    log_init_info(num_measurements, 0);
    return measurements;
}
```

This code initializes an array of `LTE_PHY_RX_CQI_MEASUREMENT_T` structures using a provided number of measurements. The function takes into account the constraints mentioned, including thread safety and resource management. However, it is important to note that the code does not include any system dependencies, external data sources, or performance optimizations as they would depend on specific use-cases. Also, this implementation assumes that `rand()` and `malloc()` functions behave correctly according to their respective standards.']

