    unsigned char srs_id[EVP_MD5_size()];
    EVP_MD5_final(srs_id, &md_ctx);

    for (; *num_elements < MAX_ELEMENTS; ++*num_elements) {
        // check if rnti is unique within the array
        // if not unique or memory allocation fails, handle accordingly and break loop

        data[*num_elements].rnti = rnti++;
        data[*num_elements].harq_pid = rand() % 16; // harq_pid range [0, 15]

        EVP_MD5_init(&md_ctx);
        EVP_MD5_final(data[*num_elements].RX_CQI_TAG, &md_ctx);
        data[*num_elements].RX_CQI_TAG[0] |= 0xF0; // set RX_CQI_TAG MSB to 1111
        data[*num_elements].RX_CQI_TAG[3] = (data[*num_elements].rnti >> 8) & 0x0F; // set RX_CQI_TAG LSB based on rnti

        data[*num_elements].PHY_RX_SRS_TAG[0] = srs_id[0];
        data[*num_elements].PHY_RX_SRS_TAG[1] = srs_id[1];
    }

    // Integrate cryptographic primitives into the OpenSSL library
    EVP_add_cipher("AES");
    EVP_add_cipher("Camellia");
    EVP_add_digest("MD5", NULL);
    EVP_add_digest("SHA1", NULL);
    EVP_add_digest_alias("rsa_sha1", "RSA_SHA1");

    // Handle memory deallocation and cleanup here
}
