#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    uint16_t rxUeInformationTag;
    uint32_t rnti;
    uint8_t crcIndicationRel8Tag;
    uint8_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* populateNFAPDUList(size_t count, double throughput, unsigned int seed) {
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *pduList = (NFAPI_CRC_INDICATION_PDU_T*) malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        perror("Memory allocation failed");
        return NULL;
    }

    double timePerPdu = 1.0 / throughput;
    clock_t start, end;

    for (size_t i = 0; i < count; ++i) {
        start = clock();
        do {
            end = clock();
        } while ((end - start) * CLOCKS_PER_SEC / timePerPdu < 1);

        pduList[i].rxUeInformationTag = rand() % 0xFFFF;
        pduList[i].rnti = rand() % 0xFFFFFFFF;
        pduList[i].crcIndicationRel8Tag = rand() % 0xFF;
        pduList[i].crcFlag = (rand() % 2) == 0 ? 1 : 0;
    }

    return pduList;
}

