```java
import org.apache.commons.codec.digest.DigestUtils;
import com.github.benmanes.caffeine.cache.Caffeine;
import io.micrometer.core.instrumentation.MeterRegistry;
import io.micrometer.core.timer.Timer;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.servlet.http.HttpServletRequest;
import javax.ws.rs.*;
import javax.ws.rs.core.Context;
import javax.ws.rs.core.Response;

@Path("md5")
public class Md5Service {

  private final ConcurrentMap<String, String> cache;
  private final Timer md5Timer;

  @Inject
  public Md5Service(MeterRegistry meterRegistry) {
    this.cache = Caffeine.newBuilder()
        .expireAfterWrite(10, TimeUnit.MINUTES)
        .maximumSize(1_000_000)
        .build();
    this.md5Timer = meterRegistry.timer("md5.request");
  }

  @POST
  public Response computeMd5(@Context HttpServletRequest request, String input) {
    try (Timer.Sample sample = md5Timer.start()) {
      String hash;
      if (cache.containsKey(input)) {
        hash = cache.get(input);
      } else {
        hash = DigestUtils.md5Hex(input.getBytes(StandardCharsets.UTF_8));
        cache.putIfAbsent(input, hash);
      }
      return Response.ok(hash).build();
    } catch (Exception e) {
      // Integrate your logging system here: Logback, Log4j2, etc.
      // ...
      throw new RuntimeException("Failed to compute MD5 hash", e);
    } finally {
      sample.stop();
    }
  }
}
