#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct FSA {
    int *transitions;
    int num_states;
} FSA;

typedef struct Set {
    int root;
    int rank;
} Set;

void make_set(Set *sets, int i) {
    if (sets[i].root != i) {
        sets[i].root = i;
    }
}

int find_set(Set *sets, int i) {
    if (sets[i].root != i) {
        sets[i].root = find_set(sets, sets[i].root);
    }
    return sets[i].root;
}

void union_sets(Set *sets, int x, int y) {
    int root_x = find_set(sets, x);
    int root_y = find_set(sets, y);

    if (root_x != root_y) {
        if (sets[root_x].rank < sets[root_y].rank) {
            sets[root_x].root = root_y;
            sets[root_y].rank++;
        } else if (sets[root_x].rank > sets[root_y].rank) {
            sets[root_y].root = root_x;
            sets[root_x].rank++;
        } else {
            sets[root_y].root = root_x;
            sets[root_x].rank++;
        }
    }
}

Set *create_sets(int num_states) {
    Set *sets = malloc(num_states * sizeof(Set));

    for (int i = 0; i < num_states; ++i) {
        sets[i].root = i;
        sets[i].rank = 1;
    }

    return sets;
}

void destroy_sets(Set *sets, int num_states) {
    free(sets);
}

struct State {
    int state;
    struct State *next;
};

void init_state(struct State **list, int state) {
    *list = malloc(sizeof(struct State));
    (*list)->state = state;
    (*list)->next = NULL;
}

struct StateList {
    struct State *head;
    size_t memory_used;
};

void append_state(struct StateList *list, struct State *state) {
    if (list->head == NULL) {
        list->head = state;
    } else {
        struct State *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = state;
    }
    list->memory_used += sizeof(struct State);
}

void free_state_list(struct StateList *list) {
    struct State *current, *temp;
    for (current = list->head; current != NULL; ) {
        temp = current;
        current = current->next;
        free(temp);
    }
}

void log_memory_usage(const char *message) {
    printf("%s: %ld bytes\n", message, sizeof(struct StateList));
}

FSA *fsa_to_state_list(int *states, int num_states, FSA *fsa) {
    Set *sets = create_sets(num_states);
    struct StateList *state_list = malloc(sizeof(struct StateList));
    struct State *current_state;
    long long disjointness_checks = 0;
    double total_time_taken = 0.0;

    log_memory_usage("Total memory usage before processing");

    for (int i = 0; i < num_states; ++i) {
        make_set(sets, i);
        init_state(&current_state, i);
        append_state(state_list, current_state);
    }

    long last_state = states[num_states - 1];
    double start_time;

    for (int i = 0; i < num_states; ++i) {
        for (int j = fsa->transitions[i * fsa->num_states + 2]; j != fsa->transitions[i * fsa->num_states + 3]; j += 4) {
            int next_state = fsa->transitions[j];
            start_time = clock() / CLOCKS_PER_SEC;
            int root_x = find_set(sets, i);
            int root_y = find_set(sets, next_state);
            disjointness_checks++;
            if (root_x != root_y) {
                union_sets(sets, root_x, root_y);
            }
            total_time_taken += (clock() / CLOCKS_PER_SEC - start_time);
        }
    }

    printf("Number of disjointness checks: %lld\n", disjointness_checks);
    printf("Total time taken for disjointness checks: %.3f seconds\n", total_time_taken);

    log_memory_usage("Memory usage after processing");

    struct State *current = state_list->head;
    struct State *next_state;
    current_state = malloc(sizeof(struct State));
    current_state->state = last_state;
    current_state->next = NULL;

    while (current != NULL) {
        next_state = current->next;
        append_state(state_list, current_state);
        current = next_state;
    }

    state_list->head->next = current_list->head;

    destroy_sets(sets, num_states);
    free(current_state);

    return state_list;
}
```']

