class ThreadPool {
private:
    std::vector<boost::thread> workers;
    std::queue<std::function<void()>> tasks;
    bool stop;

public:
    ThreadPool(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i)
            workers.emplace_back([this] { for (;;) { std::function<void()> task;
                {
                    std::unique_lock<std::mutex> lock(tasks_mtx);
                    task = move(tasks.front()); tasks.pop();
                }
                task();
                // Check if the pool should stop here, but don't hold a lock
                if (stop) return;
            }});
    }

    ~ThreadPool() {
        { std::lock_guard<std::mutex> lock(tasks_mtx); stop = true; }
        for (boost::thread & worker : workers) worker.join();
    }

    template <typename F, typename... Args>
    auto enqueue(F && f, Args &&... args) -> decltype(f(args...)) {
        using return_type = typename std::result_of<F(Args...)>::type;
        {
            std::lock_guard<std::mutex> lock(tasks_mtx);
            tasks.emplace([f = std::forward<F>(f), args...]() mutable { return f(args...); });
        }
        // Signal a task is ready to be processed
        tasks_cv.notify_one();
        // Wait for the result to be available (if we're currently in a blocking call)
        if (!tasks.empty()) tasks_cv.wait(tasks_mtx);
        return return_type();
    }

private:
    std::mutex tasks_mtx;
    std::condition_variable tasks_cv;
};

class RequestManager {
