// Custom data structure for records with integer value and string pointer
typedef struct Record {
    int value;
    char* str;
    struct Record* prev;
    struct Record* next;
} Record;

// Linked list head and tail pointers
Record* head = NULL;
Record* tail = NULL;

// Mutex for concurrent access synchronization
pthread_mutex_t mutex;

// Maximum memory limit (in bytes)
size_t max_memory = 1000000; // Set your desired maximum memory limit here

// Current memory usage (in bytes)
size_t memory_usage = 0;

// Logging function to track memory usage and performance metrics
void log_metrics(const char* message) {
    if ((memory_usage / max_memory) * 100 >= 85)
        printf("%s: Memory usage approaching critical threshold\n", message);
}

// Function to allocate record and initialize fields
Record* create_record(int value, const char* str) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->value = value;
    new_record->str = strdup(str);
    if (!new_record->str) {
        free(new_record);
        return NULL;
    }

    // Initialize pointers to the null record
    new_record->prev = tail;
    new_record->next = head;

    // Update linked list pointers for empty and non-empty lists
    if (head == NULL) {
        head = new_record;
        tail = new_record;
    } else {
        tail->next = new_record;
        head->prev = new_record;
        tail = new_record;
    }

    return new_record;
}

// Function to delete a record from the linked list
void delete_record(Record* record) {
    if (record == head && record == tail) { // Single element list
        free(record);
        head = NULL;
        tail = NULL;
    } else if (record == head) {            // Head node to be removed
        Record* next_node = record->next;
        free(record);
        head = next_node;
        head->prev = NULL;
    } else if (record == tail) {           // Tail node to be removed
        Record* prev_node = record->prev;
        free(record);
        tail = prev_node;
        tail->next = NULL;
    } else {                                // Internal node removal
        Record* prev_node = record->prev;
        Record* next_node = record->next;
        free(record);
        prev_node->next = next_node;
        next_node->prev = prev_node;
    }
}

// Function to traverse the linked list and perform an operation on each node (place holder for actual operation)
void traverse_list(void (*operation)(Record*)) {
    pthread_mutex_lock(&mutex);
        Record* current = head;
        while (current != NULL) {
            Record* next = current->next;
            operation(current);
            current = next;
        }
    pthread_mutex_unlock(&mutex);
}

// Place holder for loading data asynchronously from an external source (use your preferred method for network I/O)
void load_data() { ... }
