using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ResourceManager
{
    private readonly ConcurrentDictionary<string, (Resource, int)> _resources; // Key: Resource ID, Value: (Resource object, Version number)
    private readonly string _resourceDirectory;
    private readonly IResourceChangeListener _listener;

    public ResourceManager(string resourceDirectory, IResourceChangeListener listener)
    {
        _resources = new ConcurrentDictionary<string, (Resource, int)>();
        _resourceDirectory = resourceDirectory;
        _listener = listener;
        LoadAllResources();
    }

    private void LoadAllResources()
    {
        Directory.CreateDirectory(_resourceDirectory);
        foreach (var file in Directory.EnumerateFiles(_resourceDirectory))
        {
            var id = Path.GetFileNameWithoutExtension(file);
            if (_resources.TryAdd(id, LoadResourceFromFile(file))) continue;
            _resources[id] = LoadResourceFromFile(file);
        }
    }

    private (Resource, int) LoadResourceFromFile(string filePath)
    {
        try
        {
            using var reader = new StreamReader(filePath);
            var json = reader.ReadToEnd();
            return JsonConvert.DeserializeObject<(Resource, int)>(json);
        }
        catch (Exception ex)
        {
            throw new FileNotFoundException($"Resource with ID {Path.GetFileNameWithoutExtension(file)} could not be loaded.", ex);
        }
    }

    public Resource LoadResourceById(string id)
    {
        if (!_resources.TryGetValue(id, out var resourceWithVersion)) throw new FileNotFoundException($"Resource with ID {id} not found.");
        return resourceWithVersion.Item1;
    }

    private void SaveResourceToFile(string id, Resource resource)
    {
        var (_, version) = _resources[id];
        var filePath = Path.Combine(_resourceDirectory, $"{id}.json");
        using var writer = new StreamWriter(filePath);
        writer.Write(JsonConvert.SerializeObject((resource, version)));
    }

    private void IncrementResourceVersion(string id) => _resources[id] = (_resources[id].Item1, _resources[id].Item2 + 1);

    public void SaveResource(Resource resource)
    {
        if (!_resources.TryGetValue(resource.Id, out var existingResource)) throw new Exception("Trying to save a non-existing resource.");

        lock (this) // Ensure that multiple Save calls don't overwrite each other concurrently
        {
            if (existingResource.Item2 != resource.Version)
            {
                SaveResourceToFile(resource.Id, resource);
                IncrementResourceVersion(resource.Id);

                Task.Run(() =>
                {
                    _listener.OnResourceChanged(new ResourceChangeEventArgs
                    {
                        Id = resource.Id,
                        Action = ResourceAction.Updated,
                        Version = resource.Version
                    });
                });
            }
        }
    }

    public int GetResourceVersion(string id) => _resources[id].Item2;

    public void RegisterResourceChangeListener(IResourceChangeListener listener) => _listener += listener;
}

public delegate void ResourceChangeEventHandler(ResourceChangeEventArgs e);

public class ResourceChangeEventArgs
{
    public string Id { get; set; }
    public ResourceAction Action { get; set; }
    public int Version { get; set; }
}

public enum ResourceAction
{
    Created,
    Updated,
    Deleted
}

public interface IResourceChangeListener
{
    void OnResourceChanged(ResourceChangeEventArgs e);
}
```

