#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int *states;
    int num_states;
    int capacity;
    void (*parse_rule)(void*, const char*); // Function pointer to parse transition rules
    void (*apply_transition)(void*, int from, int* next_state); // Function pointer to apply transitions
    void (*free_rules)(void*); // Function pointer to free cached rules
    void *rule_data; // Data associated with the FSA
    pthread_mutex_t mutex; // Lock for concurrent access
} FSA;

int* expand_fsa(FSA* fsa, int *current_states, int num_current_states, int buffer_size) {
    if (buffer_size < num_current_states + 1) return NULL;

    int *new_states = malloc(buffer_size * sizeof(int));
    if (!new_states) return NULL;

    pthread_mutex_lock(&fsa->mutex);
    for (int i = fsa->num_states; i < num_current_states + 1; ++i) {
        new_states[i] = current_states[i];
    }
    fsa->num_states += num_current_states + 1;
    pthread_mutex_unlock(&fsa->mutex);

    for (int i = num_current_states - 1; i >= 0; --i) {
        int next_state = -1;
        fsa->apply_transition(fsa, current_states[i], &next_state);
        if (next_state != -1 && next_state < num_current_states) {
            pthread_mutex_lock(&fsa->mutex);
            int *next = &new_states[next_state];
            *next = current_states[i];
            pthread_mutex_unlock(&fsa->mutex);
        }
    }

    if (fsa->num_states - fsa->capacity > buffer_size / 2) {
        fsa->capacity *= 2;
        void *old_rules = fsa->rule_data;
        fsa->rule_data = realloc(fsa->rule_data, fsa->capacity * sizeof(void*));
        if (!fsa->rule_data) {
            free(new_states);
            pthread_mutex_lock(&fsa->mutex);
            fsa->num_states -= num_current_states + 1;
            pthread_mutex_unlock(&fsa->mutex);
            free(old_rules);
            return NULL;
        }
        if (old_rules) fsa->free_rules(old_rules);
    }

    return expand_fsa(fsa, new_states, num_current_states + 1, buffer_size);
}
```

