import java.io.IOException;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ConcurrentHashMap;
import java.util.ConcurrentLinkedQueue;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MD5Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5Hasher.class);
    private static final int MAX_THREADS = 10;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long TIMEOUT_MILLIS = 5000L;

    private Map<String, String> hashedStrings;
    private Queue<String> inputQueue;
    private ExecutorService executor;

    public MD5Hasher() {
        this.hashedStrings = new ConcurrentHashMap<>();
        this.inputQueue = new ConcurrentLinkedQueue<>();
        this.executor = Executors.newFixedThreadPool(MAX_THREADS);
    }

    public void addInputString(String input) {
        if (input == null || input.isBlank()) {
            LOGGER.warn("Received null or blank input string");
            return;
        }

        inputQueue.add(input);
    }

    public Map<String, String> processInputs() {
        Map<String, String> results = new ConcurrentHashMap<>(hashedStrings);

        while (!inputQueue.isEmpty()) {
            String input = inputQueue.poll();
            Runnable task = () -> processInput(input);

            executor.submit(task);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            LOGGER.error("Interrupted while waiting for task completion", e);
        }

        return results;
    }

    private void processInput(String input) {
        try {
            byte[] hash = MessageDigest.getInstance("MD5").digest(input.getBytes(StandardCharsets.UTF_8));
            String hashedValue = new BigInteger(1, hash).toString(16);

            while (hashedStrings.putIfAbsent(input, hashedValue) != null && --RETRY_ATTEMPTS > 0) {
                Thread.sleep(500L);

                try {
                    byte[] retryHash = MessageDigest.getInstance("MD5").digest(input.getBytes(StandardCharsets.UTF_8));
                    hashedValue = new BigInteger(1, retryHash).toString(16);

                    if (hashedStrings.putIfAbsent(input, hashedValue) == null) {
                        break;
                    }
                } catch (IOException e) {
                    LOGGER.warn("Failed to hash input string due to I/O error", e);
                }
            }

            if (RETRY_ATTEMPTS <= 0 && !hashedStrings.containsKey(input)) {
                LOGGER.error("Failed to hash input string after retry attempts");
            }
        } catch (Exception e) {
            LOGGER.warn("Failed to hash input string", e);
        }
    }
}
```

