#include <stdio.h>
#include <stdlib.h>
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/kdf.h>
#include <string.h>

// Key management interface
typedef void* key_t;
key_t create_key(const char *password, unsigned char *salt, size_t salt_len);
void destroy_key(key_t key);
const unsigned char* get_key(key_t key, size_t *length);

// Error codes for debugging
#define KEY_INVALID_LENGTH -1
#define MEMORY_ALLOCATION_FAILURE -2
#define INVALID_KEY -3
#define KEY_NOT_FOUND -4

// Function to initialize AES-256-GCM cipher
AES_GCM *aes_gcm_init(key_t key, const unsigned char *nonce, size_t nonce_len) {
    if (nonce_len != 12) return NULL;

    unsigned char key_material[32];
    size_t key_length = get_key(key, &key_length);

    if (key_length != 32) return NULL;

    memcpy(key_material, key, 32);
    EVP_KDF(EVP_aes_256_gcm(), nonce, sizeof(nonce), key_material, 32, key_material, 32);

    AES_GCM *cipher = AES_GCM_init(EVP_aes_256_gcm(), key_material, nonce, NULL);
    return cipher;
}

// Function to encrypt data using the initialized AES-256-GCM cipher
void aes_gcm_encrypt(AES_GCM *cipher, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    if (!cipher || !plaintext || !ciphertext) return;

    int tag_len = AES_GCM_TAGLENGTH;
    unsigned char tag[tag_len];

    AES_GCM_encrypt(cipher, ciphertext, plaintext, plaintext_len, tag, NULL);

    for (size_t i = 0; i < tag_len; ++i) {
        ciphertext[plaintext_len + i] = tag[i];
    }
}

// Function to decrypt data using the initialized AES-256-GCM cipher
int aes_gcm_decrypt(AES_GCM *cipher, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    if (!cipher || !ciphertext || !plaintext) return INVALID_KEY;

    int tag_len = AES_GCM_TAGLENGTH;
    const size_t total_len = ciphertext_len - tag_len;

    if (total_len < 0) return KEY_INVALID_LENGTH;

    unsigned char tag[tag_len];
    memcpy(tag, &ciphertext[total_len], tag_len);

    int ret = AES_GCM_decrypt(cipher, plaintext, ciphertext, total_len, tag, NULL);

    if (ret == 0) return SUCCESS;

    return INVALID_KEY;
}

