    NFAPI_CRC_INDICATION_PDU_T* data;
    sem_t semaphore;
};

void init_list(struct list* list, size_t n) {
    if (n == 0) {
        return;
    }
    list->len = n;
    list->data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    sem_init(&list->semaphore, 0, n);
}

void destroy_list(struct list* list) {
    if (list == NULL || list->len == 0) {
        return;
    }
    free(list->data);
    sem_destroy(&list->semaphore);
}

bool add_to_list(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* item) {
    if (list == NULL || item == NULL) {
        return false;
    }
    sem_wait(&list->semaphore);
    bool success = true;
    size_t index = list->len % list->len;
    NFAPI_CRC_INDICATION_PDU_T* ptr = &list->data[index];
    *ptr = (*item); // Copy the item into the list (note: no need to set CRCFLAG)
    list->len++;
    sem_post(&list->semaphore);
    return success;
}

bool remove_from_list(struct list* list, size_t index) {
    if (list == NULL || list->len <= 0) {
        return false;
    }
    sem_wait(&list->semaphore);
    bool success = true;
    if (index >= list->len) {
        success = false;
    } else {
        size_t last_index = list->len - 1;
        NFAPI_CRC_INDICATION_PDU_T* first = &list->data[0];
        memcpy(first + index, first + last_index, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->len--;
    }
    sem_post(&list->semaphore);
    return success;
}
