#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <time.h>

typedef struct {
    uint32_t rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T *array = NULL;
static size_t capacity = 0, size = 0;
static sem_t mutex = SEM_INITIALIZER_NP;
static pthread_cond_t notFull = PTHREAD_COND_INITIALIZER;
static pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;

void resize(size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
    if (!newArray) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }
    array = newArray;
    capacity = newCapacity;
}

void enqueue(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&mutex);
    for (size_t i = 0; i < size; ++i) {
        if (array[i].rnti == pdu->rnti) {
            fprintf(stderr, "RNTI collision detected\n");
            sem_post(&mutex);
            return;
        }
    }

    if (size >= capacity) {
        resize(capacity * 2);
    }
    array[size++] = (*pdu);
    sem_post(&mutex);
    pthread_cond_signal(&notFull);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue() {
    NFAPI_CRC_INDICATION_PDU_T *result = NULL;
    sem_wait(&mutex);
    if (size == 0) {
        sem_post(&mutex);
        pthread_cond_wait(&notEmpty, &mutex);
    }

    result = array[--size];
    sem_post(&mutex);
    pthread_cond_signal(&notEmpty);
    return result;
}
```

This code provides a basic dynamic array implementation with a mutex for synchronization and condition variables to handle concurrency. The `enqueue()` function checks for RNTI collisions and resizes the array when necessary, while the `dequeue()` function handles empty conditions by waiting until an element is available.

