typedef struct record {
    int *value;
    long *offset;
} Record;

void error_and_exit(const char* message) {
    printf("%s\n", message);
    exit(EXIT_FAILURE);
}

int validate_input(int size, const char* array_name, int max_size) {
    if (size <= 0 || size > max_size) {
        error_and_exit("Invalid input for array size of the 'array_name'. Must be within [1, max_size]");
        return -1;
    }

    return 1;
}

Record* create_record() {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        error_and_exit("Memory allocation failure for struct record");
    }

    record->value = malloc(sizeof(int));
    if (!record->value) {
        free(record);
        error_and_exit("Memory allocation failure for struct record->value");
    }

    record->offset = NULL;

    return record;
}

long* create_offsets(int size, pthread_mutex_t *mutex) {
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        error_and_exit("Memory allocation failure for offsets array");
    }

    if (mutex) {
        pthread_mutex_init(&mutex[0], NULL);
        for (int i = 1; i < size; ++i) {
            pthread_mutex_init(&mutex[i], NULL);
        }
    }

    return offsets;
}

void deallocate_offsets(long *offsets, int size, pthread_mutex_t *mutex) {
    if (mutex) {
        for (int i = 0; i < size; ++i) {
            pthread_mutex_destroy(&mutex[i]);
        }
    }

    free(offsets);
}

void init_values(Record* record, int value) {
    *record->value = value + rand() % 101;
    record->offset = NULL;
}

void link_offset(long *offsets, Record *record, long index) {
    record->offset = offsets + index;
    if (index > 0) {
        *(record->offset - 1) = index - 1;
    }
}

int main() {
    int offset_size, key_size;

    printf("Enter the size of offset and keys arrays: ");
    scanf("%d%d", &offset_size, &key_size);

    if (validate_input(offset_size, "offsets", 1000) != 1 || validate_input(key_size, "keys", 1000) != 1) {
        return -1;
    }

    pthread_mutex_t offsets_mutex[1000];
    long *offsets = create_offsets(offset_size, offsets_mutex);

    Record *records = malloc(sizeof(Record) * key_size);
    if (!records) {
        error_and_exit("Memory allocation failure for records array");
    }

    for (int i = 0; i < key_size; ++i) {
        records[i] = create_record();
        init_values(records[i], rand() % 101);
        link_offset(offsets, records[i], *records[i].offset);
    }

    // Print values and offsets for each record
    for (int i = 0; i < key_size; ++i) {
        printf("Record %d: value=%d, offset=%ld\n", i, records[i].value[0], *records[i].offset);
    }

    free(records);
    deallocate_offsets(offsets, offset_size, offsets_mutex);

    return 0;
}
