int initializeNfarxIndicationPduArray(NFAPI_CRC_INDICATION_PDU_T **pPDUs, size_t arraySize) {
    if (!pPDUs || arraySize == 0) {
        return -1; /* Invalid input parameters */
    }

    *pPDUs = (NFAPI_CRC_INDICATION_PDU_T *) malloc(arraySize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pPDUs) {
        return -2; /* Memory allocation failure */
    }

    size_t written = 0;
    for (size_t i = 0; i < arraySize && written < arraySize; ++i) {
        uint32_t rnti = (uint32_t) (rand() * MAX_RNTI / RAND_MAX + 1);

        /* Use the same CRCFLAG for all elements to minimize allocations */
        NFAPI_CRC_INDICATION_PDU_T *pPdu = &((*pPDUs)[written]);
        pPdu->rxUeInformationTag.tagValue = RX_UE_INFORMATION_TAG_VALUE;
        pPdu->rnti = rnti;
        pPdu->crcIndicationRel8Tag.crcFlag = rand() % 2;

        if (!isValidRnti(pPdu->rnti)) {
            /* Reuse the last valid RNTI for next iteration */
            pPdu->rnti = written > 0 ? (*pPDUs)[written - 1].rnti : rnti;
        } else {
            ++written;
        }
    }

    /* If all elements were not written, return the number of successfully initialized elements */
    return written < arraySize ? written : 0;
}
