#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    RX_CQI_TAG cqi;
    PHY_RX_SRS_TAG srs;
} Measurement;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t num_elements;
    Measurement* elements;
    size_t* rnti_cache; // Cache of used RNTI values
} MeasurementCache;

MeasurementCache* measurement_cache_init(size_t max_measurements) {
    MeasurementCache* cache = malloc(sizeof(MeasurementCache));
    if (!cache) return NULL;

    pthread_mutex_init(&cache->mutex, NULL);
    cache->capacity = max_measurements;
    cache->num_elements = 0;
    cache->elements = calloc(max_measurements, sizeof(Measurement));
    if (!cache->elements) {
        free(cache);
        return NULL;
    }
    cache->rnti_cache = malloc(sizeof(size_t) * max_measurements);
    if (!cache->rnti_cache) {
        free(cache->elements);
        free(cache);
        return NULL;
    }

    // Initialize rnti_cache with all zeros
    for (size_t i = 0; i < cache->capacity; ++i) {
        cache->rnti_cache[i] = 0;
    }

    printf("Measurement cache initialized with %zu maximum measurements.\n", max_measurements);
    return cache;
}

Measurement* measurement_cache_alloc(MeasurementCache* cache) {
    pthread_mutex_lock(&cache->mutex);

    for (size_t i = 0; i < cache->capacity; ++i) {
        if (!cache->rnti_cache[i]) {
            cache->rnti_cache[i] = 1;
            Measurement* measurement = &cache->elements[i];
            pthread_mutex_unlock(&cache->mutex);
            return measurement;
        }
    }

    pthread_mutex_unlock(&cache->mutex);
    return NULL; // Returning NULL indicates failed allocation
}

// Implement functions for generating random RNTI, HARQ_PID, and SRS_ID values within valid ranges
// Include proper error handling, thread-safety, caching, and logging as per the requirements.

void measurement_cache_free(MeasurementCache* cache) {
    pthread_mutex_destroy(&cache->mutex);
    free(cache->elements);
    free(cache->rnti_cache);
    free(cache);
}
```

