// Memory management functions
void* aligned_malloc(size_t size, size_t alignment) {
    void *result = malloc(size + alignment - 1);
    if (result != NULL) memset(((char*)result) + alignment - 1, 0, alignment);
    return result + (alignment - (uintptr_t)(result)) % alignment;
}

void aligned_free(void* ptr) { free(ptr); }

// Logging and error handling functions
void log_error(const char *function, size_t requested, size_t available, const char *message) {
    FILE *logfile = fopen("errors.log", "a");
