    size_t alignment = sizeof(NFAPI_RX_FRAME_INFO_PDU_T);
    size_t allocation_size = N * alignment;

    void *mem = aligned_malloc(allocation_size, alignment);
    if (mem == NULL) {
        log_error("create_frames", allocation_size, get_memory_usage(), "Failed to allocate memory");
        return NULL;
    }

    NFAPI_RX_FRAME_INFO_PDU_T *frames = mem;
    for (size_t i = 0; i < N; ++i) {
        frames[i].tag = RX_UE_INFORMATION_TAG_UNKNOWN;
        frames[i].rnti.rnti = -1;
        frames[i].phy_info.timeStamp = 0;
        frames[i].phy_info.signalQualityIndicator = 0;
    }

    check_memory(allocation_size);
    return frames;
}

// Semaphore for thread safety when checking and updating memory usage status
pthread_mutex_t mem_lock;
sem_t mem_semaphore;

int main() {
    pthread_mutex_init(&mem_lock, NULL);
