typedef struct _message {
    uint64_t message_id;
    time_t timestamp;
    enum priority level;
    MHPLMessageHeader header;
} Message;

static sem_t cache_mutex; // Mutex for message ID cache
static sem_t message_pool_mutex; // Mutex for message pool
static uint64_t* used_message_ids; // Cache of used message IDs
static size_t num_used_message_ids = 0;
static size_t max_messages = 1000;
static double priority_probability = 0.5;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for logging
static FILE* log_file; // Log file stream

// Initialize data structures and open log file
void init(const char *log_filename) {
    num_used_message_ids = 0;
    used_message_ids = malloc(max_messages * sizeof(uint64_t));
    if (!used_message_ids) {
        fprintf(stderr, "Failed to allocate memory for message ID cache.\n");
        return;
    }

    sem_init(&cache_mutex, 0, 1);
    sem_init(&message_pool_mutex, 0, 1);

    log_file = fopen(log_filename, "w+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'.\n", log_filename);
        return;
    }
}

// Function to generate a new message object with unique ID and timestamp
Message* allocate_message() {
    Message* msg = malloc(sizeof(Message));
    if (!msg) {
        fprintf(stderr, "Failed to allocate memory for message.\n");
        return NULL;
    }

    sem_wait(&cache_mutex);
    uint64_t message_id;
    do {
        message_id = rand() % (MAXINT - num_used_message_ids);
    } while (num_used_message_ids <= message_id && message_id >= 0);

    if (num_used_message_ids < max_messages) {
        used_message_ids[num_used_message_ids] = message_id;
        num_used_message_ids++;
    } else {
        free(msg);
        msg = NULL;
    }

    sem_post(&cache_mutex);

    if (msg) {
        msg->message_id = used_message_ids[num_used_message_ids - 1];
        msg->timestamp = time(NULL);
        msg->level = (double)rand() / RAND_MAX < priority_probability ? HIGH_PRIORITY : LOW_PRIORITY;
    }

    return msg;
}

// Log detailed information about the initialization process
void log_init_info(const char *message) {
    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

