    cache->size = 0;
    cache->data = malloc(max_measurments * sizeof(MEASUREMENT_STRUCT));
    if (!cache->data) {
        fprintf(stderr, "Error: Failed to allocate memory for measurement cache.\n");
        return;
    }
    cache->rnti_cache = malloc(max_measurments * sizeof(size_t));
    if (!cache->rnti_cache) {
        fprintf(stderr, "Error: Failed to allocate memory for RNTI cache.\n");
        free(cache->data);
        return;
    }
    pthread_mutex_init(&cache->mutex, NULL);
}

MEASUREMENT_STRUCT* get_measurement(MEASUREMENT_CACHE* cache) {
    size_t i;
    for (i = 0; i < cache->size; ++i) {
        if (!cache->data[i].rnti) { // Skipped measurement
            continue;
        }
        if (cache->rnti_cache[i] == cache->size) { // Reusable structure
            cache->rnti_cache[i] = 0;
            return &cache->data[i];
        }
    }
    if (cache->size >= cache->capacity) {
        fprintf(stderr, "Error: Measurement cache is full.\n");
        return NULL;
    }
    size_t new_index = cache->size++;
    MEASUREMENT_STRUCT* new_measurement = &cache->data[new_index];
    // Initialize the new measurement structure here with appropriate values
    // Set RNTI according to your system dependencies and external data sources for validation
    // Generate SRSFLAG, SRS_ID, HARQ_PID, etc. as per the task requirements
    cache->rnti_cache[new_index] = 0;
    return new_measurement;
}

void log_metrics(MEASUREMENT_CACHE* cache) {
    printf("Initialization metrics:\n");
    printf("# Measurements allocated: %zu\n", cache->size);
    printf("# Skipped measurements: %zu\n", cache->size - cache->capacity);
}

void deinit_measurement_cache(MEASUREMENT_CACHE* cache) {
    free(cache->data);
    free(cache->rnti_cache);
    pthread_mutex_destroy(&cache->mutex);
