#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RNTI 0xFFFF // Maximum RNTI value as per protocol specification

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom synchronization primitive using pthread_mutex_t
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Linked List node structure
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
};

struct Node* head = NULL;
const unsigned int garbage_collection_interval = 60; // In seconds

void garbage_collection() {
    pthread_mutex_lock(&list_mutex);
    struct Node* current = head;
    struct Node* next;

    while (current != NULL) {
        time_t current_time = time(NULL);
        if ((current->data.timestamp + garbage_collection_interval) < current_time) {
            next = current->next;
            free(current);
            current = next;
        } else {
            break;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}

void add_node(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list_mutex);

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    newNode->data = data;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&list_mutex);
}

void list_display() {
    struct Node* current = head;

    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %ld\n", current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG & 0x1);
        current = current->next;
    }
}

// Validate RNTI and set CRCFLAG randomly
void generate_data(uint16_t rnti) {
    if (rnti > MAX_RNTI || rnti < 1)
        return;

    NFAPI_CRC_INDICATION_PDU_T data = { .RX_UE_INFORMATION_TAG = 0xDEADBEEF, .RNTI = rnti, .CRC_INDICATION_REL8_TAG = (time(NULL) & 0xFFFFFF), .timestamp = time(NULL) };
    add_node(data);
}

// Thread-safe function to generate data and display list
void* worker(void *arg) {
    while (true) {
        generate_data(rand() % MAX_RNTI + 1);
        sleep(rand() % 5 + 2); // Variable sleep duration to simulate real-world variability
        garbage_collection();
        list_display();
    }
}

int main() {
    pthread_t workers[10];

    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&workers[i], NULL, &worker, NULL)) {
            printf("Error: Thread creation failed.\n");
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}
