hash_table* create_hash_table(unsigned int size) {
    hash_table *ht = malloc(sizeof(hash_table));
    ht->size = size;
    ht->nodes = calloc(size, sizeof(hash_node*));
    ht->lock = PTHREAD_MUTEX_INITIALIZER;
