    new_node->data = data;
    new_node->next = current;
    ht->nodes[index] = new_node;

    pthread_mutex_unlock(&ht->lock);
}

bool get_from_table(hash_table* ht, NFAPI_CRC_INDICATION_PDU_T* data) {
