    unsigned int index = hash(*data);
    hash_node *current = ht->nodes[index];

    while (current != NULL) {
        if (memcmp(current, data, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            *data = current->data;
            hash_node* temp = current;
            current = current->next;
            free(temp);
            pthread_mutex_unlock(&ht->lock);
            return true;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return false;
}

NFAPI_CRC_INDICATION_PDU_T* allocate(int N, int *currentMemory, int maxMemory) {
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!data) {
        printf("Error: Memory allocation failure.\n");
        *currentMemory -= N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        return NULL;
    }

    hash_table* ht = create_hash_table(N);

