            *currentMemory -= N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
            return NULL;
        }
    }

    int new_memory = *currentMemory + (N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_memory > maxMemory) {
