[' Here is an example of a thread-safe, dynamically resizable queue implementation in C using the `pthread_mutex_t` for synchronization and `std::vector` as the underlying data structure. The code also includes a simple API for enqueuing and dequeuing elements.

```c
#include <vector>
#include <queue>
#include <memory>
#include <pthread.h>

template<typename T>
class SafeQueue {
public:
    explicit SafeQueue(size_t capacity) : _capacity(capacity), _data(_capacity, std::unique_ptr<T>{new T()}) {}

    void enqueue(const T& value) {
        pthread_mutex_lock(&_mutex);
        if (_data.size() == _capacity) {
            resize();
        }
        _data[_data.size() - 1].reset(new T(value));
        pthread_mutex_unlock(&_mutex);
    }

    std::unique_ptr<T> dequeue() {
        pthread_mutex_lock(&_mutex);
        if (_data.empty()) {
            pthread_mutex_unlock(&_mutex);
            return nullptr;
        }
        auto result = std::move(_data.front());
        _data.pop_front();
        pthread_mutex_unlock(&_mutex);
        return result;
    }

private:
    void resize() {
        size_t newCapacity = _capacity * 10;
        std::vector<std::unique_ptr<T>> temp(newCapacity, std::unique_ptr<T>{new T()});
        pthread_mutex_lock(&_mutex);
        for (size_t i = 0; i < _data.size(); ++i) {
            if (_data[i]) {
                temp[i].reset(_data[i]);
            }
        }
        _data.swap(temp);
        _capacity = newCapacity;
        pthread_mutex_unlock(&_mutex);
    }

private:
    std::vector<std::unique_ptr<T>> _data;
    size_t _capacity;
    pthread_mutex_t _mutex;
};
```

