#include "ListManager.h"
#include <algorithm>
#include <ctime>
#include <cstdlib>
#include <system_error>

namespace {
    const size_t DEFAULT_MAX_SIZE = 1024;
}

inline ListManager::ListManager(size_t maxSize, int logLevel, std::shared_ptr<ILogger> logger) :
        capacity(maxSize > 0 ? maxSize : DEFAULT_MAX_SIZE), logLevel(logLevel), logger(logger) {
    if (capacity <= 0)
        throw std::invalid_argument("Invalid maximum size.");
}

ListManager::~ListManager() {}

void ListManager::push(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
    std::lock_guard<std::mutex> lk(mtx);
    if (data.size() >= capacity) {
        if (logLevel > 1)
            logger->log(LogLevel::INFO, "List is full. Dropping data.");
        return;
    }
    data.emplace_back(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(pdu));
}

const NFAPI_CRC_INDICATION_PDU_T* ListManager::getRandomPdu() const {
    std::lock_guard<std::mutex> lk(mtx);
    if (data.empty())
        return nullptr;
    auto it = data.begin();
    std::advance(it, rand() % data.size());
    return it->get();
}

size_t ListManager::size() const {
    std::lock_guard<std::mutex> lk(mtx);
    return data.size();
}

bool ListManager::isFull() const {
    std::lock_guard<std::mutex> lk(mtx);
    return data.size() >= capacity;
}

int ListManager::getLogLevel() const {
    return logLevel;
}

std::shared_ptr<ILogger> ListManager::getLogger() const {
    return logger;
}

