4. Java Service for MD5 Hash Calculation (Implementation)

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MD5HashServiceImpl implements MD5HashService {
    private final ExecutorService executor;

    public MD5HashServiceImpl(int numThreads) {
        this.executor = Executors.newFixedThreadPool(numThreads);
    }

    @Override
    public Map<String, byte[]> calculateMD5Hashes(List<String> inputs) {
        Map<String, byte[]> results = new HashMap<>();
        for (String input : inputs) {
            final String key = input;
            Runnable task = () -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    byte[] hash = md.digest(key.getBytes(StandardCharsets.UTF_8));
                    results.put(key, hash);
                } catch (Exception e) {
                    if (logLevel > 1)
                        logger.log(LogLevel.ERROR, "Error calculating MD5 hash for input: " + key, e);
                }
            };
            executor.execute(task);
        }
        executor.shutdown();
        while (!executor.isTerminated()) {
            try {
                executor.awaitTermination(1, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                if (logLevel > 1)
                    logger.log(LogLevel.ERROR, "Interrupted while waiting for task completion", e);
            }
        }
        return results;
    }
}
