typedef struct {
    char path[4096];
    char filename[256];
    char extension[16];
} Filename;

sem_t semaphore;

void process_filename(Filename* filename) {
    int digit_count = 0;
    int len = strlen(filename->filename);
    for (int i = 0; i < len - strlen(filename->extension); ++i) {
        if (isdigit(filename->filename[i]))
            ++digit_count;
    }

    sprintf(filename->extension, "%d.new%s", digit_count % 2 + 1, filename->extension + strlen(filename->extension));
    // ... other transformations
}

void* worker(void* arg) {
    Dir* dir = (Dir*)arg;
    process_and_transform_filenames(dir->root);
    return NULL;
}

void process_and_transform_filenames(const char* root) {
    DIR* dir = opendir(root);
    struct dirent* entry;
    Filename filename;
    while ((entry = readdir(dir)) != NULL) {
        strcpy(filename.path, root);
        strcat(filename.path, "/");
        strcat(filename.path, entry->d_name);

        // ... extract directory path, filename and extension

        sem_wait(&semaphore);
        process_filename(&filename);
        sem_post(&semaphore);
    }
    closedir(dir);
}

// Initialize semaphore, replace with your own implementation for integration into a larger system
void init_semaphore() {
    sem_init(&semaphore, 0, MAX_THREADS);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [directory]\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    Dir dir = {argv[1], MAX_THREADS};

    init_semaphore();
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, &dir);
    }
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
