typedef struct mem_block {
    size_t capacity;
    size_t used;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct mem_block *next;
} MEM_BLOCK;

struct nfapi_crc_list {
    MEM_BLOCK *head;
    MEM_BLOCK *tail;
    size_t threshold;
    pthread_mutex_t mutex;
    pthread_cond_t notifier;
};

void *mem_pool_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        // handle error condition, such as out-of-memory
    }
    return ptr;
}

void mem_pool_free(void *ptr) {
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T *mem_block_get(MEM_BLOCK *block) {
    NFAPI_CRC_INDICATION_PDU_T *data = block->data;
    if (block->used == block->capacity) {
        // handle the case when the memory pool is empty
    }
    block->used--;
    return data++;
}

void mem_block_put(MEM_BLOCK *block, NFAPI_CRC_INDICATION_PDU_T *data) {
    if (block->capacity == block->used + 1) {
        // handle the case when the memory pool is full
    }
    data->crcflag = true;
    block->data = data;
    block->used++;
}

void *nfapi_crc_list_create(size_t threshold, size_t n) {
    struct nfapi_crc_list *list = mem_pool_alloc(sizeof(struct nfapi_crc_list));
    list->head = NULL;
    list->tail = NULL;
    list->threshold = threshold;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->notifier, NULL);

    MEM_BLOCK *block = mem_pool_alloc(sizeof(MEM_BLOCK));
    block->capacity = n;
    block->used = 0;
    block->data = mem_pool_alloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    list->head = block;
    list->tail = block;

    return list;
}

void nfapi_crc_list_destroy(void *list) {
    MEM_BLOCK *current = (MEM_BLOCK *)list->head;
    while (current != NULL) {
        MEM_BLOCK *next = current->next;
        mem_pool_free(current->data);
        mem_pool_free(current);
        current = next;
    }
    pthread_mutex_destroy(&((struct nfapi_crc_list *)list)->mutex);
    pthread_cond_destroy(&((struct nfapi_crc_list *)list)->notifier);
    mem_pool_free(list);
}

void nfapi_crc_list_resize(void *list, size_t n) {
    // resize the list according to your chosen strategy
}

NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_list_get(void *list) {
    pthread_mutex_lock(&((struct nfapi_crc_list *)list)->mutex);

    if (((struct nfapi_crc_list *)list)->head->used == ((struct nfapi_crc_list *)list)->head->capacity) {
        MEM_BLOCK *new_block = mem_pool_alloc(sizeof(MEM_BLOCK));
        new_block->capacity = n;
        new_block->used = 0;
        new_block->data = mem_pool_alloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        ((struct nfapi_crc_list *)list)->tail->next = new_block;
        ((struct nfapi_crc_list *)list)->tail = new_block;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = mem_block_get(((struct nfapi_crc_list *)list)->head);

    pthread_mutex_unlock(&((struct nfapi_crc_list *)list)->mutex);

    return data;
}

void nfapi_crc_list_put(void *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&((struct nfapi_crc_list *)list)->mutex);

    mem_block_put(((struct nfapi_crc_list *)list)->head, data);

    if (pthread_atomic_load(&((struct nfapi_crc_list *)list)->head->used) >= ((struct nfapi_crc_list *)list)->threshold) {
        pthread_cond_signal(&((struct nfapi_crc_list *)list)->notifier);
    }

    pthread_mutex_unlock(&((struct nfapi_crc_list *)list)->mutex);
}
