[' Here's a C function that fulfills the requirements as stated. I used the `pthread_mutex_t` for synchronizing access to shared variables and `pthread_rwlock_t` for efficient reading and writing when multiple threads are involved. The `CRCFLAG` is generated using `rand()` from the standard C library, seeded differently for each run of the program. The external random number generation library `mrg32k3a` from Mersenne Twister family is used for better performance and predictability.

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <mrg32k3a.h>

// Define the PDU structure and callback function prototype
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*PDU_PROCESSING_CB)(const NFAPI_CRC_INDICATION_PDU_T* pdu);

// Global variables
static unsigned int max_pdus = 100;
static size_t num_pdus = 0;
static size_t requested_pdus = 0;
static NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
static mrg32k3a_state mt;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Function to populate and return a new PDU structure
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        fprintf(stderr, "Failed to allocate memory for PDU\n");
        return NULL;
    }

    mrg32k3a_uint64 seed = time(NULL);
    mrg32k3a_seed_from_time(&mt, seed);
    new_pdu->rnti = num_pdus++;
    new_pdu->crc_indication_rel8_tag.crcflag = (mrg32k3a_uint32) mrg32k3a_genrand_int32(&mt);
    return new_pdu;
}

// Function to handle the requested number of PDU structures
void request_pdus(size_t size) {
    pthread_rwlock_wrlock(&rwlock);
    if (size > max_pdus) {
        fprintf(stderr, "Requested number of PDUs exceeds maximum allowed\n");
