    int UE_ID;
    int NR_UE_CONTEXT;
    struct MeasurementReport* MEASUREMENT_REPORT;
} UEInfo;

struct MeasurementReport {
    int resource[MAX_REPORT];
};

UEInfo* initUEInfoArray(int M, int N, const char* logFile) {
    FILE *log = fopen(logFile, "w");
    if (!log) {
        fprintf(stderr, "Failed to open log file: %s\n", logFile);
        return NULL;
    }

    UEInfo* ueInfos = (UEInfo*)malloc(N * sizeof(UEInfo));
    if (!ueInfos) {
        fprintf(log, "Failed to allocate memory for UEInfo array\n");
        fclose(log);
        return NULL;
    }

    CURL* handle = curl_easy_init();
    if (N > THRESHOLD) {
        size_t apiKeyLen = strlen("YOUR_API_KEY");
        char apiRequest[apiKeyLen + 64]; // assuming API call is ~64 characters
        snprintf(apiRequest, sizeof(apiRequest), "http://external-api.com/init?key=%s", "YOUR_API_KEY");
        curl_easy_setopt(handle, CURLOPT_URL, apiRequest);
        curl_easy_perform(handle);
        if (curl_easy_getinfo(handle, CURLINFO_RESPONSE_CODE) != CURL_OK) {
            fprintf(log, "Failed to fetch context-specific initialization parameters from external API\n");
        } else {
            // Parse the response and configure NR_UE_CONTEXT dynamically based on the parsed data
        }
    }

    for (int i = 0; i < N; ++i) {
        ueInfos[i].UE_ID = i + 1;
        ueInfos[i].NR_UE_CONTEXT = 0; // default value
        ueInfos[i].MEASUREMENT_REPORT = (struct MeasurementReport*)malloc(sizeof(struct MeasurementReport));
        if (!ueInfos[i].MEASUREMENT_REPORT) {
            fprintf(log, "Failed to allocate memory for MeasurementReport in UEInfo %d\n", i);
            return NULL;
        }

        memset(ueInfos[i].MEASUREMENT_REPORT->resource, 0, sizeof(ueInfos[i].MEASUREMENT_REPORT->resource));
    }

    fclose(log);
    return ueInfos;
}
