['Here is a simplified implementation of the requirements in C# using ASP.NET Core Web API, Entity Framework Core, AutoMapper for mapping entities, and StackExchange.Redis for caching. Note that this code does not cover all the intricacies and edge cases you mentioned, but it should give you a good starting point.

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StackExchange.Redis;
using Newtonsoft.Json;
using AutoMapper;

public class ResourceController : ControllerBase
{
    private readonly MyDbContext _context;
    private readonly IDatabase _redisDatabase;
    private readonly IMapper _mapper;
    private readonly IAsyncRepository<Resource> _repository;
    private readonly RateLimiter _rateLimiter;

    public ResourceController(MyDbContext context, IDatabase redisDatabase, IMapper mapper, IAsyncRepository<Resource> repository, RateLimiter rateLimiter)
    {
        _context = context;
        _redisDatabase = redisDatabase;
        _mapper = mapper;
        _repository = repository;
        _rateLimiter = rateLimiter;
    }

    // PUT: api/Resource/{id}
    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, ResourceUpdateDto resourceUpdateDto)
    {
        if (!ModelState.IsValid || !_rateLimiter.AllowRequest())
            return BadRequest(ModelState);

        var cachedResource = await _redisDatabase.GetStringAsync($"resource:{id}");

        if (cachedResource != null)
            return Ok(_mapper.Map<Resource>(JsonConvert.DeserializeObject<dynamic>(cachedResource)));

        var existingResource = await _repository.GetByIdAsync(id);

        if (existingResource == null)
            return NotFound();

        ValidateData(resourceUpdateDto, existingResource.Schema);

        var updatedResource = _mapper.Map<Resource>(resourceUpdateDto);
        updatedResource.Id = id;

        _context.Attach(existingResource).State = EntityState.Detached;
        await _repository.UpdateAsync(updatedResource);
        await _context.SaveChangesAsync();

        // Cache the updated resource for a certain duration (TTL)
        await _redisDatabase.KeyDeleteAsync($"resource:{id}");
        await _redisDatabase.StringSetAsync($"resource:{id}", JsonConvert.SerializeObject(updatedResource), TimeSpan.FromMinutes(5));

        return Ok(_mapper.Map<ResourceDto>(updatedResource));
    }

    // DELETE: api/Resource/{id}
    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        if (!ModelState.IsValid || !_rateLimiter.AllowRequest())
            return BadRequest(ModelState);

        var existingResource = await _repository.GetByIdAsync(id);

        if (existingResource == null)
            return NotFound();

        existingResource.IsDeleted = true;
        existingResource.DeletedAt = DateTime.UtcNow;

        await _context.SaveChangesAsync();

        LoggingService.LogDeleteOperation(id);

        return Ok(new { Id = id, Status = "Deleted" });
    }
}
```

