void init_UEInfos(int M, int timeout_ms, void (*log_func)(const char*, ...), UEInfo** ue_infos, int num_ue_infos) {
    *ue_infos = malloc(num_ue_infos * sizeof(UEInfo));

    sem_init(&context_semaphore, 0, 0);

    for (int i = 0; i < num_ue_infos; ++i) {
        UEInfo* ue = &(*ue_infos)[i];
        ue->UE_ID = i + 1;
        ue->MEASUREMENT_REPORT = malloc(sizeof(struct MeasurementReport));

        // Initialize resource elements based on user-provided parameter M.

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, &fetch_NR_UE_CONTEXT, (void*)ue->UE_ID)) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    clock_t start = clock();
    clock_t now;
    int num_complete = 0;

    while (num_complete < num_ue_infos) {
        sem_wait(&context_semaphore);
        now = clock();
        if ((now - start) > timeout_ms * CLOCKS_PER_SEC / 1000.0) {
            log_func("Timeout reached while waiting for context data.");
            break;
        }
        num_complete += ++num_contexts;
    }

    sem_destroy(&context_semaphore);
}
