        callback_thread = std::make_unique<std::thread>(send_message, message);
        callback_thread->join();
    } catch (const std::exception& e) {
        if (e.code() != std::errc::not_connected) { // Handle other transient errors
            throw;
        }
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Retry after a delay
        callback_thread->reset(); // Reset the thread in case of re-entry
        callback_thread = std::make_unique<std::thread>(send_message, message);
