using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class HttpPostHandler
{
    private readonly ILogger _logger;
    private readonly IPageModelService _pageModelService;
    private readonly IElementUpdateService _elementUpdateService;
    private readonly IAnalyticsService _analyticsService;

    public HttpPostHandler(ILogger<HttpPostHandler> logger,
                            IServiceScopeFactory serviceScopeFactory)
    {
        _logger = logger;
        var scope = serviceScopeFactory.CreateScope();
        _pageModelService = scope.ServiceProvider.GetRequiredService<IPageModelService>();
        _elementUpdateService = scope.ServiceProvider.GetRequiredService<IElementUpdateService>();
        _analyticsService = scope.ServiceProvider.GetRequiredService<IAnalyticsService>();
    }

    public async Task<bool> HandleRequestAsync(string sectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
        {
            _logger.LogError("Invalid request data.");
            return false;
        }

        var pageModel = await _pageModelService.GetPageModelAsync();
        if (pageModel == null || !pageModel.Sections.Any(s => s.Id == sectionId) || !pageModel.Sections.FirstOrDefault(s => s.Id == sectionId).Elements.Any(e => e.Id == elementId))
        {
            _logger.LogError("Specified section or element does not exist.");
            return false;
        }

        var lockToken = $"{sectionId}_{elementId}";
        lock (lockToken)
        {
            if (!pageModel.Sections.FirstOrDefault(s => s.Id == sectionId).Elements.Any(e => e.Id == elementId))
            {
                _logger.LogError("Specified section or element does not exist.");
                return false;
            }

            await _elementUpdateService.UpdateElementAsync(sectionId, elementId, htmlContent);
        }

        await _analyticsService.TrackUpdateAsync(sectionId, elementId, htmlContent);

        return true;
    }
