        } else {
            if (unique_.size() >= 10000) {
                // Max list size reached, remove the least recently used entry.
                unique_.erase(list_.front().first);
                list_.pop_front();
            }

            unique_[pdu->sequence_number] = std::move(pdu);
            list_.push_back({ pdu->sequence_number, std::move(pdu) });
        }
    }

    // Read-heavy function: get the Nth PDU by sequence number.
    const std::unique_ptr<NFAPI_RLC_AM_MSG_PDU_T> get(int n) {
        auto it = list_.lower_bound({ n, nullptr });
        if (it == list_.begin()) return nullptr;

        --it;
        return it->second;
    }

private:
    std::deque<std::pair<int, std::unique_ptr<NFAPI_RLC_AM_MSG_PDU_T>>> list_;
    std::unordered_map<int, std::unique_ptr<NFAPI_RLC_AM_MSG_PDU_T>> unique_;
    std::mutex m_;
};
