extern int max_frames;
extern int log_level;

typedef struct {
    NFAPI_UL_RX_FRAME_INFO_T* frames;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t mutex;
    sem_t not_full; // Semaphore to indicate when space is available for new frame
} dynamic_list;

void init_dynamic_list(dynamic_list* list, int max_frames) {
    list->capacity = max_frames;
    list->current_size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->not_full, 0, list->capacity);
    list->frames = mmap(NULL, sizeof(NFAPI_UL_RX_FRAME_INFO_T) * max_frames, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
}

int push_frame(dynamic_list* list, const NFAPI_UL_RX_FRAME_INFO_T* frame) {
    pthread_mutex_lock(&list->mutex);
    while (list->current_size == list->capacity && sem_trywait(&list->not_full) < 0) {
        pthread_mutex_unlock(&list->mutex);
        if (log_level >= 1) {
            printf("Warning: Dynamic list is full. Dropping frame.\n");
        }
        usleep(10000); // Yield CPU to avoid busy waiting
        pthread_mutex_lock(&list->mutex);
    }
    if (list->current_size < list->capacity) {
        list->frames[list->current_size] = *frame;
        list->frames[list->current_size].TX_STATUS = rand() % 4 + 1; // Set a random TX status between 1 and 4
        ++list->current_size;
        sem_post(&list->not_full); // Signal that space is available for another frame
    }
    pthread_mutex_unlock(&list->mutex);
    return list->current_size - 1; // Return index of the last pushed frame or -1 on failure
}

void free_dynamic_list(dynamic_list* list) {
    munmap(list->frames, sizeof(NFAPI_UL_RX_FRAME_INFO_T) * list->capacity);
    pthread_mutex_destroy(&list->mutex);
    sem_destroy(&list->not_full);
}
