    size_t num_sss;
} NR_DL_BWP_CONFIG_T;

NR_DL_BWP_CONFIG_T* initialize_bandwidth_part_configurations(size_t num_config, size_t max_sss_per_config) {
    if (num_config == 0 || max_sss_per_config == 0) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        return NULL;
    }

    const size_t total_sss = num_config * max_sss_per_config;
    NR_DL_BWP_CONFIG_T* configs = (NR_DL_BWP_CONFIG_T*)malloc(num_config * sizeof(NR_DL_BWP_CONFIG_T));
    if (!configs) {
        fprintf(stderr, "Error: Out of memory.\n");
        return NULL;
    }

    uint64_t* sss = (uint64_t*)malloc(total_sss * sizeof(uint64_t));
    if (!sss) {
        fprintf(stderr, "Error: Out of memory.\n");
        free(configs);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    size_t allocated_sss = 0;
    for (size_t i = 0; i < num_config; ++i) {
        configs[i].num_sss = max_sss_per_config;
        if (allocated_sss + max_sss_per_config > total_sss) {
            fprintf(stderr, "Error: Insufficient memory for the specified number of SSS patterns.\n");
            free(configs);
            free(sss);
            return NULL;
        }

        for (size_t j = 0; j < max_sss_per_config; ++j) {
            while (true) {
                configs[i].sss[j] = rand();
                bool is_unique = true;
                for (size_t k = 0; k < j; ++k) {
                    if (configs[i].sss[j] == configs[i].sss[k]) {
                        is_unique = false;
                        break;
                    }
                }
                for (size_t k = 0; k < i; ++k) {
                    if (configs[i].sss[j] == configs[k].sss[configs[k].num_sss]) {
                        is_unique = false;
                        break;
                    }
                }
                if (is_unique) {
                    break;
                }
            }
            allocated_sss++;
        }
    }

    return configs;
}
