        camera_node = xmlNewChild(config, NULL, BAD_CAST "camera", NULL);
    } else {
        tile_node = xmlHasProp(config, BAD_CAST "tile");
        world_nodes = xmlHasProp(config, BAD_CAST "world");
        camera_node = xmlHasProp(config, BAD_CAST "camera");
    }

    if (xmlStrlen(xmlGetProp(tile_node, BAD_CAST "size")) > 0) {
