        *world_width = atoi(xmlGetProp(world_nodes, BAD_CAST "width"));
    }
    if (xmlHasProp(world_nodes, BAD_CAST "height")) {
        *world_height = atoi(xmlGetProp(world_nodes, BAD_CAST "height"));
    } else {
        fprintf(stderr, "Missing world height\n");
        xmlFreeDoc(doc);
        return -1;
    }

    if (xmlStrlen(xmlGetProp(camera_node, BAD_CAST "speed")) > 0) {
        *camera_speed = atof(xmlGetProp(camera_node, BAD_CAST "speed"));
    } else {
        fprintf(stderr, "Missing camera speed\n");
        xmlFreeDoc(doc);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    size_t num_pdus_allocated = 0;
    for (xmlNodePtr pdu_node = xmlChildNode(world_nodes, world_nodes->properties); pdu_node != NULL; pdu_node = xmlNextNode(pdu_node)) {
        if (xmlStrcmp(pdu_node->name, BAD_CAST "pdu")) continue;

        RX_UE_INFORMATION_TAG rxi = { .rnti = RNTI_UNKNOWN };
        RNTI rnti = xmlStrcmp(xmlGetProp(pdu_node, BAD_CAST "rxi"), BAD_CAST "RNTI_eUTRAN") ? RNTI_NR : RNTI_eUTRAN;
        rxi.rnti = rnti;

        CRC_INDICATION_REL8_TAG crc_indication = { .crcflag = 0 };
        if (rand() % 2) crc_indication.crcflag = 1;

        if (num_pdus_allocated == *num_pdus) {
            num_pdus_allocated *= 2;
            pdu = realloc(pdu, sizeof(*pdu) * num_pdus_allocated);
            if (!pdu) {
                fprintf(stderr, "Failed to allocate memory for PDUs\n");
                xmlFreeDoc(doc);
                return -1;
            }
        }

        pdu[num_pdus++] = (NFAPI_CRC_INDICATION_PDU_T){ .rxi = rxi, .rnti = rnti, .crc_indication = crc_indication };
    }

    *pdus = pdu;
    *num_pdus = num_pdus_allocated;

    xmlFreeDoc(doc);
    return 0;
}
