    list->size = 0;
    pthread_mutex_init(&(list->lock), NULL);
}

NFAPI_CRC_INDICATION_PDU_T* new_node() {
    NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    // Initialize CRCFLAG with a random value
    node->crc_indication.crcFlag = (unsigned char)(rand() % 2);

