    if (list->head == node) {
        list->head = node->next;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != node) {
            current = current->next;
        }
        if (current->next == NULL) return; // Node not found
        current->next = node->next;
    }
    (list->size)--;

    pthread_mutex_unlock(&(list->lock));
    free(node);
}

unsigned int calculate_cumulative_hash(struct list* list) {
    unsigned int hash = 0;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;

    pthread_mutex_lock(&(list->lock));
    while (current != NULL) {
        hash += current->crc_indication.crcFlag;
        current = current->next;
