    NFAPI_CRC_INDICATION_PDU_T* current = list->head;

    pthread_mutex_lock(&(list->lock));
    while (current != NULL) {
        current->crc_indication.crcFlag = hash % 2;
        hash = (hash << 1) ^ hash >> 31; // Rotate left and toggle sign
