    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for pool\n");
        exit(1);
    }

    pool->capacity = BUFFER_SIZE;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* acquire_from_pool(struct pool* pool) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count < pool->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &pool->data[pool->count];
        ++pool->count;
        pthread_mutex_unlock(&pool->mutex);
        return entry;
    }

    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

void release_to_pool(struct pool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count < pool->capacity) {
        memcpy(&pool->data[pool->count], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ++pool->count;
        pthread_mutex_unlock(&pool->mutex);
    }
}

void update_crcflag(NFAPI_CRC_INDICATION_PDU_T* data) {
