        if (entry) {
            update_crcflag(entry);
            // Pass the entry to the external data source for processing
            // ...
            release_to_pool(pool, entry);
        }
    }
}

int main() {
    struct pool pool;
    initialize_pool(&pool);

    pthread_t threads[10];
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        int ret = pthread_create(&threads[i], NULL, &thread_function, &pool);
        if (ret != 0) {
            fprintf(stderr, "Failed to create thread: %s\n", strerror(ret));
