struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

struct list {
    pthread_mutex_t mutex;
    int maxSize, size;
    struct node* head;
};

void initList(struct list*, int);
NFAPI_CRC_INDICATION_PDU_T* getNodeData(struct node*);
void appendNode(struct list*, NFAPI_CRC_INDICATION_PDU_T*);
int getNodeRNTI(struct node*);
void freeList(struct list*);

void initList(struct list* list, int maxSize) {
    if (maxSize <= 0 || !list) return;
    list->maxSize = maxSize;
    list->size = 0;
    pthread_mutex_init(&(list->mutex), NULL);
}

NFAPI_CRC_INDICATION_PDU_T* getNodeData(struct node* node) {
    if (!node) return NULL;
    return &(node->data);
}

void appendNode(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    struct node* newNode = malloc(sizeof(struct node));
    struct node* current = list->head;

    if (!newNode || !data) return;

    newNode->data = *data;
    newNode->next = NULL;

    pthread_mutex_lock(&(list->mutex));
    if (!list->size++) {
        list->head = newNode;
    } else {
        while (current->next) current = current->next;
        current->next = newNode;
    }
    pthread_mutex_unlock(&(list->mutex));
}

int getNodeRNTI(struct node* node) {
    if (!node) return -1;
    return node->data.rnti;
}

void freeList(struct list* list) {
    struct node* current, * temp;

    if (!list) return;

    pthread_mutex_lock(&(list->mutex));
    current = list->head;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&(list->mutex));
}
```

