    semaphore_t sem; // For synchronization when multiple threads access the array simultaneously
};

void initLog(const char *filename) {
    freopen(filename, "w+", stdout);
}

void UEContextInfo_init(UEContextInfo* contextInfo, int ueId, void* servingCellConfig, RadioResourceManagementState state) {
    contextInfo->ueId = ueId;
    contextInfo->servingCellConfig = servingCellConfig;
    contextInfo->state = state;
}

void ContextArray_init(struct ContextArray *array, size_t capacity) {
    array->capacity = capacity;
    array->size = 0;
    array->contexts = malloc(sizeof(UEContextInfo) * capacity);
    if (!array->contexts) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->mutex, NULL);
    sem_init(&array->sem, 0, capacity); // Initial value is the maximum number of concurrent UE contexts
}

void ContextArray_add(struct ContextArray *array, UEContextInfo contextInfo) {
    if (atomic_compare_exchange_weak(&array->size, &counter, counter + 1)) {
        pthread_mutex_lock(&array->mutex);
        if (array->size < array->capacity && atomic_compare_exchange_weak(&array->size, &counter, counter + 1)) {
            array->contexts[array->size - 1] = contextInfo;
        }
        pthread_mutex_unlock(&array->mutex);
    }
}

void ContextArray_remove(struct ContextArray *array, size_t index) {
    if (atomic_compare_exchange_weak(&array->size, &counter, counter - 1)) {
        pthread_mutex_lock(&array->mutex);
        if (index < array->size && atomic_compare_exchange_strong(&array->size, &counter, counter - 1)) {
            array->contexts[index] = {0}; // Clear the memory for garbage collection
        }
        pthread_mutex_unlock(&array->mutex);
    }
}

void ContextArray_updateServingCellConfig(struct ContextArray *array, size_t index, void* newServingCellConfig) {
    if (atomic_compare_exchange_weak(&array->size, &counter, counter)) {
        pthread_mutex_lock(&array->mutex);
        if (index < array->size && atomic_compare_exchange_strong(&array->size, &counter, counter)) {
            if (array->contexts[index].servingCellConfig != newServingCellConfig) { // Check for potential pointer changes
                array->contexts[index].servingCellConfig = newServingCellConfig;
            }
        }
        pthread_mutex_unlock(&array->mutex);
    }
}

void ContextArray_log(struct ContextArray *array) {
    printf("Number of contexts: %zu\n", array->size);
    for (size_t i = 0; i < array->size; ++i) {
        printf("UE ID: %d, ServingCellConfig: %p, State: %d\n", array->contexts[i].ueId, array->contexts[i].servingCellConfig, array->contexts[i].state);
    }
}
