#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
    bool valid_crci;
    pthread_mutex_t lock; // For thread safety
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
unsigned int max_concurrent_sessions = 1000; // Maximum number of active sessions
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER; // For list's thread safety

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    new_node->data = data;
    pthread_mutex_init(&new_node->data.lock, NULL); // Initialize mutex for new node

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* temp = head;
        while (temp->next != NULL && temp->next->data.rnti < data.rnti) {
            temp = temp->next;
        }

        if (temp->next == NULL || temp->data.rnti > data.rnti) {
            new_node->next = head;
            head = new_node;
        } else {
            new_node->next = temp->next;
            temp->next = new_node;
        }
    }

    if (head->data.rnti > max_concurrent_sessions) { // Remove the least recently added UE session when exceeding the limit
        Node* to_remove = head;
        head = head->next;
        free(to_remove);
    }
    pthread_mutex_unlock(&list_lock);
}

void remove(unsigned int rnti) {
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.rnti != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) { // UE session not found, no need to remove anything
        pthread_mutex_unlock(&list_lock);
        return;
    }

    if (previous == NULL) { // Removing the first node in the list
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current); // Free the memory for the removed UE session
    pthread_mutex_unlock(&list_lock);
}
```

This code defines a `NFAPI_CRC_INDICATION_PDU_T` structure and a doubly linked list to store it. The `add()` function adds an element to the list while maintaining thread safety using a mutex. It also ensures that the maximum number of concurrent active UE sessions doesn't exceed the specified limit by removing the least recently added session if needed. The `remove()` function removes an element from the list based on its RNTI. Both functions handle dynamic memory allocation efficiently and include error handling for potential failures during memory operations. To minimize memory fragmentation, we are using a doubly linked list, which allows efficient insertions and deletions while maintaining contiguous blocks of memory. The data structure is appropriate considering the expected frequency of these operations in a network environment.']

