        check_resources(1);

        pthread_mutex_lock(&mutex);
        measurements = realloc(measurements, sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T) * ++num_allocated);
        pthread_mutex_unlock(&mutex);
