    pthread_t threads[MAX_INITIALIZATION_ATTEMPTS];
    int attempts = 0, i;

    measurements = malloc(sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T) * MAX_MEASUREMENTS);

    for (i = 0; i < MAX_INITIALIZATION_ATTEMPTS; ++i) {
        if (pthread_create(&threads[attempts++], NULL, init_measurement, &i)) {
            break;
        }
    }

    for (i = 0; i < attempts; ++i) {
