// Function to generate a unique random number within a given range
unsigned int generate_unique_key(unsigned int min, unsigned int max) {
    static unsigned int unique_numbers[10000] = { 0 };
    static unsigned int count = 0;

    // Find an unused number in the range
    while (1) {
        unsigned int key = (min + rand() % (max - min + 1));
        if (!unique_numbers[key]) {
            unique_numbers[key] = 1;
            count++;
            return key;
        }
    }
}

// Function to validate record array for duplicate keys
int is_valid(Record *records, unsigned int size, unsigned int max) {
    for (unsigned int i = 0; i < size; ++i) {
        for (unsigned int j = i + 1; j < size; ++j) {
            if (records[i].key == records[j].key && i != j) {
                return 0;
            }
        }
    }

    // Ensure the total number of unique keys does not exceed the limit
    if (count >= max) {
        return 0;
    }

    return 1;
}

// Function to initialize record structures based on user input
Record* init_records(unsigned int size, unsigned int max_memory, unsigned int min, unsigned int max, pthread_mutex_t *mutex) {
