#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_RECORDS 10000 // Maximum number of records in the array
#define AVERAGE_WINDOW_SIZE 1000 // Size of SINR average calculation window

typedef struct {
    int TX_POWER_LEVEL;
    double SINR;
    int CHANNEL_QUALITY_INDICATOR;
} LTE_PHY_RX_STATS_T;

struct array_ctx_s {
    LTE_PHY_RX_STATS_T* stats_array;
    size_t current_index; // Current index of the last added record
    double running_average[AVERAGE_WINDOW_SIZE];
    FILE* output_file;
};

void lte_phy_rx_stats_init(struct array_ctx_s* ctx, size_t initial_size) {
    if (initial_size > MAX_RECORDS) {
        fprintf(stderr, "Initial size cannot exceed maximum allowed records.\n");
        return;
    }

    ctx->stats_array = calloc(initial_size, sizeof(LTE_PHY_RX_STATS_T));
    if (!ctx->stats_array) {
        perror("Memory allocation failed.");
        return;
    }

    ctx->current_index = 0;
    ctx->output_file = NULL;

    memset(ctx->running_average, 0, AVERAGE_WINDOW_SIZE * sizeof(double));
}

void lte_phy_rx_stats_reset_avg(struct array_ctx_s* ctx) {
    memset(ctx->running_average, 0, AVERAGE_WINDOW_SIZE * sizeof(double));
}

int lte_phy_rx_stats_add(struct array_ctx_s* ctx, const LTE_PHY_RX_STATS_T* stats) {
    if (ctx->current_index >= MAX_RECORDS) {
        fprintf(stderr, "Array is full. Cannot add more records.\n");
        return -1;
    }

    ctx->stats_array[ctx->current_index] = *stats;

    // Update running average
    if (++ctx->current_index >= AVERAGE_WINDOW_SIZE) {
        ctx->current_index -= AVERAGE_WINDOW_SIZE;
    }

    double sinr = stats->SINR;
    double* avg_ptr = &ctx->running_average[ctx->current_index];
    *avg_ptr += sinr;

    // Save running average every AVERAGE_WINDOW_SIZE iterations
    if (++ctx->current_index >= AVERAGE_WINDOW_SIZE) {
        ctx->current_index -= AVERAGE_WINDOW_SIZE;

        double avg = 0.0;
        for (size_t i = 0; i < AVERAGE_WINDOW_SIZE; ++i) {
            avg += ctx->running_average[i];
        }
        avg /= AVERAGE_WINDOW_SIZE;
        printf("Running SINR average: %.2f\n", avg);
    }

    // Export data to a file if necessary
    if (ctx->output_file && !(ctx->current_index % 1000)) {
        LTE_PHY_RX_STATS_T* stats_ptr = &ctx->stats_array[ctx->current_index - 1000];
        fputs("TX_POWER_LEVEL\t", ctx->output_file);
        fputs("SINR\t\t", ctx->output_file);
        fputs("CHANNEL_QUALITY_INDICATOR\n", ctx->output_file);

        for (size_t i = 0; i < 1000; ++i) {
            fprintf(ctx->output_file, "%d\t%f\t%d\n", stats_ptr[i].TX_POWER_LEVEL, stats_ptr[i].SINR, stats_ptr[i].CHANNEL_QUALITY_INDICATOR);
        }
    }

    return 0;
}

void lte_phy_rx_stats_export(struct array_ctx_s* ctx, const char* output_file) {
    if (ctx->output_file) {
        fprintf(stderr, "File is already open. Close the current file before exporting to a new one.\n");
        return;
    }

    ctx->output_file = fopen(output_file, "w");
    if (!ctx->output_file) {
        perror("Failed to open output file.");
        return;
    }
}
```

This code provides a dynamic array of `LTE_PHY_RX_STATS_T` structures with efficient memory management, a running average of SINR values, and support for exporting the collected statistics to a text file. The function is scalable and handles potential issues such as memory allocation errors and invalid input data. Periodic flushing of data to disk can be achieved by calling `lte_phy_rx_stats_add()` frequently. Error handling is implemented using standard C functions like `perror()`, `fprintf()`, and proper function return values.

To use the code, initialize an instance of the context structure with a specified initial size:

```c
