// Function to initialize and populate the array with UE contexts
void initUEContexts(const std::function<std::shared_ptr<ServingCellConfig>(uint64_t)>& getServingCellConfig) {
    std::atomic_int initialPopulationCount{ 0 };
    const int maxConcurrentThreads = 16; // Adjust this value based on your system's capabilities and desired balance between speed and resource usage

    auto createUEContext = [&](uint64_t uniqueId) {
        auto it = std::find_if(ueContexts.begin(), ueContexts.end(),
                               [uniqueId](const UEContextInfo& context) { return context.ueId == uniqueId; });

        if (it == ueContexts.end()) {
            std::lock_guard<std::mutex> lock(ueContextsMutex);

            // If the UE context doesn't already exist, create a new one with the provided ID and get the ServingCellConfig from the external data source
            if (it == ueContexts.end()) {
                ++initialPopulationCount;
                auto newContext = UEContextInfo{};
                newContext.ueId.store(uniqueId, std::memory_order_relaxed);
                newContext.servingCellConfig = getServingCellConfig(uniqueId); // Retrieve ServingCellConfig from external data source
                radioState defaultRadioState = IDLE; // Set default RadioResourceManagementState value
                newContext.radioState = defaultRadioState;

                ueContexts.push_back(std::move(newContext));
            }
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < maxConcurrentThreads; ++i) {
        threads.emplace_back(createUEContext, i); // Launch a thread to create a UE context for each unique ID up to the maximum number of concurrent threads
