["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct Table {
    Record **table;
    unsigned long capacity;
    unsigned long size;
    pthread_mutex_t mutex;
} Table;

Table* table_create(unsigned long capacity) {
    Table *table = malloc(sizeof(Table));
    if (!table) return NULL;
    table->capacity = capacity;
    table->size = 0;
    table->table = calloc(capacity, sizeof(Record*));
    if (!table->table) {
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

Record* record_create(int key, int value) {
    Record *record = malign(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->value = value;
    record->next = NULL;
    return record;
}

bool table_insert(Table *table, int key, int value) {
    pthread_mutex_lock(&table->mutex);
    if (table->size >= table->capacity) {
        unsigned long new_capacity = table->capacity * 2;
        Record **new_table = realloc(table->table, new_capacity * sizeof(Record*));
        if (!new_table) {
            pthread_mutex_unlock(&table->mutex);
            return false;
        }
        table->table = new_table;
        table->capacity = new_capacity;
    }
    int index = key % table->capacity;
    Record *record = record_create(key, value);
    if (!record) {
        pthread_mutex_unlock(&table->mutex);
        return false;
    }
    Record *head = table->table[index];
    if (head) {
        record->next = head;
        table->table[index] = record;
    } else {
        table->table[index] = record;
    }
    table->size++;
    pthread_mutex_unlock(&table->mutex);
    return true;
}

int table_get(Table *table, int key) {
    Record *record = table_find(table, key);
    if (record) return record->value;
    return -1;
}

Record* table_find(Table *table, int key) {
    pthread_mutex_lock(&table->mutex);
    int index = key % table->capacity;
    Record *current = table->table[index];
    while (current != NULL) {
        if (current->key == key) break;
        current = current->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return current;
}

void table_free(Table *table) {
    for (unsigned long i = 0; i < table->capacity; ++i) {
        Record *current = table->table[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->table);
    free(table);
}
```

This code creates a table structure to manage records with an int value, ensures efficient memory usage, and provides mechanisms for inserting, updating, and retrieving records based on their keys. The table is created using an array of pointers to Records, with each key mapping to its corresponding record through a secondary array.

The function is thread-safe by locking access to the table using a mutex. Memory alignment issues are addressed implicitly when allocating memory for the records and the table's array of pointers.

Key validation is not implemented in this example, but you can add it by validating keys before insertion or retrieval. Additionally, this implementation does not support bulk operations or performance testing; those features would require additional functions and optimizations. Finally, memory is released efficiently when the table is no longer needed using the `table_free()` function."]

