typedef struct {
    time_t timestamp;
    uint64_t session_id;
    double avg_packet_loss_rate; // Stores the average packet loss rate at initialization, updated later as more data is available
    pthread_mutex_t lock; // Protects concurrent access to the structure
    struct PacketLossEvent {
        time_t timestamp;
        double event_percentage; // Percentage of packets lost during this event
        struct PacketLossEvent *next;
    } *packet_loss_list; // A list of packet loss events for each session
} SessionStats;

void init_session(SessionStats **session, uint64_t session_id) {
    *session = malloc(sizeof(SessionStats));
    if (!*session) {
        fprintf(stderr, "Failed to allocate memory for SessionStats structure\n");
        exit(EXIT_FAILURE);
    }

    // Initialize session structure members
    (*session)->timestamp = time(NULL);
    (*session)->session_id = session_id;
    (*session)->avg_packet_loss_rate = 0.0;
    pthread_mutex_init(&(*session)->lock, NULL);
    (*session)->packet_loss_list = NULL;
}

void add_packet_loss(SessionStats *session, time_t timestamp, double event_percentage) {
    // Create a new PacketLossEvent and append it to the list
    SessionStats *current = session;
    while (current->packet_loss_list) {
        current = current->packet_loss_list;
    }

    SessionStats *new_event = malloc(sizeof(SessionStats));
    if (!new_event) {
        fprintf(stderr, "Failed to allocate memory for PacketLossEvent structure\n");
        exit(EXIT_FAILURE);
    }

    new_event->timestamp = timestamp;
    new_event->event_percentage = event_percentage;
    new_event->next = NULL;
    current->packet_loss_list = new_event;
}

void calculate_avg_packet_loss(SessionStats *session) {
    pthread_mutex_lock(&session->lock);

    double total_loss = 0.0;
    SessionStats *current = session->packet_loss_list;
    while (current) {
        total_loss += current->event_percentage;
        current = current->next;
    }

    if (session->packet_loss_list) {
        session->avg_packet_loss_rate = total_loss / session->packet_loss_list->next == NULL ? 1 : session->packet_loss_list->next->timestamp - session->packet_loss_list->timestamp;
    } else {
        session->avg_packet_loss_rate = 0.0;
    }

    pthread_mutex_unlock(&session->lock);
}
```

