#include <string.h>

typedef struct {
    uint32_t rnti;
    uint16_t rx_ue_information_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct hash_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct hash_node* next;
} HASH_NODE;

typedef struct {
    HASH_NODE** table;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HASH_MAP;

HASHMAP hashmap_init(size_t capacity) {
    HASHMAP map = {0};
    map.capacity = capacity;
    map.table = calloc(capacity, sizeof(HASH_NODE*));
    pthread_mutex_init(&map.lock, NULL);
    return map;
}

size_t hash(const void* key) {
    const NFAPI_CRC_INDICATION_PDU_T* k = key;
    uint32_t hv = (k->rx_ue_information_tag ^ k->rnti) * 0x45d9f3b;
    hv %= UINT32_MAX;
    return (size_t)hv;
}

HASH_NODE* hashmap_get(HASHMAP* map, const void* key) {
    size_t index = hash(key);
    HASH_NODE** slot = &map->table[index];
    pthread_mutex_lock(&map->lock);
    for (HASH_NODE* node = *slot; node != NULL; node = node->next) {
        if (memcmp(&node->data, key, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            pthread_mutex_unlock(&map->lock);
            return node;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return NULL;
}

void hashmap_put(HASHMAP* map, const void* key, void* value) {
    HASH_NODE** slot = &map->table[hash(key)];
    size_t i = 0;
    pthread_mutex_lock(&map->lock);
    for (; *slot != NULL; *slot = (*slot)->next, ++i) {
        if (memcmp((*slot)->data.rnti, key->rnti, sizeof(uint32_t)) == 0) {
            memcpy(&(*slot)->data, value, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&map->lock);
            return;
        }
    }
    HASH_NODE* node = malloc(sizeof(HASH_NODE));
    memcpy(&node->data, value, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->next = *slot;
    *slot = node;
    pthread_mutex_unlock(&map->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_indication() {
    NFAPI_CRC_INDICATION_PDU_T* indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    indication->rnti = hashmap_get_unique_rntI();
    indication->rx_ue_information_tag = rand() % 65535;
    indication->crcflag = (indication->rnti * indication->rx_ue_information_tag) & 1;
    return indication;
}

uint32_t hashmap_get_unique_rntI() {
    static uint64_t counter = 0;
    constexpr uint64_t mask = UINT32_MAX | (1ULL << 32);
    counter = ((counter + 1) & mask);
    return (uint32_t)(counter >> 32);
}

