import java.util.*;
import java.lang.reflect.*;
import java.time.Instant;
import java.util.concurrent.ConcurrentSkipListSet;
import java.util.stream.Collectors;

public class DisjointPairs {
    static class UnionFind {
        private final Map<Integer, Integer> parents;
        private final Map<Integer, Integer> sizes;

        public UnionFind(int size) {
            parents = new HashMap<>(size);
            sizes = new HashMap<>(size);
            for (int i = 0; i < size; ++i) {
                parents.put(i, i);
                sizes.put(i, 1);
            }
        }

        public int find(int x) {
            if (parents.get(x) != x) {
                parents.put(x, find(parents.get(x)));
            }
            return parents.get(x);
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (sizes.get(rootX) > sizes.get(rootY)) {
                parents.put(rootY, rootX);
                sizes.put(rootX, sizes.get(rootX) + sizes.get(rootY));
            } else {
                parents.put(rootX, rootY);
                sizes.put(rootY, sizes.get(rootY) + sizes.get(rootX));
            }
        }
    }

    public static String processArray(int[] array, Configuration config) {
        if (array == null || array.length <= 0 || !new HashSet<>(Arrays.asList(array)).size() == array.length
                || config == null || !config.hasKey("threshold")) {
            throw new IllegalArgumentException("Invalid input or configuration.");
        }

        UnionFind uf = new UnionFind(array.length);
        long startTime = Instant.now().toEpochMilli();
        ConcurrentSkipListSet<Pair> pairs = new ConcurrentSkipListSet<>();

        AtomicInteger disjointPairsCount = new AtomicInteger(0);
        Arrays.stream(array)
                .forEach(el -> {
                    int root = uf.find(el);
                    if (!pairs.contains(new Pair(root, el))) {
                        pairs.add(new Pair(root, el));
                        disjointPairsCount.incrementAndGet();
                        uf.union(root, el);
                    }
                });

        long timeTaken = Instant.now().toEpochMilli() - startTime;

        if (disjointPairsCount.get() <= config.getInt("threshold")) {
            return config.getString("input") + "/";
        } else {
            return null;
        }
    }

    private static class Pair implements Comparable<Pair> {
        final int root, value;

        public Pair(int root, int value) {
            this.root = root;
            this.value = value;
        }

        @Override
        public int compareTo(Pair other) {
            return Integer.compare(this.root, other.root);
        }
    }

    private static class Configuration {
        private final Map<String, Object> configMap;

        public Configuration(Object configuration) {
            if (!(configuration instanceof Map)) {
                throw new IllegalArgumentException("Configuration must be a map.");
            }
            this.configMap = (Map<String, Object>) configuration;
        }

        private boolean hasKey(String key) {
            return configMap.containsKey(key);
        }

        public int getInt(String key) {
            if (!hasKey(key)) {
                throw new IllegalArgumentException("Missing key: " + key);
            }
            return (int) configMap.get(key);
        }

        public String getString(String key) {
            if (!hasKey(key)) {
                throw new IllegalArgumentException("Missing key: " + key);
            }
            return (String) configMap.get(key);
        }
    }
}
