#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

// External logging library interface
typedef void (*log_func_t)(const char* msg);

struct pool_entry {
    RNTI rnti;
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int rssi;
    bool crcflag;
};

struct pool {
    struct pool_entry* entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    log_func_t logger;
    double rssi_threshold;
    unsigned int clean_interval; // in seconds
};

void pool_init(struct pool* pool, size_t capacity, log_func_t logger, double rssi_threshold, unsigned int clean_interval) {
    pool->entries = malloc(capacity * sizeof(struct pool_entry));
    if (!pool->entries) {
        fprintf(stderr, "Failed to allocate memory for pool.\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = capacity;
    pool->size = 0;
    pool->logger = logger;
    pool->rssi_threshold = rssi_threshold;
    pool->clean_interval = clean_interval;
    pthread_mutex_init(&pool->lock, NULL);
}

void pool_entry_set_crcflag(struct pool_entry* entry, int rssi) {
    // Implement the specified algorithm for setting CRCFLAG based on RSSI
    entry->crcflag = (rssi > rssi_threshold);
}

bool pool_is_unique_rnti(const struct pool* pool, const struct pool_entry* entry) {
    bool unique = true;
    for (size_t i = 0; i < pool->size && unique; ++i) {
        if (pool->entries[i].rnti == entry->rnti) {
            unique = false;
        }
    }
    return unique;
}

void* populate_pool(void* arg) {
    struct pool* pool = arg;
    for (size_t i = 0; i < pool->capacity && pool->size < 100000; ++i) {
        // Generate RNTI, RX_UE_INFORMATION_TAG, and CRC_INDICATION_REL8_TAG here
        struct pool_entry entry = { .rnti = i, /* generate random or sequential RNTIs */ };
        pthread_mutex_lock(&pool->lock);
        if (pool_is_unique_rnti(pool, &entry)) {
            pool_entry_set_crcflag(&entry, /* calculate RSSI here */ );
            memcpy(&pool->entries[pool->size], &entry, sizeof(struct pool_entry));
            ++pool->size;
        }
        pthread_mutex_unlock(&pool->lock);

        // Simulate some work or delay to mimic data collection
        usleep(1000); // replace with actual delay calculation or work load simulation

        if (pool->logger) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Populated entry %zu with RSSI: %d and CRCFLAG: %d", pool->size - 1, entry.rssi, entry.crcflag);
            pool->logger(log_msg);
        }
    }
    return NULL;
}

void pool_cleanup(struct pool* pool) {
    if (pool->size > 0 && clock() % pool->clean_interval == 0) {
        pthread_mutex_lock(&pool->lock);
        for (size_t i = 0; i < pool->size - 1; ++i) {
            if (pool->entries[i].rnti > pool->entries[i + 1].rnti) {
                struct pool_entry temp = pool->entries[i];
                pool->entries[i] = pool->entries[i + 1];
                pool->entries[i + 1] = temp;
            }
        }
        size_t j = 0;
        for (size_t i = 0; i < pool->size; ++i) {
            if (pool->entries[i].rnti >= pool->rssi_threshold) {
                j++;
                memcpy(&pool->entries[j], &pool->entries[i], sizeof(struct pool_entry));
            }
        }
        pool->size = j;
        pthread_mutex_unlock(&pool->lock);
    }
}
```

This code provides a basic structure for managing a pool of `NFAPI_CRC_INDICATION_PDU_T` structures. The function handles memory allocation, uniqueness validation, and RSSI-based CRCFLAG setting. It also incorporates mechanisms to periodically clean up unused or redundant entries.

