typedef struct {
    int value;
} Record;

// Configuration settings from external file
extern int offset_size;
extern int key_size;
extern int record_size;
extern long memory_threshold;
extern int min_threads;
extern int max_threads;
extern char* data_source;
extern int data_source_range_min;
extern int data_source_range_max;

long total_memory = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;

void* init_record(void* arg) {
    Record* record = (Record*)arg;
    record->value = rand() % (data_source_range_max - data_source_range_min + 1) + data_source_range_min;
    pthread_mutex_lock(&mutex);
    total_memory += sizeof(Record);
    pthread_mutex_unlock(&mutex);
    if (total_memory > memory_threshold) {
        printf("Error: Memory threshold exceeded\n");
        exit(1);
    }
}

void init_arrays(int* offsets, int keys[], Record** records, int size) {
    pthread_t threads[size];
    Record* record_pool = mmap(NULL, size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (!record_pool) {
        perror("Error: Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < size; ++i) {
        keys[i] = i;
        Record* record = &record_pool[i];
        pthread_create(&threads[i], NULL, init_record, record);
    }

    for (int i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }

    *records = record_pool;
    sem_destroy(&semaphore);
}

void reset_arrays(int* offsets, int keys[], Record** records, int size) {
    for (int i = 0; i < size; ++i) {
        Record* record = &(*records)[keys[i]];
        pthread_mutex_lock(&mutex);
        total_memory -= sizeof(Record);
        pthread_mutex_unlock(&mutex);
        record->value = 0;
    }
}

void load_config() {
    // Implement loading the configuration settings from an external file
}

int main(int argc, char** argv) {
    load_config();

    int offsets[offset_size];
    int keys[key_size];
    Record* records = NULL;

    init_arrays(offsets, keys, &records, key_size);

    // Use the initialized arrays

    free(records);
    return 0;
}
