NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu_list(int N, unsigned int seed) {
    if (N <= 0) {
        fprintf(stderr, "Error: Invalid number of PDUs provided.\n");
        return NULL;
    }

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        fprintf(stderr, "Error: Memory allocation failure.\n");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pdu_list[i].ue_tag.ue_id = rand() % UINT16_MAX + 1; // Generates UE IDs between 1 and UINT16_MAX
        pdu_list[i].rnti.value = i+1; // Assigns RNTI based on PDU index (starting from 1)
        pdu_list[i].crc_indication.crcflag = rand() % 2; // Sets CRCFLAG to either 0 or 1 randomly

        // Check for UE ID uniqueness
        bool duplicate = false;
        for (int j = 0; j < i; ++j) {
            if (pdu_list[i].ue_tag.ue_id == pdu_list[j].ue_tag.ue_id) {
                duplicate = true;
                break;
            }
        }

        // Reallocate memory for the list and continue generating PDUs if a duplicate UE ID is found
        if (duplicate) {
            free(pdu_list);
            pdu_list = malloc((N+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu_list) {
                fprintf(stderr, "Error: Memory allocation failure.\n");
                return NULL;
            }
            N++;
            i--;
        }
    }

    return pdu_list;
}
