} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _NFAPI_CRC_INDICATION_MANAGER_T {
    size_t capacity;
    size_t num_instances;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} NFAPI_CRC_INDICATION_MANAGER_T;

NFAPI_CRC_INDICATION_MANAGER_T* nfapi_crc_indication_manager_init(size_t capacity) {
    if (capacity > 10000) {
        fprintf(stderr, "Error: Requested number of instances exceeds the maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_MANAGER_T* manager = malloc(sizeof(NFAPI_CRC_INDICATION_MANAGER_T));
    if (!manager) {
        fprintf(stderr, "Error: Out of memory.\n");
        return NULL;
    }

    manager->capacity = capacity;
    manager->num_instances = 0;
    manager->buffer = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->buffer) {
        fprintf(stderr, "Error: Out of memory.\n");
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->not_full, NULL);
    pthread_cond_init(&manager->not_empty, NULL);

    return manager;
}

int nfapi_crc_indication_manager_enqueue(NFAPI_CRC_INDICATION_MANAGER_T* manager, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&manager->mutex);

    while (manager->num_instances == manager->capacity) {
        pthread_cond_wait(&manager->not_full, &manager->mutex);
    }

    memcpy(&manager->buffer[manager->num_instances], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->num_instances++;

    if (pthread_cond_signal(&manager->not_empty) != 0) {
        perror("Error: pthread_cond_signal");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_manager_dequeue(NFAPI_CRC_INDICATION_MANAGER_T* manager) {
    pthread_mutex_lock(&manager->mutex);

    while (manager->num_instances == 0) {
        pthread_cond_wait(&manager->not_empty, &manager->mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* item = &manager->buffer[manager->num_instances - 1];
    manager->num_instances--;

    if (pthread_cond_signal(&manager->not_full) != 0) {
        perror("Error: pthread_cond_signal");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    pthread_mutex_unlock(&manager->mutex);
    return item;
}

void nfapi_crc_indication_manager_destroy(NFAPI_CRC_INDICATION_MANAGER_T* manager) {
    if (!manager) {
        return;
    }

    free(manager->buffer);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->not_full);
    pthread_cond_destroy(&manager->not_empty);
    free(manager);
}
```

