#include <functional>
#include <new>

class SMC {
public:
    int imsi;
    std::string guti;
    std::vector<Pdu> pdus;
    std::mutex mtx;

    SMC(int imsi, const std::string& guti) : imsi(imsi), guti(guti) {}
};

class Pdu {
public:
    unsigned int qos_class_id;
    std::string pdn_type;
    uint32_t tid;

    Pdu(unsigned int qos_class_id, const std::string& pdn_type, uint32_t tid)
        : qos_class_id(qos_class_id), pdn_type(pdn_type), tid(tid) {}
};

class SessionManagementContext {
private:
    std::vector<std::unique_ptr<SMC>> smcs;
    std::mutex smc_mtx;

public:
    void initialize() {
        // Fetch current network status and UE mobility information from the external data source.
        // Populate SMCs with PDUs based on the fetched data.
    }

    void addPdu(int imsi, const std::string& guti, const Pdu& pdu) {
        std::unique_lock<std::mutex> lock(smc_mtx);

        for (auto& smc : smcs) {
            if (smc->imsi == imsi && smc->guti == guti) {
                smc->pdus.push_back(pdu);
                break;
            }
        }

        if (smcs.empty()) {
            // Create a new SMC if none exists for the given IMSI and GUTI.
            smcs.emplace_back(std::make_unique<SMC>(imsi, guti));
            smcs.back()->pdus.push_back(pdu);
        }
    }

    void cleanUp() {
        std::unique_lock<std::mutex> lock(smc_mtx);

        auto it = smcs.begin();
        while (it != smcs.end()) {
            if (it->pdus.empty()) {
                it = smcs.erase(it);
            } else {
                ++it;
            }
        }
    }
};
```

