} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _LIST_MANAGER {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    pthread_mutex_t mutex;
    time_t garbage_collection_interval; // Time interval for garbage collection in seconds
} LIST_MANAGER;

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
