    new_node->rx_ue_information_tag = rx_ue_information_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;
    return new_node;
}

LIST_MANAGER* create_list_manager(time_t garbage_collection_interval) {
    LIST_MANAGER *manager = (LIST_MANAGER*)malloc(sizeof(LIST_MANAGER));
    manager->head = NULL;
    manager->tail = NULL;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->garbage_collection_interval = garbage_collection_interval;
    return manager;
}

void add_to_list(LIST_MANAGER* manager, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&manager->mutex);
    if (!manager->head) {
        manager->head = node;
        manager->tail = node;
    } else {
        manager->tail->next = node;
        manager->tail = node;
    }
    ++manager->size;
    pthread_mutex_unlock(&manager->mutex);
}

void garbage_collection(LIST_MANAGER* manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = manager->head;
    while (current != NULL) {
        if (difftime(current_time, current->timestamp) > manager->garbage_collection_interval) {
            NFAPI_CRC_INDICATION_PDU_T* temp = current;
            current = current->next;
            free(temp);
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}
