NFAPI_CRC_INDICATION_PDU_T* populateCRCIndications(uint32_t* pUi32RxUEInformationTagArray, uint32_t ui32Size) {
    if (!pUi32RxUEInformationTagArray || !ui32Size)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pCrcIndicationPdu = NULL;
    uint32_t requiredMemorySize = ui32Size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Seed random number generator with current time to avoid global state conflicts.
    unsigned seed = std::chrono::system_clock::now().time_since_epoch().count();
    srand(seed);

    pCrcIndicationPdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(requiredMemorySize);

    if (!pCrcIndicationPdu) {
        free(pCrcIndicationPdu);
        return NULL;
