using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Text;
using Microsoft.Extensions.Logging;

public class WebSiteManager
{
    private readonly ILogger<WebSiteManager> _logger;
    private const int DefaultMaxConcurrency = 5;
    private const int TimeoutMilliseconds = 60_000; // 1 minute timeout

    public WebSiteManager(ILogger<WebSiteManager> logger)
    {
        _logger = logger;
    }

    public IEnumerable<string> ManageWebsiteLifecycle(string directoryPath, string siteName, bool isDebugMode, int maxConcurrency = DefaultMaxConcurrency)
    {
        // Validate directoryPath and throw exception if invalid
        if (directoryPath.Contains(".."))
            throw new ArgumentException($"Invalid path: '{directoryPath}' contains relative path traversal sequences.");

        var validChars = Path.GetInvalidPathChars().ToHashSet();
        foreach (var c in directoryPath)
        {
            if (validChars.Contains(c))
                throw new ArgumentException($"Invalid character found in '{directoryPath}'");
        }

        var webConfigFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFilePath))
            yield break;

        var operationsLog = new List<string>();
        var semaphoreSlim = new SemaphoreSlim(maxConcurrency);

        Action manageSite = () =>
        {
            try
            {
                _logger.LogInformation($"Starting site '{siteName}'...");
                Process process = new Process();
                process.StartInfo.FileName = "dotnet";
                process.StartInfo.Arguments = $"run --project '{webConfigFilePath.Replace("\\", "/")}'";
                if (isDebugMode)
                    process.StartInfo.Arguments += " --launch-profile=debug";
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;
                process.Start();

                var outputReader = new StreamReader(process.StandardOutput);
                var errorReader = new StreamReader(process.StandardError);

                string line;
                while ((line = outputReader.ReadLine()) != null)
                {
                    _logger.LogInformation($"Site '{siteName}': {line}");
                }

                string error;
                while ((error = errorReader.ReadLine()) != null)
                {
                    _logger.LogError($"Site '{siteName}': {error}");
                }

                process.WaitForExit(TimeoutMilliseconds);
                if (process.ExitCode > 0)
                    operationsLog.Add($"Failed: Site '{siteName}' exited with code {process.ExitCode}");
                else
                    operationsLog.Add($"Success: Site '{siteName}' started successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"An error occurred while starting site '{siteName}'.");
                operationsLog.Add($"Failed: An error occurred while starting site '{siteName}': {ex.Message}");
            }
        };

        semaphoreSlim.Wait();
        try
        {
            manageSite();
        }
        finally
        {
            semaphoreSlim.Release();
        }

        yield return $"Started: Total operations performed on '{siteName}'.";

        foreach (var operation in operationsLog)
            yield return operation;
    }
}
