struct memory_pool {
    Node **head;
    unsigned int capacity;
    unsigned int size;
};

void* mem_alloc(struct memory_pool *pool) {
    if (pool->size >= pool->capacity) return NULL;
    void *ptr = pool->head[pool->size++];
    return ptr;
}

void mem_free(struct memory_pool *pool, void *mem) {
    pool->size--;
    pool->head[pool->size] = mem;
}

Node* create_node(NR_DL_BWP_CONFIG_T config, NFAPI_CRC_INDICATION_PDU_T crcIndication) {
    Node *new_node = (Node*)mem_alloc(&config.memory_pool);
    if (!new_node) return NULL;

    new_node->data = config;
    new_node->crcIndication = crcIndication;
    new_node->next = NULL;

    return new_node;
}

void destroy_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
}

