typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

struct list {
    int capacity;
    Node **elements;
    int count;
    pthread_mutex_t lock;
};

void* init_list(int capacity) {
    struct list *list = mmap(NULL, sizeof(struct list), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!list) return NULL;

    list->capacity = capacity;
    list->elements = calloc(capacity, sizeof(Node*));
    if (!list->elements) goto error;

    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;

error:
    free(list->elements);
    munmap(list, sizeof(struct list));
    return NULL;
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = *data;
    node->next = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

