    if (!is_valid_rnti(data->rnti)) {
        printf("Invalid RNTI: %u\n", data->rnti);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    int index = data->tag % list->capacity;
    Node **head = &list->elements[index];
    Node **node = head;

    while (*node != NULL && (**node).rnti == data->rnti) {
        node = &(*node)->next;
    }

    if (*node != NULL) {
        printf("Duplicate RX_UE_INFORMATION_TAG: %d\n", data->tag);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *node = create_node(data);
    if (!*node) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    (*node)->next = *head;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

