        // Parse the RX_UE_INFORMATION_TAG and RNTI fields from the line using sscanf()
        sscanf(line, "%x %x", &pdu->rxUeInformationTag, &pdu->rnti);

        // Set CRCFLAG randomly
        pdu->crcIndicationRel8Tag.crcFlag = rand() % 2;

        NFAPI_CRC_INDICATION_PDU_T **pdus = realloc(count == 0 ? NULL : *count, (lineCount + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!pdus) {
            fprintf(stderr, "Error: Out of memory\n");
            free(pdu);
            fclose(file);
            return 0;
        }

        *count = lineCount;
        pdus[lineCount - 1] = pdu;
    }

    fclose(file);
    return *count;
}
