    CHECK_INVALID_FD = 1,
    CHECK_CONFIG_MISSING = 2,
    CHECK_CONFIG_INVALID = 3,
    CHECK_NOTIFICATION_FAILED = 4,
    CHECK_DEPENDENCY_FAILURE = 5,
    CHECK_RACE_CONDITION = 6,
};

int initialize_resource(Resource *res, const char *file, const json_object *config, void (*notify)(void*, const char*)) {
    res->fd = open(file, O_RDWR);
    if (res->fd < 0) {
        err(1, "Failed to open file '%s'", file);
        return CHECK_INVALID_FD;
    }

    struct stat st;
    if (fstat(res->fd, &st) < 0) {
        close(res->fd);
        err(1, "Failed to fstat file '%s'", file);
        return CHECK_RACE_CONDITION;
    }

    res->config = json_object_get(config, "configuration");
    if (!res->config) {
        close(res->fd);
        err(1, "Missing 'configuration' field in configuration object.");
        return CHECK_CONFIG_MISSING;
    }

    json_object *config_fields = json_object_get(config, "fields");
    if (!config_fields) {
        close(res->fd);
        err(1, "Missing 'fields' field in configuration object.");
        return CHECK_CONFIG_MISSING;
    }

    json_object *field;
    bool valid = true;
    gpointer config_iter;
    json_object_foreach (field, iter) {
        const char *name = json_object_get_string(json_object_get(field, "name"));
        if (!name || !json_object_get_int(field, "min")) {
            valid = false;
            break;
        }
    }

    if (!valid) {
        close(res->fd);
        errx(1, "Invalid configuration object.");
        return CHECK_CONFIG_INVALID;
    }

    res->notify = notify;
    pthread_mutex_init(&res->mutex, NULL);

    // Dependency check and handling here

    if (pthread_mutex_trylock(&res->mutex) != 0) {
        close(res->fd);
        err(1, "Failed to acquire mutex for resource.");
        return CHECK_RACE_CONDITION;
    }

    if (res->notify && pthread_cond_broadcast(&res->mutex) != 0) {
        close(res->fd);
        err(1, "Failed to broadcast on notification channel.");
        return CHECK_NOTIFICATION_FAILED;
    }

    pthread_mutex_unlock(&res->mutex);

    return CHECK_SUCCESS;
}
