namespace ManageNfapiCrcIndications
{
    public class NFAPI_CRC_INDICATION_PDU_T
    {
        public UInt32 RX_UE_INFORMATION_TAG { get; set; }
        public uint RNTI { get; set; }
        public uint CRC_INDICATION_REL8_TAG { get; set; }
        public bool CRCFLAG { get; set; }
    }

    public static class ManageNfapiCrcIndications
    {
        private const string DirPathKey = "CRC_DIR_PATH";
        private const string LogsDirPath = "/opt/nfapi/logs";
        private static readonly object LockObject = new Object();
        private static DirectoryInfo _dir;
        private static FileStream _logFile;

        public static void ManageNfapiCrcIndications(List<NFAPI_CRC_INDICATION_PDU_T> structures)
        {
            var dirPath = GetDirectoryPath();
            Directory.CreateDirectory(dirPath);

            WriteLog("Created directory: " + dirPath);

            SaveStructuresToFile(structures, dirPath + "/indications.dat");
        }

        private static string GetDirectoryPath()
        {
            var path = Environment.GetEnvironmentVariable(DirPathKey);
            return string.IsNullOrEmpty(path) ? CreateTimestampedDirectoryInNfapi() : path;
        }

        private static DirectoryInfo CreateTimestampedDirectoryInNfapi()
        {
            var timestamp = DateTime.Now.Ticks.ToString();
            var dirPath = $"/opt/nfapi/{timestamp}";
            Directory.CreateDirectory(dirPath);
            SetPermissionsRecursively(dirPath);
            return new DirectoryInfo(dirPath);
        }

        private static void SetPermissionsRecursively(string path)
        {
            var files = Directory.GetFiles(path, "*", SearchOption.AllDirectories);
            var directories = Directory.GetDirectories(path);

            foreach (var file in files) File.SetAccessControl(file, new System.Security.AccessControl.FileSecurity { Owner = new System.Security.Principal.NTAccount("nfapi") });
            foreach (var directory in directories) Directory.SetAccessControl(directory, new System.Security.AccessControl.DirectorySecurity { Owner = new System.Security.Principal.NTAccount("nfapi") });
        }

        private static void WriteLog(string message)
        {
            lock (LockObject)
            {
                if (_logFile == null || !_logFile.IsOpen)
                {
                    _logFile = File.CreateText(LogsDirPath + "/logs.txt");
                }

                _logFile.WriteLine(message);
            }
        }

        private static void SaveStructuresToFile(List<NFAPI_CRC_INDICATION_PDU_T> structures, string filePath)
        {
            using (var fileStream = File.CreateText(filePath))
            {
                foreach (var structure in structures)
                {
                    var line = string.Join(" ", structure.RX_UE_INFORMATION_TAG, structure.RNTI, structure.CRC_INDICATION_REL8_TAG, structure.CRCFLAG);
                    fileStream.WriteLine(line);
                }
            }
        }

        public static string MD5Hash(string input)
        {
            using (var md5 = MD5.Create())
            {
                var bytes = Encoding.ASCII.GetBytes(input);
                return BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-", "").ToLowerInvariant();
            }
        }
    }
}
