['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct Record {
    int key;
    long offset;
    char metadata[256];
} Record;

struct MemoryPool {
    Record* data;
    size_t capacity;
    size_t count;
    size_t freeListHead;
    pthread_mutex_t mutex;
    sem_t sem_pool, sem_freeList;
};

Record* mempool_alloc(struct MemoryPool* m) {
    if (m->freeListHead != -1) {
        size_t freeListTail = (m->freeListHead + 1) % m->capacity;
        m->freeListHead = freeListTail;
        return &m->data[freeListTail];
    }

    if (m->count == m->capacity) {
        size_t newCapacity = m->capacity * 2;
        Record* newData = realloc(m->data, sizeof(Record) * newCapacity);
        if (!newData) return NULL;
        m->data = newData;
        m->capacity = newCapacity;
    }

    return &m->data[m->count++];
}

void mempool_free(struct MemoryPool* m, Record* record) {
    pthread_mutex_lock(&m->mutex);
    record->key = -1; // Mark record as unused
    m->freeListHead = (m->freeListHead + 1) % m->capacity;
    sem_post(&m->sem_pool);
    pthread_mutex_unlock(&m->mutex);
}

void* mempool_init(size_t initialCapacity) {
    struct MemoryPool* m = calloc(1, sizeof(struct MemoryPool));
    if (!m) return NULL;

    m->data = calloc(initialCapacity, sizeof(Record));
    if (!m->data) goto cleanup;
    m->capacity = initialCapacity;
    m->count = 0;
    m->freeListHead = -1; // All records are initially in use

    pthread_mutex_init(&m->mutex, NULL);
    sem_init(&m->sem_pool, 0, initialCapacity);
    sem_init(&m->sem_freeList, 0, 0);

    return m;

cleanup:
    free(m);
    return NULL;
}

// Usage example in a thread function:
void* threadFunc(void* arg) {
    struct MemoryPool* m = arg;
    Record* record = mempool_alloc(m);
    if (!record) return NULL;

    // Fill the record...

    mempool_free(m, record);
    return NULL;
}
```

This code provides a basic memory pool implementation for managing a dynamic collection of records in a shared memory region. The `mempool_init()` function initializes the data structure with the specified initial capacity and creates semaphores to synchronize access between multiple threads. The `mempool_alloc()` function is responsible for allocating new records or reusing freed ones, while `mempool_free()` marks a record as unused and signals the availability of that record.

The example provided demonstrates how to use this memory pool in a simple concurrent context with thread functions. Keep in mind that you may need to implement additional mechanisms for cleaning up unused records periodically, monitoring resource usage, and enforcing predefined limits on resource consumption based on your specific requirements.']

