import os
import hashlib
from tqdm import tqdm

def compute_md5(file_path):
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        raise FileNotFoundError(f"File '{file_path}' does not exist or is not a file.")

    block_size = 65536
    md5 = hashlib.md5()

    with open(file_path, "rb") as f:
        for data in tqdm(iterable=iter(lambda: f.read(block_size), ''), total=os.path.getsize(file_path) // block_size + 1, unit="blocks", desc=f"Computing MD5 of '{file_path}'"):
            md5.update(data)

    os.environ["FILE_MD5"] = md5.hexdigest()

