NFAPI_CRC_INDICATION_PDU_T* get_from_mem_pool() {
    MemPoolNode *temp, *prev;
    pthread_mutex_lock(&mem_pool_mutex);
    temp = head;
    prev = NULL;

    while (temp != NULL) {
        if (temp->data == NULL) {
            if (prev != NULL)
                prev->next = temp->next;
            else
                head = temp->next;

            pthread_mutex_unlock(&mem_pool_mutex);
            return temp->data;
        }
        prev = temp;
        temp = temp->next;
    }

    pthread_mutex_unlock(&mem_pool_mutex);
    return NULL;
}

void free_to_mem_pool(NFAPI_CRC_INDICATION_PDU_T *data) {
    if (head == NULL) {
        head = malloc(sizeof(MemPoolNode));
        head->data = data;
        head->next = NULL;
    } else {
        pthread_mutex_lock(&mem_pool_mutex);
        MemPoolNode *temp = head;

        while (temp->next != NULL)
            temp = temp->next;

        temp->next = malloc(sizeof(MemPoolNode));
        temp->next->data = data;
        temp->next->next = NULL;
        pthread_mutex_unlock(&mem_pool_mutex);
    }
}

