fn register_function<T>(name: &str, f: Box<Fn(&String) -> Result<Vec<T>>>) {
    match FUNCTIONS.insert(name.to_string(), f) {
        Some(_) => panic!("Function '{}' already registered.", name),
        None => (),
    }
}

lazy_static! {
    static ref FUNCTIONS: HashMap<String, Box<Fn(&String) -> Result<Vec<T>>> = HashMap::<String, Box<Fn(&String) -> Result<Vec<T>>>::new();
}

#[derive(Debug)]
struct ElementData<T> {
    name: String,
    attributes: HashMap<String, String>,
    data: Vec<T>,
}

fn process_element<T>(
    reader: &mut EventReader<Box<dyn std::io::Read>>,
    namespace: Namespace,
    start_tag: xmlparser::StartTag,
) -> Result<Option<ElementData<T>>> {
    let name = match start_tag.local_name.as_ref() {
        Some(n) => n,
        None => return Ok(None),
    };

    let mut attributes: HashMap<String, String> = HashMap::<String, String>::new();
    for attr in &start_tag.attributes {
        match attr.name.as_ref() {
            Some(k) => {
                if let Some(v) = attr.value {
                    attributes.insert(k.to_string(), v.to_string());
                }
            }
            None => (),
        }
    }

    let mut data: Vec<T> = Vec::<T>::new();
    let mut is_empty = true;
    let mut inner_parser = EventReader::new(reader.clone());
    loop {
        match inner_parser.read_event().await? {
            xmlparser::Event::StartTag(_) | xmlparser::Event::EndTag(_) => (),
            xmlparser::Event::Text(text) => data.push(parse_text::<T>(text)?),
            Event::Characters(characters) => data.append(&mut characters.chars().map(|c| c as T).collect()),
            Event::Comment(_) | Event::Cdata(_) => (),
            Event::Error(e) => return Err(AppError::XmlParse(e)),
        }

        if let Some(text) = inner_parser.read_text().await? {
            if !text.is_empty() {
                is_empty = false;
            } else {
                break;
            }
        }
    }

    if is_emtpy && data.is_empty() {
        return Ok(None);
    }

    Ok(Some(ElementData { name: name.to_string(), attributes, data }))
}

fn parse_text<T>(text: &str) -> Result<Vec<T>> {
    match text.parse::<Vec<T>>() {
        Ok(v) => Ok(v),
        Err(_) => Err(AppError::XmlParse(xmlparser::Error::new(
            xmlparser::ErrorKind::InvalidContent,
            format!("Failed to parse text '{}' as desired data type.", text),
        ))),
    }
}

fn print_results<T>(elements: &[ElementData<T>], filter: &HashMap<String, String>) {
    let mut matched_elements = Vec::<&ElementData<T>>::new();
    for e in elements {
        if matches_filter(e, filter) {
            matched_elements.push(e);
        }
    }

    for e in &matched_elements {
        println!("Name: {}", e.name);
        for (k, v) in &e.attributes {
            println!("Attribute {}: {}", k, v);
        }

        for d in &e.data {
            println!("Data: {:?}", d);
        }
    }
}

fn matches_filter<T>(element: &ElementData<T>, filter: &HashMap<String, String>) -> bool {
    if let Some(name) = filter.get("name") {
        element.name == *name
    } else {
        true
    } && element.attributes.iter().all(|(k, v)| {
            if let Some(val) = filter.get(k) {
                v == val
            } else {
                true
            }
        })
}

