Node* create_node(void) {
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) return NULL;
    new_node->data.timestamp = time(NULL);
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = NULL;
    return new_node;
}

void append_node(Node **head_ref, Node* new_node) {
    Node *current = *head_ref;
    if (current == NULL) {
        *head_ref = new_node;
        return;
    }

    while (current->next != NULL) current = current->next;
    current->next = new_node;
    new_node->prev = current;
}

void update_timestamps(Node *head, double load) {
    pthread_mutex_t lock;
    Node* current = head;

    // Adjust the update frequency based on network load and other factors
    usleep(load * 1000000);

    while (current != NULL) {
        pthread_mutex_lock(&current->lock);
        current->data.timestamp = time(NULL);
        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }
}

