    if (list_size >= max_list_size) {
        printf("Error: List is full\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    Node* current = head;
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        return;
