#include <stdio.h>
#include <string.h>
#include <ctype.h>

char* rename_file(const char *filename, int num_digits, const char *filetype) {
    // Extract the base name and extension from the original filename
    size_t len = strlen(filename);
    char *base = malloc(len);
    char *ext = malloc(len + 1);
    strncpy(base, filename, len);
    base[len - 1] = '\0'; // Null-terminate the base name
    strcpy(ext, filename + (strlen(filename) - 4)); // Assume .ext format

    // Determine number of digits and filetype
    int num_chars = strlen(ext);
    if (num_chars > 4) {
        free(base);
        free(ext);
        return filename; // No need to rename the file
    }
    for (int i = 0; i < num_chars && isdigit(ext[i]); ++i);
    num_digits = num_chars - i;
    if (num_digits == 0) {
        num_digits = 3; // Default to three digits
    }
    char *filetype_ptr = ext + i;
    strncpy(ext, filetype, strlen(filetype));
    ext[strlen(filetype)] = '\0';

    // Create the new filename using sprintf and strcat
    int base_len = strlen(base);
    char *new_filename = malloc(base_len + num_digits + 2 + strlen(ext));
    sprintf(new_filename, "%s%0*d.%s", base, num_digits, getpid(), ext);

    return new_filename;
}
