    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint32_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void init_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->rx_ue_information_tag = 0xDEADBEEF;
    pdu->rnti = 0xBADCAFE;
    pdu->crc_indication_rel8_tag = 0xC0FFEE;
    pdu->crcflag = rand();
}

void* dynamic_list_of_crcs(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < size; ++i) {
        init_crc_pdu(list + i);
    }

    void* result = malloc(sizeof(struct dynamic_list));
    if (!result) goto cleanup;

    struct dynamic_list* dl = result;
    dl->list = list;
    dl->size = size;
    dl->lock = lock;

cleanup:
    if (list && result) pthread_mutex_destroy(&dl->lock);
    free(list);
    free(result);

    return result;
}

void dynamic_list_add(struct dynamic_list* list, size_t index) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = list->size; i <= index; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdus = list->list + i;
        list->list = realloc(pdus, (index - i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->list) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        init_crc_pdu(pdus);
    }

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_remove(struct dynamic_list* list, size_t index) {
    if (index >= list->size) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = index; i < list->size - 1; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdus = list->list + i;
        list->list[i] = list->list[i+1];
    }

    pthread_mutex_unlock(&list->lock);

    free(list->list + list->size - 1);
    list->size--;
}
```

