int main(int argc, char **argv) {
    int c;
    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"manpage", no_argument, 0, 'm'},
        {"char-count", no_argument, 0, 'c'},
        {"word-length", no_argument, 0, 'w'},
        {"output", required_argument, 0, 'o'},
        {"log-level", required_argument, 0, 'l'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "h?m::cwo:l:", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                usage();
                return 0;
            case 'm':
                manpage();
                return 0;
            case 'c':
                break; // No action needed for -c flag, we'll count characters later.
            case 'w':
                break; // Same as -c, will calculate average word length later.
            case 'o':
                output_file = optarg;
                break;
            case 'l':
                log_level = strcmp(optarg, "debug") == 0 ? DEBUG :
                           strcmp(optarg, "info") == 0 ? INFO :
                           strcmp(optarg, "warning") == 0 ? WARNING :
                           strcmp(optarg, "error") == 0 ? ERROR : CRITICAL;
                openlog("text_processor", LOG_PID | log_level, LOG_USER);
                break;
            default:
                handle_logging(ERROR, "Invalid command line argument.");
                usage();
                return -1;
        }
    }

    // Check for mandatory input file
    if (!input_file) {
        handle_logging(ERROR, "No input file specified.");
        usage();
        return -1;
    }

    FILE *input = fopen(input_file, "r");
    if (!input) {
        perror("Error opening input file");
        handle_logging(ERROR, "Could not open the input file.");
        return -1;
    }

    pthread_t threads[thread_count];

    // Read lines from input file and pass them to worker threads for processing.
    char buffer[4096];
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(char), sizeof(buffer), input)) > 0) {
        struct LineData lines[bytes_read / sizeof(struct LineData) + 1];
        for (size_t i = 0; i < bytes_read / sizeof(lines[0]); ++i) {
            lines[i].line = &buffer[i * sizeof(struct LineData)];
            lines[i].line_length = strlen(&buffer[i * sizeof(struct LineData)]);
        }
        lines[bytes_read / sizeof(struct LineData)].line = NULL;

        #pragma omp parallel for num_threads(thread_count)
        for (size_t i = 0; i < bytes_read / sizeof(struct LineData); ++i) {
            pthread_create(&threads[i], NULL, process_line, &lines[i]);
        }

        // Wait for worker threads to finish their tasks.
        for (size_t i = 0; i < bytes_read / sizeof(struct LineData); ++i) {
            pthread_join(threads[i], NULL);
        }
    }

    if (ferror(input)) {
        perror("Error reading input file");
        handle_logging(ERROR, "Could not read the input file.");
        return -1;
    }

    if (fclose(input) != 0) {
        perror("Error closing input file");
        handle_logging(ERROR, "Could not close the input file.");
        return -1;
    }

    if (output_file && freopen(output_file, "w", stdout) == NULL) {
        perror("Error redirecting output to a file");
        handle_logging(ERROR, "Failed to redirect output to the specified file.");
        return -1;
    }

    // Output the required statistics.
    printf("%ld\n", char_count);
    if (avg_word_length > 0)
        printf("%.2f\n", avg_word_length);

    endlog();
    return 0;
}

// Implementation of the functions mentioned in the task description.
void process_line(const struct LineData *data) {
    pthread_mutex_lock(&char_count_lock);
    char_count += data->line_length;
    word_count++;
    avg_word_length = (avg_word_length * word_count + count_words(data->line)) / (word_count + 1.0);
    pthread_mutex_unlock(&char_count_lock);
}

int count_words(const char *str) {
    int count = 0;
    for (size_t i = 0; i < strlen(str); ++i) {
        if (isspace(str[i])) {
            count++;
        }
    }
    return count + 1;
}

void handle_logging(enum LogLevel level, const char *message) {
    switch (log_level) {
        case DEBUG:
            syslog(LOG_DEBUG, "%s", message);
            break;
        case INFO:
            syslog(LOG_INFO, "%s", message);
            break;
        case WARNING:
            syslog(LOG_WARNING, "%s", message);
            break;
        case ERROR:
            syslog(LOG_ERR, "%s", message);
            break;
    }
}

void usage() {
    fprintf(stderr, "text_processor [OPTION]... FILE\n");
    exit(EXIT_FAILURE);
}

void endlog() {
    endlog();
}

int main(int argc, char **argv) {
    // Call the actual text_processor function.
    return text_processor(argc, argv);
}']

