// Max length for the new filename after extension change
#define MAX_EXTENSION_LEN 4
#define MAX_NEW_FILENAME_LEN (128 - MAX_EXTENSION_LEN)

char* generate_new_filename(const char *original) {
    // Trim to 20 characters, handle edge cases of empty or excessively long filenames
    size_t len = strlen(original);
    if (len > 20) len = 20;

    // Isolate last dot and its subsequent characters as the file extension
    const char *dot = memchr(original, '.', len);
    if (!dot || (dot + MAX_EXTENSION_LEN >= original + len)) {
        // No dot or dot too close to beginning, set default extension .bin
        strlcpy(const char *new_filename, original, sizeof(new_filename));
        strcat(new_filename, ".bin");
    } else {
        size_t ext_len = 0;
        for (size_t i = dot - original + 1; i < len && ext_len < MAX_EXTENSION_LEN; ++i) {
            if (!isalnum((unsigned char)original[i]) && original[i] != '.') break;
            new_filename[ext_len++] = original[i];
        }
        // If not a valid extension, set default extension .bin
        if (ext_len == 0) strcat(new_filename, ".bin");
    }

    // Determine the number of digits in the new filename based on the length of the original filename, excluding the last dot and its subsequent characters
    size_t num_digits = 0;
    for (size_t i = 0; i < len && i + num_digits < MAX_NEW_FILENAME_LEN; ++i) {
        if (!isdigit((unsigned char)original[i])) break;
        new_filename[num_digits++] = original[i];
    }

    // Add a counter to the filename for potential name collision issues
    static int64_t counter = 0;
    while (counter < MAX_NEW_FILENAME_LEN - num_digits) {
        new_filename[num_digits++] = 'a' + (counter++ % 26);
        if (num_digits >= MAX_NEW_FILENAME_LEN) break;
    }

    // Ensure the function can handle filenames from various locales and character sets
    setlocale(LC_ALL, "");

    return new_filename;
}
