    std::mutex mtx;
    std::atomic<size_t> size{0};

public:
    void add(std::unique_ptr<LTEPHY_FFT_SignalBlock> signal) {
        // Handle potential memory allocation failure here
        std::unique_lock<std::mutex> lock(mtx);
        signals.emplace_back(std::move(signal));
        size++;
    }

    void removeAt(size_t index) {
        // Handle potential out-of-bounds access here
        std::unique_lock<std::mutex> lock(mtx);
        if (index >= size || index < 0) return;
        signals[index].reset();
        size--;
    }

    const LTEPHY_FFT_SignalBlock* getAt(size_t index) const {
        // Handle potential out-of-bounds access here
        std::unique_lock<std::mutex> lock(mtx);
        if (index >= size || index < 0) return nullptr;
        return signals[index].get();
    }

    size_t getSize() const {
        std::atomic_thread_fence(std::memory_order_acquire);
        return size;
    }

