#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DataPacket {
    time_t timestamp;
    int id;
    size_t payload_size;
} DataPacket;

typedef struct DynamicArray {
    DataPacket* data;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*) malloc(sizeof(DynamicArray));
    array->data = (DataPacket*) calloc(initial_capacity, sizeof(DataPacket));
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void resize_dynamic_array(DynamicArray* array) {
    DataPacket* new_data = (DataPacket*) realloc(array->data, array->capacity * 2 * sizeof(DataPacket));
    if (!new_data) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity *= 2;
}

void add_packet(DynamicArray* array, DataPacket packet) {
    if (array->size == array->capacity) resize_dynamic_array(array);

    array->data[array->size] = packet;
    array->size++;
}

int find_packet_index(const DynamicArray* array, int id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].id == id) return i;
    }
    return -1;
}

int remove_packet(DynamicArray* array, int id) {
    int index = find_packet_index(array, id);
    if (index == -1) return -1;

    for (size_t i = index + 1; i < array->size; ++i) {
        array->data[i - 1] = array->data[i];
    }
    --array->size;
    return 0;
}

void retrieve_packets(const DynamicArray* array, time_t start, time_t end, size_t* count, DataPacket** packets) {
    *count = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].timestamp >= start && array->data[i].timestamp <= end) {
            (*packets)[*count] = array->data[i];
            ++(*count);
            if (*count == *packets) {
                resize_dynamic_array((DynamicArray*) packets);
            }
        }
    }
}

void save_to_external_store(DynamicArray* array, void (*save_fn)(const DataPacket*, FILE*)) {
    // Implement error handling and periodic batch updates as needed
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open data file\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < array->size; ++i) {
        save_fn(&array->data[i], file);
    }

    fclose(file);
}
```
