    struct _NFAPI_CRC_INDICATION_PDU_T *prev, *next;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* head = NULL;
static NFAPI_CRC_INDICATION_PDU_T* free_list = NULL;
static uint32_t max_rnti = 0;
static int error_probability = 50; // in percentage

void init_list(void) {
    head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) exit(1);

    memset(head, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    head->prev = NULL;
    head->next = NULL;

    pthread_mutex_init(&head->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* pop_node(void) {
    NFAPI_CRC_INDICATION_PDU_T *node = free_list;
    if (free_list) free_list = free_list->next;
    return node;
}

void push_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    node->prev = head;
    node->next = head->next;
    head->next = node;
}

void free_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&node->mutex);
    node->prev = NULL;
    node->next = free_list;
    free_list = node;
    pthread_mutex_unlock(&node->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *node = pop_node();
    if (!node) node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    memset(node, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->tag = tag;
    node->rnti = rnti;
    node->crc_indication.crcflag = (rand() % 100 <= error_probability) ? 1 : 0;

    pthread_mutex_init(&node->mutex, NULL);

    return node;
