CRC_INDICATION_REL8_TAG generate_crc_tag() {
    static thread_local uint32_t crc_seed = 0xdeadbeef;
    uint32_t crcflag = crc_seed & 1;
    crc_seed = crc_seed * 0x04c11db7 + 0x31337f08;
    return (CRC_INDICATION_REL8_TAG) { .crcflag = crcflag };
}

bool validate_rnti(uint16_t rnti, uint16_t min, uint16_t max) {
    return rnti >= min && rnti <= max;
