void* alloc_and_init_array(uint32_t N, RX_UE_INFORMATION_TAG** tags, uint16_t min_rnti, uint16_t max_rnti) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRC_INDICATION_PDU_T* buffer = NULL;
    if (N > 0 && tags != NULL) {
        buffer = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
        if (buffer == NULL) {
            pthread_mutex_destroy(&lock);
            return NULL;
        }

        for (size_t i = 0; i < N; ++i) {
            pthread_mutex_lock(&lock);
            while (!validate_rnti(tags[i]->rnti, min_rnti, max_rnti) || !buffer[i].rx_ue_information_tag) {
                pthread_mutex_unlock(&lock);
                sleep(1); // Yield CPU time to other threads
                pthread_mutex_lock(&lock);
