void add_to_list(node_t** head, node_t* new_node) {
    pthread_mutex_lock(&new_node->mutex);
    new_node->next = *head;
    *head = new_node;
    pthread_mutex_unlock(&new_node->mutex);
}

void remove_from_list(node_t** head, node_t* node) {
    pthread_mutex_lock(&(*head)->mutex);
    if (*head == node) *head = node->next;

    while (node->next != NULL && node->next != *head) {
        node = node->next;
    }

    if (node->next) node->next = node->next->next;
    pthread_mutex_unlock(&(*head)->mutex);
}

void destroy_list(node_t** head) {
    while (*head != NULL) {
        node_t* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
