void init_list(struct list* list, size_t initial_size) {
    list->data = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_size;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void push_back(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        while (new_capacity <= list->size) {
            new_capacity *= 2;
        }
        NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            perror("Memory allocation error");
            exit(EXIT_FAILURE);
        }
        list->data = temp_data;
        list->capacity = new_capacity;
    }
    pthread_mutex_lock(&list->lock);
    list->data[list->size] = *elem;
    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

const NFAPI_CRC_INDICATION_PDU_T* get(const struct list* list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    const NFAPI_CRC_INDICATION_PDU_T* elem = &list->data[index];
    pthread_mutex_unlock(&list->lock);
    return elem;
}

void destroy(struct list* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}
