#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t list_size = 0;
static const size_t MAX_LIST_SIZE = 10000;

void generate_list(size_t n, uint32_t min_rnti, uint32_t max_rnti, double crc_probability) {
    if (n > MAX_LIST_SIZE || n == 0) {
        fprintf(stderr, "Invalid argument: N must be between 1 and %zu\n", MAX_LIST_SIZE);
        return;
    }

    pthread_mutex_lock(&list_mutex);
    if (list != NULL && list_size >= n) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    size_t list_capacity = list ? list_size : 0;
    while (list_capacity < n) {
        NFAPI_CRC_INDICATION_PDU_T* new_data = malloc(n - list_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            perror("malloc");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        for (size_t i = 0; i < n - list_capacity; ++i) {
            new_data[i].rnti = min_rnti + rand() % ((max_rnti - min_rnti) + 1);
            new_data[i].crcflag = (rand() / (RAND_MAX + 1.0) < crc_probability);
        }

        if (list != NULL) {
            memcpy(new_data, list + list_capacity, list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        free(list);
        list = new_data;
        list_capacity += n - list_capacity;
        list_size = list_capacity;
    }

    pthread_mutex_unlock(&list_mutex);
}

