#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
    time_t ttl; // Time-to-Live in seconds
    pthread_mutex_t lock;
    struct node *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} NODE;

// Function to initialize a new node with given data and next pointer
NODE* create_node(NFAPI_CRC_INDICATION_PDU_T data, NODE* next) {
    NODE* new_node = (NODE*)malloc(sizeof(NODE));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = next;
    return new_node;
}

// Function to initialize a new linked list with given head and length
void init_list(NODE** head, size_t length) {
    for (size_t i = 0; i < length; ++i)
        *head = create_node((NFAPI_CRC_INDICATION_PDU_T){
                               .tag = (RX_UE_INFORMATION_TAG){},
                               .rnti = (RNTI){},
                               .crc_ind = (CRC_INDICATION_REL8_TAG){.crcflag = rand() % 2},
                               .ttl = time(NULL),
                               .lock = PTHREAD_MUTEX_INITIALIZER,
                               .next = NULL
        }, *head);
}

// Function to add a new node at the end of the list while locking the entire list with a read-write lock
void append(NODE** head, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_rwlock_t rwlock;
    pthread_rwlock_init(&rwlock, NULL);
    NODE* current = *head;

    // Acquire a write lock to modify the list
    pthread_rwlock_wrlock(&rwlock);

    while (current->next != NULL)
        current = current->next;

    current->next = create_node(data, NULL);
    pthread_rwlock_unlock(&rwlock);
}

// Function to remove the first node with a TTL less than the current time from the list while locking the entire list with a read-write lock
void garbage_collect(NODE** head) {
    pthread_rwlock_t rwlock;
    pthread_rwlock_init(&rwlock, NULL);
    NODE* current = *head;
    NODE* next;

    // Acquire a write lock to modify the list
    pthread_rwlock_wrlock(&rwlock);

    while (current != NULL) {
        if (time(NULL) - current->data.ttl >= CONFIG_GARBAGE_COLLECTION_INTERVAL) {
            next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&rwlock);
}
```

This code provides a basic implementation of a thread-safe, dynamically resizable linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. The use of a read-write lock (`pthread_rwlock_t`) ensures that only one thread can modify the list at a time while allowing multiple threads to access the list for reading without acquiring a write lock.

The `append()` function adds a new node to the end of the list, and the `garbage_collect()` function removes outdated entries based on the TTL policy. The functions employ an efficient resizing strategy by using dynamic memory allocation (`malloc()`) for individual nodes, and the garbage collection is handled automatically during periodic intervals defined by the `CONFIG_GARBAGE_COLLECTION_INTERVAL`.

It is important to note that you should define the necessary structures like `RX_UE_INFORMATION_TAG`, `RNTI`, and `CRC_INDICATION_REL8_TAG` according to your specific requirements. Additionally, you will need to include appropriate header files and handle any error cases or memory allocation failures in a production-ready implementation.

Regarding the performance impact, the use of a read-write lock minimizes overhead compared to acquiring individual locks for each node, but it may introduce contention under heavy load conditions. You can consider using more advanced synchronization mechanisms such as locks with finer granularity or concurrent data structures (e.g., treaps) to further optimize performance based on your specific use case and system requirements.']

