    if (context == NULL) {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Failed to allocate memory for MAC context\n");
        return NULL;
    }

    context->MAC_INSTANCE_ID = generate_unique_id();
    context->PDCCH_BUFFER_SIZE = configurable_setting;
    context->phy_layer_handle = phy_layer_acquire();
    context->MAC_STATE = MAC_IDLE; // Set initial state to idle

