void mac_list_init() {
    pthread_t* threads = malloc(MAX_ELEMENTS * sizeof(pthread_t));

    if (threads == NULL) {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Failed to allocate memory for MAC list threads\n");
        return;
    }

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_create(&threads[i], NULL, mac_context_initializer, NULL);
    }

    size_t elements_created = 0;
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_join(threads[i], (void**)&mac_list + elements_created);

        if (mac_list[elements_created]) {
            elements_created++;
        }
    }

    free(threads);
}

MAC_CONTEXT* mac_get() {
    pthread_mutex_lock(&list_mutex);

    size_t index = 0;
    MAC_CONTEXT* current = NULL;
    for (; index < MAX_ELEMENTS; ++index) {
        if (mac_list[index]) {
            if (mac_list[index]->MAC_STATE == MAC_IDLE) {
                current = mac_list + index;
                break;
            }
        }
    }

    // If no idle context is found, use the first non-idle context and set its state to idle
    if (current == NULL) {
        current = mac_list;
        while (current->MAC_STATE != MAC_IDLE && current < mac_list + MAX_ELEMENTS) {
            current++;
        }

        if (current >= mac_list + MAX_ELEMENTS) {
            // Handle case where no idle context is found after iterating through the list
            fprintf(stderr, "Failed to find an idle MAC context\n");
        } else {
            current->MAC_STATE = MAC_IDLE;
        }
    }

    pthread_mutex_unlock(&list_mutex);

    return current;
