class ScriptCache {
  constructor(cacheSize) {
    this.cache = new Map();
    this.cacheSize = cacheSize;
  }

  get(id) {
    return this.cache.get(id);
  }

  set(id, script) {
    if (!script.code) throw new Error("Script object must have a code property");
    this.cache.set(id, script);
    if (this.cache.size > this.cacheSize) this.cache.delete(this.cache.keys().next().value);
  }
}

function generateFooter(scriptCollection, cache = new ScriptCache(10)) {
  let footerHTML = "<footer>";

  for (const script of scriptCollection) {
    const id = `module-${crypto.randomUUID()}`;
    if (!cache.get(id)) {
      cache.set(id, script);
    }
    const scriptTag = document.createElement("script");
    scriptTag.setAttribute("id", id);
    scriptTag.innerHTML = cache.get(id).code;
    footerHTML += scriptTag.outerHTML;
  }

  return footerHTML + "</footer>";
}
```

