        fprintf(stderr, "Error: Requested number of structures exceeds the maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t index = 0;
    for (size_t i = 0; i < n; ++i) {
        pthread_mutex_lock(&mutex);

        if (index >= n) break; // Ensure thread safety

        pdu_list[index].tag.tagValue = i + 1;
        pdu_list[index].rnti.value = rand() % 0xFFFF;
        pdu_list[index].crc_indication.crcfFlag = (rand() % 2) == 0 ? 1 : 0; // Randomly set CRCFLAG to 0 or 1
        ++index;

        pthread_mutex_unlock(&mutex);
    }

    return pdu_list;
