import os
import hashlib
import shutil
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

class FileProcessor:
    def __init__(self, log_func):
        self.file_hashes = {}
        self.log_func = log_func
        self.metadata = {}  # Placeholder for external metadata

    def _get_hash(self, filepath):
        try:
            with open(filepath, 'rb') as f:
                hasher = hashlib.sha256()
                while True:
                    data = f.read(8192)  # Optimize for large files by reading chunks
                    if not data:
                        break
                    hasher.update(data)
                return hasher.hexdigest()
        except Exception as e:
            self.log_func(f"Error processing {filepath}: {e}")
            return None

    def _get_metadata(self, filepath):
        # Implement the logic to retrieve metadata from external sources
        pass

    def process_directory(self, basedir):
        for root, dirs, files in os.walk(basedir):
            for file in files:
                filepath = os.path.join(root, file)
                if not os.path.isfile(filepath):
                    continue
                ext = os.path.splitext(file)[1]
                if ext not in ['.txt', '.csv', '.log']:
                    continue

                hash_ = self._get_hash(filepath)
                if hash_ is None:
                    continue

                metadata = self._get_metadata(filepath)
                self.file_hashes[filepath] = (hash_, metadata)
                self.log_func(f"Processed {filepath} with hash {hash_}")

def main():
    processor = FileProcessor(lambda msg: logging.info(msg))
    processor.process_directory("/path/to/your/large/directory")

if __name__ == "__main__":
    main()
```

