```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    uint16_t TX_QUEUE_INDEX;
    uint16_t SRS_INFO_TAG;
    CHANNEL_QUALITY_INFO_T* CHANNEL_QUALITY_INFO;
} PHY_RX_FRAME_STATS_T;

typedef struct {
    size_t capacity;
    size_t count;
    PHY_RX_FRAME_STATS_T** elements;
    pthread_mutex_t mutex;
} DYNAMIC_LIST;

void* custom_malloc(size_t size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr, size_t size) {
    munmap(ptr, size);
}

DYNAMIC_LIST* dynamic_list_create() {
    DYNAMIC_LIST* list = (DYNAMIC_LIST*)custom_malloc(sizeof(DYNAMIC_LIST));
    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = 0;
    list->count = 0;
    list->elements = NULL;
    return list;
}

void dynamic_list_destroy(DYNAMIC_LIST* list) {
    for (size_t i = 0; i < list->count; ++i) {
        PHY_RX_FRAME_STATS_T** element = &(list->elements[i]);
        custom_free(*element, sizeof(PHY_RX_FRAME_STATS_T));
    }
    custom_free(list->elements, list->capacity * sizeof(PHY_RX_FRAME_STATS_T*));
    pthread_mutex_destroy(&list->mutex);
    custom_free(list, sizeof(DYNAMIC_LIST));
}

bool dynamic_list_is_full(const DYNAMIC_LIST* list) {
    return list->count == list->capacity;
}

void dynamic_list_resize(DYNAMIC_LIST* list, size_t new_capacity) {
    PHY_RX_FRAME_STATS_T** old_elements = list->elements;
    list->capacity = new_capacity;
    list->elements = (PHY_RX_FRAME_STATS_T**)custom_malloc(list->capacity * sizeof(PHY_RX_FRAME_STATS_T*));
    for (size_t i = 0; i < list->count && i < new_capacity; ++i) {
        if (old_elements[i])
            list->elements[i] = old_elements[i];
    }
    custom_free(old_elements, list->capacity * sizeof(PHY_RX_FRAME_STATS_T*));
}

void dynamic_list_append(DYNAMIC_LIST* list, PHY_RX_FRAME_STATS_T* stat) {
    pthread_mutex_lock(&list->mutex);
    if (dynamic_list_is_full(list))
        dynamic_list_resize(list, list->capacity * 2);
    list->elements[list->count] = stat;
    ++list->count;
    pthread_mutex_unlock(&list->mutex);
}

void process_batch(DYNAMIC_LIST* list, void (*callback)(PHY_RX_FRAME_STATS_T*)) {
    pthread_mutex_lock(&list->mutex);
    size_t batch_size = 500;
    PHY_RX_FRAME_STATS_T** elements = &(list->elements[list->count - batch_size]);
    size_t count = batch_size < list->count - batch_size ? batch_size : list->count - batch_size;

    for (size_t i = 0; i < count; ++i) {
        PHY_RX_FRAME_STATS_T* stat = elements[i];
        (*callback)(stat);
        // Set a random SNR value for demonstration purposes.
        stat->CHANNEL_QUALITY_INFO->SNR = (rand() % 100) + 1;
    }

    list->count -= count;
    memmove(list->elements, elements, count * sizeof(PHY_RX_FRAME_STATS_T*));
    pthread_mutex_unlock(&list->mutex);
}

void safeFunction(DYNAMIC_LIST* list) {
    // Initialize PHY_RX_FRAME_STATS_T structures here.
    // ...

    process_batch(list, &handle_frame);
}

void handle_frame(PHY_RX_FRAME_STATS_T* stat) {
    if (stat->TX_QUEUE_INDEX < 0 || stat->TX_QUEUE_INDEX > 4095) {
        fprintf(stderr, "Invalid TX_QUEUE_INDEX: %d\n", stat->TX_QUEUE_INDEX);
        return;
    }

    // Handle the frame here.
}
```

