['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    unsigned int size;
    Node **nodes;
    pthread_mutex_t mutex;
};

void log(const char *message) {
    printf("%s\n", message);
}

void resize_list(struct list *list, unsigned int new_size) {
    Node **new_nodes = malloc(new_size * sizeof(Node*));
    if (new_nodes == NULL) {
        log("Memory allocation failure.");
        return;
    }

    if (list->size > 0) {
        memcpy(new_nodes, list->nodes, list->size * sizeof(Node*));
    }

    pthread_mutex_destroy(&list->mutex);
    free(list->nodes);

    list->nodes = new_nodes;
    list->size = new_size;
    pthread_mutex_init(&list->mutex, NULL);
}

void push_back(struct list *list, NFAPI_CRAC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->nodes[0]->next) {
        resize_list(list, list->size * 2 + 1);
    }

    list->nodes[list->size]->next = malloc(sizeof(Node));
    if (list->nodes[list->size]->next == NULL) {
        log("Memory allocation failure.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    list->nodes[list->size]->next->data = data;
    list->nodes[list->size]->next->next = NULL;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

struct list *create_list(unsigned int initial_size) {
    struct list *list = malloc(sizeof(struct list));
    if (list == NULL) {
        log("Memory allocation failure.");
        return NULL;
    }

    list->nodes = malloc((initial_size + 1) * sizeof(Node*));
    if (list->nodes == NULL) {
        log("Memory allocation failure.");
        free(list);
        return NULL;
    }

    for (unsigned int i = 0; i < initial_size; ++i) {
        list->nodes[i] = malloc(sizeof(Node));
        if (list->nodes[i] == NULL) {
            log("Memory allocation failure.");
            free(list);
            return NULL;
        }

        list->nodes[i]->next = NULL;
    }

    list->size = initial_size + 1;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}
```

