#include <stdint.h>

typedef struct NICP_PDU {
    uint32_t nei;
    uint32_t ani;
    uint64_t sci;
} NICP_PDU;

typedef struct array_guard {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NICP_PDU* data;
} ArrayGuard;

ArrayGuard* init_nicp_array(size_t size) {
    ArrayGuard* array = (ArrayGuard*) malloc(sizeof(ArrayGuard));
    if (!array) return NULL;

    array->capacity = size;
    array->size = 0;
    array->data = (NICP_PDU*) calloc(size, sizeof(NICP_PDU));
    if (!array->data) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_nicp_array(ArrayGuard* array) {
    if (array && array->data) {
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

NICP_PDU* get_nicp_array(ArrayGuard* array, size_t index) {
    if (!index < array->size && index < array->capacity) {
        pthread_mutex_lock(&array->lock);
        NICP_PDU* pdu = &array->data[index];
        // You can initialize the PDU fields here with valid default values or user-defined methods.
        pthread_mutex_unlock(&array->lock);
        return pdu;
    }
    return NULL;
}
```

