public class ConfigurationLoader
{
    private const string ConfigFile = "config.xml";
    private const int MaxMemoryUsage = 100_000_000; // in bytes, adjust according to your system's memory constraints
    private readonly Random _random = new Random();
    private XmlDocument _doc;

    public ConfigurationLoader()
    {
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        if (!File.Exists(ConfigFile))
        {
            throw new FileNotFoundException($"Configuration file '{ConfigFile}' not found.");
        }

        _doc = new XmlDocument();
        _doc.Load(ConfigFile);
    }

    public (int tileSize, int worldWidth, int worldHeight, float cameraSpeed) GetWorldDimensions()
    {
        var tileSizeNode = _doc.SelectSingleNode("/Configuration/TileSize");
        var worldWidthNode = _doc.SelectSingleNode("/Configuration/WorldWidth");
        var worldHeightNode = _doc.SelectSingleNode("/Configuration/WorldHeight");
        var cameraSpeedNode = _doc.SelectSingleNode("/Configuration/CameraSpeed");

        if (tileSizeNode == null || worldWidthNode == null || worldHeightNode == null || cameraSpeedNode == null)
        {
            throw new XmlException("Invalid configuration file.");
        }

        int tileSize = int.Parse(tileSizeNode.InnerText);
        int worldWidth = int.Parse(worldWidthNode.InnerText);
        int worldHeight = int.Parse(worldHeightNode.InnerText);
        float cameraSpeed = float.Parse(cameraSpeedNode.InnerText);

        return (tileSize, worldWidth, worldHeight, cameraSpeed);
    }

    public NFAPI_CRC_INDICATION_PDU_T[] AllocatePduStructures(int numberOfStructures)
    {
        if (numberOfStructures > MaxMemoryUsage / sizeof(NFAPI_CRC_INDICATION_PDU_T))
        {
            throw new ArgumentException("Requested number of structures exceeds available memory.");
        }

        var pduStructures = new List<NFAPI_CRC_INDICATION_PDU_T>();

        for (int i = 0; i < numberOfStructures; ++i)
        {
            RX_UE_INFORMATION_TAG rxUeInformationTag = new RX_UE_INFORMATION_TAG();
            uint rnti = unchecked((uint)(_random.Next() | (uint)0x80000000)); // Ensure the most significant bit is set, as per 3GPP TS 36.213 V15.4.0 (p. 2-49)
            CRC_INDICATION_REL8_TAG crcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG { CRCFlag = _random.Next(2) == 0 };

            var pdu = new NFAPI_CRC_INDICATION_PDU_T
            {
                RxUEInformationTag = rxUeInformationTag,
                Rnti = rnti,
                CrcIndicationRel8Tag = crcIndicationRel8Tag
            };

            pduStructures.Add(pdu);
        }

        return pduStructures.ToArray();
    }
}

