#ifndef DYNAMIC_ARRAY_H
#define DYNAMIC_ARRAY_H

#include <pthread.h>
#include <stdbool.h>

typedef struct lte_phy_rx_metric {
    uint32_t ue_id;
    uint16_t subframe_num;
    int rsrp;
    int cqi;
} LTE_PHY_RX_METRIC;

typedef struct dynamic_array {
    LTE_PHY_RX_METRIC *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* dynamic_array_create(size_t initial_capacity);
void dynamic_array_destroy(DYNAMIC_ARRAY* array);
size_t dynamic_array_size(const DYNAMIC_ARRAY* array);
bool dynamic_array_append(DYNAMIC_ARRAY* array, const LTE_PHY_RX_METRIC* metric);
void dynamic_array_compress(DYNAMIC_ARRAY* array);
void dynamic_array_log_exceptional_values(const DYNAMIC_ARRAY* array);
void dynamic_array_set_memory_policy(DYNAMIC_ARRAY* array, size_t (*memory_policy)(size_t current_capacity, size_t desired_capacity));
bool dynamic_array_is_overloaded(const DYNAMIC_ARRAY* array);

#endif // DYNAMIC_ARRAY_H
```

**dynamic_array.c**
```c
#include "dynamic_array.h"
#include <stdlib.h>
#include <string.h>

size_t memory_policy_grow(size_t current_capacity, size_t desired_capacity) {
    return current_capacity * 2;
}

DYNAMIC_ARRAY* dynamic_array_create(size_t initial_capacity) {
    DYNAMIC_ARRAY* array = (DYNAMIC_ARRAY*)malloc(sizeof(DYNAMIC_ARRAY));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(LTE_PHY_RX_METRIC));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->memory_policy = memory_policy_grow;

    return array;
}

void dynamic_array_destroy(DYNAMIC_ARRAY* array) {
    if (array->data) free(array->data);
    free(array);
}

size_t dynamic_array_size(const DYNAMIC_ARRAY* array) {
    return array->size;
}

bool dynamic_array_append(DYNAMIC_ARRAY* array, const LTE_PHY_RX_METRIC* metric) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = (array->memory_policy)(array->capacity, array->capacity * 2);
        LTE_PHY_RX_METRIC* temp = realloc(array->data, new_capacity * sizeof(LTE_PHY_RX_METRIC));
        if (!temp) {
            pthread_mutex_unlock(&array->lock);
            return false;
        }
        array->data = temp;
        array->capacity = new_capacity;
    }
    memcpy(array->data + array->size, metric, sizeof(LTE_PHY_RX_METRIC));
    ++array->size;
    pthread_mutex_unlock(&array->lock);
    return true;
}

void dynamic_array_compress(DYNAMIC_ARRAY* array) {
    // Implement custom compression algorithm here
}

void dynamic_array_log_exceptional_values(const DYNAMIC_ARRAY* array) {
    // Implement a mechanism to detect and log exceptional values here
}

void dynamic_array_set_memory_policy(DYNAMIC_ARRAY* array, size_t (*memory_policy)(size_t current_capacity, size_t desired_capacity)) {
    array->memory_policy = memory_policy;
}

bool dynamic_array_is_overloaded(const DYNAMIC_ARRAY* array) {
    // Implement a method to check if the array is overloaded here
    return false;
}
