           // Custom memory expansion strategy
           size_t newCapacity = queue->capacity * 2;
           LTE_PHY_RX_metric* tempData = realloc(queue->data, newCapacity * sizeof(LTE_PHY_RX_metric));
           if (!tempData) {
               pthread_mutex_unlock(&queue->lock);
               return; // Handle error here
           }
           queue->data = tempData;
           queue->capacity = newCapacity;
       }
       RBTreeInsert(queue->tree, (void*)metric, metric->ueId);
       queue->count++;
       pthread_mutex_unlock(&queue->lock);
   }

   const struct LTE_PHY_RX_metric* dequeue(struct LTE_PHY_RX_queue* queue) {
       pthread_mutex_lock(&queue->lock);
       void* minData = RBTreeMinimum(queue->tree);
       if (minData) {
           const struct LTE_PHY_RX_metric* metric = (const struct LTE_PHY_RX_metric*)minData;
           RBTreeRemoveMin(queue->tree);
           queue->count--;
           pthread_mutex_unlock(&queue->lock);
           return metric;
