#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    AES_KEY aes;
    unsigned char iv[16]; // Default IV length for GCM mode
    unsigned char *encryption_key;
    size_t key_length;
} AES256GCM_context;

void AES256GCM_init(AES256GCM_context* ctx, const char* passphrase, size_t iv_len) {
    if (iv_len > 16 || iv_len == 0) {
        fprintf(stderr, "Invalid IV length. IV should be between 1 and 16 bytes.\n");
        return;
    }

    ctx->iv_length = iv_len;
    memcpy(ctx->iv, iv_len ? iv : openssl_random_bytes(iv_len), iv_len);

    EVP_CIPHER_CTX *enc_ctx = EVP_AES_256_GCM_ctx_new();
    if (!enc_ctx) {
        fprintf(stderr, "Failed to allocate AES-256-GCM context.\n");
        return;
    }

    // Set passphrase and IV for encryption/decryption and authentication
    if (1 != EVP_EncryptInit_ex(enc_ctx, NULL, NULL, (uint8_t*)passphrase, ctx->iv, NULL)) {
        fprintf(stderr, "Failed to initialize AES-256-GCM context.\n");
        EVP_AES_256_GCM_ctx_free(enc_ctx);
        return;
    }

    // Derive encryption key from passphrase and store it securely
    unsigned char key[32];
    size_t key_len = sizeof(key);
    if (1 != EVP_CipherFinal_ex(enc_ctx, key, &key_len)) {
        fprintf(stderr, "Failed to derive encryption key.\n");
        EVP_AES_256_GCM_ctx_free(enc_ctx);
        return;
    }

    // Allocate and store the derived encryption key
    ctx->key_length = key_len;
    ctx->encryption_key = malloc(key_len);
    if (!ctx->encryption_key) {
        fprintf(stderr, "Failed to allocate memory for encryption key.\n");
        EVP_AES_256_GCM_ctx_free(enc_ctx);
        return;
    }
    memcpy(ctx->encryption_key, key, key_len);

    // Free resources and clean up
    EVP_CIPHER_CTX_free(enc_ctx);
}

void AES256GCM_cleanup(AES256GCM_context* ctx) {
    if (ctx->encryption_key) {
        free(ctx->encryption_key);
        ctx->encryption_key = NULL;
    }
}
```

