[' Here's a C implementation of the dynamic collection using a doubly-linked list with memory management and error handling. I haven't included the synchronization part since it depends on specific requirements for your external data source.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    float value;
    int index;
    struct Node *prev, *next;
} Node;

typedef struct Collection {
    unsigned int capacity;
    unsigned int size;
    Node *head, *tail;
} Collection;

Collection *create_collection(unsigned int initial_capacity) {
    Collection *collection = malloc(sizeof(Collection));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->head = NULL;
    collection->tail = NULL;
    return collection;
}

void insert_left(Collection *collection, float value, int index) {
    if (collection->size == collection->capacity) resize_collection(collection);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory during allocation.\n");
        return;
    }

    new_node->value = value;
    new_node->index = index;
    new_node->prev = NULL;
    new_node->next = collection->head;

    if (collection->head) {
        collection->head->prev = new_node;
        collection->head = new_node;
    } else {
        collection->head = collection->tail = new_node;
    }

    collection->size++;
}

void insert_right(Collection *collection, float value, int index) {
    if (collection->size == collection->capacity) resize_collection(collection);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory during allocation.\n");
        return;
    }

    new_node->value = value;
    new_node->index = index;
    new_node->prev = collection->tail;
    new_node->next = NULL;

    if (collection->tail) {
        collection->tail->next = new_node;
        collection->tail = new_node;
    } else {
        collection->head = collection->tail = new_node;
    }

    collection->size++;
}

void delete(Collection *collection, Node *node) {
    if (node == collection->head) {
        collection->head = node->next;
        if (collection->head) {
            collection->head->prev = NULL;
        } else {
            collection->tail = NULL;
        }
    } else if (node == collection->tail) {
        collection->tail = node->prev;
        if (collection->tail) {
            collection->tail->next = NULL;
        } else {
            collection->head = NULL;
        }
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    collection->size--;
}

void resize_collection(Collection *collection) {
    unsigned int new_capacity = 2 * collection->capacity;
    Collection *new_collection = create_collection(new_capacity);

    for (Node *current = collection->head; current != NULL; current = current->next) {
        insert_right(new_collection, current->value, current->index);
    }

    free(collection);
    collection = new_collection;
}

void print_collection(Collection *collection) {
    for (Node *current = collection->head; current != NULL; current = current->next) {
        printf("(%f, %d)\n", current->value, current->index);
    }
}
```

With this code, you have a dynamic collection that supports inserting and deleting items efficiently at both ends of the linked list. The function minimizes memory usage by resizing when needed and gracefully handles allocation failures using error messages. To traverse the list and print its contents, use the `print_collection` function provided.']

