```cpp
#include <atomic>
#include <mutex>
#include <memory>
#include <list>
#include <vector>
#include <iostream>

class InterfaceConfig {
public:
    std::string id;
    std::string ip;
    std::string subnetMask;
    std::string gateway;
};

// Thread-safe dynamic linked list to manage interface configurations
class NetworkConfigManager {
private:
    using InterfaceList = std::list<std::unique_ptr<InterfaceConfig>>;
    InterfaceList data_;
    std::mutex mtx_;
    std::atomic<size_t> size_{0};

public:
    // Insert a new interface configuration (thread-safe)
    void insert(const InterfaceConfig& config) {
        std::unique_ptr<InterfaceConfig> newConfig = std::make_unique<InterfaceConfig>(config);
        std::lock_guard<std::mutex> lock(mtx_);
        data_.push_back(std::move(newConfig));
        ++size_;
    }

    // Remove an interface configuration by ID (thread-safe)
    void removeById(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx_);
        for (auto it = data_.begin(); it != data_.end(); ++it) {
            if ((*it)->id == id) {
                data_.erase(it);
                --size_;
                break;
            }
        }
    }

    // Return the interface configuration by ID (thread-safe, returns nullptr if not found)
    std::unique_ptr<InterfaceConfig> findById(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        for (const auto& config : data_) {
            if (config->id == id) {
                return config;
            }
        }
        return nullptr;
    }

    // Return the number of interface configurations
    size_t getSize() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return size_;
    }
};
