char* process_string(const char *input, size_t limit, bool pad) {
    // Calculate the length of the input string excluding the null terminator
    size_t input_len = strlen(input);

    // Handle edge cases: empty strings and very long strings
    if (input_len == 0 || input_len >= INT_MAX - limit) {
        return NULL;
    }

    // Allocate memory for the output string with the correct size
    char *output = malloc(limit + (pad ? 2 : 1));
    if (!output) {
        // Handle memory allocation failure gracefully
        return NULL;
    }

    // Copy the input string to the output buffer, truncating or padding as needed
    size_t output_idx = 0;
    for (size_t i = 0; i < input_len; ++i) {
        output[output_idx++] = input[i];
        // Truncate if necessary and append padding or null terminator
        if (output_idx == limit) break;
    }

    // Append padding or null terminator
    if (pad) {
        output[output_idx++] = '/';
        output[output_idx] = '\0';
    } else {
        output[output_idx] = '\0';
    }

    return output;
}
