            pduArray[i].rnti = rnti;
            pduArray[i].crc_indication.crcFlag = generateCRCFLAG();

            while (!isValidCRCFLAG(pduArray[i].crc_indication.crcFlag)) {
                attempts++;
                correctCRCFLAG(&pduArray[i].crc_indication.crcFlag);
                logEvent("Corrected CRCFLAG due to invalid value", 1);
            }

            rntiCount[i] = 1;
        }
    }

    if (attempts > MAX_STRUCTURES / PRIME_NUMBER) {
        free(pduArray);
        logEvent("Failed to allocate memory after excessive attempts", 0);
        return NULL;
    }

    logEvent(sprintf("Allocated and populated PDU array with %d structures", i), 1);
    return pduArray;
