#include <time.h>
#include <pthread.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define MAX_STRUCTURES 10000
#define LOG_ROTATION_DAYS 7
#define THRESHOLD_CPU 80
#define THRESHOLD_MEMORY 90

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryBlock {
    void* start;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryPool {
    MemoryBlock *head;
    pthread_mutex_t mutex;
};

MemoryPool createMemoryPool(size_t initialSize, size_t blockSize) {
    MemoryPool pool = {NULL, PTHREAD_MUTEX_INITIALIZER};
    MemoryBlock* newBlock = malloc(initialSize);
    if (newBlock == NULL) {
        fprintf(stderr, "Error: Failed to allocate initial memory for memory pool\n");
        return pool;
    }

    pool.head = newBlock;
    pool.head->size = initialSize;
    pool.head->next = NULL;
    pool.head->start = mmap(newBlock, initialSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool.head->start == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to map memory for memory pool\n");
        free(newBlock);
        return pool;
    }

    MemoryBlock *current = pool.head;
    size_t currentSize = initialSize;
    while (currentSize < blockSize) {
        current->next = malloc(blockSize - currentSize);
        if (current->next == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for memory pool\n");
            munmap(pool.head->start, initialSize);
            free(newBlock);
            return pool;
        }
        current = current->next;
        current->size = blockSize - currentSize;
        current->start = mmap(current, current->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (current->start == MAP_FAILED) {
            fprintf(stderr, "Error: Failed to map memory for memory pool\n");
            munmap(pool.head->start, initialSize);
            free(newBlock);
            return pool;
        }
        currentSize += blockSize;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* createStructure(MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)pool->head;
    if ((pool->head + 1)->size <= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Memory pool exhausted\n");
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    pool->head++;
    memset(structure, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    structure->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
    structure->RNTI = rand() % ((1LL << 48) - 1);
    structure->CRC_INDICATION_REL8_TAG = rand() % UINT32_MAX;
    structure->CRCFLAG = rand() % 2 == 0 ? true : false;
    pthread_mutex_unlock(&pool->mutex);
    return structure;
}

void logEvent(const char* fileName, const char* message) {
    FILE *file = fopen(fileName, "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    } else {
        fprintf(stderr, "Error: Failed to open log file for writing: %s\n", fileName);
    }
}

void cleanUp(MemoryPool* pool) {
    MemoryBlock *current = pool->head;
    while (current != NULL) {
        MemoryBlock *next = current->next;
        munmap(current->start, current->size);
        free(current);
        current = next;
    }
}

void* createStructures(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    uint64_t structCount = 0;
    double cpuUsage, memoryUsage;

    while (structCount < MAX_STRUCTURES) {
        NFAPI_CRC_INDICATION_PDU_T* structure = createStructure(pool);
        if (structure == NULL) break;

        structCount++;
        logEvent("crc_indication_log.txt", "[Created] Structure #%llu: RX_UE_INFORMATION_TAG=%u, RNTI=%llu, CRC_INDICATION_REL8_TAG=%u, CRCFLAG=%d\n", structCount, structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRC_INDICATION_REL8_TAG, structure->CRCFLAG);

        cpuUsage = calculateCPUUsage(); // Implement this function to get current CPU usage
        memoryUsage = calculateMemoryUsage(); // Implement this function to get current memory usage

        if ((cpuUsage > THRESHOLD_CPU) || (memoryUsage > THRESHOLD_MEMORY)) {
            logEvent("resource_usage.log", "[Throttled] CPU usage=%.2f%%, Memory usage=%.2f%%\n", cpuUsage * 100, memoryUsage * 100);
            break;
        }
    }

    cleanUp(pool);
    return NULL;
}

int main() {
    MemoryPool* pool = createMemoryPool(); // Implement this function to initialize a MemoryPool object
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, createStructures, (void*)pool)) {
            fprintf(stderr, "Error: Failed to create thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error: Failed to join thread\n");
            return EXIT_FAILURE;
        }
    }

