typedef struct {
    char sourceIP[INET6_ADDRSTRLEN];
    char destinationIP[INET6_ADDRSTRLEN];
    int protocol; // TCP, UDP, ICMP, etc. defined as enumerations elsewhere
    size_t payloadLength;
} NetworkPacket;

const char *defined_protocols[] = { "TCP", "UDP", "ICMP", /* ... */ };
const uint32_t subnet_start = 0x0A0B0C0D; // Your subnet range starts here
const uint32_t subnet_end = 0x0A0B0CFF; // and ends here
const size_t max_packets = 256;
pthread_mutex_t db_mutex = PTHREAD_MUTEX_INITIALIZER;

int createNetworkPackets(NetworkPacket **packets, size_t N) {
    if (N > max_packets) {
        return -1; // Error: Too many packets requested
    }

    *packets = malloc(sizeof(NetworkPacket) * N);
    if (!*packets) {
        perror("Memory allocation failed");
        return -2; // Error: Failed to allocate memory
    }

    for (size_t i = 0; i < N; ++i) {
        NetworkPacket *packet = (*packets + i);

        // Initialize packet header fields to their default state
        memset(packet, 0, sizeof(NetworkPacket));

        // Generate source IP within subnet range
        uint32_t src_ip = (rand() % ((uint32_t)(subnet_end - subnet_start) + 1)) + subnet_start;
        inet_ntop(AF_INET, &src_ip, packet->sourceIP, sizeof(packet->sourceIP));

        // Generate destination IP randomly within the same subnet range as source
        uint32_t dest_ip = src_ip;
        while (dest_ip == src_ip) {
            dest_ip = (rand() % ((uint32_t)(subnet_end - subnet_start) + 1)) + subnet_start;
        }
        inet_ntop(AF_INET, &dest_ip, packet->destinationIP, sizeof(packet->destinationIP));

        // Set random payload length between 0 and 1500 bytes
        packet->payloadLength = rand() % 1501;

        // Check if the generated protocol is valid
        for (size_t j = 0; j < sizeof(defined_protocols) / sizeof(defined_protocols[0]); ++j) {
            if (packet->protocol == j) {
                break;
            }
            if (!strcmp(defined_protocols[j], "TCP") || !strcmp(defined_protocols[j], "UDP")) {
                // Only TCP and UDP are handled here, but you can extend this for other protocols
                if (i == 0) {
                    pthread_mutex_lock(&db_mutex);
                    // Asynchronously fetch the rest of the packet data from an external database
                    // ...
                    pthread_mutex_unlock(&db_mutex);
                }
            }
        }

        if (packet->protocol < 0) {
            free(*packets);
            *packets = NULL;
            return -3; // Error: Invalid protocol
        }
    }

    return 0; // Success: Packets were created without errors
}
