void updateAndSortVector(std::vector<int>& v, int valueToAdd, int targetValue, size_t startIndex) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex before modifying the vector to ensure thread-safety

    auto it = std::lower_bound(v.begin() + startIndex, v.end(), targetValue);
    if (it != v.end() && *it == targetValue) {
        *it += valueToAdd;
    } else {
        it = v.insert(it, targetValue); // Efficient insertion using lower_bound as hint for the iterator position
