```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <mutex>
#include <queue>
#include <memory>
#include <thread>

struct PHY_MEASUREMENT_RESULT {
    std::string measurementType;
    std::chrono::system_clock::time_point timestamp;
    int frequencyBand;
    double signalStrength, noiseLevel, interference;
};

class LteMeasurementList {
public:
    explicit LteMeasurementList(size_t maxSize, std::chrono::seconds retentionPeriod)
        : _maxSize(maxSize), _retentionPeriod(retentionPeriod), _cleanupThread() {
        _cleanupThread = std::thread(&LteMeasurementList::cleanup, this);
    }

    void addResult(const PHY_MEASUREMENT_RESULT& result) {
        auto key = std::make_pair(result.timestamp, result.frequencyBand);
        if (_results.find(key) != _results.end()) return; // already exists, do nothing

        if (_results.size() >= _maxSize) {
            LOG_ERROR("Exceeded maximum size, discarding data.");
            return;
        }

        std::unique_ptr<PHY_MEASUREMENT_RESULT> newResult(new PHY_MEASUREMENT_RESULT(result));
        _results[key] = std::move(newResult);
    }

private:
    void cleanup() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::unique_lock<std::mutex> lock(_mutex);
            auto it = _results.begin();
            auto end = _results.end();

            auto currentTime = std::chrono::system_clock::now();
            while (it != end && (currentTime - it->first.time_since_epoch()) > (_retentionPeriod.count() * 1e9)) {
                lock.unlock();
                it = _results.erase(it);
                lock.lock();
            }
        }
    }

    size_t _maxSize;
    std::chrono::seconds _retentionPeriod;
    std::unordered_map<std::pair<std::chrono::time_point<std::chrono::system_clock>, int>, std::unique_ptr<PHY_MEASUREMENT_RESULT>> _results;
    std::mutex _mutex;
    std::thread _cleanupThread;
};
