        new_node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        memcpy(new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU));
        current->next = new_node;
        new_node->next = NULL;
    }
    pthread_mutex_unlock(&list_mutex);

    // Validate RNTI uniqueness and log total CRCFLAG count for debugging
    list_node_t *current = head;
    while (current != NULL) {
