#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct MAC_PDU {
    unsigned long MAC_HEADER;
    char MACSDU[1024];
} MAC_PDU;

struct dynamic_array {
    MAC_PDU* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void init_dynamic_array(struct dynamic_array* da, size_t initial_capacity) {
    da->data = malloc(initial_capacity * sizeof(MAC_PDU));
    if (!da->data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

void resize_dynamic_array(struct dynamic_array* da) {
    MAC_PDU* temp = realloc(da->data, (da->capacity * 2) * sizeof(MAC_PDU));
    if (!temp) {
        perror("Memory allocation failed");
        return;
    }
    da->data = temp;
    da->capacity *= 2;
}

void create_PDU(MAC_PDU* pdu, unsigned long* sequence_number) {
    *sequence_number = (*sequence_number + 1) % ((unsigned long)1 << 32); // Increment sequence number modulo 4.29 billion to avoid overflow
    pdu->MAC_HEADER = *sequence_number;
    memset(pdu->MACSDU, rand(), sizeof(pdu->MACSDU));
}

void log_PDU(const MAC_PDU* pdu) {
    // Integrate with a logging framework here
    printf("MAC_HEADER: 0x%lx\n", pdu->MAC_HEADER);
    printf("MACSDU: ");
    for (size_t i = 0; i < sizeof(pdu->MACSDU); ++i) {
        printf("%c ", pdu->MACSDU[i]);
    }
    printf("\n");
}

void add_PDU_to_dynamic_array(struct dynamic_array* da, MAC_PDU* pdu) {
    pthread_mutex_lock(&da->mutex);

    if (da->size == da->capacity) {
        resize_dynamic_array(da);
    }

    memcpy(&da->data[da->size], pdu, sizeof(MAC_PDU));
    ++da->size;

    pthread_mutex_unlock(&da->mutex);
}

void manage_dynamic_array(struct dynamic_array* da) {
    // Handle external data sources here

    MAC_PDU pdu;
    unsigned long sequence_number;
    create_PDU(&pdu, &sequence_number);
    add_PDU_to_dynamic_array(da, &pdu);
    log_PDU(&pdu);
}
```
