                            var insertQuery = connection.CreateCommand($"{queryType} INTO {parameters["Table"]} {string.Join(", ", parameters.Keys.Select(k => $"{k} = @{k}"))}") as DbCommand;
                            await insertQuery.ExecuteNonQueryAsync(parameters);
                            if (idParameter != null)
                                idParameter.Value = ((IDbDataAdapter)insertQuery.CreateDataAdapter()).SelectCommand.Parameters[0].Value;
                            break;
                        case "UPDATE":
                            await connection.ExecuteAsync(connection.CreateCommand($"{queryType} FROM {parameters["Table"]} WHERE {parameters["Condition"]}", parameters));
                            break;
                        case "DELETE":
                            await connection.ExecuteAsync(connection.CreateCommand($"{queryType} FROM {parameters["Table"]} WHERE {parameters["Condition"]}", parameters));
                            break;
                    }

                    stopwatch.Stop();
                    _log.InfoFormat("Executed query: {0}, Time taken: {1}", queryType, stopwatch.Elapsed);
                }
            }
            catch (Exception ex)
            {
                if (retryAttempt < _maxRetries)
                {
                    retryAttempt++;
                    _log.ErrorFormat("Failed to execute query: {0}, Attempt: {1}", queryType, retryAttempt);
                    await Task.Delay(_retryDelay);
                    await ExecuteQueryAsync(queryType, parameters, setParameters);
                }
                else
                {
                    _log.ErrorFormat("Max retries reached for query: {0}, Exception: {1}", queryType, ex.Message);
                    throw;
                }
            }
        }

        // Logging service integration...

        public void Dispose()
        {
            _connection?.Dispose();
            _redisDatabase?.Dispose();
        }
    }
}
