typedef struct {
    RX_FRAME_HEADER header;
    subframe_t* subframes;
} NFAPI_RX_FRAME_PDU_T;

void initialize_rx_frame(NFAPI_RX_FRAME_PDU_T** frame, size_t max_subframes) {
    *frame = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    assert(*frame);
    (*frame)->subframes = calloc(max_subframes, sizeof(subframe_t));
    assert((*frame)->subframes);
}

void populate_rx_frame(NFAPI_RX_FRAME_PDU_T* frame, size_t num_subframes) {
    size_t total_payload = 0;

    for (size_t i = 0; i < num_subframes; ++i) {
        subframe_t* current_subframe = &((*frame)->subframes[i]);
        size_t random_bytes = rand() % 100 + 100;
        current_subframe->length = sizeof(RX_FRAME_HEADER) + random_bytes;
        current_subframe->data[0] = i; // Header field

        current_subframe->data[sizeof(RX_FRAME_HEADER)] = (uint8_t*) calloc(random_bytes, 1);
        assert(current_subframe->data[sizeof(RX_FRAME_HEADER)]);

        memcpy(current_subframe->data + sizeof(RX_FRAME_HEADER),
            current_subframe->data[sizeof(RX_FRAME_HEADER)] , random_bytes);

        total_payload += current_subframe->length;
    }

    // Calculate and store CRC checksum for the entire frame, including headers and payloads.
    uint32_t crc = calculate_crc(frame->data + sizeof(RX_FRAME_HEADER), total_payload - sizeof(RX_FRAME_HEADER));
    memcpy(&frame->header.crc, &crc, sizeof(crc));

    // If the total payload size exceeds the maximum threshold, free excess subframes and their data.
    if (total_payload > MAX_PAYLOAD_BYTES) {
        for (size_t i = num_subframes; i > 0; --i) {
            free(frame->subframes[i].data);
        }
        // Re-calculate the number of valid subframes and reallocate memory if needed.
        size_t new_num_subframes = (size_t)((MAX_PAYLOAD_BYTES - sizeof(RX_FRAME_HEADER)) / (sizeof(subframe_t) + sizeof(RX_FRAME_HEADER)));
        subframe_t* new_subframes = realloc((*frame)->subframes, new_num_subframes * sizeof(subframe_t));
        assert(new_subframes);
        (*frame)->subframes = new_subframes;
    }
}

void deinitialize_rx_frame(NFAPI_RX_FRAME_PDU_T* frame) {
    free((*frame)->subframes);
    free(*frame);
}
