#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    LTE_UPLINK_NAS_TRANSPORT transport;
    S1AP_UE_CONTEXT *ue_context;
    NAS_MESSAGE *nas_message;
    EPS_BEARER_CONTEXT *eps_bearer;
    pthread_mutex_t mutex;
    time_t created_at;
} bearer_t;

typedef struct {
    bearer_t **collection;
    size_t capacity;
    size_t size;
    pthread_mutex_t collection_mutex;
    malloc_pool_t *memory_pool;
    time_t idle_timeout;
    performance_logger_t *performance_logger;
} bearer_manager_t;

void destroy_bearer(bearer_t **bearer) {
    if (*bearer == NULL) return;

    pthread_mutex_destroy(&(*bearer)->mutex);
    free((*bearer)->ue_context);
    free((*bearer)->nas_message);
    free((*bearer)->eps_bearer);
    free(*bearer);
    *bearer = NULL;
}

void reset_bearer_manager(bearer_manager_t *manager) {
    size_t i;

    for (i = 0; i < manager->size; ++i) {
        destroy_bearer(&manager->collection[i]);
    }
    manager->size = 0;
}

void cleanup_bearers(bearer_manager_t *manager) {
    size_t i, j;
    time_t current_time = time(NULL);

    for (i = 0; i < manager->size; ) {
        if (current_time - manager->collection[i]->created_at >= manager->idle_timeout) {
            destroy_bearer(&manager->collection[i]);
            memmove(manager->collection + i, manager->collection + i + 1, --manager->size - i);
        } else {
            ++i;
        }
    }
}

void log_performance(const char *message, double time) {
    if (manager->performance_logger != NULL) {
        manager->performance_logger->log(message, time);
    }
}

bearer_t* create_bearer(s1ap_ue_context_t *ue_context, nas_message_t *nas_message, eps_bearer_context_t *eps_bearer) {
    bearer_t *new_bearer = malloc_from_pool(manager->memory_pool);
    if (new_bearer == NULL) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    pthread_mutex_init(&new_bearer->mutex, NULL);
    new_bearer->ue_context = s1ap_ue_context_clone(ue_context);
    if (new_bearer->ue_context == NULL) {
        destroy_bearer(&new_bearer);
        fprintf(stderr, "UE context cloning failure\n");
        return NULL;
    }
    new_bearer->nas_message = nas_message_clone(nas_message);
    if (new_bearer->nas_message == NULL) {
        destroy_bearer(&new_bearer);
        fprintf(stderr, "NAS message cloning failure\n");
        return NULL;
    }
    new_bearer->eps_bearer = eps_bearer_context_clone(eps_bearer);
    if (new_bearer->eps_bearer == NULL) {
        destroy_bearer(&new_bearer);
        fprintf(stderr, "EPS bearer context cloning failure\n");
        return NULL;
    }
    new_bearer->created_at = time(NULL);
    log_performance("Bearer initialization", time(NULL) - new_bearer->created_at);
    return new_bearer;
}

void initialize_and_configure_bearers(bearer_manager_t *manager, int num_bearers) {
    size_t i;
    bearer_t *new_bearer;

    for (i = 0; i < num_bearers && manager->size < manager->capacity; ++i) {
        new_bearer = create_bearer(/* S1AP UE Context and NAS message */);
        if (new_bearer == NULL) break;

        pthread_mutex_lock(&manager->collection_mutex);
        if (manager->size >= manager->capacity) {
            pthread_mutex_unlock(&manager->collection_mutex);
            destroy_bearer(&new_bearer);
            continue;
        }
        manager->collection[manager->size++] = new_bearer;
        pthread_mutex_unlock(&manager->collection_mutex);
    }

    if (i < num_bearers) {
        fprintf(stderr, "Error creating bearers: Out of memory\n");
    }
}
