    for (unsigned long i = 0; i < max_bearers && total_memory_usage + sizeof(LTE_UPLINK_NAS_TRANSPORT) + sizeof(EPS_Bearer_Context) <= max_memory_usage; ++i) {
        current = create_transport();
        if (current) {
            if (!head) {
                head = current;
            } else {
                current->next = head;
                head = current;
            }
        }
    }
}

void free_bearers(LTE_UPLINK_NAS_TRANSPORT **head) {
    LTE_UPLINK_NAS_TRANSPORT *current = *head;
    while (current) {
        LTE_UPLINK_NAS_TRANSPORT *next = current->next;
        delete_transport(&current);
        current = next;
    }
}

void init_synchro() {
    sem_init(&memory_lock, 0, 1);
    pthread_mutex_init(&log_lock, NULL);
}
```

