#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PDCP_PDU_T {
    uint32_t PDCP_SN;
    uint16_t PDCP_RLC_SN;
    uint8_t PDCP_SEQ_STATUS;
    uint8_t PDCP_RLC_STATUS;
};

#define MIN_SIZE 100
#define MAX_SIZE 10000
#define STEP_SIZE 100

struct pdcp_array {
    struct LTE_PDCP_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
};

void initialize(struct pdcp_array* arr, size_t N) {
    if (N < MIN_SIZE || N > MAX_SIZE) {
        N = ((size_t)(MAX_SIZE - MIN_SIZE)) / STEP_SIZE * STEP_SIZE;
    }
    arr->data = malloc(N * sizeof(struct LTE_PDCP_PDU_T));
    if (!arr->data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    pthread_mutex_init(&arr->mutex, NULL);
    arr->size = 0;
    arr->capacity = N;
}

void resize(struct pdcp_array* arr) {
    if (arr->size >= arr->capacity && arr->capacity < MAX_SIZE) {
        size_t new_capacity = arr->capacity + STEP_SIZE;
        if (new_capacity > MAX_SIZE) new_capacity = MAX_SIZE;
        struct LTE_PDCP_PDU_T* temp = realloc(arr->data, new_capacity * sizeof(struct LTE_PDCP_PDU_T));
        if (!temp) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(1);
        }
        arr->data = temp;
        arr->capacity = new_capacity;
    }
}

void add_pdu(struct pdcp_array* arr, const struct LTE_PDCP_PDU_T pdu) {
    pthread_mutex_lock(&arr->mutex);
    resize(arr);
    arr->data[arr->size] = pdu;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

void update_seq_status(struct pdcp_array* arr, uint32_t PDCP_SN, uint8_t status) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i].PDCP_SN == PDCP_SN) {
            arr->data[i].PDCP_SEQ_STATUS = status;
            break;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
}

const struct LTE_PDCP_PDU_T* get_pdu(const struct pdcp_array* arr, uint32_t PDCP_SN) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i].PDCP_SN == PDCP_SN) {
            return &arr->data[i];
        }
    }
    return NULL;
}

size_t count_retx(const struct pdcp_array* arr) {
    size_t retx = 0;
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i].PDCP_RLC_STATUS == RLC_RETRANSMISSION) {
            retx++;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return retx;
}
