extern bool is_valid_RNTI(uint16_t rnti);
extern bool is_valid_CRC_INDICATION_REL8_TAG(uint16_t tag);

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_NFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T** pList, size_t* pSize) {
    // Initialize random number generator and seed it with current time
    random_init();
    srand((unsigned int)time(NULL));

    // Allocate memory for the list and initialize its size to 0
    *pSize = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    // Reserve space for up to 10,000 elements with a reallocation factor of 2
    const size_t reserve_factor = 2;
    *pSize = 10000;
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*pSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Loop through the reserved elements, generating and populating each structure
    size_t index = 0;
    while (index < *pSize) {
        // Generate a valid RX_UE_INFORMATION_TAG
        uint8_t rx_ue_tag;
        do {
            rx_ue_tag = random_uint16_range(0, UINT8_MAX);
        } while (!is_valid_RX_UE_INFORMATION_TAG(rx_ue_tag));

        // Generate a valid RNTI that does not match the previous one (or the first one for the first iteration)
        uint16_t rnti;
        if (index > 0) {
            do {
                rnti = random_uint16_range(0, UINT16_MAX);
            } while (!is_valid_RNTI(rnti) || list[index - 1].RNTI == rnti || (index - 2 >= 0 && list[index - 2].RNTI == rnti));
        } else {
            rnti = random_uint16_range(0, UINT16_MAX);
        }

        // Generate a valid CRC_INDICATION_REL8_TAG with the CRCFLAG randomly set
        uint16_t crc_indication_tag;
        do {
            crc_indication_tag = random_uint16_range(0, UINT16_MAX);
        } while (!is_valid_CRC_INDICATION_REL8_TAG(crc_indication_tag));

        bool crcflag = rand() % 2 == 0;

        // Store the generated structure in the list and increment the index
        list[index].RX_UE_INFORMATION_TAG = rx_ue_tag;
        list[index].RNTI = rnti;
        list[index].CRC_INDICATION_REL8_TAG = crc_indication_tag;
        list[index].CRCFLAG = crcflag;
        index++;

        // If the current size is less than the reserved size and the list is full, reallocate more memory
        if (index == *pSize) {
            *pSize *= reserve_factor;
            list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list, *pSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
}
