#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* next;
} Node;

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
    }
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    return new_node;
}

void serialize_list(const char* filename, Node* head) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_list(const char* filename, Node** head) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    Node* current = NULL;
    Node* head_node = NULL;
    while (1) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation failed");
            break;
        }
        size_t read_bytes = fread(&new_node->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (read_bytes != 1) {
            free(new_node);
            break;
        }
        new_node->next = NULL;
        if (!head_node) {
            head_node = new_node;
            current = head_node;
        } else {
            current->next = new_node;
            current = current->next;
        }
    }
    fclose(file);
    *head = head_node;
}

void add_to_list(Node** head, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = create_node(pdu);
    if (!new_node) return;
    new_node->data.crcFlag = rand() % 2; // Set CRCFLAG randomly

    Node* current = *head;
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
}

Node* find_by_rnti(const Node* head, uint32_t rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) return current;
        current = current->next;
    }
    return NULL;
}

void remove_by_rnti(Node** head, uint32_t rnti) {
    Node* current = *head;
    if (current == NULL) return;

    if (current->data.rnti == rnti) {
        *head = current->next;
        free(current);
        return;
    }

    while (current->next != NULL && current->next->data.rnti != rnti) {
        current = current->next;
    }

    if (current->next == NULL) return;

    Node* temp = current->next;
    current->next = temp->next;
    free(temp);
}
```

