#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
static uint32_t max_pool_size = 0;
static uint32_t next_free_index = 0;
static pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t used_rntis[MAX_RNTI] = {0};

void init_pool(uint32_t size) {
    max_pool_size = size;
    pool = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!pool) {
        perror("Memory allocation failure");
        return;
    }

    for (uint32_t i = 0; i < max_pool_size; ++i) {
        pool[i].crc_tag.crcflag = rand() % 2;
        pool[i].rnti = generate_unique_rnti();
    }
}

uint32_t generate_unique_rnti() {
    pthread_mutex_lock(&rnti_mutex);

    uint32_t rnti;
    do {
        rnti = rand() % MAX_RNTI;
    } while (used_rntis[rnti]);

    used_rntis[rnti] = 1;
    pthread_mutex_unlock(&rnti_mutex);

    return rnti;
}

NFAPI_CRC_INDICATION_PDU_T *get_pdu() {
    pthread_mutex_lock(&pool_mutex);

    if (next_free_index >= max_pool_size) {
        // Handle memory exhaustion gracefully, e.g., by increasing the pool size or dropping requests
        perror("Pool exhaustion");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[next_free_index];
    next_free_index++;

    pthread_mutex_unlock(&pool_mutex);

    return pdu;
}
```

