        for (size_t i = 0; i < N; ++i) {
            list.emplace_back();
            list.back().CRCFLAG = rand() % 2;
        }
    }

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        auto it = rntiToIndex.find(pdu.RNTI);
        if (it != rntiToIndex.end()) {
            list[it->second] = pdu;
        } else {
            list.emplace_back(pdu);
            rntiToIndex[pdu.RNTI] = list.size() - 1;
        }
    }

    void removeByRNTI(uint16_t rnti) {
        auto it = rntiToIndex.find(rnti);
        if (it != rntiToIndex.end()) {
            size_t index = it->second;
            rntiToIndex.erase(it);
            list.erase(list.begin() + index);
        }
