        std::ofstream file(filename, std::ios::binary | std::ios::trunc);
        if (!file.is_open())
            throw std::runtime_error("Could not open file for writing");

        size_t numElements = list.size();
        file.write((char*)&numElements, sizeof(numElements));
        for (const auto& pdu : list) {
            file.write(reinterpret_cast<const char*>(&pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    void deserialize(const char *filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open())
            throw std::runtime_error("Could not open file for reading");

        size_t numElements;
        file.read((char*)&numElements, sizeof(numElements));

        list.clear();
        rntiToIndex.clear();
        for (size_t i = 0; i < numElements; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            file.read(reinterpret_cast<char*>(&pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list.emplace_back(pdu);
            rntiToIndex[pdu.RNTI] = list.size() - 1;
        }
    }
};
