struct PDCP_PDU { /* Define your structure here */ };

class PDUPool {
public:
    PDUPool(std::size_t bufferSize, std::size_t align = std::alignment_of<PDCP_PDU>::value)
        : buffer_(static_cast<std::uintptr_t>(std::align_val_t(0), bufferSize), align), pool_(buffer_) {}

    PDUPool(const PDUPool&) = delete;
    PDUPool& operator=(const PDUPool&) = delete;

    PDCP_PDU* allocate() {
        if (unused_.empty()) {
            void* p = ::operator new(sizeof(PDCP_PDU), std::align_val_t<std::uintptr_t>(buffer_, align_));
            new (p) PDCP_PDU(); // Construct in-place
            unused_.push_back(p);
        }
        auto p = unused_.back();
        unused_.pop_back();
        return static_cast<PDCP_PDU*>(p);
    }

    void deallocate(PDCP_PDU* p) noexcept {
        p->~PDCP_PDU(); // Destruct in-place
        unused_.push_back(static_cast<void*>(p));
    }

private:
    std::uintptr_t buffer_;
    std::vector<void*, aligned_allocator<void, align_>> unused_;
    std::aligned_storage_t<sizeof(PDCP_PDU), align_> pool_;
    static constexpr std::size_t align_ = alignof(PDCP_PDU);
};

