    int account_id;
    double amount;
    int transaction_id;
} Transaction;

// Global variables for sliding window and rate limiting
static sem_t txn_sem, log_sem; // Semaphores for rate limiting and logging
static pthread_mutex_t txn_window_lock; // Mutex for managing the sliding window
static size_t txn_window_size = 3; // Sliding window size: last 3 seconds of transactions
static size_t txns_in_window = 0; // Number of transactions in the current window
static Transaction *txn_window; // Dynamic array for the sliding window
static double avg_amount = 0.0; // Average transaction amount
static int max_id = INT32_MIN; // Maximum transaction ID
static double total_volume = 0.0; // Total transaction volume

// External logging service function prototype
void log_txn(Transaction txn);

// Function to process transactions, handle rate limiting and sliding window logic
void process_transaction(Transaction txn) {
    sem_wait(&txn_sem); // Wait if the rate limit is reached

    pthread_mutex_lock(&txn_window_lock);
    // Add transaction to the sliding window and update metrics
    txns_in_window++;
    total_volume += txn.amount;
    avg_amount = (total_volume / txns_in_window);
    if (txn.transaction_id > max_id) {
        max_id = txn.transaction_id;
    }
    // Remove transactions older than the sliding window size
    if (txns_in_window > txn_window_size) {
        size_t index = (txn_window_size - 1 + txns_in_window) % txns_in_window;
        total_volume -= txn_window[index].amount;
        txns_in_window--;
    }
    // Add new transaction to the window and shift other transactions
    if (txns_in_window < txn_window_size) {
        Transaction *new_txn_window = realloc(txn_window, sizeof(Transaction) * (txns_in_window + 1));
        if (!new_txn_window) {
            printf("Memory allocation error!\n");
            pthread_mutex_unlock(&txn_window_lock);
            return;
        }
        txn_window = new_txn_window;
        memcpy(txn_window + 1, txn_window, sizeof(Transaction) * txns_in_window);
        txn_window[0] = txn;
    }
    pthread_mutex_unlock(&txn_window_lock);

    // Process the transaction and log it if successful within 100 milliseconds
    struct timespec timeout;
    clock_gettime(CLOCK_MONOTONIC, &timeout);
    timeout.tv_sec += 0.1;
    if (pthread_equal(pthread_self(), pthread_main())) {
        log_txn(txn); // Main thread can log directly without rate limiting
    } else {
        struct timespec now;
        while (clock_gettime(CLOCK_MONOTONIC, &now) && (now.tv_sec - timeout.tv_sec < 0.1)) {}
        if (now.tv_sec - timeout.tv_sec >= 0.1) {
            sem_wait(&log_sem); // Wait if the logger is busy
            log_txn(txn);
            sem_post(&log_sem);
        }
    }

    sem_post(&txn_sem); // Signal that a transaction has been processed
}
