struct DataPacket {
    int id;
    size_t length;
    std::int64_t timestamp;
};

class DataPacketManager {
private:
    std::unordered_map<int, DataPacket*> packets_;
    mutex mtx_;

public:
    void addPacket(DataPacket packet) {
        // Perform additional checks to prevent out-of-memory conditions and ensure consistent state across threads.
        auto new_packet = new DataPacket(packet);
        std::unique_lock<mutex> lock(mtx_);
        packets_[new_packet->id] = new_packet;
    }

    DataPacket* getPacketById(int id) {
        std::unique_lock<mutex> lock(mtx_);
        auto it = packets_.find(id);
        if (it != packets_.end())
            return it->second;
        else
            return nullptr;
    }

    void updatePacketLength(int id, size_t new_length) {
        std::unique_lock<mutex> lock(mtx_);
        auto it = packets_.find(id);
        if (it != packets_.end()) {
            it->second->length = new_length;
            return;
        }
    }

    void enrichPacketMetadata(int id, std::function<void(DataPacket&)> enricher) {
        // Implement a thread-safe method for fetching external data asynchronously.
        auto packet = getPacketById(id);
        if (packet != nullptr) {
            enricher(*packet);
        } else {
            // Handle the case where the packet is not found and manage potential delays or failures gracefully.
        }
    }

    ~DataPacketManager() {
        std::unique_lock<mutex> lock(mtx_);
        for (auto& packet : packets_) {
            delete packet.second;
        }
        packets_.clear();
    }
};
