#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int id;
    size_t payload_length;
    time_t timestamp;
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} DataPacket;

typedef struct PacketQueue {
    DataPacket* packets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} PacketQueue;

void initHash(uint32_t* hash, uint32_t key) {
    hash[0] = key;
    for (size_t i = 1; i < sizeof(hash) / sizeof(hash[0]); ++i)
        hash[i] = (key + i) % ((sizeof(hash) / sizeof(hash[0])) - 1);
}

uint32_t hashFunction(uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    static uint32_t hash[sizeof(DataPacket) / sizeof(uint32_t)] = {0};
    initHash(hash, RX_UE_INFORMATION_TAG ^ RNTI);

    for (size_t i = 0; i < (sizeof(DataPacket) / sizeof(uint32_t)); ++i) {
        if (hash[i] == 0) continue;

        DataPacket* packet = &packets[hash[i]];
        if (packet->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            packet->RNTI == RNTI) return -1;
    }

    return 0;
}

PacketQueue* createPacketQueue(size_t initial_capacity) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->packets = (DataPacket*)calloc(initial_capacity, sizeof(DataPacket));
    if (!queue->packets) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

int insertPacket(PacketQueue* queue, DataPacket packet) {
    uint32_t hash_result = hashFunction(packet.RX_UE_INFORMATION_TAG, packet.RNTI);
    if (hash_result < 0) return -1; // Packet ID collision

    if (queue->count == queue->capacity) {
        DataPacket* old_packets = queue->packets;
        size_t new_capacity = queue->capacity * 2;
        queue->packets = (DataPacket*)realloc(old_packets, new_capacity * sizeof(DataPacket));
        if (!queue->packets) {
            free(old_packets);
            pthread_mutex_destroy(&queue->lock);
            free(queue);
            return -1; // Allocation failure
        }
        queue->capacity = new_capacity;
    }

    pthread_mutex_lock(&queue->lock);
    memcpy(&queue->packets[hash_result], &packet, sizeof(DataPacket));
    queue->count++;
    pthread_mutex_unlock(&queue->lock);

    return 0; // Successful insertion
}

DataPacket* findPacket(PacketQueue* queue, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    uint32_t hash_result = hashFunction(RX_UE_INFORMATION_TAG, RNTI);
    if (hash_result < 0) return NULL; // Packet ID not found

    pthread_mutex_lock(&queue->lock);
    DataPacket* packet = &queue->packets[hash_result];
    if (packet->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
        packet->RNTI == RNTI) {
        DataPacket* result = malloc(sizeof(DataPacket));
        memcpy(result, packet, sizeof(DataPacket));
        pthread_mutex_unlock(&queue->lock);
        return result; // Packet found
    }
    pthread_mutex_unlock(&queue->lock);
    return NULL; // Packet not found
}

void updatePacket(PacketQueue* queue, DataPacket packet) {
    uint32_t hash_result = hashFunction(packet.RX_UE_INFORMATION_TAG, packet.RNTI);
    if (hash_result < 0) return; // Packet ID collision

    pthread_mutex_lock(&queue->lock);
    memcpy(&queue->packets[hash_result], &packet, sizeof(DataPacket));
    pthread_mutex_unlock(&queue->lock);
}

void destroyPacketQueue(PacketQueue* queue) {
    free(queue->packets);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
```

This code implements a simple packet queue using dynamic memory allocation and a hash function to minimize memory fragmentation. The `DataPacket` structure stores the required fields, including a CRCFLAG that is randomly set for uniqueness and integrity. The `PacketQueue` struct manages an array of `DataPacket` structures, with support for insertion, retrieval, update operations, and dynamic resizing when necessary.

The function `hashFunction()` generates a hash based on the RX_UE_INFORMATION_TAG and RNTI fields to store packets in a more organized manner. The packet queue is thread-safe, utilizing a mutex lock to synchronize access between multiple network threads. Error handling is also implemented for potential failures during allocation or data retrieval processes.']

