typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
    uint8_t MD5Hash[MD5_DIGEST_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNfareports(int N) {
    NFAPI_CRC_INDICATION_PDU_T *reports = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);

    if (!reports) return NULL;

    time_t t;
    srand((unsigned)time(&t));

    for (int i = 0; i < N; ++i) {
        reports[i].RX_UE_INFORMATION_TAG = i + 1;
        reports[i].RNTI = rand() % 65536;
        reports[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        reports[i].CRCFLAG = (rand() & 1) + (rand() >> 4); // ensures CRCFLAG is always between 0 and 7

        char str[sizeof(NFAPI_CRC_INDICATION_PDU_T)];
        memcpy(str, &reports[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        SHA1((unsigned char *)str, sizeof(str), reports[i].MD5Hash);
    }

    return reports;
}
