#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <netstack_api.h> // Include the network stack API here

typedef struct {
    uint32_t rxi;
    uint16_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

int findLargest(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; ++i)
        if (arr[i] > max)
            max = arr[i];
    return max;
}

void* allocatePDUArray(int size) {
    void *arr = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!arr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return arr;
}

void populatePDUs(int* arr, int size, void* pdus) {
    int largest = findLargest(arr, size);
    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU *pdu = ((NFAPI_CRC_INDICATION_PDU*)pdus) + i;
        pdu->rxi = arr[i];
        pdu->rnti = largest - i; // Derive RNTI based on the index and largest integer
        pdu->crcflag = rand() % 2 == 0; // Set CRCFLAG randomly
    }
}

void sendPDUs(int size, void* pdus) {
    int retries = 3;
    while (size > 0 && retries > 0) {
        if (netstack_send_pdu(pdus, size) == NETSTACK_SUCCESS) {
            retries = 0;
            size -= sizeof(NFAPI_CRC_INDICATION_PDU);
        } else {
            --retries;
            printf("Failed to send PDU. Retrying...\n");
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to send PDU after retries.\n");
    }
}

int main() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; ++i) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", arr + i);
    }

    void *pdus = allocatePDUArray(n);
    populatePDUs(arr, n, pdus);
    sendPDUs(n, pdus);

    free(arr);
    free(pdus);
    return 0;
}
```

