class Event {
public:
    std::int64_t timestamp;
    std::string eventType;
    std::string messageBody;

    Event(std::int64_t ts, const std::string& et, const std::string& mb)
        : timestamp(ts), eventType(et), messageBody(mb) {}
};

class EventManager {
public:
    struct EventData {
        std::shared_ptr<Event> event;
        std::function<void()> onCompleteCallback;
    };

    void appendEvent(const Event& event, const std::function<void()>& onCompleteCallback);
    EventData getNextEvent();

private:
    std::deque<std::shared_ptr<Event>> events_;
    boost::circular_buffer<EventData> buffers_[10];
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic_int bufferIndex_{ 0 };

    void processBuffer();
};

void EventManager::appendEvent(const Event& event, const std::function<void()>& onCompleteCallback) {
    std::unique_lock<std::mutex> lock(mutex_);
    events_.push_back(std::make_shared<Event>(event));
    auto data = std::make_shared<EventData>();
    data->event = events_.back();
    data->onCompleteCallback = onCompleteCallback;

    cv_.notify_one();
}

EventManager::EventData EventManager::getNextEvent() {
    std::unique_lock<std::mutex> lock(mutex_);

    if (!events_.empty()) {
        auto event = events_.front();
        events_.pop_front();
        return std::make_shared<EventData>(event, [this](){processBuffer();});
    }

    int index = (bufferIndex_+1) % buffers_.size();
    while(buffers_[index].empty()) {
        lock.unlock();
        cv_.wait(lock);
        lock.lock();
        if (!events_.empty()) {
            auto event = events_.front();
            events_.pop_front();
            return std::make_shared<EventData>(event, [this](){processBuffer();});
        }
    }

    return buffers_[index].front();
    buffers_[index].pop_front();
}

void EventManager::processBuffer() {
    // Implement external data source integration with rate-limiting and handling delays.
    // Update bufferIndex_ and call notify_all to wake up all threads waiting on cv_.
}
