#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_RRC_CU_MSG {
    int tag; // Valid range for tag is [0, MAX_TAG]
    char* payload;
} LTE_RRC_CU_MSG;

const int MAX_TAG = 255;

pthread_mutex_t msg_factory_lock = PTHREAD_MUTEX_INITIALIZER;

// External message factory service callback function with error handling
typedef void* (*msg_factory_cb)(int tag);

void* msg_factory(int tag, msg_factory_cb cb) {
    pthread_mutex_lock(&msg_factory_lock);
    void* payload = cb(tag);
    if (!payload) {
        perror("Error creating message payload");
        pthread_mutex_unlock(&msg_factory_lock);
        return NULL;
    }
    pthread_mutex_unlock(&msg_factory_lock);
    return malloc(sizeof(LTE_RRC_CU_MSG) + strlen((char*)payload));
}

void init_dynamic_array(LTE_RRC_CU_MSG** array, int size, msg_factory_cb cb) {
    *array = calloc(size, sizeof(LTE_RRC_CU_MSG));
    if (!*array) {
        perror("Error allocating memory for dynamic array");
        return;
    }

    pthread_t thread;
    for (int i = 0; i < size; ++i) {
        // Create and join a new thread for each message, to minimize the impact of service timeouts
        int rc = pthread_create(&thread, NULL, msg_factory, i, cb);
        if (rc) {
            perror("Error creating thread");
            continue;
        }

        pthread_join(thread, *array + i);

        // Validate the message tag and handle allocation failures gracefully
        if ((*array + i)->tag >= MAX_TAG || !(*array + i)->payload) {
            free((*array + i)->payload);
            free(*array + i);
            (*array + i) = NULL;
        }
    }
}
```
