['```c
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint16_t nei;
    uint16_t ani;
    uint32_t sci;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* mem_pool = NULL;
pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* mem_alloc(size_t size) {
    pthread_mutex_lock(&mem_pool_lock);
    MemBlock* current = mem_pool;
    MemBlock* new_block = NULL;

    if (!current) {
        new_block = malloc(sizeof(MemBlock));
        new_block->size = size;
        new_block->next = NULL;
        mem_pool = new_block;
    } else {
        while (current->next && current->next->size >= size)
            current = current->next;

        if (!current->next) {
            current->next = malloc(sizeof(MemBlock));
            current->next->size = size;
            current->next->next = NULL;
        }

        new_block = current->next;
        current->next = new_block->next;
    }

    void* data = new_block->data;
    memset(data, 0, size);
    pthread_mutex_unlock(&mem_pool_lock);

    return data;
}

void create_and_populate_array(NFAPI_CRC_INDICATION_PDU_T** array, unsigned int N) {
    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&mem_pool_lock);
    MemBlock* current = mem_pool;
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    for (unsigned int i = 0; i < N; ++i) {
        if (!current || current->size < block_size) {
            current = mem_alloc(block_size);
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = current->data;
        *pdu = (NFAPI_CRC_INDICATION_PDU_T){ .rx_tag = (RX_UE_INFORMATION_TAG)i,
                                             .rnti = i,
                                             .crc_indication = (CRC_INDICATION_REL8_TAG){ .crcflag = rand() % 2 },
                                             .nei = i + 100,
                                             .ani = i * 5 + 20,
                                             .sci = ((uint32_t)time(NULL) + i) & ((1 << 32) - 1) };
        current = current->next;
    }
    pthread_mutex_unlock(&mem_pool_lock);
}
```
