NFAPI_CRC_INDICATION_PDU_T* create_node() {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
    }

    new_node->tag = get_ue_information_tag();
    new_node->rnti = get_rnti();
    new_node->crc_indication.length = sizeof(new_node->crcflag);
    new_node->crc_indication.data = &new_node->crcflag;

    // Ensure no two consecutive nodes have the same CRCFLAG value
    do {
        new_node->crcflag = rand() % 2;
    } while (new_node->next && new_node->next->crcflag == new_node->crcflag);

    new_node->next = NULL;

    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *current = *head;

    while (current->next != NULL && current->next->crcflag == new_node->crcflag) {
        current = current->next;
    }

    new_node->next = current->next;
    current->next = new_node;
}

