typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    unsigned char crcflag;
    int metadata; // To store the count of successfully allocated structures
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_count = 0;
static size_t max_memory_limit = 1000000; // Set your own MAX_MEMORY limit here

NFAPI_CRC_INDICATION_PDU_T* allocate_array(size_t n) {
    if (n == 0 || max_memory_limit - sizeof(NFAPI_CRC_INDICATION_PDU_T) * allocated_count < sizeof(NFAPI_CRC_INDICATION_PDU_T) * n) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = realloc(allocated_count > 0 ? allocated_count : NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!data) {
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);
    allocated_count += n;
    for (size_t i = allocated_count - n; i < allocated_count; ++i) {
        data[i].metadata = i + 1; // Update metadata field with the count of successfully allocated structures
        data[i].crcflag = rand() % 2;
    }
    pthread_mutex_unlock(&memory_lock);

    return data;
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    if (!data || !count) {
        return;
    }

    pthread_mutex_lock(&memory_lock);
    allocated_count -= count;
    for (size_t i = 0; i < count; ++i) {
        data[i].metadata = 0; // Reset metadata field when deallocating
    }
    pthread_mutex_unlock(&memory_lock);

    free(data);
}
