    // Delay handling potential delays in firmware installation.
    bool is_firmware_installed = false;
    if (!nfapi_check_firmware_version(handle)) {
        printf("Waiting for firmware installation...\n");
        sleep(60); // Assuming a firmware update takes about 1 minute. Adjust as needed.
        is_firmware_installed = nfapi_check_firmware_version(handle);
    }

    if (is_firmware_installed) {
        // Configure the network interface parameters.
        rx_frame_config.max_frames_per_burst = 128; // Optimized for high throughput under peak loads.
        rx_queue_config.num_buffers = 4096; // Balance between cache usage and memory allocation to improve performance.
        rx_queue_config.buffer_size = 1518; // Maximum expected Ethernet frame size (1500 bytes + overhead).

        // Create a dynamically allocated list of NFAPI_RX_FRAME structures.
        void** rx_frames = malloc(sizeof(void*) * rx_queue_config.num_buffers);
        if (!rx_frames) {
            printf("Failed to allocate memory for RX frames.\n");
            return false;
        }

        // Allocate buffers for each frame and populate RF_RX_FRAME_INFO and RX_FRAME_SYNC_TAG data.
        for (size_t i = 0; i < rx_queue_config.num_buffers; ++i) {
            rx_frames[i] = malloc(rx_queue_config.buffer_size);
            if (!rx_frames[i]) {
                printf("Failed to allocate buffer for RX frame #%zu.\n", i);
                return false;
            }

            // Initialize RF_RX_FRAME_INFO and RX_FRAME_SYNC_TAG data.
            RF_RX_FRAME_INFO* rx_frame_info = (RF_RX_FRAME_INFO*)rx_frames[i];
            rx_frame_info->buffer = rx_frames[i];
            rx_frame_info->buffer_size = rx_queue_config.buffer_size;
            rx_frame_info->sync_tag = i;
        }

        // Configure the RX queue with the prepared frames and parameters.
        bool result = nfapi_rx_queue_configure(handle, &rx_queue_config, rx_frames);
        if (!result) {
            printf("Failed to configure RX queue.\n");
            return false;
        }

        // Monitor memory usage and implement periodic garbage collection if necessary.
        // (Not included in this example due to complexity and platform-specific considerations.)
    } else {
        printf("Firmware update failed. Cannot initialize network interface.\n");
    }

    return is_firmware_installed;
}
