void create_and_populate_list(int N, const char *hostname, NFAPI_CRC_INDICATION_PDU_T **list) {
    int status;
    struct hostent *he;
    struct in_addr **addr_list;

    pthread_t threads[N];
    NFAPI_CRC_INDICATION_PDU_T *data_arr[N];

    // Resolve the hostname to IP address
    he = gethostbyname(hostname);
    if (he == NULL) {
        custom_log(LOG_ERROR, "DNS resolution failed");
        *list = NULL;
        return;
    }
    addr_list = (struct in_addr **)he->h_addr_list;

    // Allocate memory for the list and data structures
    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        custom_log(LOG_ERROR, "Memory allocation failed");
        return;
    }
    data_arr[0] = *list;

    // Create and populate list elements in parallel threads
    for (int i = 1; i < N; ++i) {
        data_arr[i] = &(*list)[i - 1];
        status = pthread_create(&threads[i], NULL, [=]() {
            // Populate the current data structure with random values and set CRCFLAG based on a random number generator
            RX_UE_INFORMATION_TAG tag = rand() % MAX_RX_UE_INFORMATION_TAG;
            RNTI rnti = rand() % MAX_RNTI;
