typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    unsigned long access_count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct listnode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct listnode *next;
} ListNode;

static ListNode *head = NULL;
static unsigned int num_entries = 0;
static const unsigned int MAX_ENTRIES = 10000;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t access_log_mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned long *access_log = malloc(MAX_ENTRIES * sizeof(unsigned long));

void init_list() {
    if (head) return;

    head = malloc(sizeof(ListNode));
    if (!head) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    head->next = NULL;
}

void destroy_list() {
    ListNode *current, *next;

    pthread_mutex_lock(&list_mutex);

    current = head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
    num_entries = 0;

    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T *get_entry_by_rnti(int rnti) {
    ListNode *current = head->next;
    NFAPI_CRC_INDICATION_PDU_T *data = NULL;

    pthread_mutex_lock(&list_mutex);

    while (current != NULL) {
        if (current->data->rnti == rnti) {
            data = current->data;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    return data;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    ListNode *new_node, *current = head;

    pthread_mutex_lock(&list_mutex);

    if (num_entries >= MAX_ENTRIES) {
        perror("List is full");
        goto unlock;
    }

    new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        perror("Memory allocation failure");
        goto unlock;
    }

    new_node->data = entry;
    new_node->next = NULL;

    while (current->next != NULL) {
        current = current->next;
    }

    current->next = new_node;
    num_entries++;

unlock:
    pthread_mutex_unlock(&list_mutex);
}

void remove_entry(int rnti) {
    ListNode *current = head, *prev;

    pthread_mutex_lock(&list_mutex);

    while (current != NULL && current->data->rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        perror("Entry not found");
        goto unlock;
    }

    prev->next = current->next;
    free(current);
    num_entries--;

unlock:
    pthread_mutex_unlock(&list_mutex);
}

void log_access(int rnti) {
    unsigned long *index = access_log + rnti;

    pthread_mutex_lock(&access_log_mutex);
    (*index)++;
    pthread_mutex_unlock(&access_log_mutex);
}

void log_stats() {
    unsigned int i, total_accesses = 0;
    for (i = 0; i < MAX_ENTRIES; ++i) {
        total_accesses += access_log[i];
    }

    printf("Total accesses: %lu\n", total_accesses);
}
```

