```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

typedef struct {
    char *str;
    int id;
} node_t;

size_t aligned_alloc(size_t size, size_t alignment) {
    void *p;
    if (posix_memalign(&p, alignment, size)) {
        return 0;
    }
    return p;
}

void* malloc_trim(size_t size) {
    char *ptr = malloc(size + sysconf(_SC_PAGE_SIZE));
    memset((char*)ptr + size, 0, sysconf(_SC_PAGE_SIZE) - size);
    return ptr;
}

int allocate_nodes(node_t **nodes, size_t num, size_t max, size_t init_len) {
    if (num > max) {
        return 1;
    }

    *nodes = malloc_trim(sizeof(node_t) * num);
    node_t* current_node = *nodes;

    for (size_t i = 0; i < num; ++i) {
        current_node[i].id = i + 1;
        current_node[i].str = aligned_alloc(init_len, alignof(char));
        if (!current_node[i].str) {
            // handle error and free allocated memory here
            return 1;
        }
        memset(current_node[i].str, 'a', init_len);
        current_node[i].str[init_len] = '\0';
        ++current_node;
    }

    return 0;
}

void deallocate_nodes(node_t *nodes, size_t num) {
    for (size_t i = 0; i < num; ++i) {
        free(nodes[i].str);
    }
    free(nodes);
}
