} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t num_elements;
    NFAPI_CRC_INDICATION_PDU_T *data;
} PDUList;

PDUList* create_pdulist(size_t num_elements) {
    PDUList *list = mmap(NULL, sizeof(PDUList), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    list->num_elements = num_elements;
    list->data = calloc(num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void populate_pdus(PDUList *list) {
    for (size_t i = 0; i < list->num_elements; ++i) {
        list->data[i].RX_UE_INFORMATION_TAG = i;
        list->data[i].RNTI = i % 256;
        list->data[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void log_creation(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] - %s\n", time_string, message);
}

void add_pdu_to_list(PDUList *list) {
    pthread_mutex_lock(&list->lock);
    list->data[list->num_elements++] = (NFAPI_CRC_INDICATION_PDU_T) { .RX_UE_INFORMATION_TAG = list->num_elements,
                                                                     .RNTI = list->num_elements % 256,
                                                                     .CRC_INDICATION_REL8_TAG = rand() % 2 };
    pthread_mutex_unlock(&list->lock);
}

// Assuming you have an external data source function get_data() that returns a pointer to a buffer of size BUFFER_SIZE
void integrate_external_data(PDUList *list, const void *buffer, size_t buffer_size) {
    if (buffer_size > 0 && buffer != NULL) {
        pthread_mutex_lock(&list->lock);
        for (size_t i = 0; i < buffer_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
            list->data[list->num_elements++] = *((NFAPI_CRC_INDICATION_PDU_T *) ((char *)buffer + (i * sizeof(NFAPI_CRC_INDICATION_PDU_T))));
        }
        pthread_mutex_unlock(&list->lock);
    }
}

