int populate_list(cb_t& list, size_t initial_size, size_t max_structures, std::function<void(const char*)> log) {
    static thread_local std::default_random_engine generator; // thread-bound engine for random number generation
    static thread_local std::uniform_int_distribution<> rnti_dist(0, max_structures - 1);
    static thread_local std::uniform_int_distribution<> crcflag_dist(0, 1);

    list.reserve(initial_size);

    for (size_t i = 0; i < max_structures; ++i) {
        rnti_t rnti = rnti_dist(generator); // generate RNTI value
        NFAPI_CRC_INDICATION_PDU_T pdu;
