        pdu.rnti = rnti; // set RNTI value
        pdu.crc_indication_rel8_tag.crcflag = crcflag_dist(generator); // set CRCFLAG value

        while (list.size() >= list.capacity()) { // check if buffer is full
            std::this_thread::yield();
        }

        if (!list.push_back(pdu)) { // try to push new PDU onto the buffer
            rnti_t conflicting_rnti = pdu.rnti;
            log("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure with RNTI " + std::to_string(conflicting_rnti) + "\n");
            ++g_error_count;
            continue;
        }

        // validate RNTI uniqueness using a lock-free data structure
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == pdu) {
                rnti_t conflicting_rnti = pdu.rnti;
                log("Error: Duplicate RNTI value " + std::to_string(conflicting_rnti) + "\n");
                ++g_error_count;
                it = list.erase(it); // remove duplicate PDU from the buffer
            } else {
                ++it;
            }
        }
    }

    log_performance();

    if (g_error_count > 0) {
        return -1;
    }
    return 0;
}
