};

typedef struct UE_Session_Data {
    uint32_t UE_ID;
    enum RRC_Connection_Status RRC_Connection_Status;
    struct Measurement_Report* head_measurement;
    pthread_mutex_t mutex;
    time_t creation_time;
} UE_Session_Data;

UE_Session_Data* create_ue_session(uint32_t id, enum RRC_Connection_Status status) {
    UE_Session_Data* new_ue = malloc(sizeof(UE_Session_Data));
    if (!new_ue) return NULL;

    pthread_mutex_init(&new_ue->mutex, NULL);
    new_ue->UE_ID = id;
    new_ue->RRC_Connection_Status = status;
    new_ue->head_measurement = NULL;
    new_ue->creation_time = time(NULL);

    return new_ue;
}

void destroy_ue_session(UE_Session_Data* ue) {
    free(ue);
}

void push_measurement(UE_Session_Data* ue, time_t timestamp, int cell_id, int signal_strength) {
    pthread_mutex_lock(&ue->mutex);

    struct Measurement_Report* new_report = malloc(sizeof(struct Measurement_Report));
    if (!new_report) goto unlock_and_return;

    new_report->timestamp = timestamp;
    new_report->cell_id = cell_id;
    new_report->signal_strength = signal_strength;
    new_report->next = ue->head_measurement;
    ue->head_measurement = new_report;

unlock_and_return:
    pthread_mutex_unlock(&ue->mutex);
}

UE_Session_Data* find_session(UE_Session_Data** session_list, uint32_t id) {
    for (UE_Session_Data* ue = *session_list; ue != NULL; ue = ue->next) {
        if (ue->UE_ID == id) return ue;
    }

    return NULL;
}

void resize_session_array(UE_Session_Data** session_list, size_t new_capacity) {
    UE_Session_Data** new_session_list = realloc(*session_list, new_capacity * sizeof(UE_Session_Data*));
    if (!new_session_list) return; // handle error and return

    memset(new_session_list + old_capacity, 0, (new_capacity - old_capacity) * sizeof(UE_Session_Data*));
    *session_list = new_session_list;
}

void cleanup_outdated_reports(UE_Session_Data** session_list, time_t current_time, time_t expiration_threshold) {
    for (UE_Session_Data* ue = *session_list; ue != NULL; ) {
        UE_Session_Data* next_ue = ue->next;

        if ((current_time - ue->creation_time) > expiration_threshold) {
            destroy_ue_session(ue);
            ue = next_ue;
            continue;
        }

        pthread_mutex_lock(&ue->mutex);
        UE_Session_Data* head = ue;
        struct Measurement_Report* current = head->head_measurement;
        while (current != NULL) {
            if ((current->timestamp + EXPIRATION_THRESHOLD_IN_SECONDS) < current_time) {
                UE_Session_Data* temp_ue = current;
                current = current->next;
                free(temp_ue);
            } else {
                break;
            }
        }
        pthread_mutex_unlock(&ue->mutex);

        ue = next_ue;
    }
}
