```cpp
#include <vector>
#include <deque>
#include <chrono>
#include <mutex>
#include <thread>
#include <atomic>

struct UE_Session_Data {
    int UE_ID;
    int RRC_Connection_Status;
    struct Measurement_Report {
        std::tm timestamp; // Represent the timestamp as a C++ standard library time object. You may need to convert it to your desired format.
        int cellID;
        double signalStrength;
        std::array<double, 2> locationCoordinates;
        int networkLoadMetrics;
    }* measurements; // Dynamically allocated list of Measurement_Reports
};

class UE_DataContainer {
private:
    std::vector<UE_Session_Data> data;
    int expirationThreshold;
    std::mutex mtx;
    std::atomic<bool> isRunning;
    std::thread cleanupThread;

public:
    UE_DataContainer(int threshold) : expirationThreshold(threshold), isRunning(true) {}

    ~UE_DataContainer() {
        isRunning = false;
        if (cleanupThread.joinable()) {
            cleanupThread.join();
        }
    }

    void startCleanup() {
        if (!cleanupThread.joinable()) {
            cleanupThread = std::thread([this](){
                while(isRunning) {
                    clearOutdatedData();
                    std::this_thread::sleep_for(std::chrono::milliseconds(1000)); // Adjust sleep duration as needed
                }
            });
        }
    }

    void pushData(const UE_Session_Data& data) {
        std::lock_guard<std::mutex> lock(mtx);
        data.measurements = new Measurement_Report[1]; // Dynamically allocate memory for a single measurement
        this->data.push_back(data);
    }

    UE_Session_Data* getLatestData(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(this->data.begin(), this->data.end(), [id](const UE_Session_Data& d){ return d.UE_ID == id; });
        if (it != this->data.end()) {
            return &*it;
        }
        return nullptr;
    }

    void clearOutdatedData() {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = this->data.begin();
        while (it != this->data.end()) {
            if ((std::chrono::system_clock::now().time_since_epoch().count() - it->timestamp.tm_sec) > expirationThreshold) {
                delete[] it->measurements; // Deallocate memory for outdated measurements
                it = this->data.erase(it);
            } else {
                ++it;
            }
        }
    }
};
```

