        list->data = new_data;
        list->capacity = new_capacity;
    }
    pthread_mutex_lock(&list->mutex);
    memcpy(&list->data[list->len], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->len++;
    pthread_mutex_unlock(&list->mutex);
}

const NFAPI_CRC_INDICATION_PDU_T* dynamic_list_at(const struct dynamic_list* list, size_t index) {
