void destroyList(Node** head) {
    Node* current = *head;
    Node* nextNode;

    pthread_mutex_lock(&listMutex);

    while (current != NULL) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    *head = NULL;

    pthread_mutex_unlock(&listMutex);
}

int appendToList(Node** head, const NFAPI_CRC_INDICATION_PDU* data) {
    Node* newNode = createNode(data->tag, data->rnti, data->crcIndication);
