void initRNTICache(RNTICache *cache, size_t capacity) {
    cache->lock = PTHREAD_MUTEX_INITIALIZER;
    cache->capacity = capacity;
    cache->count = 0;
    cache->cache = calloc(capacity, sizeof(unsigned long));
