} List_t;

List_t* create_list(unsigned int max_cache_size, const char* serialization_path, unsigned int serialization_frequency) {
    // Allocate and initialize the list structure
    List_t *list = malloc(sizeof(List_t));
    if (!list) {
        perror("Memory allocation failed.");
        return NULL;
    }
    list->head = NULL;
    list->size = 0;
    list->capacity = 0;
    list->max_cache_size = max_cache_size;
    list->cache_size = 0;
    list->serialization_path = serialization_path;
    list->serialization_frequency = serialization_frequency;
    list->last_save_time = 0;
    pthread_mutex_init(&list->list_mutex, NULL);
    pthread_mutex_init(&list->cache_mutex, NULL);
    pthread_cond_init(&list->cache_cond, NULL);
    list->cache = malloc(max_cache_size * sizeof(Node*));
    if (!list->cache) {
        perror("Memory allocation for cache failed.");
        free(list);
        return NULL;
    }
    return list;
}

void destroy_list(List_t *list) {
    // Free all allocated memory and clean up resources
    if (list->head) {
        Node *current = list->head, *next;
        while (current) {
            next = current->data.next;
            free(current);
            current = next;
        }
        list->head = NULL;
        list->size = 0;
    }
    if (list->cache) {
        free(list->cache);
        list->cache = NULL;
    }
    pthread_mutex_destroy(&list->list_mutex);
    pthread_mutex_destroy(&list->cache_mutex);
    pthread_cond_destroy(&list->cache_cond);
    free(list);
}

Node_t* create_node(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    Node_t *new_node = malloc(sizeof(Node_t));
    if (!new_node) {
