    new_node->rx_ue_information = rx_ue_information;
    new_node->rnti = rnti;
    new_node->crc_indication.CRCFLAG = rand() % 2; // Set CRC flag randomly
    new_node->next = NULL;
    return new_node;
}

Node* populate_list(List_t *list, void filter_fn(const Node_t* node), size_t num_nodes) {
    if (num_nodes > list->capacity) {
        grow_list(list, num_nodes);
    }
    for (size_t i = 0; i < num_nodes; ++i) {
        Node *current = list->head;
        Node *prev = NULL;

        // Filter the structures based on the provided function
        if (filter_fn) {
            while (current && !filter_fn(current->data)) {
                prev = current;
                current = current->next;
            }
        } else {
            while (current) {
                prev = current;
                current = current->next;
            }
        }

        if (!current) { // Create a new node if there's no suitable one available
            Node_t *new_node = create_node(RX_UE_INFORMATION_TAG_example, RNTI_example, CRC_INDICATION_REL8_TAG_example);
            if (prev) {
                prev->next = new_node;
            } else {
                list->head = new_node;
            }
        }
    }
    return list->head;
}

void grow_list(List_t *list, size_t new_capacity) {
    if (new_capacity > list->capacity) {
        Node **nodes = realloc(list->cache, new_capacity * sizeof(Node*));
        if (!nodes) {
            perror("Memory allocation failed.");
            return;
        }
        list->cache = nodes;
        list->capacity = new_capacity;
    }
