static inline size_t next_power_of_two(size_t value) {
    size_t result = 1;

    while (result < value) result *= 2;

    return result;
}

void nfapi_dynamic_list_resize(NFAPI_DYNAMIC_LIST* list, size_t new_capacity) {
    if (new_capacity <= list->length) return;

    NFAPI_CRC_INDICATION_PDU_T* tmp = realloc(list->data, next_power_of_two(new_capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tmp) {
        pthread_mutex_destroy(&list->lock);
        free(list);
        return;
    }

    list->data = tmp;
    list->capacity = new_capacity;
}

void nfapi_dynamic_list_push_back(NFAPI_DYNAMIC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
