    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    Node** list;
    size_t capacity, size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} DynamicList;

DynamicList* create_dynamic_list(size_t N) {
    DynamicList* list = malloc(sizeof(DynamicList));
    list->capacity = N;
    list->size = 0;
    list->list = calloc(N, sizeof(Node*));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->not_full, PTHREAD_COND_INITIALIZER);
    pthread_cond_init(&list->not_empty, PTHREAD_COND_INITIALIZER);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        free(list->list[i]);
    }
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->not_full);
    pthread_cond_destroy(&list->not_empty);
    free(list);
}

Node* create_node() {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    node->data.crc_indication.crcflag = rand() % 2;
    node->next = NULL;
    return node;
}

void add_node(DynamicList* list, Node* node) {
    pthread_mutex_lock(&list->mutex);
    while (list->size == list->capacity && !list->list[list->size - 1]) {
        pthread_cond_wait(&list->not_full, &list->mutex);
    }
    if (!list->list[list->size]) {
        list->list[list->size] = node;
        ++list->size;
        if (list->size == list->capacity / 4)
            resize(list);
        pthread_cond_signal(&list->not_empty);
    }
    pthread_mutex_unlock(&list->mutex);
}

void resize(DynamicList* list) {
    size_t new_capacity = list->capacity * 2;
    Node** new_list = realloc(list->list, new_capacity * sizeof(Node*));
    if (!new_list) return;
    memcpy(new_list + list->capacity, list->list, list->size * sizeof(Node*));
    free(list->list);
    list->list = new_list;
    list->capacity = new_capacity;
}

