int load_resource_bundle(const char *file_path, size_t *num_items) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        perror("Error opening file");
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    size_t file_size = ftell(fp);
    rewind(fp);

    void *bundle = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    if (bundle == MAP_FAILED) {
        perror("Error mapping file");
        fclose(fp);
        return 2;
    }

    size_t num_loaded = 0;
    CacheNode *cache = NULL;
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    while (num_loaded < file_size) {
        pdu = (NFAPI_CRC_INDICATION_PDU_T *)((char *)bundle + num_loaded);

