        if (!isValidCRCIndication(pdu->crc_ind)) {
            continue;
        }

        pthread_mutex_init(&pdu->lock, NULL);
        CacheNode *node = malloc(sizeof(CacheNode));
        if (!node) {
            perror("Error allocating cache node");
            goto error;
        }

        node->data = pdu;
        node->len = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        node->next = NULL;
        node->priority = getPriority(pdu->tag);

        if (!cache) {
            cache = node;
        } else {
            CacheNode *current = cache;
            while (current->next) {
                current = current->next;
            }
            current->next = node;
        }

        num_loaded += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    fclose(fp);
    *num_items = num_loaded / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return 0;

error:
    if (bundle) {
        munmap(bundle, file_size);
    }
    if (fp) {
        fclose(fp);
    }
    free(cache);
    return 3;
}

// Implement isValidCRCIndication(), getPriority(), and logging mechanism here.
