    msgs = allocate_messages(num_messages);
    if (!msgs)
        return 1;

    // Launch worker threads to add messages concurrently
    for (size_t i = 0; i < num_messages; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))add_message, (void *)msgs);
    }

    // Wait for all threads to finish their work
    for (size_t i = 0; i < num_messages; ++i) {
        pthread_join(threads[i], NULL);
    }

