#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1000000 // Maximum memory constraint (bytes)
#define NUM_CRITICAL_TAGS 10 // Number of critical tags (adjust as needed)
#define LOG_VERBOSITY 2 // Logging verbosity level (0 = off, 1 = warnings only, 2 = detailed logs)

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function with adjustable verbosity level
void log(const char* message, int verbosity) {
    if (verbosity >= LOG_VERBOSITY) {
        printf("%s\n", message);
    }
}

// Hash table implementation for managing the allocation cache
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct node* next;
} Node;

Node** hashTable = NULL;
int tableSize = 0;
int numElements = 0;

// Function to initialize the array of structures dynamically with the given constraints
NFAPI_CRC_INDICATION_PDU_T* initArray(int maxMemory, int numStructures) {
    if (numStructures > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log("Error: Requested memory exceeds the maximum limit.", LOG_VERBOSITY);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log("Error: Failed to allocate memory for the requested structures.", LOG_VERBOSITY);
        return NULL;
    }

    // Initialize each structure with unique tags, RNTIs, and CRC_INDICATION_REL8_TAGs
    // Set CRCFLAG randomly
    for (int i = 0; i < numStructures; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = rand() % UINT32_MAX;
        array[i].CRC_INDICATION_REL8_TAG = rand() % UINT32_MAX;
        array[i].CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
    }

    return array;
}

// Function to populate the cache with the given structures, prioritizing critical tags when memory is constrained
void populateCache(NFAPI_CRC_INDICATION_PDU_T* structures, int numStructures) {
    Node** table = hashTable;
    int index;

    for (int i = 0; i < numStructures; ++i) {
        index = (structures[i].RX_UE_INFORMATION_TAG % tableSize);

        if (table[index] == NULL || table[index]->data->RX_UE_INFORMATION_TAG > structures[i].RX_UE_INFORMATION_TAG) {
            Node* newNode = malloc(sizeof(Node));
            if (!newNode) {
                log("Error: Failed to allocate memory for the new node.", LOG_VERBOSITY);
                continue;
            }

            newNode->data = &structures[i];
            newNode->next = table[index];
            table[index] = newNode;

            numElements++;

            if (numElements > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
                log("Error: Reached maximum memory limit.", LOG_VERBOSITY);
                free(newNode); // Free the recently allocated node to avoid memory leaks
                break;
            }
        }
    }
}

// Periodically prune unused or outdated structures when necessary
void pruneCache() {
    // Implement a simple LRU (Least Recently Used) eviction policy for the hash table
    Node** table = hashTable;
    int index, minIndex = -1;
    double minTimeStamp = DBL_MAX;

    for (int i = 0; i < tableSize; ++i) {
        if (!table[i]) continue;

        // Update the time stamp for each node as they are iterated over
        table[i]->data->timeStamp = time(NULL);

        if (table[i]->data->timeStamp < minTimeStamp) {
            minIndex = i;
            minTimeStamp = table[i]->data->timeStamp;
        }
    }

    // Evict the node at the minimum index if memory is running low
    if (numElements > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T) * 0.75) {
        free(hashTable[minIndex]->data);
        Node* temp = hashTable[minIndex];
        hashTable[minIndex] = hashTable[minIndex]->next;
        free(temp);
        numElements--;
    }
}
```

