    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int find_available_RNTI(Node** list, int max_list_size, int current_count) {
    if (current_count == 0 || max_list_size < INT_MAX) {
        for (int i = 1; i <= max_list_size; ++i) {
            if (!check_RNTI_exists(list, i)) return i;
        }
    }
    return -1; // RNTI not found, list is full or out of range
}

bool check_RNTI_exists(Node** list, int rnti) {
    for (Node* current = *list; current != NULL; current = current->next) {
        if (current->data.RNTI == rnti) return true;
    }
    return false;
}

void populate_list(Node** list, int n, int max_list_size, FILE* config_file) {
    srand(time(NULL));

    for (int i = 0; i < n && *list != NULL; ++i) {
        int rnti = find_available_RNTI(list, max_list_size, i);
        if (rnti == -1) continue; // list is full, exit loop

        fseek(config_file, 0, SEEK_SET); // reset config file pointer to begin for next fetch

        NFAPI_CRC_INDICATION_PDU_T data = {
            .RX_UE_INFORMATION_TAG = rand() % UINT16_MAX,
            .RNTI = rnti,
            .CRC_INDICATION_REL8_TAG = rand() % 0x7F + 1,
            .CRCFLAG = rand() % 2 == 0 ? true : false
        };

        Node* new_node = create_node(data);
        if (*list == NULL) {
            *list = new_node;
        } else {
            for (Node* current = *list; current->next != NULL; current = current->next) {}
            current->next = new_node;
        }
    }
}

void handle_errors(const char* error_message, FILE* config_file, int retry_count) {
    if (retry_count == 0) {
        fprintf(stderr, "Error: %s\n", error_message);
        fclose(config_file);
        exit(EXIT_FAILURE);
    } else {
        sleep(1); // add some delay before retrying
        populate_list(list, n, max_list_size, config_file);
    }
}

void generate_list(int n, int max_list_size, const char* config_file) {
    FILE* file = fopen(config_file, "r");
    if (!file) handle_errors("Cannot open configuration file", file, retry_count);

    Node* list = NULL;
    populate_list(&list, n, max_list_size, file);

    free_list(&list);
}
