    // Other members as needed
} NFAPI_L1_CONTEXT_T;

struct mem_pool {
    void *start;
    size_t size;
    size_t used;
    size_t alignment;
};

struct context_list {
    NFAPI_L1_CONTEXT_T *contexts;
    size_t capacity;
    size_t count;
    struct mem_pool pool;
    pthread_mutex_t lock;
};

void init_mem_pool(struct mem_pool *pool, size_t size, size_t alignment) {
    pool->start = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->start == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    pool->size = size;
    pool->used = 0;
    pool->alignment = alignment;
}

NFAPI_L1_CONTEXT_T *pool_alloc(struct mem_pool *pool) {
    void *ptr = (void *)((uintptr_t)pool->start + pool->used);
    if (((uintptr_t)ptr % pool->alignment) != 0) {
        ptr += pool->alignment - ((uintptr_t)ptr % pool->alignment);
    }
    pool->used += pool->alignment;
    return (NFAPI_L1_CONTEXT_T *)ptr;
}

void context_list_init(struct context_list *list, size_t capacity, size_t alignment) {
    init_mem_pool(&list->pool, sizeof(NFAPI_L1_CONTEXT_T) * capacity, alignment);
    list->contexts = pool_alloc(&list->pool);
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void* configure_context(NFAPI_L1_CONTEXT_T *ctx) {
    // Implement your configuration logic here, potentially using an external configuration service.
    // You can use a separate function or directly implement the logic in this function.
    // Ensure to handle errors and potential mismatches gracefully.
}

void context_list_resize(struct context_list *list, size_t new_capacity) {
    if (new_capacity <= list->count) return;

    struct mem_pool old_pool = list->pool;
    init_mem_pool(&list->pool, sizeof(NFAPI_L1_CONTEXT_T) * new_capacity, old_pool.alignment);

    NFAPI_L1_CONTEXT_T *new_contexts = pool_alloc(&list->pool);

    size_t min = (new_capacity < list->capacity) ? new_capacity : list->capacity;
    for (size_t i = 0; i < min; ++i) {
        memcpy(new_contexts + i, list->contexts + i, sizeof(NFAPI_L1_CONTEXT_T));
    }

    free(old_pool.start);
    list->capacity = new_capacity;
    list->contexts = new_contexts;
}

void context_list_push(struct context_list *list, NFAPI_L1_CONTEXT_T ctx) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        context_list_resize(list, list->count + 10); // Increase capacity by 10 for scalability
    }
    memcpy(list->contexts + list->count, &ctx, sizeof(NFAPI_L1_CONTEXT_T));
    ++list->count;
    pthread_mutex_unlock(&list->lock);
}

void context_list_foreach(struct context_list *list, void (*func)(NFAPI_L1_CONTEXT_T *ctx)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        func(list->contexts + i);
    }
    pthread_mutex_unlock(&list->lock);
}
