#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <zlib.h>
#include <time.h>

typedef struct {
    uint16_t CI;
    uint32_t TC_RNTI;
    // Add measurement report structure here
} LTE_UE_Context;

struct ThreadData {
    size_t* array_size;
    LTE_UE_Context** contexts;
};

void serialize_context(LTE_UE_Context* context, int fd) {
    gzwrite(fd, &context->CI, sizeof(uint16_t));
    gzwrite(fd, &context->TC_RNTI, sizeof(uint32_t));
    // Serialize measurement report structure here
}

void* init_ue_contexts(void* data) {
    struct ThreadData* td = data;
    size_t index = (size_t) pthread_self();
    LTE_UE_Context* context = calloc(1, sizeof(LTE_UE_Context));
    if (!context) {
        fprintf(stderr, "Error allocating memory for UE context\n");
        return NULL;
    }

    context->CI = index;
    context->TC_RNTI = (index << 16) | td->array_size[index];

    // Initialize measurement report structure here

    td->contexts[index] = context;
    return context;
}

void init_dynamic_ue_context_array(size_t* array_size, LTE_UE_Context*** contexts) {
    pthread_t threads[array_size];
    *contexts = malloc(array_size * sizeof(LTE_UE_Context*));

    for (size_t i = 0; i < array_size; ++i) {
        pthread_create(&threads[i], NULL, init_ue_contexts, &data);
    }

    for (size_t i = 0; i < array_size; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    const char* filename = "ue_contexts.bin";
    int fd = open(filename, O_WRONLY | O_CREAT | O_EXCL | O_NDSYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    if (fd == -1 && errno != EEXIST) {
        perror("Error opening file");
        return 1;
    }

    fd = ftruncate(fd, array_size * sizeof(LTE_UE_Context));
    if (fd == -1) {
        perror("Error truncating file");
        close(fd);
        return 1;
    }

    mmap_t* map = mmap(NULL, array_size * sizeof(LTE_UE_Context), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

    if (map == MAP_FAILED) {
        perror("Error mapping file");
        close(fd);
        return 1;
    }

    size_t* array_size = malloc(array_size * sizeof(size_t));
    LTE_UE_Context** contexts = map + sizeof(LTE_UE_Context) * array_size;

    init_dynamic_ue_context_array(array_size, &contexts);

    for (size_t i = 0; i < array_size; ++i) {
        LTE_UE_Context* context = contexts[i];
        serialize_context(context, fd);
    }

    munmap(map, array_size * sizeof(LTE_UE_Context));
    close(fd);

    // Implement asynchronous serialization, error handling, and logging here

    return 0;
}
```

