    if (!list) {
        perror("Memory allocation failed for the list");
        return NULL;
    }

    list->UEMM_CONTEXT_ID = 0;
    memset(list->IMSI, '\0', sizeof(list->IMSI));
    list->nas_message = NULL;

    return list;
}

void dynamic_list_push(LTE_UESIM_ACCESS_REQUEST** list, uint32_t UEMM_CONTEXT_ID, char* IMSI, NAS_MESSAGE* nas_message) {
    LTE_UESIM_ACCESS_REQUEST* new_element = (LTE_UESIM_ACCESS_REQUEST*)malloc(sizeof(LTE_UESIM_ACCESS_REQUEST));
    if (!new_element) {
        perror("Memory allocation failed for the new element");
        return;
    }

    new_element->UEMM_CONTEXT_ID = UEMM_CONTEXT_ID;
    strcpy(new_element->IMSI, IMSI);
    new_element->nas_message = nas_message;

    // Validate the NAS_MESSAGE here (e.g., check for correct format and size)

    int index = 0;
    for (LTE_UESIM_ACCESS_REQUEST* current_element = *list; current_element != NULL; current_element = (*list++)) {
        if (index == UEMM_CONTEXT_ID) {
            new_element->nas_message = current_element->nas_message;
            free(current_element);
            break;
        }
        index++;
    }

    if (index != UEMM_CONTEXT_ID) {
        *list = (LTE_UESIM_ACCESS_REQUEST*)realloc(*list, sizeof(LTE_UESIM_ACCESS_REQUEST) * (index + 2));
        if (!*list) {
            perror("Memory reallocation failed");
            free(new_element);
            return;
        }
        memmove((*list + 1), *list, sizeof(LTE_UESIM_ACCESS_REQUEST) * index);
        (*list)[index] = new_element;
    }
}

void dynamic_list_pop(LTE_UESIM_ACCESS_REQUEST** list, uint32_t UEMM_CONTEXT_ID) {
    int index = 0;
    for (LTE_UESIM_ACCESS_REQUEST* current_element = *list; current_element != NULL; current_element = (*list++)) {
        if (index == UEMM_CONTEXT_ID) {
            free(current_element->nas_message);
            free(current_element);
            break;
        }
        index++;
    }
}
