    std::list<LTE_UESIM_ACCESS_REQUEST> requests;
    boost::mutex mutex;
    boost::asio::io_service io_service;

public:
    void initialize(uint32_t contextID, const std::string& imsi, const char* nasMessage) {
        {
            boost::lock_guard<boost::mutex> lock(mutex);
            requests.emplace_back(std::chrono::system_clock::now(), contextID, imsi, std::unique_ptr<char[]>(new char[strlen(nasMessage) + 1]));
            std::strcpy(requests.rbegin()->NAS_MESSAGE.get(), nasMessage);
        }
    }

    void update(uint32_t contextID, const char* nasMessage) {
        auto it = requests.begin();
        while (it != requests.end()) {
            if (it->UEMM_CONTEXT_ID == contextID) {
                it->NAS_MESSAGE.reset(new char[strlen(nasMessage) + 1]);
                std::strcpy(it->NAS_MESSAGE.get(), nasMessage);
                it = requests.erase(it);
                break;
            }
            ++it;
        }
    }

