    list->config = config;
    list->logger = logger;
}

void destroyList(struct list* list) {
    node_t* current = list->head;
    while (current != NULL) {
        node_t* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

