    pthread_mutex_lock(&list->lock);

    node_t* newNode = malloc(sizeof(node_t));
    if (newNode == NULL) {
        LOG_ERROR("Failed to allocate memory for new structure.");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    newNode->data = *data;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }

    pthread_mutex_unlock(&list->lock);

    return true;
}

node_t* getFromList(const struct list* list) {
    if (list->head == NULL) {
        LOG_INFO("No structures available in the list.");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    node_t* temp = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }

    pthread_mutex_unlock(&list->lock);

    return temp;
}

void cleanUpList(struct list* list) {
