        pthread_mutex_lock(&g_log_mutex);
        fprintf(g_log_file, "RNTI: %u, CRCFLAG: %d\n", pdu->rnti, pdu->crc_indication.crcflag);
        pthread_mutex_unlock(&g_log_mutex);
    }

    return pdu;
