void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (mempool != MAP_FAILED && mempool_used + NFAPI_CRC_INDICATION_PDU_T_SIZE <= mempool_max) {
        // Free the PDU and reuse its memory in the memory pool if possible
        free(pdu);
        mempool_used -= NFAPI_CRC_INDICATION_PDU_T_SIZE;
    } else {
        // If memory pool is full or too small, free the PDU normally
        free(pdu);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t N, bool debug) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    size_t i;

    // Ensure memory pool is large enough to hold N PDUs
    if (mempool_used + N * NFAPI_CRC_INDICATION_PDU_T_SIZE > mempool_max) {
        if (mempool != MAP_FAILED) {
            munmap(mempool, mempool_max);
        }

        // Reallocate memory pool to hold at least N PDUs plus some overhead
        mempool = mmap(NULL, N * NFAPI_CRC_INDICATION_PDU_T_SIZE + PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (mempool == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        mempool_max = mempool_used + N * NFAPI_CRC_INDICATION_PDU_T_SIZE;
    }

    // Allocate PDUs from the memory pool if possible, otherwise allocate new memory
    pdus = (NFAPI_CRC_INDICATION_PDU_T*)((char*)mempool + mempool_used);
    mempool_used += N * NFAPI_CRC_INDICATION_PDU_T_SIZE;

    // Create each PDU and validate that RNTIs are unique
    for (i = 0; i < N; ++i) {
        pdus[i] = create_pdu(debug);
        if (!pdus[i]) {
            free_pdus(pdus, i);
            return NULL;
        }

        for (size_t j = 0; j < i; ++j) {
            if (pdus[i].rnti == pdus[j].rnti) {
                // Handle duplicate RNTI values gracefully, e.g., by re-creating the PDUs with unique RNTIs
                free_pdus(pdus + i);
                pdus[i] = create_pdu(debug);
                if (!pdus[i]) {
                    free_pdus(pdus, i);
                    return NULL;
                }
            }
        }
    }

    return pdus;
}

void init_logging(const char *log_filename) {
