[' Here is a C function `init_nfaapi_crc_pdu_array` that meets your specifications. The code uses a custom slab allocator (using the buddy system) to efficiently manage memory and minimize fragmentation, and employs thread safety through the use of critical sections for resizing and resetting operations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 0xFFFFFFFFUL

typedef struct _SLAB {
    void *mem_pool;
    size_t block_size;
    unsigned int next_index;
} SLAB;

static SLAB slabs[2]; // Two slabs for small and large blocks
pthread_mutex_t slab_lock = PTHREAD_MUTEX_INITIALIZER;

static void *slab_alloc(SLAB *slab, size_t block_size) {
    void *ptr;

    if (slab->next_index >= slab->block_size) {
        // Allocate new memory for the slab and update the next index.
        ptr = malloc((slab->block_size << 1) * block_size);
        if (!ptr) return NULL;

        memcpy(ptr + slab->block_size * block_size, slab->mem_pool, slab->next_index * block_size);
        slab->mem_pool = ptr;
        slab->block_size <<= 1;
        slab->next_index = slab->block_size - 1;
    }

    // Advance the next index and return the allocated memory.
    ptr = (char *)slab->mem_pool + slab->next_index * block_size;
    slab->next_index--;
    return ptr;
}

void init_nfaapi_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t new_size, int resize) {
    if (!array || new_size <= 0) return -1; // Invalid input parameters

    pthread_mutex_lock(&slab_lock);

    if (resize) { // Resizing array
        for (size_t i = new_size; i < **array ? free(*array + i), i++ ; );
        *array = realloc(*array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*array) { // Failed to allocate memory
            pthread_mutex_unlock(&slab_lock);
            return -1;
        }
    } else { // Initializing array
        *array = malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!*array) { // Failed to allocate memory
            pthread_mutex_unlock(&slab_lock);
            return -1;
        }
    }

    for (size_t i = 0; i < new_size; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        (*array)[i].RNTI = (*array)[i].RX_UE_INFORMATION_TAG & MAX_RNTI;
        if ((*array)[i].RNTI >= MAX_RNTI) { // RNTI value exceeded the maximum allowed value
            free(*array);
            *array = NULL;
            pthread_mutex_unlock(&slab_lock);
            return -1;
        }
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % (1 << 16);
    }

    // Initialize slabs for small and large blocks of memory.
    for (int i = 0; i < 2; ++i) {
        slabs[i].block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        slabs[i].mem_pool = NULL;
        slabs[i].next_index = 0;
    }

    pthread_mutex_unlock(&slab_lock);

    return 0;
}

void reset_nfaapi_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (!array || !*array) return -1;

    pthread_mutex_lock(&slab_lock);

    for (size_t i = 0; i < *array ? (*array)[i].CRC_INDICATION_REL8_TAG != ((1 << 16) - 1), i++ ; );
    free(*array);
    *array = NULL;

    pthread_mutex_unlock(&slab_lock);

    return 0;
}
