    // Other relevant fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct nodelist {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct nodelist *next;
} NodeList;

struct listmanager {
    NodeList** list;
    int capacity, size;
    pthread_mutex_t mutex;
};

void init_list(struct listmanager* lm, int capacity) {
    lm->capacity = capacity;
    lm->size = 0;
    lm->list = malloc(sizeof(NodeList*) * capacity);
    memset(lm->list, 0, sizeof(NodeList*) * capacity);
    pthread_mutex_init(&lm->mutex, NULL);
}

void free_list(struct listmanager* lm) {
    for (int i = 0; i < lm->capacity; ++i)
        if (lm->list[i])
            free(lm->list[i]);
    free(lm->list);
    pthread_mutex_destroy(&lm->mutex);
}

void insert(struct listmanager* lm, NFAPI_CRC_INDICATION_PDU_T data) {
    // Find an empty slot or the first non-empty slot that is far enough from the current position to ensure no contention.
    int index = (lm->size % lm->capacity + 5) % lm->capacity;

    pthread_mutex_lock(&lm->mutex);

    while (lm->list[index]) {
        ++index;
        if (++index >= lm->capacity)
            index = 0;
    }

    NodeList* new_node = malloc(sizeof(NodeList));
    new_node->data = data;
    new_node->next = lm->list[index];
    lm->list[index] = new_node;
    ++lm->size;

    pthread_mutex_unlock(&lm->mutex);
}

void remove(struct listmanager* lm, int index) {
    if (index < 0 || index >= lm->capacity) return;

    pthread_mutex_lock(&lm->mutex);

    NodeList** current = &lm->list[index];
    while (*current && *current != &lm->list[index])
        current = &(*current)->next;

    if (!*current) {
        pthread_mutex_unlock(&lm->mutex);
        return;
    }

    NodeList* temp = *current;
    *current = (*current)->next;
    free(temp);
    --lm->size;

    pthread_mutex_unlock(&lm->mutex);
}

void update(struct listmanager* lm, int index, unsigned int new_crc) {
    if (index < 0 || index >= lm->capacity) return;

    pthread_mutex_lock(&lm->mutex);

    NodeList** current = &lm->list[index];
    while (*current && (*current)->data.crc_flag != index)
        current = &(*current)->next;

    if (!*current || (*current)->data.crc_flag != index) {
        pthread_mutex_unlock(&lm->mutex);
        return;
    }

    (*current)->data.crc_flag = new_crc;

    pthread_mutex_unlock(&lm->mutex);
}

int count(struct listmanager* lm) {
    pthread_mutex_lock(&lm->mutex);
    int count = lm->size;
    pthread_mutex_unlock(&lm->mutex);
    return count;
}
