static void randomize(LTE_PHY_RX_CQI_MEASUREMENT_T* data, size_t size) {
    static unsigned short seed = 0x12345678;
    for (size_t i = 0; i < size; ++i) {
        data[i].srs_id = (unsigned char)(seed % 256);
        seed = (uint32_t)(seed * 16807L % 0x7fffffff);
    }
}

static bool is_unique(const LTE_PHY_RX_CQI_MEASUREMENT_T* data, size_t start, size_t len, uint32_t rnti) {
    for (size_t i = start; i < start + len; ++i) {
        if (data[i].rnti == rnti) return false;
    }
    return true;
}

static LTE_PHY_RX_CQI_MEASUREMENT_T* init_struct(uint32_t rnti, uint8_t harq_pid) {
    LTE_PHY_RX_CQI_MEASUREMENT_T* new_measurement = malloc(sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!new_measurement) return NULL;

    new_measurement->rnti = rnti;
    new_measurement->harq_pid = harq_pid;

    // Initialize srs_id generation here or use an external source
    new_measurement->srs_id = (unsigned char)(time(NULL) % 256);

    return new_measurement;
}

void init_dynamic_array(size_t num_elements, LTE_PHY_RX_CQI_MEASUREMENT_T*** out_array) {
    *out_array = malloc(num_elements * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T*));
    if (!*out_array) {
        perror("Memory allocation failed");
        return;
    }

    size_t used = 0;
    LTE_PHY_RX_CQI_MEASUREMENT_T* data = calloc(num_elements, sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!data) {
        perror("Memory allocation failed");
        free(*out_array);
        *out_array = NULL;
        return;
    }

    while (used < num_elements) {
        uint32_t rnti = used; // unique rnti value based on index
        size_t idx = 0;
        for (size_t i = 0; i < used; ++i) {
            if (!is_unique(data, idx, used - idx, rnti)) {
                rnti += num_elements; // increment to find an available unique rnti value
            }
            idx++;
        }

        LTE_PHY_RX_CQI_MEASUREMENT_T* new_measurement = init_struct(rnti, used >> 8); // use high bits of index as harq_pid to distribute evenly across possible values
        data[used] = new_measurement;
        (*out_array)[used++] = new_measurement;
    }

    randomize(data, num_elements);
}
