[" Here is a simple implementation using C++11's `std::map` and `std::mutex` for thread safety. This example uses an `std::unordered_map<int, std::unique_ptr<Record>>` to store the records, ensuring unique int keys and fast lookup time. The `std::sorted_map<int, long>` is used to store offsets and maintain sorted keys in ascending order.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <map>
#include <memory>
#include <mutex>
#include <functional>
#include <cassert>

struct Record {
    int value;
};

class ConcurrentRecordStore {
private:
    std::unique_ptr<std::vector<Record>> records;
    std::unordered_map<int, std::unique_ptr<Record>> indexedRecords;
    std::mutex mutex;
    std::sorted_map<int, long> sortedKeys;
    long currentOffset = 0;

public:
    explicit ConcurrentRecordStore(int maxValue) {
        assert(maxValue > 0);
        records = std::make_unique<std::vector<Record>>();
        for (int i = 0; i < maxValue; ++i) {
            records->emplace_back(Record{i});
        }
    }

    Record* getRecord(int key) {
        std::scoped_lock lock(mutex);
        auto it = indexedRecords.find(key);
        if (it != indexedRecords.end())
            return it->second.get();
        else {
            for (auto& record : *records) {
                if (record.value == key) {
                    long offset = currentOffset;
                    currentOffset += sizeof(Record);
                    sortedKeys.insert({key, offset});
                    it = indexedRecords.emplace(key, std::unique_ptr<Record>(new Record{key})).first;
                    return it->second.get();
                }
            }
        }
        assert(false); // key not found
        return nullptr;
    }
};
```

This implementation assumes the `Record` struct only contains an int value. If additional data members are included, adjust the size of the record accordingly when computing currentOffset. Make sure to include proper error handling and synchronization mechanisms according to your specific use case requirements for handling concurrent access from multiple threads."]

