NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu_list(unsigned int N, uint32_t seed) {
    if (N == 0) {
        fprintf(stderr, "Error: Invalid input, N must be a positive value.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        fprintf(stderr, "Error: Failed to allocate memory for PDUs.\n");
        return NULL;
    }

    pthread_mutex_t ue_id_mutex = PTHREAD_MUTEX_INITIALIZER;
    uint32_t unique_ue_ids[N] = {0};

    // Parallelize the generation of UE identifiers to improve performance for large N values.
    pthread_t thread_pool[N];
    for (unsigned int i = 0; i < N; ++i) {
        unique_ue_ids[i] = seed + i;
        pdu_list[i].ue_tag.ueId = unique_ue_ids[i];

        if (pthread_create(&thread_pool[i], NULL, generate_rnti, &pdu_list[i])) {
            fprintf(stderr, "Error: Failed to create thread.\n");
            free(pdu_list);
            return NULL;
        }
    }

    for (unsigned int i = 0; i < N; ++i) {
        if (pthread_join(thread_pool[i], NULL)) {
            fprintf(stderr, "Error: Failed to join thread.\n");
            free(pdu_list);
            return NULL;
        }
    }

    // Set CRCFLAG randomly for each PDU in the list.
    for (unsigned int i = 0; i < N; ++i) {
        pdu_list[i].crc_indication.crcFlag = rand() % 2;
    }

    return pdu_list;
}

void* generate_rnti(void *data) {
    // Acquire the lock to ensure thread-safe UE ID generation.
    pthread_mutex_lock(&ue_id_mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)data;
    RX_UE_INFORMATION_TAG *ue_tag = &pdu->ue_tag;

    // Iterate through the list of unique UE IDs, searching for an available one.
    int id_index = 0;
    while (unique_ue_ids[id_index] != 0) {
        if (++id_index == N) {
            fprintf(stderr, "Error: Failed to find a unique UE ID.\n");
            pthread_mutex_unlock(&ue_id_mutex);
            return NULL;
        }
    }

    // Set the UE ID and RNTI in the PDU structure.
    ue_tag->ueId = unique_ue_ids[id_index];
    pdu->rnti = generate_rnti_from_ue_id(ue_tag->ueId);

    // Release the lock after generating a UE ID to allow other threads to continue.
    pthread_mutex_unlock(&ue_id_mutex);

    return NULL;
}
