typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[2];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *prev, *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    new_node->data = data;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Node* new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next && memcmp(&current->next->data.RNTI, &new_node->data.RNTI, sizeof(current->next->data.RNTI)) == 0) {
        // Log duplicate RNTI entry here
        fprintf(stderr, "Duplicate RNTI entry: %lu\n", new_node->data.RNTI);
        free(new_node);
        return;
    }

    if (memcmp(&current->data.RNTI, &new_node->data.RNTI, sizeof(current->data.RNTI)) > 0) {
        new_node->next = current;
        current->prev = new_node;
    } else {
        Node* start = *head;
        while (start->prev) {
            start = start->prev;
        }
        start->prev = new_node;
        new_node->next = *head;
        (*head)->prev = new_node;
    }
}

void populate_doubly_linked_list(Node** head, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Generate unique RNTI value
        uint32_t rnti = (uint32_t)((time(NULL) * i + 1) % ((uint64_t)1 << 32));
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = htons(RX_UE_INFORMATION_TAG_VALUE);
        data.RNTI = rnti;
        data.CRC_INDICATION_REL8_TAG[0] = (uint8_t)(rand() % 2);
        data.CRC_INDICATION_REL8_TAG[1] = (uint8_t)(rand() % 2);

        Node* new_node = create_node(data);
        if (!new_node) {
            return;
        }
        insert_node(head, new_node);
    }
}
