        json_object_put(obj);
        fprintf(stderr, "Invalid JSON: missing or invalid fields\n");
        return false;
    }

    const int expires = json_object_get_int(json_object_get_exact(obj, "expires_in"));
    if (expires <= 0) {
        json_object_put(obj);
        fprintf(stderr, "Invalid expires_in value\n");
        return false;
    }

    const int* integers = NULL;
    size_t integers_len = 0;
    /* Process integers from standard input and store in a memory-efficient array */
    for (char c; scanf("%d%c", &c, &c) == 1 && c != '\n') {
        if (integers_len >= MAX_STRUCTURES - 1) {
            fprintf(stderr, "Input list exceeds maximum limit\n");
            json_object_put(obj);
            return false;
        }
        integers = realloc(integers, sizeof(int) * (integers_len + 2));
        integers[integers_len++] = c - '0';
    }
    if (integers_len == 0) {
        fprintf(stderr, "Empty input list\n");
        json_object_put(obj);
        return false;
    }

    /* Find the largest integer and sort the array for easier processing */
    int largest = 0;
    find_largest(integers, integers_len, &largest);
    qsort(integers, integers_len, sizeof(int), (int (*)(const void*, const void*))cmpfunc);

    /* Create and populate NFAPI_CRC_INDICATION_PDU_T structures */
    *structures = calloc(largest + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*structures) {
        fprintf(stderr, "Memory allocation failed\n");
        json_object_put(obj);
        free(integers);
        return false;
    }

    size_t structures_used = 0;
    for (size_t i = 0; i < integers_len && structures_used < largest + 1; ++i) {
        (*structures)[structures_used].RX_UE_INFORMATION_TAG = integers[i];
        (*structures)[structures_used].RNTI = integers[i] * i; /* Derive unique RNTI values */
        (*structures)[structures_used++].CRC_INDICATION_REL8_TAG = rand() % 0x1FFF + 1;
    }

    *structures_len = structures_used;
    free(integers);
    json_object_put(obj);
    return true;
}

/* Comparison function for qsort */
int cmpfunc(const void* a, const void* b) {
    return (*(const int*)a - *(const int*)b);
}
