#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/time.h>

typedef struct UserDataRecord {
    int user_id;
    time_t last_update;
    bool active;
    struct UserDataRecord *next;
} USER_DATA_RECORD;

struct AuthService {
    void* auth_service_connection;
    bool is_connected;
};

struct ListManager {
    USER_DATA_RECORD** records;
    int capacity;
    int size;
    struct AuthService auth_service;
    pthread_mutex_t mutex;
    long retry_delay;
    long timeout;
};

void list_manager_init(struct ListManager* manager, long retry_delay, long timeout) {
    manager->records = NULL;
    manager->capacity = 0;
    manager->size = 0;
    manager->auth_service.auth_service_connection = NULL;
    manager->auth_service.is_connected = false;
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->retry_delay = retry_delay;
    manager->timeout = timeout;
}

void list_manager_deinit(struct ListManager* manager) {
    if (manager->records != NULL) {
        for (int i = 0; i < manager->capacity && manager->records[i] != NULL; ++i) {
            free(manager->records[i]);
        }
        free(manager->records);
    }
}

void list_manager_connect_auth_service(struct ListManager* manager, void* connection) {
    manager->auth_service.auth_service_connection = connection;
    manager->auth_service.is_connected = true;
}

int unique_user_id_check(struct ListManager* manager, int user_id) {
    USER_DATA_RECORD* current = manager->records[0];
    for (; current != NULL; current = current->next) {
        if (current->user_id == user_id) {
            return 0;
        }
    }
    return 1;
}

bool list_manager_add(struct ListManager* manager, int user_id, time_t last_update, bool active) {
    pthread_mutex_lock(&manager->mutex);
    if (!unique_user_id_check(manager, user_id)) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->records = realloc(manager->records, sizeof(USER_DATA_RECORD*) * manager->capacity);
    }

    USER_DATA_RECORD* new_record = malloc(sizeof(USER_DATA_RECORD));
    new_record->user_id = user_id;
    new_record->last_update = last_update;
    new_record->active = active;
    new_record->next = manager->records[manager->size];
    manager->records[manager->size] = new_record;
    ++manager->size;
    pthread_mutex_unlock(&manager->mutex);
    return true;
}

bool list_manager_remove(struct ListManager* manager, int user_id) {
    pthread_mutex_lock(&manager->mutex);
    USER_DATA_RECORD** prev = &manager->records[0];
    USER_DATA_RECORD* current = manager->records[0];
    for (; current != NULL; prev = &current->next, current = current->next) {
        if (current->user_id == user_id) {
            if (*prev == current) {
                *prev = current->next;
            } else {
                (*prev)->next = current->next;
            }
            free(current);
            --manager->size;
            pthread_mutex_unlock(&manager->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return false;
}

bool list_manager_update(struct ListManager* manager, int user_id, time_t last_update, bool active) {
    USER_DATA_RECORD* current = manager->records[0];
    for (; current != NULL; current = current->next) {
        if (current->user_id == user_id) {
            current->last_update = last_update;
            current->active = active;
            return true;
        }
    }
    return false;
}
```

