} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_created = 0;
static NFAPI_CRC_INDICATION_PDU_T* data = NULL;

void generateNFACRCIndications(NFAPI_CRC_INDICATION_PDU_T** pdu, size_t N) {
    if (num_created + N > 1024 * 1024 || N == 0) {
        printf("Error: Requested number of structures exceeds memory limit or is zero.\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(data, (num_created + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    data = temp;
    num_created += N;
    pthread_mutex_unlock(&mutex);

    for (size_t i = num_created - 1; i < num_created; --i) {
        data[i].RX_UE_INFORMATION_TAG = i + 1;
        data[i].RNTI = i * 123456789;
        data[i].CRC_INDICATION_REL8_TAG = i % 1024;
        data[i].CRCFLAG = rand() % (1 << 16);
    }
}
