#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    unsigned int rrc_cause;
    char* rrc_cause_str;
} LTE_RRC_CMEIE_T;

typedef struct node {
    LTE_RRC_CMEIE_T data;
    struct node *next;
} Node;

Node* create_node(LTE_RRC_CMEIE_T data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(Node** head, LTE_RRC_CMEIE_T data) {
    Node* current = *head;
    Node* new_node = create_node(data);

    if (!current || data.rrc_cause < current->data.rrc_cause) {
        new_node->next = current;
        *head = new_node;
    } else {
        while (current && data.rrc_cause > current->next->data.rrc_cause) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_by_value(Node** head, unsigned int value) {
    if (!*head) return;

    Node* temp = *head;
    Node* previous = NULL;

    while (temp && temp->data.rrc_cause == value) {
        previous = temp;
        temp = temp->next;
        free(previous->rrc_cause_str);
        free(previous);
        previous = NULL;
    }

    if (!previous) return;

    while (temp && previous->next == temp) {
        previous = temp;
        temp = temp->next;
    }

    if (temp) previous->next = temp->next;
}

LTE_RRC_CMEIE_T* find_by_value(Node* head, unsigned int value) {
    Node* current = head;

    while (current) {
        if (current->data.rrc_cause == value) return &current->data;
        current = current->next;
    }

    return NULL;
}
```
