typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
    struct Node *next;
} Node;

typedef struct {
    int size;
    Node **nodes;
    pthread_mutex_t mutex;
    pthread_cond_t cond_full, cond_empty;
    int mem_threshold;
    SerialLib* serializer;
    FILE* cache_file;
    int cache_size;
} List;

List* list_init(int mem_threshold) {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;
    list->size = 0;
    list->nodes = malloc(sizeof(Node*) * mem_threshold);
    if (!list->nodes) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond_full, NULL);
    pthread_cond_init(&list->cond_empty, NULL);
    list->mem_threshold = mem_threshold;
    return list;
}

Node* node_create(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication, uint32_t crcflag) {
    Node *node = malloc(sizeof(Node));
    if (!node) return NULL;
    node->tag = tag;
    node->rnti = rnti;
    node->crc_indication = crc_indication;
    node->crcflag = crcflag;
    node->next = NULL;
    return node;
}

void list_push(List *list, Node *node) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->mem_threshold) {
        pthread_cond_wait(&list->cond_empty, &list->mutex);
    }
    int idx = list->size % list->mem_threshold;
    list->nodes[idx] = node;
    node->next = list->nodes[(idx + 1) % list->mem_threshold];
    list->size++;
    pthread_cond_signal(&list->cond_full);
    pthread_mutex_unlock(&list->mutex);
}

void list_pop(List *list, Node **node) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == 0) {
        pthread_cond_wait(&list->cond_full, &list->mutex);
    }
    int idx = list->size - 1;
    *node = list->nodes[idx];
    list->nodes[idx] = (*node)->next;
    free(*node);
    (*node) = NULL;
    list->size--;
    pthread_cond_signal(&list->cond_empty);
    pthread_mutex_unlock(&list->mutex);
}

void garbage_collect(List *list) {
    if (list->size < list->mem_threshold / 2) return;
    Node **temp = malloc(sizeof(Node*) * list->mem_threshold);
    int i, j = 0;
    pthread_mutex_lock(&list->mutex);
    for (i = 0; i < list->size; ++i) {
        if (list->nodes[i]) {
            temp[j++] = list->nodes[i];
        }
    }
    free(list->nodes);
    list->nodes = temp;
    for (i = j; i < list->mem_threshold; ++i) {
        list->nodes[i] = NULL;
    }
    list->size = j;
    pthread_mutex_unlock(&list->mutex);
}

void save(List *list, const char *path, SerialLib* serializer, FILE* cache_file, int cache_size) {
