    for (size_t i = 0; i < size; ++i, ++data_ptr) {
        hash_node *current_hash = hashes[hash(*((RNTI*) data_ptr))];
        hash_node *new_node = malloc(sizeof(hash_node));
        new_node->data = data_ptr;
        new_node->next = current_hash;
        if (current_hash == NULL) {
            hashes[hash(*((RNTI*) data_ptr))] = new_node;
        } else {
            while (current_hash->next != NULL) {
                current_hash = current_hash->next;
