        else hashes[index] = current_hash->next;
        free(current_hash);
        current_hash = prev_hash->next;
        --*size;
        prev_hash = NULL;
    }

    if (current_hash != NULL) {
        prev_hash = current_hash;
    }

    while (current_hash != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_data = current_hash->next != NULL ? current_hash->next->data : NULL;
        if (next_data->rnti == rnti) {
            if (prev_hash != NULL) prev_hash->next = current_hash->next;
            else hashes[hash(next_data->rnti)] = current_hash->next;
            free(current_hash);
            --*size;
            current_hash = prev_hash->next;
        } else {
            prev_hash = current_hash;
            current_hash = current_hash->next;
        }
    }
}

