**Custom Memory Pool Implementation:**
```c
#include <malloc.h> // For posix_memalign

typedef struct {
    void* memory_block;
    size_t allocated_bytes;
    size_t free_bytes;
} MemoryPoolBlock;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        handle_error("Failed to allocate memory for MemoryPool.");
        return NULL;
    }

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->total_allocated_bytes = pool->block_size * pool->num_blocks;
    pool->used_bytes = 0;
    pool->free_blocks = num_blocks;
    pool->blocks = malloc(num_blocks * sizeof(MemoryPoolBlock));
    if (!pool->blocks) {
        handle_error("Failed to allocate memory for MemoryPool blocks.");
        free(pool);
        return NULL;
    }

    initialize_memory_blocks(pool);
    return pool;
}

void* acquire_memory(MemoryPool *pool) {
    if (pool->free_blocks <= 0) {
        handle_error("No free blocks available in the MemoryPool.");
        return NULL;
    }

    size_t index = --pool->free_blocks;
    MemoryPoolBlock* block = &pool->blocks[index];

    if (block->allocated_bytes == 0) {
        posix_memalign(block->memory_block, pool->block_size, pool->block_size);
        if (!block->memory_block) {
            handle_error("Failed to allocate memory from the MemoryPool.");
            return NULL;
        }
        block->allocated_bytes = pool->block_size;
        block->free_bytes = pool->block_size;
    }

    void* result = block->memory_block;
    block->free_bytes -= pool->used_bytes;
    pool->used_bytes = 0;
    return result;
}

void release_memory(MemoryPool *pool, void* memory) {
    MemoryPoolBlock* block = (MemoryPoolBlock*) ((char*)memory - offsetof(MemoryPoolBlock, memory_block));
    if (!block->free_bytes) {
        handle_error("Tried to free already-freed memory.");
        return;
    }

    pool->used_bytes += block->free_bytes;
    block->free_bytes = 0;
}
```

