class ThreadSafeRandom {
private:
    std::mutex mtx;
    std::random_device rd;
    std::mt19937 gen;
public:
    ThreadSafeRandom() : gen(rd()) {}

    uint16_t get_rnti(uint32_t session_id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto seed = std::hash<uint32_t>{}(session_id);
        gen.seed(seed);
        return gen();
    }
};

class Session {
private:
    uint32_t session_id;
    ThreadSafeRandom random;
    std::map<uint16_t, NFAPI_CRC_INDICATION_PDU> pdu_list;
public:
    explicit Session(uint32_t id) : session_id(id), random(id) {}

    NFAPI_CRC_INDICATION_PDU* allocate_pdu() {
        auto pdu = new NFAPI_CRC_INDICATION_PDU();
        pdu->RX_UE_INFORMATION_TAG = 0xdeadbeef; // Set your desired values here
        pdu->RNTI = random.get_rnti(session_id);
        pdu->CRC_INDICATION.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        return pdu;
    }

    void add_pdu(NFAPI_CRC_INDICATION_PDU* pdu) {
        pdu_list[pdu->RNTI] = *pdu;
    }
};

class PDUProducer {
private:
    std::vector<Session*> sessions;
public:
    explicit PDUProducer(int num_sessions) {
        for (int i = 0; i < num_sessions; ++i) {
            sessions.push_back(new Session(i));
        }
