    void produce_PDUs(int N, int threads) {
        std::vector<std::thread> threads_vec;
        auto n_per_thread = N / threads;
        int remaining = N % threads;

        pthread_barrier_t barrier;
        pthread_barrier_init(&barrier, NULL, threads);

        for (int i = 0; i < threads; ++i) {
            auto start = i * n_per_thread + (remaining > 0 ? i : 0);
            auto end = (i == threads - 1) ? N : start + (n_per_thread + (remaining > 0 ? 1 : 0));
            threads_vec.push_back(std::thread([this, start, end]() {
                for (int j = start; j < end; ++j) {
                    auto session = sessions[j % sessions.size()];
                    auto pdu = session->allocate_pdu();
                    session->add_pdu(pdu);
                    // Log operation here
                }
                pthread_barrier_wait(&barrier);
            }));
