#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/mman.h>

// Define MAC_FRAME structure
typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    FRAME_CONTROL control;
} MAC_FRAME;

// Lock for thread-safe operations
pthread_mutex_t list_lock;

// Dynamic list of MAC_FRAME structures
MAC_FRAME* frames;
size_t frames_capacity;
size_t frames_length;

// Configurable checksum algorithm function pointer
void (*checksum_func)(const MAC_HEADER*, const MAC_PAYLOAD*);

// Function to enqueue a new frame
void enqueue_frame(const MAC_FRAME* frame) {
    if (frames_length == frames_capacity) {
        // Resize the list when it's full
        void* old_frames = frames;
        frames_capacity *= 2;
        frames = mmap(NULL, frames_capacity * sizeof(MAC_FRAME), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (frames == MAP_FAILED) {
            // Handle error
            free(old_frames);
            frames = old_frames;
            return;
        }
        memcpy(frames, old_frames, frames_length * sizeof(MAC_FRAME));
        munmap(old_frames, frames_capacity * sizeof(MAC_FRAME));
    }

    // Lock the list before adding a new frame
    pthread_mutex_lock(&list_lock);
    frames[frames_length] = *frame;
    frames_length++;
    pthread_mutex_unlock(&list_lock);
}

// Function to process frames asynchronously
void* process_frames(void* arg) {
    while (true) {
        // Lock the list before processing frames
        pthread_mutex_lock(&list_lock);

        size_t i;
        for (i = 0; i < frames_length; ++i) {
            if (!frames[i].control.FLAG) {
                continue; // Skip invalid or processed frames
            }

            // Validate frame integrity using checksum algorithm
            if ((*checksum_func)(&frames[i].header, &frames[i].payload)) {
                printf("Invalid frame: checksum error\n");
                continue;
            }

            // Process the valid frame and mark it as processed
            process_frame(&frames[i]);
            frames[i].control.FLAG = false;
        }

        pthread_mutex_unlock(&list_lock);

        // Sleep for a short period before checking again
        usleep(100000);
    }

    return NULL;
}

// Initialize the dynamic list of MAC_FRAME structures
void init_frame_list() {
    frames = mmap(NULL, frames_capacity * sizeof(MAC_FRAME), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (frames == MAP_FAILED) {
        // Handle error
        frames = NULL;
        return;
    }

    pthread_mutex_init(&list_lock, NULL);
}
```

