// Function to populate the packet array with packets asynchronously
void* populate_packet_array(void *arg) {
    while (num_packets < MAX_PACKETS) {
        UdpPacket *packet = generate_packet(&data_size_range, &packet_id);
        pthread_mutex_lock(&packet_array_lock);
        if (!contains_ip(packet->source_ip.sin_addr.s_addr) && !contains_ip(packet->destination_ip.sin_addr.s_addr)) {
            packet_array[num_packets] = packet;
            num_packets++;
        }
        pthread_mutex_unlock(&packet_array_lock);
    }
    return NULL;
}

// Helper function to check if an IP address is already in the packet array
int contains_ip(in_addr_t ip) {
    for (size_t i = 0; i < num_packets; ++i) {
        if (packet_array[i]->source_ip.sin_addr.s_addr == ip || packet_array[i]->destination_ip.sin_addr.s_addr == ip) {
            return 1;
        }
    }
    return 0;
}

// Function to initialize and populate the packet array asynchronously
UdpPacket** init_packet_array(size_t num_packets, size_t *data_size_range) {
    // Initialize and open log file here (not included in this code snippet)
    // ...
    num_packets = MAX_PACKETS;
    packet_id = 0;
    packet_array = malloc(num_packets * sizeof(UdpPacket));
    pthread_t threads[num_packets];

    for (size_t i = 0; i < num_packets; ++i) {
        pthread_create(&threads[i], NULL, populate_packet_array, NULL);
    }

    // Wait for all threads to finish execution
    for (size_t i = 0; i < num_packets; ++i) {
        pthread_join(threads[i], NULL);
    }

