#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h> // for shmem_open, shmem_get_size, etc. (for shared memory)

typedef struct SRB1_TNL_PDU {
    uint32_t transport_block;
    uint32_t sn;
    struct SRB1_TNL_PDU *next;
} SRB1_TNL_PDU;

struct config {
    size_t buffer_size; // buffer for PDUs, dynamically resizable
    pthread_mutex_t lock; // thread synchronization
    sem_t sem_prod_cons; // producer-consumer synchronization
    void *shmem; // shared memory region (for external dependencies)
    size_t shmem_size; // size of the shared memory region
};

struct dynamic_list {
    SRB1_TNL_PDU *head;
    struct config *config;
};

void init_dynamic_list(struct dynamic_list **lst, const struct config *cfg) {
    if (cfg->buffer_size <= 0) {
        fprintf(stderr, "Buffer size must be greater than zero.\n");
        return;
    }

    *lst = malloc(sizeof(struct dynamic_list));
    if (!*lst) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    (*lst)->config = malloc(sizeof(struct config));
    if (!(*lst)->config) {
        perror("malloc");
        free(*lst);
        exit(EXIT_FAILURE);
    }

    memcpy((*lst)->config, cfg, sizeof(struct config));

    pthread_mutex_init(&(*lst)->config->lock, NULL);
    sem_init(&(*lst)->config->sem_prod_cons, 0, 1); // initial value = 1 (empty list)
}

void free_dynamic_list(struct dynamic_list *lst) {
    SRB1_TNL_PDU *pdu = lst->head;
    while (pdu) {
        SRB1_TNL_PDU *tmp = pdu;
        pdu = pdu->next;
        free(tmp);
    }

    free(lst); // free dynamic list structure itself
}

SRB1_TNL_PDU dequeue_dynamic_list(struct dynamic_list *lst) {
    SRB1_TNL_PDU ret = NULL;
    pthread_mutex_lock(&lst->config->lock);

    if (lst->head) {
        ret = lst->head;
        lst->head = lst->head->next;
        sem_post(&lst->config->sem_prod_cons); // signal that a PDU has been dequeued
    }

    pthread_mutex_unlock(&lst->config->lock);
    return ret;
}

void enqueue_dynamic_list(struct dynamic_list *lst, SRB1_TNL_PDU pdu) {
    pthread_mutex_lock(&lst->config->lock);

    if (lst->head == NULL) {
        lst->head = pdu;
        sem_wait(&lst->config->sem_prod_cons); // block until a PDU can be enqueued (if list is full)
    } else {
        pdu->next = lst->head;
        lst->head = pdu;
    }

    pthread_mutex_unlock(&lst->config->lock);
}
```

