void create_node(node_t** node) {
    *node = malloc(sizeof(node_t));
    if (!(*node)) {
        perror("Memory allocation error");
        return;
    }

    (*node)->tag.present = true;
    (*node)->rnti = rand() % 1000000; // Set RNTI within a reasonable range
    (*node)->crc_tag.present = true;
    (*node)->crcflag = (rand() % 2); // Randomly set CRCFLAG to 0 or 1
    (*node)->next = NULL;
}

int add_node(node_t** head, node_t* new_node) {
    pthread_mutex_lock(&mutex);

    if (head == NULL || *head == NULL) {
        *head = new_node;
    } else {
        node_t* current = *head;
        while (current->next != NULL && current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    if ((*head) && (*head)->next != NULL && (*head_len) >= max_nodes) {
        node_t* to_remove = (*head);
        *head = (*head)->next;
        free(to_remove);
    }

    pthread_mutex_unlock(&mutex);
}

node_t* get_node_by_rnti(int rnti) {
    node_t* current = head;
    while (current != NULL) {
        if (current->rnti == rnti)
            return current;
        current = current->next;
    }
    return NULL;
}

