#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>

struct DataPacket {
    int id;
    time_t timestamp;
    size_t payload_size;
    struct DataPacket* next;
};

typedef struct DataPacket Node;

struct DynamicList {
    Node* head;
    Node* tail;
    sem_t mutex;
    sem_t prune_sem;
    time_t inactive_threshold;
    void (*external_validation)(Node*); // function pointer for external validation
};

void init_list(struct DynamicList* list, time_t inactive_threshold) {
    list->head = NULL;
    list->tail = NULL;
    list->inactive_threshold = inactive_threshold;
    sem_init(&(list->mutex), 1, 1); // initial value 1 means lock is unlocked
    sem_init(&(list->prune_sem), 0, 0); // no initial value, semaphore locked by default
}

void insert(struct DynamicList* list, Node* new_node) {
    sem_wait(&(list->mutex));
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    sem_post(&(list->mutex));
}

Node* remove(struct DynamicList* list) {
    Node* temp = list->head;
    if (temp != NULL) {
        list->head = temp->next;
        if (list->head == NULL)
            list->tail = NULL;
    }
    return temp;
}

Node* find(struct DynamicList* list, int id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->id == id)
            return current;
        current = current->next;
    }
    return NULL;
}

void prune_list(struct DynamicList* list) {
    sem_wait(&(list->prune_sem));
    Node* current = list->head;
    Node* temp;
    time_t now = time(NULL);

    while (current != NULL) {
        if ((now - current->timestamp) > list->inactive_threshold) {
            temp = current;
            current = current->next;
            free(temp);
        } else {
            current = current->next;
        }
    }

    sem_post(&(list->prune_sem));
}

void validate_and_update(struct DynamicList* list, Node* node) {
    if (list->external_validation != NULL)
        list->external_validation(node);
}
```

