#include <time.h>
#include <sys/time.h>

#define MAX_THREADS 10

struct Customer {
    int id;
    char name[50];
};

struct Order {
    int id;
    struct Customer* customer;
    time_t order_time;
};

struct Payment {
    char transaction_id[32];
    double amount;
    bool valid;
};

typedef struct DataTransferObject {
    struct Order order;
    struct Payment payment;
    struct Customer customer;
} DataTransferObject;

static DataTransferObject* data_transfer_objects = NULL;
static int data_transfer_objects_capacity = 0;
static int data_transfer_objects_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_valid_transaction(struct Payment* payment) {
    // Implement your business rules validation here, such as checking transaction ID uniqueness and valid amount.
    // This example checks if the amount is greater than 0 and the transaction ID is unique within the data structure.
    for (int i = 0; i < data_transfer_objects_count; ++i) {
        if (strcmp(data_transfer_objects[i].payment.transaction_id, payment->transaction_id) == 0 && payment->amount <= 0) {
            return false;
        }
    }
    return true;
}

void init_data_transfer_object(DataTransferObject* dto) {
    // Assuming the customer and order details come from external data sources.
    // Here, we simulate some latency by introducing a short sleep.
    usleep(100 * 1000); // 0.1 seconds of sleep

    struct Customer* customer = malloc(sizeof(struct Customer));
    if (!customer) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    strcpy(customer->name, "John Doe");
    customer->id = 1;

    struct Order* order = malloc(sizeof(struct Order));
    if (!order) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    order->id = 1;
    order->customer = customer;
    order->order_time = time(NULL);

    struct Payment* payment = malloc(sizeof(struct Payment));
    if (!payment) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    snprintf(payment->transaction_id, sizeof(payment->transaction_id), "%ld", (long)time(NULL)); // Generates a new transaction ID.
    payment->amount = 100.5;
    payment->valid = is_valid_transaction(payment);

    dto->order = *order;
    dto->payment = *payment;
    dto->customer = *customer;
}

void add_data_transfer_object(DataTransferObject* dto) {
    pthread_mutex_lock(&mutex);
    if (data_transfer_objects_count + 1 > data_transfer_objects_capacity) {
        while (data_transfer_objects_count + 1 > data_transfer_objects_capacity * 0.9) { // Allow up to 10% growth before reallocating memory.
            pthread_mutex_unlock(&mutex);
            usleep(100 * 1000); // Sleep for a short while to avoid thrashing the system when growing the array too frequently.
            pthread_mutex_lock(&mutex);
        }

        data_transfer_objects = realloc(data_transfer_objects, (data_transfer_objects_capacity + 1) * sizeof(DataTransferObject));
        if (!data_transfer_objects) {
            perror("realloc");
            pthread_mutex_unlock(&mutex);
            exit(EXIT_FAILURE);
        }
        data_transfer_objects_capacity++;
    }

    data_transfer_objects[data_transfer_objects_count] = *dto;
    data_transfer_objects_count++;
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    for (int i = 0; i < data_transfer_objects_count; ++i) {
        free(data_transfer_objects[i].customer);
        free(data_transfer_objects[i].order.customer);
        free(data_transfer_objects[i].payment.transaction_id);
    }
    free(data_transfer_objects);
}

void* worker(void* arg) {
    int id = *(int*)arg;

    while (true) {
        DataTransferObject dto;
        init_data_transfer_object(&dto);

        if (!is_valid_transaction(&dto.payment)) {
            continue; // Skip invalid transactions and retry later.
        }

        add_data_transfer_object(&dto);
    }

    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        int* id = malloc(sizeof(int));
        *id = i;
        if (pthread_create(&threads[i], NULL, worker, id)) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }
    }

    cleanup();
    return 0;
}
```

