#include <time.h>
#include <pthread.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 0xFFFF // Maximum RNTI value
#define CACHE_SIZE 1024 // Cache size for external data source
#define LOCK_COUNT 64 // Number of lock variables in a ring buffer

static pthread_mutexattr_t attr;
static pthread_mutex_t locks[LOCK_COUNT];
static uint32_t cache[CACHE_SIZE][MAX_RNTI + 1];
static int cache_index = 0;

void pthread_mutexattr_init(pthread_mutexattr_t *attr) {
    pthread_mutexattr_init(attr);
    pthread_mutexattr_settype(attr, PTHREAD_MUTEX_RECURSIVE);
}

void* get_next_rnti() {
    pthread_mutex_lock(&locks[cache_index]);
    int i;
    for (i = 0; i < CACHE_SIZE; ++i) {
        if (cache[cache_index][i] == 0 || cache[cache_index][i + 1] > cache[cache_index][i]) {
            cache[cache_index][i] = 1;
            pthread_mutex_unlock(&locks[cache_index]);
            return (uint32_t) i;
        }
    }
    pthread_mutex_unlock(&locks[cache_index]);
    ++cache_index;
    if (cache_index >= LOCK_COUNT) cache_index = 0;
    return get_next_rnti();
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T** list, int n, uint32_t seed) {
    srand(seed);
    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        printf("Error: Failed to allocate memory for list.\n");
        return;
    }

    int i, j;
    pthread_mutexattr_init(&attr);
    for (i = 0; i < n - 1; ++i) {
        do {
            (*list)[i].rnti = (uint32_t) get_next_rnti();
        } while ((*list)[j].rnti == (*list)[i].rnti && j + 1 < i);

        (*list)[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALUE; // Replace with your actual RX_UE_INFORMATION_TAG value
        (*list)[i].crc_indication.crcflag = (rand() % 2) ? 1 : 0; // Generate random CRC flag within a valid range
    }

    // Populate the last element in the list with valid values, ensuring no repeated RNTIs
    (*list)[n - 1].rnti = (uint32_t) get_next_rnti();
    (*list)[n - 1].rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALUE;
    (*list)[n - 1].crc_indication.crcflag = (rand() % 2) ? 1 : 0;
}
