typedef struct LTE_DL_FRAME_STRUCT {
    enum MESSAGE_TYPE { LTE_UL_CCCH_UE_MSG, LTE_UL_DCCH_UE_MSG, /* Add other message types */ };
    enum MESSAGE_TYPE message_type;
    // Other necessary fields for each message type
} LTE_DL_FRAME;

struct frame_array {
    LTE_DL_FRAME* frames;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

void init_frame_array(struct frame_array* array, size_t initial_size) {
    array->frames = malloc(initial_size * sizeof(LTE_DL_FRAME));
    if (!array->frames) {
        fprintf(stderr, "Failed to allocate memory for frame array\n");
        return;
    }

    array->capacity = initial_size;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void resize_frame_array(struct frame_array* array, size_t new_capacity) {
    if (new_capacity <= array->capacity) {
        return;
    }

    LTE_DL_FRAME* temp = realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAME));
    if (!temp) {
        fprintf(stderr, "Failed to resize frame array\n");
        return;
    }

    array->frames = temp;
    array->capacity = new_capacity;
}

bool add_frame(struct frame_array* array, const LTE_DL_FRAME* frame) {
    pthread_mutex_lock(&array->mutex);

    if (array->length == array->capacity) {
        resize_frame_array(array, array->capacity * 2);
    }

    bool valid = validate_frame(frame);
    if (valid) {
        array->frames[array->length] = *frame;
        array->length++;
    }

    pthread_mutex_unlock(&array->mutex);
    return valid;
}

void periodic_revalidation(struct frame_array* array, uint64_t interval_ms) {
    struct timespec revalidate_interval = { .tv_sec = 0, .tv_nsec = interval_ms * 1_000_000 };
    while (true) {
        nanosleep(&revalidate_interval, NULL);

        pthread_mutex_lock(&array->mutex);
        for (size_t i = 0; i < array->length; ++i) {
            bool valid = validate_frame(&array->frames[i]);
            if (!valid) {
                // Handle invalid frame, e.g., log error, remove from array, or reset the frame
            }
        }
        pthread_mutex_unlock(&array->mutex);
    }
}

// Define validate_frame function here to ensure the integrity of each message and frame structure.
