    memset(frame->payload, rand(), buf_size + ETH_ZLEN + ETH_FCS_LEN); // Fill with random data and error correction codes
    frame->payload_len = buf_size;

    return frame;
}

uint16_t calc_checksum(const uint8_t *buf, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i += 2) {
        sum += *(uint16_t*)&buf[i];
        if ((i + 1) < len)
            sum += *(uint16_t*)&buf[i+1];
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    sum = ~sum;
    return sum >> 16 | (sum << 16) >> 16; // Convert to network byte order and one's complement
}

void configure_mac_frame(MAC_FRAME *frame, const void *hash_func) {
    frame->header.checksum = calc_checksum(frame->payload, frame->payload_len + ETH_ZLEN); // Validate MAC_HEADER checksum
