#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    void *data;
    struct entry *next;
} entry;

struct collection {
    int capacity;
    int size;
    pthread_mutex_t mutex;
    entry *head;
    entry *tail;
};

void init_collection(struct collection *col, int capacity) {
    col->capacity = capacity;
    col->size = 0;
    col->head = NULL;
    col->tail = NULL;
    pthread_mutex_init(&col->mutex, NULL);
}

void *create_data(int size) {
    double *data = malloc(sizeof(double) * size);
    if (!data) return NULL;

    for (int i = 0; i < size; ++i)
        data[i] = ((double)rand() / RAND_MAX) * 100.0;

    return data;
}

void insert(struct collection *col, void *data) {
    pthread_mutex_lock(&col->mutex);

    entry *new_entry = malloc(sizeof(entry));
    if (!new_entry) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&col->mutex);
        return;
    }

    new_entry->data = data;
    new_entry->next = NULL;

    if (col->size == 0) {
        col->head = new_entry;
        col->tail = new_entry;
    } else {
        col->tail->next = new_entry;
        col->tail = new_entry;
    }

    ++col->size;

    if (col->size >= col->capacity / 2)
        resize(col);

    pthread_mutex_unlock(&col->mutex);
}

void resize(struct collection *col) {
    pthread_mutex_lock(&col->mutex);

    int new_capacity = col->capacity * 2;
    void **new_data = realloc(calloc(new_capacity, sizeof(void *)), new_capacity * sizeof(void*));
    if (!new_data) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&col->mutex);
        return;
    }

    entry *current = col->head;
    int index = 0;
    while (current != NULL) {
        new_data[index] = current->data;
        current = current->next;
        ++index;
    }

    free(col->head);
    col->head = NULL;
    col->tail = NULL;
    col->capacity = new_capacity;

    pthread_mutex_unlock(&col->mutex);
}

void delete(struct collection *col, void **data) {
    pthread_mutex_lock(&col->mutex);

    entry *current = col->head;
    entry *prev = NULL;

    if (current == NULL) {
        perror("Empty collection");
        pthread_mutex_unlock(&col->mutex);
        return;
    }

    while (current != NULL) {
        if (current->data == *data) {
            if (prev == NULL) {
                col->head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            --col->size;

            if (col->size < col->capacity / 4 && col->size > 0)
                resize(col);

            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&col->mutex);
}

void traverse(struct collection *col, void (*callback)(void*)) {
    entry *current = col->head;

    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
}
