static struct ue_session *free_list = NULL;
static sem_t queue_sem = SEM_INITIALIZE(1); // Protects the number of concurrent UE sessions

void init_system() {
    if (max_ue_sessions > 50000) max_ue_sessions = 50000;
    free_list = malloc(sizeof(struct ue_session) * max_ue_sessions);
    if (!free_list) {
        fprintf(stderr, "Failed to allocate memory for free list\n");
        exit(1);
    }

    for (int i = 0; i < max_ue_sessions; ++i) {
        struct ue_session *ses = &free_list[i];
        ses->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ses->pdu) {
