        sem_init(&ses->update_sem, 0, 0);
    }
}

struct ue_session *get_ue_session() {
    struct ue_session *ses;

    pthread_mutex_lock(&sessions_mutex);
    if (free_list) {
        ses = free_list++;
        sem_post(&queue_sem); // Release the queue semaphore to allow more UE sessions
    } else {
        pthread_mutex_unlock(&sessions_mutex);
        ses = malloc(sizeof(struct ue_session));
        if (!ses) {
