    for (uint64_t i = 0; i < RNTI_MAX; ++i) {
        cache->used_rntis[i] = false;
    }

    return cache;
}

bool rnti_cache_get(RNTI_CACHE* cache, uint64_t* out_rnti) {
    pthread_mutex_lock(&cache->lock);
    for (uint64_t i = cache->next_rnti; i < RNTI_MAX; ++i) {
        if (!cache->used_rntis[i]) {
            cache->used_rntis[i] = true;
            *out_rnti = i;
            pthread_mutex_unlock(&cache->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return false;
}
