int add_mac_transaction(MAC_TRANSACTION_RECORD* transaction) {
    if (!transaction || !VALID_QUALITY || allocated_elements >= MAX_ELEMENTS)
        return -1; // Invalid parameters or array full

    pthread_mutex_lock(&allocation_mutex);

    // Validate reception_quality here to minimize contention and improve performance
    if (!VALID_QUALITY) {
        pthread_mutex_unlock(&allocation_mutex);
        return -2; // Invalid reception_quality
    }

    if (allocated_elements == 0) {
        array = malloc(MAX_ELEMENTS * sizeof(MAC_TRANSACTION_RECORD));
        if (!array) {
            pthread_mutex_unlock(&allocation_mutex);
            return -3; // Memory allocation failure
        }
    }

    memcpy(&array[allocated_elements], transaction, sizeof(MAC_TRANSACTION_RECORD));

    allocated_elements++;
    transaction->transaction_id = unique_id++;

    pthread_mutex_unlock(&allocation_mutex);
    return 0; // Success
}

