class DynamicArray final {
public:
    template<typename T>
    void resize(size_t newSize) {
        if (newSize > currentSize) {
            T* newData = static_cast<T*>(realloc(data, newSize * sizeof(T)));
            if (!newData)
                throw std::bad_alloc();
            data = newData;
            currentSize = newSize;
        } else {
            T* newData = static_cast<T*>(realloc(data, newSize * sizeof(T)));
            if (newData) {
                memset(&data[currentSize], 0, (oldSize - newSize) * sizeof(T));
                currentSize = newSize;
            }
        }
    }

private:
    T* data;
    size_t currentSize;
    size_t oldSize;
};

class Allocator final {
