                lock.unlock();
                spdlog::info("Allocation for UE {} success", threadId);
                lock.lock();
            });
        }

        for (auto& t : threads)
            t.join();
    }
};

void freeMemory(Allocator& allocator) {
    allocator.pdus.resize(0);
}
