    pthread_mutex_lock(&((*list)->mutex);
    Node* current = (*list)->head;

    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&((*list)->mutex));

    return true;
}

bool destroy_list(NFAPI_CRC_INDICATION_PDU_T** list) {
    if (!(*list)) return false;

    pthread_mutex_lock(&((*list)->mutex);
    Node* current = (*list)->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
