#include <mutex>

struct Event {
    std::uint64_t timestamp;
    std::uint64_t id;
    std::string payload;
};

class EventManager {
private:
    std::vector<Event> events;
    std::unordered_map<std::uint64_t, size_t> eventMap;
    std::atomic<size_t> nextId{0};
    mutex dataMutex;

public:
    EventManager() = default;

    void addEvent(const std::string& payload) {
        std::unique_ptr<Event> newEvent(new Event());
        std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
        newEvent->timestamp = duration_cast<std::chrono::nanoseconds>(now.time_since_epoch()).count();
        newEvent->id = nextId++;
        newEvent->payload = payload;

        std::lock_guard<mutex> lock(dataMutex);
        events.push_back(*newEvent);
        eventMap[newEvent->id] = events.size() - 1;
    }

    Event* getEventById(const std::uint64_t id) {
        auto it = eventMap.find(id);
        if (it != eventMap.end()) {
            std::lock_guard<mutex> lock(dataMutex);
            return &events[it->second];
        }
        return nullptr;
    }

    void updatePayloadById(const std::uint64_t id, const std::string& payload) {
        Event* event = getEventById(id);
        if (event != nullptr) {
            std::lock_guard<mutex> lock(dataMutex);
            event->payload = payload;
        }
    }

    void clear() {
        std::lock_guard<mutex> lock(dataMutex);
        events.clear();
        eventMap.clear();
        nextId = 0;
    }
};
```

