#define MAX_N 10000 // Maximum number of structures
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static_assert(sizeof(NFAPI_CRC_INDICATION_PDU_T) <= sizeof(void*), "Structure size exceeds pointer size");

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function for logging errors
void log_error(const char* message) {
    printf("[ERROR] %s\n", message);
}

// Function to initialize the dynamic list
bool init_list() {
    if (!head) {
        head = malloc(sizeof(Node));
        if (!head) return false;
        head->next = NULL;
    }
    return true;
}

// Function to add a new structure to the dynamic list
bool add_to_list(const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head->next;
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    while (current && current->data.RNTI == data->RNTI) {
        free(new_node);
        new_node = NULL;
        pthread_mutex_unlock(&list_mutex);
        log_error("Duplicate RNTI found.");
        return false;
    }

    if (!current) {
        head->next = new_node;
    } else {
        while (current->next) current = current->next;
        current->next = new_node;
    }

    new_node->data = *data;
    new_node->next = NULL;
    pthread_mutex_unlock(&list_mutex);
    return true;
}

// Function to set CRCFLAG for a specific RNTI
bool set_crcflag(uint32_t rnti, bool crcflag) {
    pthread_mutex_lock(&list_mutex);

    Node* current = head->next;
    while (current) {
        if (current->data.RNTI == rnti) {
            current->data.CRCFLAG = crcflag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);

    // Check for consistency of CRC flags and return error if inconsistent
    Node* consistent = head;
    while (consistent->next) {
        if (!consistent->next->data.CRCFLAG && consistent->next->data.CRC_INDICATION_REL8_TAG.CRCFLAG) {
            log_error("Inconsistent CRC flags found.");
            return false;
        }
        consistent = consistent->next;
    }
    return true;
}
```

