void add_node(Node** head, Node* new_node) {
    if (!new_node || !(*head)) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next && current->next->rnti == new_node->data.rnti) current = current->next;

    if (!current->next) {
        current->next = new_node;
        new_node->prev = current;
        return;
    }

    Node* tmp = create_node(new_node->data);
    if (!tmp) return;

    tmp->next = current->next;
    current->next->prev = tmp;
    current->next = tmp;
    tmp->prev = current;
}

void remove_node(Node** head, Node* node_to_remove) {
    if (!(*head)) return;

    Node* current = *head;
    while (current && current != node_to_remove) current = current->next;

    if (!current) return;

    if (current == *head) *head = current->next;
    if (current->next) current->next->prev = current->prev;
    if (current->prev) current->prev->next = current->next;

    free(current);
}

