#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <semaphore.h>

#define MAX_EVENTS 10000
#define BUFFER_SIZE 5000
#define EVENT_DETAIL_MAX 256

typedef struct {
    time_t timestamp;
    int event_type;
    char *detail;
} TrafficEvent;

struct buffer {
    TrafficEvent events[BUFFER_SIZE];
    size_t head, tail;
    sem_t not_full, not_empty;
};

static struct buffer buffer;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

TrafficEvent *allocate_event() {
    TrafficEvent *event = malloc(sizeof(TrafficEvent));
    if (!event) {
        log("Allocation failure");
        return NULL;
    }
    event->detail = calloc(EVENT_DETAIL_MAX, sizeof(char));
    if (!event->detail) {
        free(event);
        log("Detail allocation failure");
        return NULL;
    }
    return event;
}

void free_event(TrafficEvent *event) {
    if (event && event->detail) {
        free(event->detail);
    }
    free(event);
}

void enqueue(TrafficEvent *event) {
    sem_wait(&buffer.not_full);
    buffer.events[buffer.head] = *event;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (sem_trywait(&buffer.not_empty)) {
        // Wake up a waiting thread
        sem_post(&buffer.not_empty);
    }
}

TrafficEvent *dequeue() {
    TrafficEvent *event = NULL;
    if (buffer.tail != buffer.head) {
        event = &buffer.events[buffer.tail];
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
        sem_post(&buffer.not_full);
    }
    return event;
}

void init() {
    // Initialize semaphores to avoid initial underflow/overflow
    sem_init(&buffer.not_full, 0, BUFFER_SIZE);
    sem_init(&buffer.not_empty, 0, 0);
}

// Implement the function to process events and handle the external data feed.
