class UEDataManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<int, size_t> rntiMap;
    std::mt19937 rng;

public:
    UEDataManager() : rng(std::chrono::system_clock::now().time_since_epoch().count()) {}

    int addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        auto it = rntiMap.find(element.rnti);
        if (it == rntiMap.end() || data[it->second].rxTag != element.rxTag) {
            // Generate random CRCFLAG
            element.crcIndicationTag.crcFlag = (uint8_t)(rng() % 2);
            data.push_back(element);
            rntiMap[element.rnti] = data.size() - 1;
            return 1;
        }
        return 0;
    }

    int deleteElement(int rnti) {
        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end())
            return -1; // RNTI not found

        size_t index = it->second;
        rntiMap.erase(it);
        data[index] = data.back();
        data.pop_back();
        --data.size();
        assert(rntiMap.find(data[index].rnti) == rntiMap.end()); // Ensure deleted RNTI is not reused
        return 1;
    }

    void shuffle() {
        std::random_shuffle(data.begin(), data.end());
    }

    int populateArray(size_t maxSize) {
