    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node** createList(size_t size) {
    Node **list = (Node**)malloc(sizeof(Node*) * size);
    for (size_t i = 0; i < size; ++i)
        list[i] = NULL;
    return list;
}

void resizeList(Node** list, size_t current_size, size_t new_size) {
    Node** new_list = (Node**)malloc(sizeof(Node*) * new_size);
    for (size_t i = 0; i < current_size; ++i)
        if (list[i])
            new_list[i] = list[i];

    free(list);
    list = new_list;
}

size_t getIndex(Node** list, RNTI rnti) {
    for (size_t i = 0; i < *((size_t*)&list + 1); ++i)
        if (list[i] && list[i]->data.rnti == rnti)
            return i;
    return SIZE_MAX;
}

void addElement(Node** list, size_t* count, NFAPI_CRC_INDICATION_PDU_T element) {
    size_t index = getIndex(list, element.rnti);
    if (index == SIZE_MAX) {
        if (*count >= *((size_t*)&list + 1))
            resizeList(list, *((size_t*)&list + 1), *((size_t*)&list + 1) * 2);
        index = *count;
    }
    list[index] = (Node*)malloc(sizeof(Node));
    if (!list[index]) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    list[index]->data = element;
    list[index]->next = NULL;
    (*count)++;
}

void removeElement(Node** list, size_t* count, RNTI rnti) {
    size_t index = getIndex(list, rnti);
    if (index != SIZE_MAX && list[index]) {
        Node* tmp = list[index];
        list[index] = list[index]->next;
        free(tmp);
        (*count)--;
    }
}

NFAPI_CRC_INDICATION_PDU_T populateElement() {
