    return strstr(line, keyword) != NULL;
}

void process_file(struct file_data *fd) {
    char line[4096];
    size_t lines = 0;

    while (fgets(line, sizeof(line), fd->file)) {
        sem_wait(&sem_mutex);
        lines++;
        fd->lines = lines;
        sem_post(&sem_mutex);

        if (is_keyword(line, argv[2])) {
            line_data *ld = malloc(sizeof(line_data));
            ld->file = fd;
            ld->line_num = lines;
            // Enqueue sorted by file name and line number
