int main(int argc, char **argv) {
    if (argc < 3 || (argc > 4 && strcmp(argv[3], "--help") != 0)) {
        printf("Usage: %s [directory|file] [keyword] [--help]\n", argv[0]);
        return EXIT_FAILURE;
    }

    sem_init(&sem_mutex, 1, 1);
    sem_init(&sem_queue, 1, 0);

    DIR *dir = argc == 2 ? opendir(argv[1]) : fdopen(fopen(argv[1], "r"), "r");

    if (!dir) {
        perror("opening directory/file");
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    struct file_data **files = malloc(sizeof(struct file_data*) * 128);
    int i = 0;

    if (argc == 2) {
        while ((entry = readdir(dir)) != NULL) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", argv[1], entry->d_name);

            struct stat st;
            if (lstat(path, &st) == -1 || S_ISDIR(st.st_mode)) {
                continue;
            }

            files[i++] = malloc(sizeof(struct file_data));
            strcpy(files[i - 1]->filename, path);
            files[i - 1]->file = fopen(path, "r");
        }
    } else {
        struct file_data *fd = malloc(sizeof(struct file_data));
        fd->filename = argv[1];
        fd->file = fdopen(fopen(argv[1], "r"), "r");
        files[i++] = fd;
    }

    pthread_t threads[i];

    for (int j = 0; j < i; ++j) {
        pthread_create(&threads[j], NULL, process_file, files[j]);
    }

    // Wait for all threads to finish and clean up resources
    // ... (implement your own thread management functions)

    return EXIT_SUCCESS;
}
