#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    time_t timestamp;
    enum EventType { CONNECTION_ESTABLISHED, DATA_TRANSFER, DISCONNECTION } event_type;
    char status_message[256];
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} Node;

struct EventArray {
    pthread_mutex_t mutex;
    Node* head;
    size_t capacity;
    size_t count;
};

void EventArrayInit(struct EventArray* array, size_t initial_capacity) {
    array->head = NULL;
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void EventArrayDestroy(struct EventArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&array->mutex);
}

bool EventArrayAdd(struct EventArray* array, const NetworkEvent* event) {
    if (array->count >= array->capacity) {
        // Resize the data structure if necessary
        Node** nodes = realloc(array->head, sizeof(Node*) * (array->capacity * 2));
        if (!nodes) return false;
        array->head = nodes;
        array->capacity *= 2;
    }

    pthread_mutex_lock(&array->mutex);

    Node* current = array->head;
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->mutex);
        return false;
    }

    new_node->event = *event;
    new_node->next = current;
    array->head = new_node;
    array->count++;

    pthread_mutex_unlock(&array->mutex);

    // Asynchronously log the event if possible
    LogEvent(new_node->event);

    return true;
}

NetworkEvent* EventArrayGetByTypeAndTimestamp(const struct EventArray* array, enum EventType type, time_t timestamp) {
    pthread_mutex_lock(&array->mutex);

    Node* current = array->head;
    while (current != NULL) {
        if (current->event.timestamp == timestamp && current->event.event_type == type) {
            NetworkEvent* event = malloc(sizeof(NetworkEvent));
            *event = current->event;
            pthread_mutex_unlock(&array->mutex);
            return event;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->mutex);

    // Return a dummy event if the requested event doesn't exist (avoid segmentation fault)
    NetworkEvent* event = malloc(sizeof(NetworkEvent));
    event->timestamp = 0;
    event->event_type = 0;
    strcpy(event->status_message, "Non-existent Event");
    return event;
}

// ... Implement other functions for updating events and handling edge cases.
```

