typedef struct node {
    NFAPI_RX_FRAME_INFO_PDU_T data;
    struct node *next;
} Node;

Node* create_node(NFAPI_RX_FRAME_INFO_PDU_T data) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

Node** create_list(size_t N) {
    Node **list = (Node**)calloc(N, sizeof(Node*));
    for (size_t i = 0; i < N; ++i)
        list[i] = NULL;
    return list;
}

bool find(RRC_CONTAINER_ID rrc_container_id, Node **list, size_t *length) {
    for (size_t i = 0; i < *length; ++i) {
        if (list[i] != NULL && list[i]->data.rrc_container_id == rrc_container_id)
            return true;
    }
    return false;
}

size_t add(RRC_CONTAINER_ID rrc_container_id, Node **list, size_t *length) {
    size_t idx = (*length) % list_size;
    if (list[idx] != NULL) {
        do {
            ++idx;
            if (idx == list_size) idx = 0;
        } while (list[idx] != NULL);
    }
    list[idx] = create_node((NFAPI_RX_FRAME_INFO_PDU_T){ .rrc_container_id = rrc_container_id, .phy_flag = rand() % 2 });
    ++*length;
    return *length - 1;
}

size_t remove(RRC_CONTAINER_ID rrc_container_id, Node **list, size_t *length) {
    for (size_t i = 0; i < *length; ++i) {
        if (list[i] != NULL && list[i]->data.rrc_container_id == rrc_container_id) {
            Node* temp = list[i];
            list[i] = list[i]->next;
            free(temp);
            --*length;
            return 1;
        }
    }
    return 0;
}

