function updateClinicStatus($clinicId, $newStatus, $userId, $cacheTtl) {
    $db = new Database($dbParams);
    $apiClient = new APIClient($apiBaseUrl);

    // Validate inputs and preconditions
    if (!$clinicId || !$newStatus || !is_numeric($clinicId)) {
        return json_encode(['success' => false, 'message' => 'Invalid input', 'log_entry' => null]);
    }

    $currentClinic = $db->getClinicById($clinicId);
    if (!$currentClinic) {
        return json_encode(['success' => false, 'message' => 'Clinic not found', 'log_entry' => null]);
    }

    $statusDefinitions = $apiClient->getStatusDefinitions();
    if ($newStatus !== $currentClinic['status'] && !in_array($newStatus, $statusDefinitions)) {
        return json_encode(['success' => false, 'message' => 'Invalid status', 'log_entry' => null]);
    }

    // Handle concurrency control with optimistic locking
    $lockKey = md5($clinicId . $newStatus);
    $currentLockValue = $db->getClinicLockValue($clinicId, $lockKey);
    $newLockValue = time();

    if ($currentLockValue !== $newLockValue) {
        // An update is in progress, log the attempt and return failure
        $logEntry = ['timestamp' => time(), 'clinic_id' => $clinicId, 'user_id' => $userId, 'status_before' => $currentClinic['status'], 'status_after' => $newStatus];
        return json_encode(['success' => false, 'message' => 'Concurrency conflict', 'log_entry' => $logEntry]);
    }

    // Update the database and log the details
    try {
        $db->beginTransaction();
