        $db->rollback();
        return json_encode(['success' => false, 'message' => $e->getMessage(), 'log_entry' => $logEntry]);
    }

    // Return the JSON response and cache the status definitions for future use
    if ($statusDefinitions !== false) {
        cache($apiClient->getStatusDefinitions(), $cacheTtl);
    }

    return json_encode(['success' => true, 'message' => 'Update successful', 'log_entry' => isset($logEntry) ? $logEntry : null]);
}
