```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <chrono>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueInfoTag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    bool crcFlag;
};

class ListManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<int, size_t> rntiMap;
    size_t capacity = 1024;

public:
    ListManager(size_t N) : data(N), capacity(N) {}

    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        if (data.size() == capacity) {
            capacity *= 2;
            data.resize(capacity);
        }
        data[rntiMap.at(element.rnti)] = element;
        rntiMap[element.rnti] = data.size();
    }

    void removeElementByRNTI(int rnti) {
        if (rntiMap.find(rnti) == rntiMap.end()) return;

        size_t index = rntiMap[rnti];
        for (size_t i = index + 1; i < data.size(); ++i) {
            if (rntiMap.find(data[i].rnti) != rntiMap.end()) {
                rntiMap[data[i].rnti] = index;
                break;
            }
        }
        data.erase(index);
        rntiMap.erase(rnti);
    }

    size_t getElementCount() const {
        return data.size();
    }

    NFAPI_CRC_INDICATION_PDU_T* findByRNTI(int rnti) {
        if (rntiMap.find(rnti) == rntiMap.end()) return nullptr;
        return &data[rntiMap[rnti]];
    }
};

void generateData() {
    std::random_device rd;
    std::mt19937 g(rd());
    std::uniform_int_distribution<> dist64(0, INT64_MAX);
    std::vector<NFAPI_CRC_INDICATION_PDU_T> elements;

    for (size_t i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T elem;
        elem.ueInfoTag = static_cast<RX_UE_INFORMATION_TAG>(dist64(g));
        elem.rnti = static_cast<int>(dist64(g));
        elem.crcIndicationRel8Tag.value = dist64(g);
        elem.crcFlag = (dist64(g) & 1) != 0;
        elements.push_back(elem);
    }
}

int main() {
    ListManager manager(1024);
    generateData();

    for (const auto& element : elements) {
        manager.addElement(element);
    }

    // Simulate removal of multiple elements with the same RNTI
    manager.removeElementByRNTI(1);
    manager.removeElementByRNTI(2);

    std::cout << "Current number of entries: " << manager.getElementCount() << "\n";

    // Query an existing element by its RNTI
    NFAPI_CRC_INDICATION_PDU_T* found = manager.findByRNTI(3);
    if (found) {
        std::cout << "Found element with RNTI: " << found->rnti << "\n";
    } else {
        std::cout << "Element not found\n";
    }

    return 0;
}
```

