void add_entry(RX_UE_INFORMATION_TAG rti, RNTI rnti) {
    if (is_valid_rnti(rnti)) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) {
