        new_entry->RNTI = rnti;
        new_entry->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_crcflag();

        // Linear probe for list insertion to minimize memory reallocations
        int i;
        for (i = num_entries; i >= 0; --i) {
            if (!dynamic_list[i % MAX_ENTRIES]) {
                dynamic_list[i % MAX_ENTRIES] = new_entry;
                ++num_entries;
                pthread_mutex_unlock(&list_mutex);
                return;
            }
        }
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    } else {
        fprintf(stderr, "Invalid RNTI: %d\n", rnti);
    }
}

// Function to clean up the dynamic list when needed
