    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = dynamic_list[i % MAX_ENTRIES];
        if (entry) {
            free(entry);
            dynamic_list[i % MAX_ENTRIES] = NULL;
        }
    }
    num_entries = 0;
    pthread_mutex_unlock(&list_mutex);
}
