int initialize_data(LTE_PHY_RX_CQI_MEASUREMENT_T** data, size_t* data_size, const uint32_t rntis[], size_t rntis_count) {
    *data = malloc(rntis_count * DATASET_MAX_SIZE * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!*data) {
        log("Failed to allocate memory");
        return -1;
    }

    size_t total_initialized = 0;
    for (size_t i = 0; i < rntis_count; ++i) {
        size_t current_size = DATASET_MAX_SIZE;
        LTE_PHY_RX_CQI_MEASUREMENT_T* dataset = (*data) + total_initialized;

