            dataset[j].srs_id = (rand() % 256) + 1; // adjust this range if necessary

            bool duplicate_rnti = false;
            for (size_t k = total_initialized; k < total_initialized + current_size; ++k) {
                if (dataset[j].rnti == dataset[k].rnti) {
                    duplicate_rnti = true;
                    break;
                }
            }

            if (!duplicate_rnti) {
                ++total_initialized;
                if (total_initialized >= *data_size) {
                    *data = realloc(*data, total_initialized * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
                    if (!*data) {
                        log("Memory reallocation failed");
                        free(*data);
                        return -1;
                    }
                    *data_size = total_initialized;
                }
            } else {
                log( "Duplicate RNTI detected: rnti=%u", dataset[j].rnti);
                break;
            }
        }
    }

    if (total_initialized == 0) {
        free(*data);
        *data = NULL;
        return -1;
    }

    log("Initialized %zu structures", total_initialized);
    return 0;
}
