    if (!new_node) {
        log_error("Out of memory");
        exit(EXIT_FAILURE);
    }

    initialize(new_node);
    return new_node;
}

void insert_node(NR_NAS_PDU_T *naspdu) {
    pthread_mutex_lock(&list_lock);

    naspdu->next = head;
    head = naspdu;

    pthread_mutex_unlock(&list_lock);
}

void remove_node(NR_NAS_PDU_T *naspdu) {
    if (!head) return;

    pthread_mutex_lock(&list_lock);

    NR_NAS_PDU_T *current = head, *prev = NULL;
    while (current != NULL) {
        if (current == naspdu) {
            if (prev) prev->next = current->next;
            else head = current->next;
            free(naspdu);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
}

void check_validity() {
    NR_NAS_PDU_T *current = head;
    while (current != NULL) {
        if (!current->NAS_MESSAGE_ID || !current->imsi[0] || current->NAS_MESSAGE_TYPE < 0 || current->NAS_MESSAGE_TYPE >= 256 || current->NAS_FLAG < 0 || current->NAS_FLAG > 1) {
            log_error("Invalid structure detected");
