#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

typedef struct {
    unsigned int capacity;
    unsigned int size;
    Node** table;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table(unsigned int capacity) {
    HashTable* hash_table = malloc(sizeof(HashTable));
    hash_table->capacity = capacity;
    hash_table->size = 0;
    hash_table->table = calloc(capacity, sizeof(Node*));
    hash_table->mutex = PTHREAD_MUTEX_INITIALIZER;
    return hash_table;
}

unsigned int hash_function(unsigned int key, unsigned int capacity) {
    return key % capacity;
}

void resize_hash_table(HashTable* hash_table) {
    unsigned int old_capacity = hash_table->capacity;
    unsigned int new_capacity = old_capacity * 2;
    Node** new_table = calloc(new_capacity, sizeof(Node*));

    for (unsigned int i = 0; i < old_capacity; ++i) {
        Node* current = hash_table->table[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            add_entry(new_table[hash_function(temp->data.RNTI, new_capacity)], temp);
        }
    }

    free(hash_table->table);
    hash_table->table = new_table;
    hash_table->capacity = new_capacity;
}

void add_entry(Node** list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list[hash_function(data.RNTI, list_size(list))]->mutex);

    if (list_size(list) == 0 || list[0]->data.RNTI != data.RNTI) {
        if (list_size(list) >= list->capacity) resize_hash_table(list);
        Node* new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = *list;
        *list = new_node;
    } else {
        Node* current = *list;
        while (current->next != NULL && current->next->data.RNTI == data.RNTI) {
            if (current->next->data.CRCFLAG == 1) {
                fprintf(stderr, "Duplicate RNTI detected: %u\n", data.RNTI);
                break;
            }
            current = current->next;
        }
        current->next->CRCFLAG = (current->next->CRCFLAG == 0) ? 1 : 0;
    }

    pthread_mutex_unlock(&list[hash_function(data.RNTI, list_size(list))]->mutex);
}

void update_entry(HashTable* hash_table, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&hash_table->mutex);

    unsigned int index = hash_function(data.RNTI, hash_table->capacity);
    Node* current = hash_table->table[index];

    while (current != NULL && current->data.RNTI != data.RNTI) {
        current = current->next;
    }

    if (current == NULL) {
        fprintf(stderr, "Invalid RNTI: %u\n", data.RNTI);
        pthread_mutex_unlock(&hash_table->mutex);
        return;
    }

    current->data = data;
    pthread_mutex_unlock(&hash_table->mutex);
}

void remove_entry(HashTable* hash_table, uint16_t RNTI) {
    pthread_mutex_lock(&hash_table->mutex);

    unsigned int index = hash_function(RNTI, hash_table->capacity);
    Node* current = hash_table->table[index];

    if (current == NULL) {
        fprintf(stderr, "Invalid RNTI: %u\n", RNTI);
        pthread_mutex_unlock(&hash_table->mutex);
        return;
    }

    if (current->data.RNTI == RNTI) {
        hash_table->table[index] = current->next;
        free(current);
        --hash_table->size;
        if (hash_table->capacity / 4 > hash_table->size) return;
    }

    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
        if (current == NULL) break;
        index = hash_function(current->next->data.RNTI, hash_table->capacity);
    }

    if (current == NULL) return;

    Node* temp = current->next;
    current->next = temp->next;
    free(temp);
    --hash_table->size;

    if (hash_table->capacity / 4 > hash_table->size) return;

    resize_hash_table(hash_table);

    pthread_mutex_unlock(&hash_table->mutex);
}
```
