    if (cache->head != cache->tail) {
        cache->cache[cache->tail] = *pdu;
        cache->tail = (cache->tail + 1) % cache->capacity;
    } else {
        // Handle overflow and possibly allocate more memory for the cache
    }
    pthread_mutex_unlock(&cache->mutex);
}
