// Define the deque structure
typedef struct Deque {
    size_t size;
    size_t capacity;
    LTEPHY_RxTrafData** items;
} Deque;

// Allocate and initialize a new Deque with given capacity
Deque* create_deque(size_t initial_capacity) {
    Deque* deque = malloc(sizeof(Deque));
    if (!deque) return NULL;
    deque->size = 0;
    deque->capacity = initial_capacity;
    deque->items = calloc(initial_capacity, sizeof(LTEPHY_RxTrafData*));
    return deque;
}

// Add an item to the rear of the Deque
void push_rear(Deque* deque, LTEPHY_RxTrafData* item) {
    if (deque->size >= deque->capacity) {
        size_t new_capacity = deque->capacity * 2;
        LTEPHY_RxTrafData** new_items = realloc(deque->items, new_capacity * sizeof(LTEPHY_RxTrafData*));
        if (!new_items) return; // Handle allocation errors gracefully
        deque->items = new_items;
        deque->capacity = new_capacity;
    }
    deque->items[deque->size] = item;
    ++(deque->size);
}

// Remove and return the front item from the Deque
LTEPHY_RxTrafData* pop_front(Deque* deque) {
    if (deque->size == 0) return NULL;
    LTEPHY_RxTrafData* item = deque->items[0];
    memcpy(deque->items, deque->items + 1, (--(deque->size)) * sizeof(LTEPHY_RxTrafData*));
