#include <stdio.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

typedef struct TCP_CONNECTION_RECORD_T {
    struct sockaddr_in addr;
    unsigned short port_number;
    enum CONNECTION_STATE { DISCONNECTED, CONNECTING, ESTABLISHED, CLOSING } state;
    bool flag;
    pthread_mutex_t mutex;
} TCP_CONNECTION_RECORD;

typedef struct DYNAMIC_LIST_T {
    size_t capacity;
    size_t size;
    TCP_CONNECTION_RECORD** records;
    pthread_mutex_t lock;
} DYNAMIC_LIST;

DYNAMIC_LIST* dynamic_list_create(size_t initial_capacity) {
    DYNAMIC_LIST* list = malloc(sizeof(DYNAMIC_LIST));
    list->capacity = initial_capacity;
    list->size = 0;
    list->records = calloc(initial_capacity, sizeof(TCP_CONNECTION_RECORD*));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_reserve(DYNAMIC_LIST* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;
    TCP_CONNECTION_RECORD** temp = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD*));
    if (!temp) {
        fprintf(stderr, "Reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    list->records = temp;
    list->capacity = new_capacity;
}

void dynamic_list_shrink(DYNAMIC_LIST* list) {
    if (list->size <= list->capacity / 2) return;
    TCP_CONNECTION_RECORD** temp = realloc(list->records, list->capacity / 2 * sizeof(TCP_CONNECTION_RECORD*));
    if (!temp) {
        fprintf(stderr, "Reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    list->records = temp;
    list->capacity /= 2;
}

TCP_CONNECTION_RECORD* dynamic_list_get(DYNAMIC_LIST* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    TCP_CONNECTION_RECORD* record = list->records[index];
    if (!record) {
        fprintf(stderr, "Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&list->lock);
    return record;
}

void dynamic_list_add(DYNAMIC_LIST* list, TCP_CONNECTION_RECORD* record) {
    if (list->size >= list->capacity) dynamic_list_reserve(list, list->capacity * 2);
    pthread_mutex_init(&record->mutex, NULL);
    record->flag = rand() % 2;
    size_t index = list->size++;
    list->records[index] = record;
}

TCP_CONNECTION_RECORD* dynamic_list_find(DYNAMIC_LIST* list, const struct sockaddr_in* addr) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        TCP_CONNECTION_RECORD* record = list->records[i];
        if (!record || memcmp(&record->addr, addr, sizeof(struct sockaddr_in))) continue;
        pthread_mutex_unlock(&list->lock);
        return record;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void dynamic_list_update(DYNAMIC_LIST* list, const struct sockaddr_in* addr, unsigned short port, enum CONNECTION_STATE state) {
    TCP_CONNECTION_RECORD* record = dynamic_list_find(list, addr);
    if (!record) return;
    pthread_mutex_lock(&record->mutex);
    if (record->port_number != port) {
        fprintf(stderr, "Trying to update a non-existent connection.\n");
        pthread_mutex_unlock(&record->mutex);
        return;
    }
    record->state = state;
    pthread_mutex_unlock(&record->mutex);
}

void dynamic_list_remove(DYNAMIC_LIST* list, const struct sockaddr_in* addr, unsigned short port) {
    TCP_CONNECTION_RECORD* record = dynamic_list_find(list, addr);
    if (!record || record->port_number != port) return;
    pthread_mutex_lock(&record->mutex);
    size_t index = (size_t)(list->records - list->records[0]);
    memmove(list->records + index, list->records + index + 1, --list->size - index);
    free(record);
    pthread_mutex_unlock(&record->mutex);
}
```

This code implements a dynamic list using an array of pointers to `TCP_CONNECTION_RECORD` structures. The `DYNAMIC_LIST` struct contains the current size and capacity, as well as a mutex for thread safety. The API allows adding new connections, finding existing ones based on IP address and port number, updating the state of an existing connection, and removing a connection by IP address and port number.

The code uses pthread_mutex_lock() and pthread_mutex_unlock() to ensure thread safety when accessing the records in the list. The dynamic_list_reserve() function handles resizing the array based on the current size of the list, while dynamic_list_shrink() shrinks the array when necessary.

The `TCP_CONNECTION_RECORD` struct includes a sockaddr_in for the IP address and port number, a connection state, and a flag that is randomly set during creation. The mutex associated with each record ensures concurrent access is safe.

To accommodate real-world constraints, missing or delayed updates from the external monitoring system can be handled gracefully by allowing the update function to do nothing if it cannot find an existing connection. Additionally, the list's capacity is doubled when adding a new connection to account for potential growth in the number of connections.']

