#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    void* metadata;
    void* payload;
} TX_MESSAGE;

sem_t queue_mutex, worker_sync, backpressure;
size_t worker_count = 0;
pthread_t* worker_threads;

void* worker(void* arg) {
    while (true) {
        TX_MESSAGE* msg;

        sem_wait(&queue_mutex);
        if (!sem_trywait(&backpressure)) { // Back-pressure mechanism
            sem_post(&queue_mutex);
            continue;
        }

        if (queue_empty()) break; // No more messages to process

        msg = dequeue();
        sem_post(&worker_sync);

        // Process message and log errors
        if (!process_message(msg)) {
            free(msg);
            pthread_exit(-1);
        }

        sem_wait(&worker_sync);
    }

    pthread_exit(0);
}

size_t process_messages(TX_MESSAGE* messages, size_t count) {
    size_t processed = 0;
    for (size_t i = 0; i < count; ++i) {
        if (!messages[i]) continue; // Skipping partially processed messages

        if (!process_message(messages[i])) {
            free(messages[i]);
            processed--;
        } else {
            processed++;
        }
    }

    return processed;
}

int main() {
    sem_init(&queue_mutex, 0, 1);
    sem_init(&worker_sync, 0, worker_count);
    sem_init(&backpressure, 0, MAX_THREADS); // Adjust this value based on your requirements

    clock_t start = clock();

    while (true) {
        TX_MESSAGE* msg = receive_message();
        if (!msg) break;

        sem_wait(&backpressure); // Apply back-pressure when a new message arrives

        sem_post(&queue_mutex);
        process_messages((TX_MESSAGE*)realloc(msg, sizeof(TX_MESSAGE) * (worker_count + 1)), 1);

        if (worker_count < MAX_THREADS && clock() - start > UPDATE_INTERVAL) { // Update worker count based on current load
            worker_threads = realloc(worker_threads, sizeof(pthread_t) * ++worker_count);
            pthread_create(&worker_threads[worker_count - 1], NULL, &worker, NULL);
        }
    }

    // Cleanup thread pool and log errors
    for (size_t i = 0; i < worker_count; ++i) {
        void* ret;
        pthread_join(worker_threads[i], &ret);
        if (ret == -1) {
            printf("Error in thread %zu\n", i);
        }
    }

    free(worker_threads);
    sem_destroy(&queue_mutex);
    sem_destroy(&worker_sync);
    sem_destroy(&backpressure);

    return 0;
}
```

