typedef struct QueueNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct QueueNode *next;
} QueueNode;

static QueueNode* queue_head = NULL;
static QueueNode* queue_tail = NULL;
static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t memory_usage = 0;
static const size_t MAX_MEMORY_USAGE = <your_maximum_memory_size>;

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    QueueNode* new_node = malloc(sizeof(QueueNode));
    if (!new_node) {
        // Memory allocation failed, log error and clean up any partially allocated resources.
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_lock);
    if (queue_head == NULL) {
        queue_head = new_node;
        queue_tail = new_node;
    } else {
        queue_tail->next = new_node;
        queue_tail = new_node;
    }
    pthread_mutex_unlock(&queue_lock);

    memory_usage++;
    if (memory_usage > MAX_MEMORY_USAGE) {
        // Memory limit reached, degrade gracefully.
        free(new_node);
        memory_usage--;
    }
}

NFAPI_CRC_INDICATION_PDU_T dequeue() {
    pthread_mutex_lock(&queue_lock);
    QueueNode* temp = queue_head;
    if (temp != NULL) {
        queue_head = temp->next;
        memory_usage--;
        pthread_mutex_unlock(&queue_lock);

        NFAPI_CRC_INDICATION_PDU_T data = temp->data;
        free(temp);
        return data;
    }
    pthread_mutex_unlock(&queue_lock);

    // Queue is empty, return empty struct as placeholder.
    (NFAPI_CRC_INDICATION_PDU_T){0};
}

size_t getMemoryUsage() {
    return memory_usage;
}
