struct node {
    NFAPI_LTE_PDCP_PDU_T data;
    struct node* next;
};
typedef struct node Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t num_nodes = 0;

// Add new element to the list
void add_node(NFAPI_LTE_PDCP_PDU_T* pdu, uint32_t seq_num, bool ack_flag) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory!\n");
        return;
    }
    new_node->data = (*pdu);
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    num_nodes++;
    pthread_mutex_unlock(&list_mutex);
}

// Iterate over the list and update element based on its sequence number
void update_element(uint32_t seq_num, NFAPI_LTE_PDCP_PDU_T* pdu) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.TX_SEQ_NUM == seq_num) {
            *pdu = current->data;
            break;
        }
        current = current->next;
    }
}
