['```php
<?php

// Load environment variables
$config = require('config.php');

function updateClinicStatus($clinicId, $status, $notificationService) {
    // Database connection
    $pdo = new PDO($config['dsn'], $config['username'], $config['password']);

    // Start transaction to handle rollback and prevent race conditions
    $transaction = $pdo->beginTransaction();

    try {
        // Validate inputs
        if (!is_numeric($clinicId) || !in_array($status, ['active', 'inactive'])) {
            throw new InvalidArgumentException('Invalid input');
        }

        // Get the current clinic details and lock for concurrent updates
        $stmt = $pdo->prepare("SELECT * FROM `{$config['tablePrefix']}clinics` WHERE id = :id FOR UPDATE");
        $stmt->execute([':id' => $clinicId]);
        $clinic = $stmt->fetch();

        // Check if the clinic exists
        if (!$clinic) {
            throw new NotFoundException('Clinic not found');
        }

        // Update the status, last_modified_ip and last_modified_date
        $stmt = $pdo->prepare("UPDATE `{$config['tablePrefix']}clinics` SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id");
        $stmt->execute([':id' => $clinicId, ':status' => $status, ':ip' => $_SERVER['REMOTE_ADDR']]);

        // Rate limit client requests (assuming Redis is available)
        redisRateLimiter();

        // Commit the transaction and trigger notification
        $transaction->commit();
        $notificationService->notify('Clinic status updated', 'Clinic #' . $clinicId . ' status has been changed to ' . $status);

    } catch (\Exception $e) {
        // Rollback the transaction on error
        $transaction->rollBack();
        throw $e;
    } finally {
        // Release the lock and close the connection
        $stmt->closeCursor();
        unset($stmt, $clinic);
        $pdo = null;
    }
}

function redisRateLimiter() {
    // Assuming a Redis client is already initialized ($redis)
    $key = 'rate_limiting:user:' . $_SERVER['REMOTE_ADDR'];
    $limit = 10; // Set your desired limit per minute
    $reset = 60; // Reset time in seconds (e.g., every minute)

    if ($redis->incr($key) > $limit) {
        sleep(pow(2, $redis->ttl($key)) + $reset); // Exponential backoff for transient errors
    }
}
```

