#define MAX_RTNIS 1024 // Maximum number of concurrent RNTIs
typedef enum { FALSE, TRUE } bool;

struct rnti_counter {
    int counter[MAX_RTNIS];
    pthread_mutex_t lock;
};

struct rnti_map {
    int map[MAX_RTNIS];
    pthread_mutex_t lock;
};

struct RX_UE_INFORMATION_TAG {
    uint8_t tag; // Tag value (must be defined in your external library)
};

typedef struct {
    uint32_t rnti;
    uint16_t crc_indication_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void init_counters(struct rnti_counter *counter) {
    int i;
    for (i = 0; i < MAX_RTNIS; ++i) {
        counter->counter[i] = 0;
    }
    pthread_mutex_init(&counter->lock, NULL);
}

bool is_rnti_available(struct rnti_counter *counter, uint32_t rnti) {
    pthread_mutex_lock(&counter->lock);
    if (counter->counter[rnti] < MAX_RTNIS) {
        counter->counter[rnti]++;
        pthread_mutex_unlock(&counter->lock);
        return true;
    }
    pthread_mutex_unlock(&counter->lock);
    return false;
}

void release_rnti(struct rnti_counter *counter, uint32_t rnti) {
    pthread_mutex_lock(&counter->lock);
    if (counter->counter[rnti] > 0) {
        counter->counter[rnti]--;
    }
    pthread_mutex_unlock(&counter->lock);
}

void init_map(struct rnti_map *map) {
    int i;
    for (i = 0; i < MAX_RTNIS; ++i) {
        map->map[i] = -1;
    }
    pthread_mutex_init(&map->lock, NULL);
}

uint32_t get_available_rnti(struct rnti_map *map) {
    uint32_t rnti;
    pthread_mutex_lock(&map->lock);
    for (rnti = 0; rnti < MAX_RTNIS; ++rnti) {
        if (map->map[rnti] == -1) {
            map->map[rnti] = getpid(); // Assign unique process ID to RNTI for tracking purposes
            pthread_mutex_unlock(&map->lock);
            return rnti;
        }
    }
    pthread_mutex_unlock(&map->lock);
    return -1; // RNTI not available, retry generation
}

void generate_and_populate_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu_list, int *pdu_count, int n) {
    struct rnti_counter counter;
    struct rnti_map map;
    init_counters(&counter);
    init_map(&map);
    pthread_t threads[n];
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    int i, j, attempts = 0;

    for (i = 0; i < n; ++i) {
        if ((pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            fprintf(stderr, "Error allocating memory for PDU\n");
            return;
        }

        while (!is_rnti_available(&counter, (uint32_t)(get_available_rnti(&map)))) {
            attempts++;
            if (attempts >= MAX_ATTEMPTS) {
                fprintf(stderr, "Failed to generate valid PDUs after %d attempts\n", MAX_ATTEMPTS);
                return;
            }
        }

        pdu->rnti = i + RNTI_START; // Define starting value for RNTIs in your external library
        pdu->crc_indication_tag = CRC_INDICATION_TAG_VALUE; // Define valid tag values in your external library
        pdu->crcflag = (rand() % 2) ? TRUE : FALSE;

        if (pthread_create(&threads[i], NULL, generate_and_populate_pdu_worker, (void *)pdu) != 0) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
        (*pdu_list)[(*pdu_count)] = threads[i]->result;
        (*pdu_count)++;
        release_rnti(&counter, pdu->rnti);
    }
}

void* generate_and_populate_pdu_worker(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = arg;
    // Implement the generation and population of the PDU structure here, leveraging multi-threading where appropriate.
    // Remember to return the generated PDU on thread completion.
    pthread_exit(pdu);
}
