NFAPI_CRC_INDICATION_PDU_T* getDataFromCache(RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti) {
    pthread_mutex_lock(&cacheLock);
    CacheNode *current = cacheHead;

    while (current != NULL) {
        if (current->data.rx_ue_info == rx_ue_info && current->data.rnti == rnti) {
            if (time(NULL) < current->expiry) {
                pthread_mutex_unlock(&cacheLock);
                return &current->data;
            } else { // Evict the stale cache entry
                CacheNode *temp = current;
                current = current->next;
                free(temp);
            }
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&cacheLock);
    return NULL;
}

