        data = loadLocalData();
    }

    if (data != NULL) {
        NFAPI_CRC_INDICATION_PDU_T result;
        parseXMLChunk(data, strlen(data));

        // Store the result in the cache with an expiry time
        CacheNode *newNode = malloc(sizeof(CacheNode));
        newNode->data = result;
        newNode->next = NULL;
        newNode->expiry = time(NULL) + CACHE_EXPIRY_TIME;

        pthread_mutex_lock(&cacheLock);
        if (cacheTail == NULL) {
            cacheHead = newNode;
            cacheTail = newNode;
        } else {
            cacheTail->next = newNode;
            cacheTail = newNode;
        }
        pthread_mutex_unlock(&cacheLock);

        return &newNode->data;
    }

    fprintf(stderr, "Failed to fetch data for RX_UE_INFORMATION_TAG: %d and RNTI: %d\n", rx_ue_info, rnti);
    return NULL;
}
