['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    uint16_t TransportChannelIdentity;
    uint16_t RemoteStationIdentity;
    uint16_t TransportFormat;
} MAC_TransportLayerControlPdu;

struct list_node {
    MAC_TransportLayerControlPdu pdu;
    struct list_node *next;
};

struct transport_list {
    struct list_node* head;
    size_t capacity;
    size_t count;
    sem_t resize_sem;
    pthread_mutex_t lock;
};

void init_transport_list(struct transport_list* list, size_t initial_capacity) {
    list->head = NULL;
    list->capacity = initial_capacity;
    list->count = 0;
    sem_init(&list->resize_sem, 0, list->capacity);
    pthread_mutex_init(&list->lock, NULL);
}

void push_transport_list(struct transport_list* list, const MAC_TransportLayerControlPdu* pdu) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (!new_node) {
        return;
    }

    new_node->pdu = *pdu;
    new_node->next = NULL;

    sem_wait(&list->resize_sem);
    pthread_mutex_lock(&list->lock);
    if (list->count + 1 >= list->capacity) {
        list->capacity *= 2;
        sem_post(&list->resize_sem);
        resize_transport_list(list);
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void resize_transport_list(struct transport_list* list) {
    struct list_node *new_nodes, *current, *next;
    size_t new_capacity = list->capacity;

    new_nodes = malloc(sizeof(struct list_node) * new_capacity);
    if (!new_nodes) {
        return;
    }

    current = new_nodes;
    for (size_t i = 0; i < list->count; ++i) {
        next = malloc(sizeof(struct list_node));
        if (!next) {
            break;
        }
        *next = *list->head;
        current->next = next;
        current = next;
        if (++i >= list->count) {
            free(list->head);
            list->head = new_nodes;
        }
    }
    list->capacity = new_capacity;
}
