int connection_compare(const void *a, const void *b) {
    Connection *connA = (Connection *)a;
    Connection *connB = (Connection *)b;

    return memcmp(&connA->addr, &connB->addr, sizeof(struct sockaddr_in));
}

void cleanup_inactive_connections(ConnectionList *list) {
    pthread_mutex_lock(&list->mutex);

    size_t i;
    for (i = 0; i < list->size; ++i) {
        if (!is_connection_alive(list->connections[i].sockfd)) {
            free(list->connections + i);
            memmove((list->connections + i), (list->connections + i + 1), --list->size * sizeof(Connection));
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void add_connection(ConnectionList *list, int sockfd, const struct sockaddr *addr) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        Connection *new_connections = realloc(list->connections, sizeof(Connection) * (2 * list->capacity));
        if (!new_connections) {
            perror("realloc failed");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->capacity *= 2;
        list->connections = new_connections;
    }

    Connection *new_conn = list->connections + list->size++;
    memcpy(new_conn, &{
        .sockfd = sockfd,
        .addr = *(struct sockaddr_in *)addr
    }, sizeof(Connection));

    pthread_mutex_unlock(&list->mutex);
}

Connection *find_connection(ConnectionList *list, const struct sockaddr *addr) {
    pthread_mutex_lock(&list->mutex);

    size_t i;
    for (i = 0; i < list->size; ++i) {
        if (!memcmp(&list->connections[i].addr, addr, sizeof(struct sockaddr_in))) {
            Connection *found_conn = list->connections + i;
            pthread_mutex_unlock(&list->mutex);
            return found_conn;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

ConnectionList *create_connection_list(size_t initial_capacity) {
    ConnectionList *list = malloc(sizeof(ConnectionList));
    if (!list) {
        perror("malloc failed");
        return NULL;
    }

    list->connections = calloc(initial_capacity, sizeof(Connection));
    if (!list->connections) {
        free(list);
        perror("calloc failed");
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}
