NFAPI_CRC_INDICATION_PDU_LIST_T* nfapi_crc_indication_pdu_list_create() {
    NFAPI_CRC_INDICATION_PDU_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
    if (!list) return NULL;

    list->buffer = malloc(5000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->buffer) {
        free(list);
        return NULL;
    }

    list->head = 0;
    list->tail = 0;
    list->capacity = 5000;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void nfapi_crc_indication_pdu_list_destroy(NFAPI_CRC_INDICATION_PDU_LIST_T* list) {
    free(list->buffer);
    free(list);
}

bool nfapi_crc_indication_pdu_list_push(NFAPI_CRC_INDICATION_PDU_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        size_t new_capacity = (list->capacity * 2 > MAX_SIZE_T) ? MAX_SIZE_T : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_buffer = realloc(list->buffer, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }

        list->buffer = new_buffer;
        list->capacity = new_capacity;
    }

    size_t index = (list->head + ++list->count) % list->capacity;
    memcpy(&(list->buffer[index]), data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&list->mutex);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list_query_rnti(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = list->head; i != list->tail; i = (i + 1) % list->capacity) {
        if (list->buffer[i].rnti == rnti && i != list->tail) continue;

        pthread_mutex_unlock(&list->mutex);
        return &list->buffer[i];
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}
