void roll_average(struct list_head *list, int log_interval, int granularity) {
    time_t now = time(NULL);

    if (now - list->data.timestamp > log_interval * granularity) {
        list->data.rolling_average = calculate_rolling_average(list);
        list->data.timestamp = now;
    }
