    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->size + 1 >= list->capacity) {
        resize_list(list, list->capacity * 2);
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void resize_list(struct list_head *list, int new_capacity) {
    struct list_node *current = list->head;
    struct list_node **new_head = malloc(sizeof(struct list_node *) * new_capacity);

    if (!new_head) {
        return;
    }

    int i;
    for (i = 0; i < list->size && current != NULL; ++i) {
        new_head[i] = current;
        current = current->next;
    }

    free(list->head);
    list->head = new_head;
    list->capacity = new_capacity;
}

