void populateNfarxList(forward_list<NFAPI_CRC_INDICATION_PDU_T>& narxList, const string& jsonFilePath) {
    ifstream jsonFile(jsonFilePath);
    if (!jsonFile.is_open()) {
        SPDLOG_ERROR("Failed to open JSON file: {}", jsonFilePath);
        throw runtime_error("Unable to open JSON file");
    }

    value data;
    try {
