    } catch (const exception& e) {
        SPDLOG_ERROR("Error parsing JSON data: {}", e.what());
        throw runtime_error("Error while parsing JSON data");
    }

    const auto& ueInfo = data.get("UE_INFORMATION").get(0).get("UE_INFORMATION").get(0);
    const string RX_UE_INFORMATION_TAG = ueInfo["RX_UE_INFORMATION_TAG"].get<string>();

    map<uint32_t, bool> foundRNTIs; // To track already encountered RNTI values

    forward_list<string> tagList; // List to store UE tags for insertion logic

    // Initialize narxList with randomly populated structures
    default_random_engine generator(random_device{}());
    uniform_int_distribution<> distribution(0, 1);

    for (auto& ue : ueInfo.get("UE").get("UE")) {
        uint32_t rnti = ue["RNTI"].get<uint32_t>();
        if (foundRNTIs.find(rnti) == foundRNTIs.end()) {
            NFAPI_CRC_INDICATION_PDU_T pdut;
            pdut.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            pdut.RNTI = rnti;
            pdut.CRC_INDICATION_REL8_TAG = distribution(generator) ? 1 : 0;
            pdut.CRCFLAG = distribution(generator);

            narxList.push_front(pdut);
            foundRNTIs[rnti] = true;
        }
    }

    // Insert tag strings based on the given conditions
    smatch match;
    regex re(R"((("(?:RX_UE_INFORMATION_TAG|CRC_INDICATION_REL8_TAG)_T))|(\b(?:RX_UE_INFORMATION_TAG|CRC_INDICATION_REL8_TAG)\b))");

    string line;
    while (getline(ueInfo.get("UE").get("UE"), line)) {
        if (regex_search(line, match, re)) {
