```c
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    enum { LOW, MEDIUM, HIGH } priority;
    void* payload; // Task-specific data
    char* source; // Data source name
} TaskData;

// Thread-safe queue structure for tasks with priorities
typedef struct PriorityQueue {
    pthread_mutex_t lock;
    int size;
    TaskData** items;
} PriorityQueue;

void createPriorityQueue(PriorityQueue* queue, int capacity) {
    queue->size = 0;
    queue->items = malloc(capacity * sizeof(TaskData*));
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue(PriorityQueue* queue, TaskData* task) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size < capacity) {
        queue->items[queue->size++] = task;
    } else {
        free(task); // Return memory when full
    }
    pthread_mutex_unlock(&queue->lock);
}

TaskData* dequeue(PriorityQueue* queue, int priority) {
    pthread_mutex_lock(&queue->lock);
    TaskData** current = queue->items;
    TaskData* result = NULL;

    for (int i = 0; i < queue->size; ++i) {
        if (current[i]->priority == priority && current[i]) {
            result = current[i];
            memmove(&current[i], &current[i+1], (queue->size-i-1)*sizeof(TaskData*));
            queue->size--;
            break;
        }
    }

    pthread_mutex_unlock(&queue->lock);
    return result;
}

// Worker thread function
void* worker(void* arg) {
    PriorityQueue* queues[3]; // Low, Medium, High priority queues
    createPriorityQueue(queues[0], MAX_THREADS * 2);
    createPriorityQueue(queues[1], MAX_THREADS * 2);
    createPriorityQueue(queues[2], MAX_THREADS * 2);

    while (true) {
        TaskData* task;

        // Process high priority tasks first
        task = dequeue(queues[2], HIGH);
        if (task) processTask(task);

        // Process medium priority tasks
        task = dequeue(queues[1], MEDIUM);
        if (task) processTask(task);

        // Process low priority tasks
        task = dequeue(queues[0], LOW);
        if (task) processTask(task);
    }
    return NULL;
}
```

This code creates a priority queue for each task priority level and uses them in the worker function to manage the concurrency of tasks. Keep in mind that this is just a starting point, and you'll need to further develop the code to cover all the design challenges, engineering tradeoffs, and demonstrative examples provided. Good luck!"]

