void free_checksum(Checksum *cs) {
    free(cs);
}

uint32_t update_checksum(Checksum *cs, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    uint32_t old = cs->current;
    cs->current += pdu->rx_ue_info.value + pdu->rnti.value + pdu->crc_indication.value;
    return old;
}

int check_checksum(Checksum *cs, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
