void initialize_dyn_list(dyn_list* list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->length = 0;
    list->nodes = malloc(sizeof(list_node*) * initial_capacity);
    for (size_t i = 0; i < initial_capacity; ++i) {
        list->nodes[i] = NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
}

dyn_list* create_dyn_list() {
    dyn_list* list = malloc(sizeof(dyn_list));
    initialize_dyn_list(list, 10);
    return list;
}

void destroy_dyn_list(dyn_list* list) {
