        list_node* node = list->nodes[i];
        if (node != NULL) {
            free(node->data.content_tags);
            free(node);
        }
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void resize_dyn_list(dyn_list* list) {
    if (list->capacity == list->length) return;

    size_t new_capacity = list->capacity * 2;
    list_node** new_nodes = malloc(sizeof(list_node*) * new_capacity);
    for (size_t i = 0; i < new_capacity; ++i) {
        new_nodes[i] = NULL;
    }

    pthread_mutex_lock(&list->mutex);

    size_t curr_index = 0;
    list_node* curr_node = list->nodes[0];
    while (curr_node != NULL) {
        list_node* next_node = curr_node->next;
        new_nodes[curr_index] = curr_node;
        curr_index++;
        curr_node = next_node;
    }

    free(list->nodes);
    list->nodes = new_nodes;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->mutex);
}

void push_back(dyn_list* list, const NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* data) {
