    list_node* new_node = malloc(sizeof(list_node));
    new_node->data = *data;
    new_node->next = NULL;

    if (list->length == 0) {
        list->nodes[0] = new_node;
    } else {
        list_node* last_node = list->nodes[list->length - 1];
        last_node->next = new_node;
    }

    ++list->length;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* get(dyn_list* list, size_t index) {
    if (index >= list->length || index < 0) return NULL;

    pthread_mutex_lock(&list->mutex);

    list_node* current = list->nodes[index];
    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* data = &current->data;
    pthread_mutex_unlock(&list->mutex);
    return data;
}

void set(dyn_list* list, size_t index, const NFAPI_RRC_CONNECTION_RECONFIGURATION_PDU_T* new_data) {
    if (index >= list->length || index < 0) return;

