public:
    DynamicList() : last_cleanup(std::chrono::steady_clock::now()) {}

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> new_data(new NFAPI_CRC_INDICATION_PDU_T(data));
        std::chrono::steady_clock::time_point start = std::chrono::steady_clock::now();
        std::unique_lock<std::mutex> lock(mtx);
        if (size >= max_size) {
            // Handle maximum size reached, remove unused elements or increase max_size
            log("Maximum size reached, cleaning up...");
            cleanup();
        }
        data.push_back(std::move(new_data));
        lock.unlock();
        ++size;
        avg_time = (avg_time * (size - 1) + (std::chrono::steady_clock::now() - start).count()) / size;
    }

    void cleanup() {
        std::unique_lock<std::mutex> lock(cleanup_mtx);
        if (std::chrono::steady_clock::now() - last_cleanup > std::chrono::seconds(10)) {
            log("Cleanup started...");
            auto it = data.begin();
            while (it != data.end()) {
                it = data.erase_if([&](const auto& elem) {
                    return !elem->crc_indication.crcflag;
                });
            }
            lock.unlock();
            last_cleanup = std::chrono::steady_clock::now();
        }
    }

    // Implement logging function, consider using a logging library for better scalability and maintainability
};

std::default_random_engine DynamicList::generator;
