typedef struct MAC_Entity {
    uint8_t id[6]; // MAC Entity ID
    struct Config config; // Configuration Structure
    enum State state; // State Machine with a randomly initialized state
} MAC_Entity;

typedef struct EntityPool {
    MAC_Entity *entities;
    size_t capacity;
    size_t num_entities;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} EntityPool;

EntityPool* create_entity_pool() {
    EntityPool *pool = malloc(sizeof(EntityPool));
    pool->capacity = 500;
    pool->num_entities = 0;
    pool->entities = calloc(pool->capacity, sizeof(MAC_Entity));
    if (!pool->entities) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

MAC_Entity* acquire_entity(EntityPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->num_entities == pool->capacity) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }

    MAC_Entity *entity = &(pool->entities[pool->num_entities]);
    entity->state = (enum State)rand() % 3; // Randomly initialize state

    pool->num_entities++;
    pthread_mutex_unlock(&pool->mutex);
    return entity;
}

void release_entity(EntityPool *pool, MAC_Entity *entity) {
    pthread_mutex_lock(&pool->mutex);
    // Log the successfully created entity
    printf("Entity created: ID %02x:%02x:%02x:%02x:%02x:%02x\n", entity->id[0], entity->id[1], entity->id[2],
           entity->id[3], entity->id[4], entity->id[5]);
    pthread_mutex_unlock(&pool->mutex);
}

void log_failures(EntityPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->num_entities < pool->capacity) {
        printf("Failed to create %zu entities\n", pool->capacity - pool->num_entities);
    }
    pthread_mutex_unlock(&pool->mutex);
}

