#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct Record {
    double value;
    char buffer[256];
} record;

// Custom allocator for record arrays with growable buffer size
record* record_array_alloc(size_t size) {
    size_t buffer_size = 256;
    record *records = (record *) malloc(sizeof(record) * size);
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = 0.0;
        records[i].buffer[0] = '\0';
    }

    pthread_mutex_t *locks = (pthread_mutex_t *) malloc(sizeof(pthread_mutex_t) * size);
    if (!locks) {
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        if (pthread_mutex_init(&locks[i], NULL)) {
            free(records);
            free(locks);
            return NULL;
        }
    }

    return (record *) reallocarray(records, sizeof(record) * size + buffer_size * size, sizeof(record));
}

// Resize the record's char buffer and update all affected records
void resize_buffer(record *records, size_t size) {
    size_t new_buffer_size = 2 * (size > 1 ? buffer_size : 256);
    record *new_records = reallocarray(records, sizeof(record) * size + new_buffer_size * size, sizeof(record));
    if (!new_records) return;

    memcpy(new_records, records, sizeof(record) * size);

    for (size_t i = 0; i < size; ++i) {
        new_records[i].buffer[buffer_size] = '\0';
        buffer_size = new_buffer_size;
    }

    free(records);
    records = new_records;
}

// Thread-safe version of strncpy to handle potential overflow
void thread_strncpy(char *dest, const char *src, size_t n) {
    pthread_mutex_lock(&dest[0]);
    strncpy(dest, src, n);
    pthread_mutex_unlock(&dest[0]);
}
