typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

node_t *head = NULL;
unsigned int num_elements = 0;
const unsigned int max_ue_connections = 256;
unsigned int current_load = 0;
unsigned int memory_allocated = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    if (num_elements + 1 > max_ue_connections || memory_allocated + sizeof(node_t) > BUFFER_SIZE) {
        // Rate-limiting or memory overflow, handle gracefully
        return;
    }

    node_t *new_node = (node_t*) malloc(sizeof(node_t));
    if (!new_node) {
        // Handle memory allocation failure
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    new_node->data.sequence_number = num_elements++;
    new_node->data.crcflag = rand() % 2;
    if (head == NULL) {
        head = new_node;
    } else {
        node_t *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    memory_allocated += sizeof(node_t);
    pthread_mutex_unlock(&mutex);
}

void dequeue() {
    if (head == NULL) {
        return;
    }

    node_t *to_free = head;
    head = head->next;
    memory_allocated -= sizeof(node_t);
    free(to_free);
}

