#include <pthread.h>

#define MAX_ELEMENTS 1000
#define STACK_SIZE 65536

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG ctag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int allocated_elements = 0;

void* allocate_pdu(void* arg) {
    static NFAPI_CRC_INDICATION_PDU_T* buffer;

    if (allocated_elements >= MAX_ELEMENTS)
        return NULL;

    buffer[allocated_elements].ctag.crcflag = rand() % 2;
    ++allocated_elements;
    return &buffer[allocated_elements - 1];
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(int N) {
    pthread_t* threads = malloc(sizeof(pthread_t) * N);
    void** results = malloc(N * sizeof(void*));

    for (int i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, allocate_pdu, NULL);
        pthread_join(threads[i], &results[i]);
    }

    NFAPI_CRC_INDICATION_PDU_T* allocated_pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; ++i) {
        assert(results[i] != NULL);
        memcpy(&allocated_pdus[i], results[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    free(threads);
    free(results);

    return allocated_pdus;
}

// Main function for testing purposes
int main() {
    int N = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_pdus(N);

    // Access elements concurrently in a separate thread or function
    pthread_t thread;
    void* result;

    pthread_create(&thread, NULL, process_pdus, &pdus);
    pthread_join(thread, &result);

    free(pdus);
    return 0;
}
