#pragma once
#include <vector>
#include <random>
#include <cstdint>

class Nfademo {
private:
    static constexpr uint32_t MIN_RNTI = 1;
    static constexpr uint32_t MAX_RNTI = 65535;
    static constexpr uint8_t MIN_CRCFLAG = 0;
    static constexpr uint8_t MAX_CRCFLAG = 1;
    uint32_t listSize;

public:
    Nfademo(uint32_t listSize) : listSize(listSize) {}

    std::vector<NFAPI_CRC_INDICATION_PDU_T> populateCRCIndications() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> RNTI_dist(MIN_RNTI, MAX_RNTI);
        std::uniform_int_distribution<NFAPI_CRC_INDICATION_PDU_T::crcFlag_t> CRCFLAG_dist(MIN_CRCFLAG, MAX_CRCFLAG);

        std::vector<NFAPI_CRC_INDICATION_PDU_T> indications;
        indications.reserve(listSize);

        for (size_t i = 0; i < listSize; ++i) {
            NFAPI_CRC_INDICATION_PDU_T indication;
            indication.rnti = RNTI_dist(gen);
            indication.crcFlag = CRCFLAG_dist(gen);
            indications.push_back(indication);
        }

        return indications;
    }
};
