    size_t length;   // Number of elements currently in use (elements)
    NFAPI_CRC_INDICATION_PDU_T *data; // Pointer to the dynamically allocated data array
} MemBlock;

MemBlock* create_memblock(size_t n) {
    if (n > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Requested memory exceeds available resources.\n");
        return NULL;
    }

    MemBlock *mem = malloc(sizeof(MemBlock));
