        return NULL;
    }

    mem->capacity = n;
    mem->length = 0;
    mem->data = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mem->data) {
        perror("Error: Memory allocation failed.");
        free(mem);
        return NULL;
    }

    return mem;
}

void destroy_memblock(MemBlock *mem) {
    free(mem->data);
    free(mem);
}

size_t used_memory() {
