    MemBlock *current = heap;

    while (current != NULL) {
        memory += current->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    return memory;
}

MemBlock* reallocate_memblock(MemBlock *mem, size_t new_capacity) {
    if (new_capacity < mem->length) {
        fprintf(stderr, "Error: New capacity is smaller than current capacity.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *tmp = realloc(mem->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!tmp) {
        perror("Error: Memory reallocation failed.");
        return NULL;
    }

    mem->capacity = new_capacity;
    mem->data = tmp;
    return mem;
}

MemBlock* push_to_memblock(MemBlock *mem, const NFAPI_CRC_INDICATION_PDU_T *element) {
    if (mem->length >= mem->capacity && reallocate_memblock(mem, mem->length + THRESHOLD) == NULL) {
        fprintf(stderr, "Error: Failed to allocate more memory.\n");
        return NULL;
    }

    memcpy(&mem->data[mem->length], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mem->length++;

    return mem;
}

void pop_from_memblock(MemBlock *mem) {
    if (mem->length == 0) {
        return;
    }

    mem->length--;
}

