const fs = require('fs');

function processFileContents(filename, maxSize) {
  const offsets = [];
  const keys = [];
  const records = [];

  // Validate input size
  if (maxSize > 1000) {
    console.error('Maximum allowed size limit is 1000 elements.');
    return;
  }

  try {
    // Read file asynchronously
    fs.readFile(filename, 'utf8', (err, data) => {
      if (err) {
        console.error(`Error reading file: ${err}`);
        return;
      }

      const lines = data.split('\n');

      let offsetIndex = 0;
      let keyIndex = 0;
      let recordIndex = 0;

      // Process each line in the file (assuming there is a space-separated pair of integers per line)
      lines.forEach((line, i) => {
        const values = line.split(' ');
        if (values.length === 2 && !isNaN(parseInt(values[0])) && !isNaN(parseInt(values[1]))) {
          // Allocate and store offset and key values
          offsets[offsetIndex] = parseInt(values[0]);
          keys[keyIndex] = parseInt(values[1]);
          offsetIndex++;
          keyIndex++;
        }
      });

      // Allocate memory for records array and fill with initialized structures
      for (let i = 0; offsetIndex > 0 && keyIndex > 0 && recordIndex < maxSize; i++) {
        const randomValue = Math.floor(Math.random() * 101);
        records[i] = { value: randomValue, offset: offsets[offsetIndex - 1] };
        offsets[--offsetIndex] = null; // Set to null for garbage collection
        keyIndex--;
        recordIndex++;
      }

      console.log('Processed file contents:\n');
      records.forEach((record, i) => {
        console.log(`Record ${i}: value=${record.value}, offset=${record.offset}`);
      });
    });
  } catch (error) {
    console.error(`Error initializing structures: ${error}`);
  }
}
