#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TTL 60 // seconds

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    NFAPI_CRC_INDICATION_PDU *head;
    NFAPI_CRC_INDICATION_PDU *tail;
    pthread_mutex_t list_lock;
    pthread_cond_t not_empty_cond;
} CRCIList;

void init_crc_list(CRCIList *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
    pthread_cond_init(&list->not_empty_cond, NULL);
}

void cleanup_crc_list(CRCIList *list) {
    NFAPI_CRC_INDICATION_PDU *cur, *next;
    time_t current = time(NULL);

    pthread_mutex_lock(&list->list_lock);

    for (cur = list->head; cur != NULL; ) {
        next = cur->next;

        if ((current - cur->timestamp) > MAX_TTL) {
            // Remove outdated entry
            free(cur);
            cur = next;
            continue;
        }

        cur = next;
    }

    pthread_mutex_unlock(&list->list_lock);
}

NFAPI_CRC_INDICATION_PDU *create_crc_entry() {
    NFAPI_CRC_INDICATION_PDU *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!entry) return NULL;

    entry->timestamp = time(NULL);
    entry->crciFlag = rand() % 2; // randomly set CRCFLAG

    pthread_mutex_init(&entry->lock, NULL);
    entry->next = NULL;

    return entry;
}

void add_crc_entry(CRCIList *list, NFAPI_CRC_INDICATION_PDU *entry) {
    pthread_mutex_lock(&list->list_lock);

    if (!list->head) {
        list->head = entry;
        list->tail = entry;
    } else {
        list->tail->next = entry;
        list->tail = entry;
    }

    pthread_mutex_unlock(&list->list_lock);
    pthread_cond_signal(&list->not_empty_cond);
}

NFAPI_CRC_INDICATION_PDU *get_crc_entry(CRCIList *list) {
    NFAPI_CRC_INDICATION_PDU *entry;

    pthread_mutex_lock(&list->list_lock);

    while (list->head == NULL) {
        pthread_cond_wait(&list->not_empty_cond, &list->list_lock);
    }

    entry = list->head;
    list->head = entry->next;

    if (list->head == NULL) list->tail = NULL;

    pthread_mutex_unlock(&list->list_lock);

    return entry;
}
```
