// Preallocate a small number of PDUs for quick response in case of delays
static NFAPI_CRC_INDICATION_PDU_T *cached_pdu = NULL;
static size_t cached_pdu_count = 0;

void* init_cached_pdus() {
    // Initialize a small number of PDUs for quick response in case of delays
    cached_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * CACHED_PDU_COUNT);
    if (!cached_pdu) return NULL;

    size_t i;
    for (i = 0; i < CACHED_PDU_COUNT; ++i) {
        cached_pdu[i].rx_ue = (RX_UE_INFORMATION_TAG){ .id = i };
        cached_pdu[i].rnti = RNTI_GENERATE();
        cached_pdu[i].crc_ind.crcflag = rand() % 2;
    }

    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* alloc_pdus(size_t N) {
    // Allocate PDUs with a small buffer for cached preallocated PDUs
    size_t total_count = CACHED_PDU_COUNT + N;
    if (total_count > MAX_PDU_COUNT) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * total_count);
    if (!pdu) return NULL;

    // Initialize the first `CACHED_PDU_COUNT` elements using preallocated PDUs
    memcpy(pdu, cached_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * CACHED_PDU_COUNT);

    size_t i;
    for (i = CACHED_PDU_COUNT; i < total_count; ++i) {
        pdu[i].rx_ue.id = i - CACHED_PDU_COUNT;
        pdu[i].rnti = RNTI_GENERATE();
        pdu[i].crc_ind.crcflag = rand() % 2;
    }

    // Check if we need to preallocate more PDUs for the cache
    if (total_count >= MAX_PDU_COUNT - CACHED_PDU_COUNT) {
        init_cached_pdus();
    }

    return pdu;
}
