Now, let's implement the constructor, destructor, push_back, and remove_expired methods:

```c
LinkedList::LinkedList(time_t ttl) : head(nullptr), lock(), ttl(ttl) {
    pthread_mutex_init(&lock, nullptr);
}

LinkedList::~LinkedList() {
    clear();
    pthread_mutex_destroy(&lock);
}

void LinkedList::push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
    pthread_mutex_lock(&lock);

    Node* node = new Node;
    if (node == nullptr) {
        // Handle out-of-memory error
    }

    node->data = data;
    node->creation_time = time(nullptr);
    node->next = head;
    head = node;

    pthread_mutex_unlock(&lock);
}

void LinkedList::remove_expired() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    Node* temp;
    time_t now = time(nullptr);

    while (current != nullptr) {
        if ((now - current->creation_time) > ttl) {
            temp = current;
            current = current->next;

            delete temp;
            temp = nullptr;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
