#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_CACHE_SIZE 10000
#define MIN_CACHE_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cache_node *prev, *next;
};

typedef struct cache_node cache_node_t;

struct lru_cache {
    size_t size;
    cache_node_t *head, *tail;
    pthread_mutex_t lock;
};

void lru_cache_init(struct lru_cache *cache) {
    cache->size = MIN_CACHE_SIZE;
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

void lru_cache_push(struct lru_cache *cache, NFAPI_CRC_INDICATION_PDU_T data) {
    cache_node_t* new_node = malloc(sizeof(cache_node_t));
    if (!new_node) {
        fprintf(stderr, "Error allocating memory\n");
        return;
    }

    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&cache->lock);
    if (!cache->head) {
        cache->head = new_node;
        cache->tail = new_node;
    } else {
        cache_node_t *iter = cache->head;
        while (iter->next) iter = iter->next;
        iter->next = new_node;
        new_node->prev = iter;
        cache->tail = new_node;
    }
    pthread_mutex_unlock(&cache->lock);
}

NFAPI_CRC_INDICATION_PDU_T lru_cache_pop(struct lru_cache *cache) {
    NFAPI_CRC_INDICATION_PDU_T data;
    cache_node_t *to_remove;

    pthread_mutex_lock(&cache->lock);
    if (!cache->head) {
        data.tag = (RX_UE_INFORMATION_TAG){};
        data.rnti = RNTI_INVALID;
        data.crc_tag = (CRC_INDICATION_REL8_TAG){.crcflag = 0};
        pthread_mutex_unlock(&cache->lock);
        return data;
    }

    to_remove = cache->head;
    cache->head = to_remove->next;
    if (to_remove == cache->tail) {
        cache->tail = NULL;
    } else {
        to_remove->prev->next = to_remove->next;
        if (cache->head) cache->head->prev = to_remove->prev;
    }
    data = to_remove->data;
    free(to_remove);
    pthread_mutex_unlock(&cache->lock);

    return data;
}

void lru_cache_resize(struct lru_cache *cache, size_t new_size) {
    if (new_size < MIN_CACHE_SIZE || new_size > MAX_CACHE_SIZE) {
        fprintf(stderr, "Invalid cache size: %zu\n", new_size);
        return;
    }

    if (new_size != cache->size) {
        pthread_mutex_lock(&cache->lock);
        while (cache->size < new_size && cache->tail) {
            lru_cache_pop(cache);
        }
        while (cache->head && cache->size > new_size) {
            lru_cache_pop(cache);
        }
        cache->size = new_size;
        pthread_mutex_unlock(&cache->lock);
    }
}

void* generate_pdu(void *params) {
    struct lru_cache *cache = params;
    float probability = *(float *)((long long)params + sizeof(struct lru_cache *));
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Generate PDU structure with random CRCFLAG based on provided probability
    pdu.tag = (RX_UE_INFORMATION_TAG){};
    pdu.rnti = RNTI_INVALID;
    pdu.crc_tag = (CRC_INDICATION_REL8_TAG){.crcflag = rand() < RAND_MAX * probability};

    lru_cache_push(cache, pdu);
}

void generate_pdus(struct lru_cache *cache, int M, float probability, int fd) {
    pthread_t threads[M];

    for (int i = 0; i < M; ++i) {
        if (pthread_create(&threads[i], NULL, generate_pdu, (void *)params) != 0) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < M; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (fd >= 0) {
        // Write the generated PDUs to a file, assuming file descriptor fd is open and ready for writing
        // ...
    }
}

int main(int argc, char *argv[]) {
    struct lru_cache cache;
    int M = argc > 1 ? atoi(argv[1]) : 10;
    float probability = argc > 2 ? atof(argv[2]) : 0.5;
    int fd = argc > 3 ? open(argv[3], O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH) : -1;

    lru_cache_resize(&cache, 10);
    generate_pdus(&cache, M, probability, fd);

    return 0;
}

In this code snippet:
- The `lru_cache` structure represents a cache for PDUs. It has a mutex to ensure thread safety.
- `generate_pdu()` function creates a new PDU with a random CRCFLAG based on the given probability.
- `generate_pdus()` function generates M number of PDUs in parallel using threads, optionally writing them to a file if a valid file descriptor is provided.
- The `main()` function sets up the cache, parameters for generating PDUs, and starts generating them.']

