#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    time_t last_accessed;
    pthread_mutex_t lock;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct list_head {
    NFAPI_CRC_INDICATION_PDU *head;
    unsigned int size_limit;
    unsigned int current_size;
    pthread_mutex_t lock;
} ListHead;

ListHead* create_list(unsigned int size_limit) {
    ListHead *head = (ListHead*)malloc(sizeof(ListHead));
    if (!head) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    head->size_limit = size_limit;
    head->current_size = 0;
    pthread_mutex_init(&head->lock, NULL);
    head->head = NULL;

    return head;
}

NFAPI_CRC_INDICATION_PDU* create_node(unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU *new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = rand();
    new_node->CRCFLAG = (rand() % 2) == 0;
    time(&new_node->last_accessed);
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

void lru_eviction(ListHead *head) {
    if (head->current_size > head->size_limit) {
        NFAPI_CRC_INDICATION_PDU *lru = NULL;
        NFAPI_CRC_INDICATION_PDU *node;
        time_t max_time = 0;

        pthread_mutex_lock(&head->lock);
        for (node = head->head; node != NULL; node = node->next) {
            if (difftime(time(NULL), node->last_accessed) > max_time) {
                lru = node;
                max_time = node->last_accessed;
            }
        }
        pthread_mutex_unlock(&head->lock);

        if (lru != NULL) {
            free(lru);
            pthread_mutex_destroy(&lru->lock);

            pthread_mutex_lock(&head->lock);
            for (node = head->head; node != NULL && node != lru; node = node->next) {}
            if (node != NULL) {
                if (node == head->head) {
                    head->head = node->next;
                } else {
                    node->prev->next = node->next;
                }
                head->current_size--;
            }
            pthread_mutex_unlock(&head->lock);
        }
    }
}

NFAPI_CRC_INDICATION_PDU* insert(ListHead *head, unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI);
    if (!new_node) {
        return NULL;
    }

    lru_eviction(head);

    pthread_mutex_lock(&head->lock);
    if (head->head == NULL) {
        head->head = new_node;
        new_node->prev = NULL;
        new_node->next = NULL;
    } else {
        NFAPI_CRC_INDICATION_PDU *last = head->head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
        new_node->prev = last;
        new_node->next = NULL;
    }
    head->current_size++;
    pthread_mutex_unlock(&head->lock);

    return new_node;
}

void log_operation(const char *operation, unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    // Implement a logging mechanism of your choice here.
}

NFAPI_CRC_INDICATION_PDU* find(ListHead *head, unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU *node;

    pthread_mutex_lock(&head->lock);
    for (node = head->head; node != NULL; node = node->next) {
        if (node->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && node->RNTI == RNTI) {
            pthread_mutex_unlock(&head->lock);
            return node;
        }
    }
    pthread_mutex_unlock(&head->lock);

    return NULL;
}

void delete(ListHead *head, unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU *node = find(head, RX_UE_INFORMATION_TAG, RNTI);
    if (node != NULL) {
        pthread_mutex_lock(&head->lock);
        if (node->prev == NULL) {
            head->head = node->next;
        } else {
            node->prev->next = node->next;
        }
        if (node->next != NULL) {
            node->next->prev = node->prev;
        }
        free(node);
        pthread_mutex_destroy(&node->lock);
        head->current_size--;
        pthread_mutex_unlock(&head->lock);
    }
}
