#include <memory>
#include <list>
#include <atomic>
#include <new>
#include <chrono>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUEInfo;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    TIME_STAMP_TAG timeStamp;
};

struct ListNode final {
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> data;
    std::atomic<ListNode*> next;

    ListNode() : next(this) {}

    ~ListNode() {
        if (data) delete data.release();
    }
};

class DynamicLinkedList final {
private:
    static constexpr size_t MAX_SIZE = 10000;
    std::list<std::unique_ptr<ListNode>> nodes_;
    std::atomic<size_t> head_;
    std::mt19937 rng_; // random number generator for CRCFLAG
public:
    DynamicLinkedList() {
        try {
            for (size_t i = 0; i < MAX_SIZE; ++i)
                nodes_.emplace_back(new ListNode);
        } catch (...) {
            // If allocation fails, free all previously allocated memory
            while (!nodes_.empty()) {
                auto nodePtr = nodes_.front().release();
                delete nodePtr;
                nodes_.pop_front();
            }
            throw;
        }

        rng_.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());
    }

    ~DynamicLinkedList() {
        while (!nodes_.empty()) {
            auto nodePtr = nodes_.front().release();
            delete nodePtr;
            nodes_.pop_front();
        }
    }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        ListNode* head = nodes_[head_].get();

        // Find the end of the list by iterating from the head
        for (ListNode* current = head; current->next != head; current = current->next.load()) {}

        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> newData(new NFAPI_CRC_INDICATION_PDU_T);
        new (newData.get()) NFAPI_CRC_INDICATION_PDU_T(data.rxUEInfo, data.rnti, {static_cast<uint32_t>(rng_()), 0}, std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count());
        current->data = std::move(newData);

        head_++;
    }

    // Iteration functions for forward and reverse traversal omitted due to length constraints, but they can be implemented using the existing data structure.
};
```"]

