#define MAX_ELEMENTS 5000

typedef struct {
    int FRAME_ID;
    int TX_POWER_LEVEL;
    int MCS;
    float SNR;
} TX_FRAME_STATS_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
TX_FRAME_STATS_T* frame_stats_list = NULL;
int num_elements = 0;

void append_frame_stats(const TX_FRAME_STATS_T* stats) {
    if (num_elements >= MAX_ELEMENTS) return; // Max capacity reached, ignore further requests.

    TX_FRAME_STATS_T* new_entry = malloc(sizeof(TX_FRAME_STATS_T));
    if (!new_entry) return; // Failed to allocate memory, ignore request.

    memcpy(new_entry, stats, sizeof(TX_FRAME_STATTS_T));
    pthread_mutex_lock(&list_mutex);
    frame_stats_list[num_elements] = *new_entry;
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

void free_frame_stats() {
    TX_FRAME_STATS_T* current_element = frame_stats_list;
    for (int i = 0; i < num_elements; ++i) {
        frame_stats_list[i] = *(frame_stats_list + i + 1);
        free(current_element);
        current_element = frame_stats_list + i + 1;
    }

    free(frame_stats_list);
    num_elements = 0;
    frame_stats_list = NULL;
}
