unsigned int generate_ue_id(const float *numbers, size_t len) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < len; ++i) {
        hash = ((hash << 5) + hash) + numbers[i];
    }
    return hash % UINT_MAX;
}

