        num_elements++;
        messages = realloc(messages, num_elements * sizeof(LTE_ENB_RRC_MESSAGE_T));
        if (!messages) die("Memory allocation failed");

        messages[num_elements - 1].bd_tag = htonl(INADDR_LOOPBACK); // Use a valid IP address for LTE_EMBMS_SYSTEM_INFO_BD_TAG
