#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    double value;
    char* identifier;
} entry;

struct cache_node {
    entry data;
    struct cache_node *next;
};

struct cache {
    struct cache_node *head;
    size_t capacity;
};

struct logger {
    void (*log)(const char*, ...);
};

struct collection {
    entry* entries;
    size_t size;
    size_t capacity;
    struct cache cache;
    pthread_mutex_t mutex;
    struct logger log_system;
};

void init_cache(struct cache* cache, size_t capacity) {
    cache->head = NULL;
    cache->capacity = capacity;
}

entry* get_or_create_entry(struct collection* self, const char* identifier) {
    pthread_mutex_lock(&self->mutex);
    struct cache_node *node = self->cache.head;
    for (; node && strcmp(node->data.identifier, identifier); node = node->next) {}

    if (!node) {
        if (self->cache.head == NULL || self->cache.capacity == self->cache.head->next->capacity) {
            struct cache_node* new_node = malloc(sizeof(struct cache_node));
            init_cache(&new_node->data.cache, 4);
            new_node->next = self->cache.head;
            self->cache.head = new_node;
        }

        node = self->cache.head;
        for (; node->capacity < self->size && node->next != NULL; node = node->next) {}

        if (node == self->cache.head) {
            node->capacity++;
        } else {
            struct cache_node* new_node = malloc(sizeof(struct cache_node));
            memcpy(new_node, node, sizeof(struct cache_node));
            new_node->data.identifier = strdup(identifier);
            new_node->capacity = self->size;
            new_node->next = node->next;
            node->next = new_node;
        }
    }

    entry* data = &node->data;
    if (data->value == 0.0) { // Replace with the desired random value initialization logic
        data->value = rand() / (double) RAND_MAX * 100.0;
    }
    pthread_mutex_unlock(&self->mutex);
    return data;
}

void log_memory(struct logger* logger, const char* message, void* memory_ptr, size_t size) {
    if (logger && logger->log) {
        logger->log(message, "Memory block %p of size %zu bytes allocated", memory_ptr, size);
    }
}

void init_collection(struct collection* self, size_t initial_capacity, size_t max_entries, void(*logger_init)(struct logger*)) {
    self->size = 0;
    self->capacity = initial_capacity;
    self->max_entries = max_entries;
    init_cache(&self->cache, 4);
    pthread_mutex_init(&self->mutex, NULL);

    self->entries = mmap(NULL, self->capacity * sizeof(entry), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (self->entries == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    log_memory(self->log_system.log, "Entries memory block", self->entries, self->capacity * sizeof(entry));

    if (logger_init) {
        logger_init(&self->log_system);
    }
}

void deinit_collection(struct collection* self) {
    munmap(self->entries, self->capacity * sizeof(entry));
    pthread_mutex_destroy(&self->mutex);
}
```
