void init_meas_array(LTE_PHY_RX_MEASUREMENT** arr, size_t* capacity, size_t* size) {
    *arr = (LTE_PHY_RX_MEASUREMENT*) malloc(*capacity * sizeof(LTE_PHY_RX_MEASUREMENT));
    *size = 0;
    *capacity = 16; // initial capacity
}

void resize_meas_array(LTE_PHY_RX_MEASUREMENT** arr, size_t* capacity, size_t* size) {
    LTE_PHY_RX_MEASUREMENT* temp = (LTE_PHY_RX_MEASUREMENT*) realloc(*arr, (*capacity) * sizeof(LTE_PHY_RX_MEASUREMENT));
    if (temp != NULL) {
        *arr = temp;
        *capacity *= 2; // double the capacity upon resize
    }
}

void add_meas(LTE_PHY_RX_MEASUREMENT** arr, size_t* size) {
    (*arr)[(*size)] = (LTE_PHY_RX_MEASUREMENT) {
        .measurement.rnti = rand() % 65535, // valid rnti range: 0 to 65535
        .measurement.harq_pid = rand() % 15, // valid harq_pid range: 0 to 14
        .srsTag.srs_id = rand() % 1024, // valid srs_id range: 0 to 1023
        .srsTag.resource_block_index = rand() % 10, // valid resource_block_index range: 0 to 9
        .srsTag.subcarrier = rand() % 64 // valid subcarrier range: 0 to 63
    };

    if (*size + 1 >= *capacity) {
        resize_meas_array(arr, capacity, size);
    }
    (*size)++;
