#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct cell {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cell *next;
} cell_t;

struct list {
    pthread_mutex_t mutex;
    int size;
    cell_t **head;
};

void init_list(struct list *list, int capacity) {
    if (capacity <= 0 || capacity > 1024)
        capacity = 1024;

    list->size = 0;
    list->head = calloc(capacity, sizeof(cell_t*));
}

void push(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    int idx = list->size % capacity;
    cell_t **cur = &list->head[idx];

    pthread_mutex_lock(&list->mutex);

    if (!*cur)
        *cur = calloc(1, sizeof(cell_t));

    (*cur)->data = data;
    (*cur)->next = NULL;

    list->size++;

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T pop(struct list *list) {
    cell_t **cur = &list->head[0];
    NFAPI_CRC_INDICATION_PDU_T data;

    pthread_mutex_lock(&list->mutex);

    if (!*cur)
        return (NFAPI_CRC_INDICATION_PDU_T){}; // Return an empty structure on an empty list

    data = (*cur)->data;
    cell_t *temp = *cur;

    *cur = (*cur)->next;
    free(temp);

    if (!*cur) {
        for (int i = 1; i < capacity; ++i)
            if (*(list->head + i)) {
                cur = list->head + i;
                break;
            }
    }

    list->size--;

    pthread_mutex_unlock(&list->mutex);

    return data;
}
```

