    *size = 0;
    *array = calloc(*size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* cached_tags[MAX_ARRAY_SIZE];
    size_t cached_count = 0;

    for (size_t i = 0; i < *size; ++i) {
        bool unique = true;
        RX_UE_INFORMATION_TAG tag = rand() % MAX_ARRAY_SIZE;
        (*array)[i].tag = tag;
        cached_tags[cached_count] = &(*array)[i];
        cached_count++;

        for (size_t j = 0; j < i; ++j) {
            if ((*array)[i].tag == cached_tags[(cached_count - 1)]->tag) {
                unique = false;
                break;
            }
        }

        if (unique) continue;

        (*array)[i].tag += 1;
        if ((*array)[i].tag == MAX_ARRAY_SIZE) {
            --(*size);
            i--;
            continue;
        }

        cached_tags[cached_count - 1] = &(*array)[i];
    }

    (*array)[(*size)].CRC_INDICATION_REL8_TAG = rand() % 256;
    (*array)[(*size)]._BoolCRCFLAG = (rand() % 2 == 0);
