// Function to find the first occurrence of a specified key in the keys array
int find_first(const int* keys, size_t len, int key) {
    for (size_t i = 0; i < len; ++i)
        if (keys[i] == key)
            return i;
    return -1;
}

// Function to update the value of a record with a random integer between 1 and 1000
void update_value(Record* records, size_t len, int key, int new_value) {
    int index = find_first(records, len, key);
    if (index != -1)
        records[index].value = new_value;
}

// Function to sort the records based on their key values using stable quicksort algorithm
void stable_quicksort(Record* arr, size_t len, size_t capacity, int(*compare)(const void*, const void*)) {
    if (len < 2) return;

    size_t pivot_index = len / 2;
    size_t left = 0, right = len - 1;
    bool done = false;

    Record temp[capacity];

    while (!done) {
        done = true;
        for (size_t i = left + 1; i < right; ++i) {
            if ((*compare)(&arr[left], &arr[i]) > 0) {
                swap(&arr[left], &arr[i]);
                swap(&arr[i], &temp[right--]);
                done = false;
            }
        }

        for (size_t i = right - 1; i > left; --i) {
            if ((*compare)(&arr[i], &arr[right]) < 0) {
                swap(&arr[i], &arr[right]);
                swap(&arr[right], &temp[left++]);
                done = false;
            }
        }
    }

    if (len > capacity) {
        stable_quicksort(arr, left, capacity, compare);
        stable_quicksort(arr + left, len - left, capacity, compare);
    }
}

// Function to sort the records based on their key values using a stable quicksort algorithm
