#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Node {
    int id;
    float value;
    bool flag;
    struct Node* next;
} Node;

typedef struct HashTable {
    unsigned int size;
    Node** table;
} HashTable;

unsigned int hash(int key, unsigned int table_size) {
    return key % table_size;
}

void resize_hash_table(HashTable* ht) {
    unsigned int old_size = ht->size;
    unsigned int new_size = old_size * 2;
    Node** new_table = malloc(new_size * sizeof(Node*));

    for (int i = 0; i < new_size; ++i) {
        new_table[i] = NULL;
    }

    for (unsigned int i = 0; i < old_size; ++i) {
        Node* node = ht->table[i];
        while (node != NULL) {
            unsigned int index = hash(node->id, new_size);
            node->next = new_table[index];
            new_table[index] = node;
            node = node->next;
        }
    }

    free(ht->table);
    ht->size = new_size;
    ht->table = new_table;
}

void init_arrays(double** arr_d, char** arr_c, struct Node*** arr_s, HashTable* ht) {
    *arr_d = malloc(100 * sizeof(double));
    *arr_c = calloc(100, sizeof(char));
    *arr_s = malloc(100 * sizeof(struct Node*));
    ht->size = 100;
    ht->table = malloc(ht->size * sizeof(Node*));
}

void init_random_data(double* arr_d, unsigned int size) {
    for (unsigned int i = 0; i < size; ++i) {
        arr_d[i] = (float)(rand() / RAND_MAX * 100);
    }
}

void insert(HashTable* ht, struct Node** list, int id, float value, bool flag) {
    struct Node* new_node = malloc(sizeof(struct Node));
    new_node->id = id;
    new_node->value = value;
    new_node->flag = flag;
    new_node->next = ht->table[hash(id, ht->size)];
    ht->table[hash(id, ht->size)] = new_node;

    if (list_length(*list) < size) {
        (*list)[list_length(*list)] = new_node;
    } else {
        resize_list(list);
        (*list)[list_length(*list)] = new_node;
    }
}

void delete(HashTable* ht, struct Node** list, int id) {
    if (ht->table[hash(id, ht->size)] == NULL) {
        return;
    }

    struct Node* prev = NULL;
    struct Node* current = ht->table[hash(id, ht->size)];
    while (current != NULL && current->id == id) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        ht->table[hash(id, ht->size)] = current;
        return;
    }

    prev->next = current;

    struct Node* node_to_free = malloc(sizeof(struct Node));
    *node_to_free = *current;

    free(current);

    for (unsigned int i = 0; i < list_length(*list); ++i) {
        if ((*list)[i]->id == id) {
            memmove((*list + i), (*list + i + 1), (list_length(*list) - (i + 1)) * sizeof(struct Node*));
            free(*(list + list_length(*list) - 1));
            break;
        }
    }
}

unsigned int list_length(const struct Node** list) {
    unsigned int length = 0;
    const struct Node* node = *list;
    while (node != NULL) {
        ++length;
        node = node->next;
    }
    return length;
}

void resize_list(struct Node** list) {
    unsigned int old_size = sizeof(*list) / sizeof(struct Node*);
    struct Node** new_list = malloc((old_size + 1) * sizeof(struct Node*));
    memcpy(new_list, *list, old_size * sizeof(struct Node*));
    free(*list);
    *list = new_list;
}
