#define MAX_STRUCTURES 2000
#define SLIDING_WINDOW_SIZE 100

typedef struct {
    uint32_t rnti;
    uint16_t harq_pid;
    bool crcflag;
    // Other relevant fields...
} LTE_PHY_RX_CQI_MEASUREMENT_T;

void generate_pseudo_random(bool* flag) {
    static double seed = 123456789.0;
    seed = (69 * seed + 12345);
    if (seed > RAND_MAX) seed -= RAND_MAX;
    *flag = (*(unsigned int*)&seed >> 31) & 1;
}

void moving_average(double* window, double value, size_t* index) {
    if (*index < SLIDING_WINDOW_SIZE - 1) {
        ++(*index);
    } else {
        *window = (*window * (SLIDING_WINDOW_SIZE - 1) + value) / SLIDING_WINDOW_SIZE;
        --(*index);
    }
}

LTE_PHY_RX_CQI_MEASUREMENT_T* initialize_array(size_t N) {
    LTE_PHY_RX_CQI_MEASUREMENT_T* arr;
    size_t i, j, unique_rnti[N];

    if (N > MAX_STRUCTURES) return NULL;

    arr = malloc(N * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!arr) return NULL;

    unique_rnti[0] = 1;

    for (i = 1; i < N; ++i) {
        j = 0;
        while (j < i && unique_rnti[j] != 0) ++j;

        unique_rnti[i] = unique_rnti[j] + 1;
    }

    for (i = 0; i < N; ++i) {
        arr[i].rnti = unique_rnti[i];
        arr[i].harq_pid = i + 1;
        generate_pseudo_random(&arr[i].crcflag);
    }

    size_t index = N - SLIDING_WINDOW_SIZE;
    double moving_avg = 0.0;

    for (i = 0; i < N; ++i) {
        if (i >= index && i < index + SLIDING_WINDOW_SIZE) {
            moving_average(&moving_avg, arr[i].signal_quality, &index);
            arr[i].signal_quality = moving_avg;
        }
    }

    return arr;
}

void reset_crcflags(LTE_PHY_RX_CQI_MEASUREMENT_T* arr, size_t N) {
    for (size_t i = 0; i < N; ++i) arr[i].crcflag = false;
}
