size_t generate_records(Record** records, size_t n_offsets, size_t n_keys, size_t max_key) {
    if (!*records || *n_keys > max_key || *n_offsets > INT32_MAX / sizeof(long)) {
        fprintf(stderr, "Invalid input\n");
        return 0;
    }

    // Allocate memory for keys and initialize to -1 (unassigned)
    int* unique_keys = malloc((*n_keys + 1) * sizeof(int));
    if (!unique_keys) {
        perror("Memory allocation failed");
        return 0;
    }
    memset(unique_keys, -1, (*n_keys + 1) * sizeof(int));

    // Allocate memory for records and offsets arrays
    Record* allocated_records = malloc(sizeof(Record) * n_offsets);
    long* offsets = malloc(n_offsets * sizeof(long));
    if (!allocated_records || !offsets) {
        perror("Memory allocation failed");
        free(unique_keys);
        return 0;
    }

    // Seed random number generator with current time to ensure deterministic results
    srand((unsigned int)time(NULL));

    size_t num_records = 0;
    for (size_t i = 0; i < n_offsets && num_records < n_offsets; ++i) {
        // Generate a random key within the specified range, ensuring it is unique in both keys and records arrays
        int key = rand() % max_key + 1;
        while (unique_keys[key] >= 0 || (num_records > 0 && allocated_records[num_records - 1].key == key)) {
            key = rand() % max_key + 1;
        }

        unique_keys[key] = i;
        offsets[i] = i + 1; // First index is unused, so use the next index as the actual offset
        allocated_records[num_records].offset = offsets[i];
        allocated_records[num_records].key = key;
        ++num_records;
    }

    *records = allocated_records;
    return num_records;
}
