void cleanup(DistributedHashTable& dht) {
    auto expiredEntries = std::vector<std::pair<UserSessionData*, time_t>>();
    for (auto const& e : dht.hashTable.get<0>()) {
        if (std::chrono::system_clock::now() - std::chrono::system_clock::time_point(e->first->get_time_t()).get_sec() > dht.cleanupInterval.count()) {
            expiredEntries.push_back({ e->first, std::chrono::system_clock::now().time_since_epoch().count() });
        }
    }
    for (auto const& e : expiredEntries) {
        auto it = dht.sessionMap.find(e.first->get<0>());
        if (it != dht.sessionMap.end()) {
            delete it->second;
            dht.sessionMap.erase(it);
            dht.hashTable.erase(e.first);
        }
    }
}
