#include <time.h>
#include <sys/mman.h>

typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
    struct Record *prev, *next;
} Record;

struct PoolAllocator {
    void *memory;
    size_t capacity, used;
};

void pool_init(struct PoolAllocator *pool, size_t size) {
    pool->capacity = size;
    pool->used = 0;
    pool->memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->memory == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }
}

void *pool_alloc(struct PoolAllocator *pool, size_t size) {
    void *ptr = pool->memory + pool->used;
    if ((pool->used + size) > pool->capacity) {
        fprintf(stderr, "Memory exceeded\n");
        return NULL;
    }
    pool->used += size;
    return ptr;
}

Record* create_record(struct PoolAllocator *pool) {
    Record *rec = (Record*)pool_alloc(pool, sizeof(Record));
    if (!rec)
        return NULL;

    rec->key = find_unique_key();
    rec->offset = 0;
    rec->timestamp = time(NULL);
    rec->prev = rec->next = NULL;
    return rec;
}

int find_unique_key() {
    int key, i, shift;
    do {
        key = rand() % MAX_KEY_RANGE;
        shift = 1;
        for (i = key - 1; i >= 0; i--)
            if (records[i].key == key) {
                shift++;
                break;
            }
    } while (shift < MAX_SHIFT);

    return key;
}

void insert(Record *rec, Record **head) {
    rec->next = *head;
    if (*head)
        (*head)->prev = rec;
    *head = rec;
    if (rec->prev)
        rec->prev->next = rec;
}

void free_record(Record *rec) {
    if (rec->prev)
        rec->prev->next = rec->next;
    if (rec->next)
        rec->next->prev = rec->prev;
}

int main() {
    struct PoolAllocator pool;
    Record *head = NULL, **itr;
    pool_init(&pool, 1024*1024); // Initialize a 1MB memory pool

    for (int i = 0; i < NUM_RECORDS; ++i) {
        Record *rec = create_record(&pool);
        if (!rec) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
