        printf("Key: %d Offset: %ld Timestamp: %s\n", itr->key, itr->offset, ctime(&itr->timestamp));
        _mm_prefetch((char*)itr + 64, _MM_HINT_TTL); // Prefetching technique to reduce cache misses
    }

    return 0;
}
