class RNTI_CACHE {
public:
    std::set<uint32_t> used_rntis;
    std::mutex mtx;

    void add_used_rnti(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mtx);
        if (used_rntis.find(rnti) == used_rntis.end()) {
            used_rntis.insert(rnti);
        }
    }

    uint32_t get_unused_rnti() {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = used_rntis.begin(); it != used_rntis.end(); ++it) {
            if (it->second == 0) {
                auto rnti = *it;
                it->second = 1;
                return rnti;
            }
        }
        throw std::system_error(errno, std::generic_category(), "No more unused RNTI available");
    }
};

