#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int value;
} record;

typedef struct hash_table {
    unsigned long size;
    unsigned long capacity;
    pthread_mutex_t lock;
    record **data;
} HashTable;

void hash_table_init(HashTable *ht, unsigned long capacity) {
    ht->size = 0;
    ht->capacity = capacity;
    ht->data = calloc(ht->capacity, sizeof(record*));
    pthread_mutex_init(&ht->lock, NULL);
}

unsigned long hash(const void *key, unsigned long capacity) {
    const unsigned char *k = (const unsigned char *) key;
    unsigned long h = 0, len = strlen((char*)key);
    for (size_t i = 0; i < len; ++i)
        h = (h << 5) + h + k[i];
    return h % capacity;
}

void hash_table_insert(HashTable *ht, const void *key, record value) {
    pthread_mutex_lock(&ht->lock);
    unsigned long index = hash(key, ht->capacity);
    for (int i = index; !HT_EMPTY(ht, i); i = (i + 1) % ht->capacity) {
        if (!memcmp(ht->data[i], &value, sizeof(record)))
            break;
        index = (index + 1) % ht->capacity;
    }
    record *new_entry = malloc(sizeof(record));
    *new_entry = value;
    ht->data[index] = new_entry;
    ht->size++;
    pthread_mutex_unlock(&ht->lock);
}

record* hash_table_lookup(const HashTable *ht, const void *key) {
    unsigned long index = hash(key, ht->capacity);
    for (int i = index; !HT_EMPTY(ht, i); i = (i + 1) % ht->capacity) {
        if (!memcmp(ht->data[i], &key, sizeof(record)))
            return ht->data[i];
    }
    return NULL;
}

