[' Here's a C implementation that addresses the given programming task. I've used a combination of slab allocation for `record` structures and an optimized array for `int` keys, along with a custom memory pool for large file offset storage. The code also includes error handling, memory tracking, and the randomization of `record` values.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef unsigned long long offset_t;
typedef struct record {
    int value;
    offset_t offset;
    pthread_mutex_t ref_count_lock;
    int ref_count;
} record;

#define MAX_KEYS 10000
#define MAX_RECORDS 1000000
#define MAX_OFFSET_BYTES (10 * 1024 * 1024) // Max memory for offset_t array: 10 MB
#define MAX_RECORD_BYTES (5 * 1024 * 1024) // Max memory for record array: 5 MB

// Memory pool structure for large file offsets
typedef struct mem_pool {
    void* buffer;
    size_t total_allocated;
    size_t allocated;
} mem_pool;

// Custom allocator for records
void* record_alloc(size_t n) {
    // Use slab allocation with a fixed number of blocks and the given record count
    static record block[MAX_RECORDS / (1 + (MAX_RECORDS % MAX_KEYS))];
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate new blocks if necessary
    if (n > MAX_RECORDS / (1 + (MAX_RECORDS % MAX_KEYS))) {
        printf("Out of memory for record allocator\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    size_t idx = n / (1 + (MAX_RECORDS % MAX_KEYS));
    record* records = block + idx;
    size_t count = 0;

    while (count < n) {
        if (!records[count].ref_count || records[count].value == 0) {
            records[count].value = rand() % 100 + 1;
            records[count].offset = 0;
            records[count].ref_count++;
            count++;
        } else {
            records += count;
        }
    }

    pthread_mutex_unlock(&lock);

    return records;
}

// Memory pool for large file offsets
mem_pool offset_pool = {NULL, 0, 0};

void* offset_alloc(size_t n) {
    if (!offset_pool.buffer) {
        // Allocate initial memory for the memory pool
        offset_pool.buffer = malloc(MAX_OFFSET_BYTES);
        if (!offset_pool.buffer) {
            fprintf(stderr, "Out of memory for offset memory pool\n");
            return NULL;
        }
        offset_pool.total_allocated = MAX_OFFSET_BYTES;
    }

    // Update the total allocated memory and current allocation
    offset_pool.allocated += n;

    void* ptr = offset_pool.buffer + offset_pool.total_allocated - offset_pool.allocated;

    if (offset_pool.allocated > MAX_OFFSET_BYTES) {
        fprintf(stderr, "Exceeded memory limit for offset memory pool\n");
        free(offset_pool.buffer);
        offset_pool.buffer = NULL;
        return NULL;
    }

    return ptr;
}

// Frees the memory allocated by offset_alloc()
void offset_free(void* mem) {
    if (!offset_pool.buffer)
        return;

    // Update the total allocated memory and current allocation
    offset_pool.allocated -= (mem - offset_pool.buffer + offset_pool.total_allocated);
}

// Function to handle concurrent calls and manage memory resources
void* my_function(void* arg) {
    int *keys = malloc(MAX_KEYS * sizeof(int));

    if (!keys) {
        fprintf(stderr, "Out of memory for keys\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize keys with random values
    for (int i = 0; i < MAX_KEYS; ++i) {
        keys[i] = rand() % 100 + 1;
    }

    record* records = record_alloc(1000);

    if (!records) {
        free(keys);
        return NULL;
    }

    // Perform necessary computations using keys and records

    // Cleanup and track memory usage
    pthread_mutex_lock(&lock);
    for (int i = 0; i < 1000; ++i) {
        if (records[i].ref_count == 0) {
            offset_free(records[i].offset);
        }
    }
    pthread_mutex_unlock(&lock);

    free(keys);
    free(records);

    return NULL;
}
```

This code defines the necessary structures and custom allocators for each component. The `my_function()` is responsible for handling concurrent calls, initializing memory, performing computations, and cleaning up after execution. Keep in mind that this code does not include multi-threading synchronization mechanisms like semaphores or condition variables, which should be added to ensure proper operation under heavy load conditions.']

