use serde::{Deserialize, Serialize};
use uuid::Uuid;

use nfapi::{CRCFLAG, CRC_INDICATION_REL8_TAG, NFAPI_CRC_INDICATION_PDU_T, RNTI, RX_UE_INFORMATION_TAG};
use serde_json::Value;

fn create_temp_dir(base_path: &str) -> Path {
    let temp_dir = env::var("TEMP_DIR").unwrap_or_else(|_| format!("{}temp", base_path));
    let temp_dir = Path::new(&temp_dir);

    if !temp_dir.exists() {
        std::fs::create_dir_all(temp_dir).expect("Failed to create temp directory");
        env::set_var("TEMP_DIR", temp_dir.to_str().unwrap());
    }

    temp_dir
}

fn generate_list(num: u32, base_path: &str) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let temp_dir = create_temp_dir(base_path);
    let mut rng = thread_rng();

    let mut pdu_list = vec![];

    for _ in 0..num {
        let rnti = RNTI::new(Uuid::new_v4());
        let crcflag = CRCFLAG::new(rng.gen());
        let pdu = NFAPI_CRC_INDICATION_PDU_T {
            tag: CRC_INDICATION_REL8_TAG,
            rnti,
            crcflag,
        };
        let ue_info_tag = RX_UE_INFORMATION_TAG::default();
        pdu_list.push(NFAPI_CRC_INDICATION_PDU_T { tag: ue_info_tag, data: Value::Null })
    }

    // Save the list to a JSON file in the temp directory for later retrieval
    let output_path = temp_dir.join("pdus.json");
    let mut file = BufWriter::new(File::create(&output_path).unwrap());
    serde_json::to_writer_pretty(file, &pdu_list).expect("Failed to write JSON");

    pdu_list
}
