use std::env;
use std::fs::File;
use std::io::{BufWriter, Write};
use std::path::PathBuf;
use std::sync::Mutex;
use log::{info, trace};
use rand::{thread_rng, Rng};
use rayon::prelude::*;
use crc32fast as crc;

struct PduT {
    rx_ue_information_tag: u8,
    rnti: u16,
    crc_indication_rel8_tag: u8,
    crcflag: bool,
}

static TEMP_DIR: Mutex<PathBuf> = Mutex::new(get_temp_dir());

fn get_temp_dir() -> PathBuf {
    let temp_dir = env::var("TEMP_DIR").unwrap_or_else(|_| "/tmp".to_owned());
    if !Path::new(&temp_dir).is_dir() {
        std::fs::create_dir_all(&temp_dir).expect("Could not create temp directory");
    }
    PathBuf::from(temp_dir)
}

fn log_pdu(pdu: &PduT) {
    let timestamp = chrono::Utc::now().to_rfc3339();
    let log_path = TEMP_DIR.lock().unwrap().join("log.txt");
    let file = File::create(&log_path).expect("Could not create log file");
    let mut writer = BufWriter::new(file);
    writeln!(writer, "{}: {:?}", timestamp, pdu).expect("Error writing to log");
}

fn generate_pdu(count: usize) -> Vec<PduT> {
    let rng = thread_rng();
    (0..count)
        .map(|_| PduT {
            rx_ue_information_tag: 1, // replace with desired value
            rnti: rng.gen(),           // replace with desired range
            crc_indication_rel8_tag: rng.gen(),
            crcflag: rng.gen::<bool>(),
        })
        .collect()
}

fn process_pdus(pdus: Vec<PduT>, num_threads: usize) {
    let num_pdus = pdus.len();
    let chunk_size = num_pdus / num_threads;
    trace!("Chunk size: {}", chunk_size);
    pdus.par_iter(num_threads).for_each(|chunk| {
        for pdu in chunk {
            // CRC computation and other heavy processing go here
            let crc = crc::checksum_ieee(pdu as u32);
            pdu.crc_indication_rel8_tag = (crc & 0xff) as u8;
        }
    });
}

fn main() {
    // Initialize logging service here
    // Set up a logging handler with the required format and asynchronous operations

    let count = 100000;
    let num_threads = std::env::args().nth(1).map(|s| s.parse::<usize>().unwrap_or(1)).unwrap();
    info!("Generating {} PDUs with {} threads", count, num_threads);
    let pdus = generate_pdu(count);
    process_pdus(pdus, num_threads);
    log_pdu(&pdus[0]);
}
