// Define the record structure and a custom deleter for efficient memory management
struct record {
    int *value;
    long *offset;
};

struct MemPool {
    std::vector<std::unique_ptr<record>> pool;
    void* allocated_memory = nullptr;
    size_t capacity = 0, allocated = 0;
    std::mutex mtx;

    MemPool(size_t initial_capacity) : pool(initial_capacity, new record) {
        capacity += initial_capacity;
    }

    record* alloc() {
        if (allocated < capacity) {
            ++allocated;
            return pool.back().release();
        }

        std::unique_ptr<record> new_entry(new record);
        allocateMemoryIfNeeded(1);
        return new_entry.release();
    }

    void dealloc(record* r) {
        if (!r) return;
        std::unique_ptr<record>(r).reset();
        --allocated;
    }

private:
    void allocateMemoryIfNeeded(size_t additional_capacity) {
        mtx.lock();
        if (additional_capacity + allocated > capacity * 2) {
            capacity *= 2;
            void* new_memory = std::malloc(capacity * sizeof(record));
            if (!new_memory) {
                mtx.unlock();
                throw std::bad_alloc();
            }
            pool.resize(capacity);
            for (size_t i = allocated; i < capacity; ++i)
                pool[i] = std::unique_ptr<record>(new record, MemPoolDeleter{&pool[i - allocated], this});
            std::memcpy(pool.data() + allocated, allocated_memory, (capacity - allocated) * sizeof(record));
            std::free(allocated_memory);
        }
        mtx.unlock();
    }
};

struct MemPoolDeleter {
    record* ptr;
    MemPool* pool;

    MemPoolDeleter(record*, MemPool*) : ptr(ptr), pool(pool) {}

    void operator()(record* p) const noexcept {
        pool->dealloc(p);
    }
};

