    }

    long* offsets = static_cast<long*>(mem_pool.alloc());
    int* keys = mem_pool.alloc();
    for (int i = 0; i < key_size; ++i) {
        keys[i] = i;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    for (int i = 0; i < offset_size; ++i) {
        offsets[keys[i]] = i;
        auto r = mem_pool.alloc();
        r->value = &dis(gen);
        r->offset = offsets + keys[i];
    }
}

void printRecords(const MemPool& mem_pool) {
    for (const auto& record : mem_pool.pool) {
        std::cout << "Value: " << *record->value << ", Offset: " << *record->offset << std::endl;
    }
}

