void init_record(Record* record) {
    record->value = 0;
    record->offsets = malloc(sizeof(long));
    if (!record->offsets) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }
    record->capacity = 1;
    record->size = 0;
