void resize_record(Record* record, size_t new_size) {
    if (new_size <= record->capacity) return;

    long* new_offsets = realloc(record->offsets, new_size * sizeof(long));
    if (!new_offsets) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }
    record->capacity = new_size;
    record->offsets = new_offsets;
}

void init_list(List* list, size_t size) {
    if (size > MAX_RECORDS) {
        fprintf(stderr, "Error: too many records\n");
        exit(EXIT_FAILURE);
    }

    list->records = malloc(sizeof(Record) * size);
    if (!list->records) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        init_record(&list->records[i]);
    }

    list->size = size;
    list->capacity = size;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_list(List* list, size_t new_size) {
    if (new_size <= list->capacity) return;

    Record* new_records = realloc(list->records, sizeof(Record) * new_size);
    if (!new_records) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }

    list->records = new_records;
    for (size_t i = list->size; i < new_size; ++i) {
        init_record(&list->records[i]);
    }

    list->capacity = new_size;
}

void update_int(List* list, size_t index, int value) {
    pthread_mutex_lock(&list->mutex);
    list->records[index].value = value;
    pthread_mutex_unlock(&list->mutex);
}

void set_random_values(List* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        list->records[i].value = rand() % VALUE_RANGE;
    }
    pthread_mutex_unlock(&list->mutex);
}

void clear_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].offsets) free(list->records[i].offsets);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

void destroy_list(List* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
}
