} LTE_PHY_RX_CQI_MEASUREMENT;

typedef struct RNTI_NODE_T {
    LTE_PHY_RX_CQI_MEASUREMENT measurement;
    struct RNTI_NODE_T* next;
} RNTI_NODE;

static RNTI_NODE* rnti_head = NULL;
static RNTI_NODE* rnti_tail = NULL;
static const size_t MAX_SIZE = 1000; // Adjust this to balance memory usage and performance
static pthread_mutex_t rnti_list_lock = PTHREAD_MUTEX_INITIALIZER;

LTE_PHY_RX_CQI_MEASUREMENT* init_measurement() {
    LTE_PHY_RX_CQI_MEASUREMENT* measurement = malloc(sizeof(LTE_PHY_RX_CQI_MEASUREMENT));
    if (!measurement) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }

    measurement->rnti = 0; // Initialize with an invalid rnti value
    measurement->harq_pid = 0;

    // Generate a random SRS ID within the specified range
    for (int i = 0; i < sizeof(measurement->srs_id); ++i) {
        measurement->srs_id[i] = rand() % 256;
    }

    return measurement;
}

RNTI_NODE* find_idle_rnti() {
    pthread_mutex_lock(&rnti_list_lock);

    RNTI_NODE* current = rnti_head;
    if (current) {
        for (size_t i = 0; i < MAX_SIZE; ++i, current = current->next) {
            // Check if the measurement structure is idle and return it
            if (!current->measurement.rnti) {
                rnti_head = current->next;
                if (!rnti_tail) {
                    rnti_tail = current;
                }
                pthread_mutex_unlock(&rnti_list_lock);
                return current;
            }
        }
    }

    // If no idle RNTI is found, continue to the next iteration without unlocking the mutex

    pthread_mutex_unlock(&rnti_list_lock);

    if (current == rnti_tail) {
        // Recycle an old RNTI from the end of the list
        current->measurement.rnti = 0; // Mark as idle
        return current;
    }

    // If the list is full, attempt to recycle a used RNTI and log an informational message if necessary
    RNTI_NODE* node_to_free = rnti_head;
    node_to_free->measurement.rnti = 0; // Mark as idle
    free(node_to_free->measurement.srs_id); // Free the SRS ID array
    free(node_to_free); // Free the RNTI node

    if (rnti_head == rnti_tail) {
        rnti_head = rnti_tail = NULL;
    } else {
        rnti_head = node_to_free->next;
