    uint8_t phy_rx_cqi;
    uint8_t rx_cqi_tag;
    uint16_t srs_id;
} LTE_PHY_RX_CQI_MEASUREMENT_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_structures = 0;
static bool log_failures = false;

void *generate_tag(void *arg) {
    while (true) {
        LTE_PHY_RX_CQI_MEASUREMENT_T *structure = malloc(sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
        if (!structure) continue;

        structure->rnti = (*((uint32_t *)arg)).rnti;
        structure->harq_pid = (*((uint32_t *)arg)).harq_pid;
        structure->phy_rx_cqi = rand() % 15 + 1; // Valid range: 1-15 for CQI measurements
        structure->rx_cqi_tag = rand();
        structure->srs_id = rand() % (LTE_MAX_SRS_ID - LTE_MIN_SRS_ID + 1) + LTE_MIN_SRS_ID; // Valid range: LTE_MIN_SRS_ID to LTE_MAX_SRS_ID

        pthread_mutex_lock(&mutex);
        if (num_structures < MAX_STRUCTURES && num_structures >= MIN_STRUCTURES) {
            // Check for duplicate rnti and distinct srs_id within the structure
            bool unique = true;
            for (int i = 0; i < num_structures; ++i) {
                if (structure->rnti == structs[i].rnti || structure->srs_id == structs[i].srs_id) {
                    unique = false;
                    break;
                }
            }

            if (unique) {
                structs = realloc(structs, sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T) * ++num_structures);
                memcpy(&structs[num_structures - 1], structure, sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
                pthread_mutex_unlock(&mutex);
                break;
            }
        }
        pthread_mutex_unlock(&mutex);

        free(structure);
    }
}

void init_structures(uint32_t *rntis, uint8_t *harq_pids) {
    int num_threads = (MAX_STRUCTURES - num_structures < MIN_STRUCTURES) ? MAX_STRUCTURES - num_structures : MIN_STRUCTURES;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        uint32_t rnti = rntis[rand() % sizeof(rntis)/sizeof(*rntis)]; // Randomly select an available RNTI from the provided array
        pthread_create(&threads[i], NULL, generate_tag, (void *) &((uint32_t){rnti, harq_pids[rand() % sizeof(harq_pids)/sizeof(*harq_pids)]}));
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (log_failures && num_structures != MAX_STRUCTURES) {
        printf("Failed to initialize %d structures out of %d.\n", MAX_STRUCTURES - num_structures, MAX_STRUCTURES);
    }
}
