void log_message(enum LOG_LEVEL level, const char *format, ...) {
    if (level <= log_level) {
        FILE *log_file = fopen(log_filename, "a");
        va_list args;
        time_t current_time;
        struct tm *time_info;

        if (log_file != NULL) {
            current_time = time(NULL);
            time_info = localtime(&current_time);

            fprintf(log_file, "%s", asctime(time_info));
            va_start(args, format);
            vfprintf(log_file, format, args);
            va_end(args);
            fputc('\n', log_file);
            fclose(log_file);
        }
    }
}

int init_dynamic_array(size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        log_message(ERROR, "Requested number of elements exceeds the maximum allowed.\n");
        return -1;
    }

    data = mmap(NULL, sizeof(struct PHY_RX_MEASUREMENT) * num_elements, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    pthread_rwlock_init(&data_lock, NULL);

    // Initialize elements with unique rnti and randomly generated srs_id
    for (size_t i = 0; i < num_elements; ++i) {
        RX_CQI_TAG* tag = &data[i].rx_cqi_tag;
        uint16_t found_rnti = 0;

        do {
            tag->rnti = i;
            tag->harq_pid = (i >> 4) + 1; // Assuming harq_pid is between 1 and 15

            for (size_t j = 0; j < i; ++j) {
                if (data[j].rx_cqi_tag.rnti == tag->rnti) {
                    found_rnti = 1;
                    break;
                }
            }
        } while (found_rnti);

        uint16_t srs_id = rand() % 8 + 1; // Assuming a valid range of 1-8 for srs_id
        data[i].phy_rx_srs_tag.srs_id = srs_id;
    }

    return 0;
}

void cleanup() {
    if (data != NULL) {
        munmap(data, sizeof(struct PHY_RX_MEASUREMENT) * MAX_ELEMENTS);
        pthread_rwlock_destroy(&data_lock);
        data = NULL;
    }
}
