void log_error(const char* error) {
    clock_gettime(CLOCK_REALTIME, &log_timestamp);
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%ld.%09ld: Error: %s\n",
             (long)log_timestamp.tv_sec, log_timestamp.tv_nsec, error);
    write(fileno(log_file), log_entry, strlen(log_entry));
