    request->RNTI = get_rnti();
    request->CRCFLAG = rand() < 3 * RAND_MAX / 4 ? 1 : 0;
    return NULL;
}

void process_queue() {
    pthread_t threads[MAX_ENTRIES];
    record* requests = mmap(NULL, sizeof(record) * MAX_ENTRIES, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (requests == MAP_FAILED) {
        log_error("Memory mapping failed");
        return;
    }

    sem_wait(&queue_mutex);
    int queue_size = 0;
    for (int i = 0; i < MAX_ENTRIES && queue_size < MAX_ENTRIES; ++i) {
        if (!sem_trywait(&mem_mutex)) {
            if (mem_used + sizeof(record) <= mem_threshold * getpagesize()) {
                mem_used += sizeof(record);
                requests[queue_size] = (record){0};
                ++queue_size;
            }
            sem_post(&mem_mutex);
        }
    }
    sem_post(&queue_mutex);

    for (int i = 0; i < queue_size; ++i) {
        pthread_create(&threads[i], NULL, process_request, &requests[i]);
    }

    for (int i = 0; i < queue_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    munmap(requests, sizeof(record) * MAX_ENTRIES);
}

void init() {
    sem_init(&log_mutex, 1, 1);
    sem_init(&queue_mutex, 1, 1);
    sem_init(&mem_mutex, 1, 1);
    log_file = fopen("error.log", "a");
}

int main() {
    init();

    // Implement your own request handling mechanism here to accept requests and enqueue them
    // ...

    while (true) {
        process_queue();
        // ...
    }

    fclose(log_file);
    return 0;
}
