#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char str[256];
    struct entry* next_entry;
    struct metadata* meta;
} entry_t;

typedef struct {
    entry_t* entry;
    struct metadata* meta;
} data_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_elements = 0;
static const size_t element_capacity = 16;
static data_t* data = NULL;

void append_entry(data_t* data, double value, char* str, struct entry* next_entry, struct metadata* meta) {
    pthread_mutex_lock(&mutex);
    if (num_elements >= element_capacity) {
        data_t* new_data = realloc(data, sizeof(data_t) * (element_capacity + 8));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        data = new_data;
        element_capacity += 8;
    }
    data[num_elements].entry->value = value;
    strcpy(data[num_elements].entry->str, str);
    data[num_elements].entry->next_entry = next_entry;
    data[num_elements].entry->meta = meta;
    num_elements++;
    pthread_mutex_unlock(&mutex);
}

void merge(data_t* src, data_t* dest) {
    pthread_mutex_lock(&mutex);
    size_t min_len = (src->num_elements < dest->num_elements) ? src->num_elements : dest->num_elements;
    for (size_t i = 0; i < min_len; ++i) {
        dest->data[i]->entry->value = src->data[i]->entry->value;
        strcpy(dest->data[i]->entry->str, src->data[i]->entry->str);
        dest->data[i]->entry->next_entry = src->data[i]->entry->next_entry;
        dest->data[i]->entry->meta = src->data[i]->entry->meta;
    }
    free(src->data);
    src->num_elements = 0;
    pthread_mutex_unlock(&mutex);
}

void serialize(const data_t* data, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    fwrite(&num_elements, sizeof(size_t), 1, file);
    for (size_t i = 0; i < num_elements; ++i) {
        fwrite(&data[i].entry->value, sizeof(double), 1, file);
        size_t str_len = strlen(data[i].entry->str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(data[i].entry->str, sizeof(char), str_len, file);
    }

    fclose(file);
}

void deserialize(data_t* data, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file for reading\n");
        return;
    }

    fread(&num_elements, sizeof(size_t), 1, file);
    realloc(data, sizeof(data_t) * num_elements);

    for (size_t i = 0; i < num_elements; ++i) {
        fread(&data[i].entry->value, sizeof(double), 1, file);
        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        data[i].entry->str = malloc(str_len + 1);
        fread(data[i].entry->str, sizeof(char), str_len, file);
        data[i].entry->str[str_len] = '\0';
    }

    fclose(file);
}
```

