#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct Record {
    int key;
    int offset;
    int value;
} Record;

static unsigned long max_keys = 10000;
static unsigned long current_keys = 0;
static Record* records;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Generate a unique key within the given range
unsigned long generate_key() {
    return (rand() % max_keys) + 1;
}

void init_records(int num_records, int min_value, int max_value) {
    records = mmap(NULL, sizeof(Record) * num_records, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    for (int i = 0; i < num_records; ++i) {
        records[i].key = generate_key();
        records[i].offset = i;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    qsort(records, num_records, sizeof(Record), compare);
}

int compare(const void* a, const void* b) {
    return ((Record*)a)->key - ((Record*)b)->key;
}

void update_value(unsigned long key, int new_value) {
    pthread_mutex_lock(&lock);

    // Find the record with the given key
    Record* target = NULL;
    for (int i = 0; i < current_keys; ++i) {
        if (records[i].key == key && records[i].value != new_value) {
            target = &records[i];
            break;
        }
    }

    // If the record was found, update its value and re-sort the list
    if (target != NULL) {
        target->value = new_value;
        qsort(records, current_keys, sizeof(Record), compare);
    }

    pthread_mutex_unlock(&lock);
}

void free_memory() {
    munmap(records, sizeof(Record) * current_keys);
    records = NULL;
}

// ... (Other helper functions to handle concurrent updates, validation checks, etc.)
