['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    double value;
    size_t index;
} item;

typedef struct node {
    item *item;
    struct node *next;
    struct node *prev;
} node;

struct list {
    node *head;
    node *tail;
    size_t capacity;
    size_t length;
    size_t ttl;
    pthread_mutex_t mutex;
    node **cache; // cache for frequently accessed items
};

void init_list(struct list *list, size_t capacity, size_t ttl) {
    list->head = NULL;
    list->tail = NULL;
    list->capacity = capacity;
    list->length = 0;
    list->ttl = ttl;
    pthread_mutex_init(&list->mutex, NULL);
    list->cache = calloc(capacity, sizeof(node*));
}

void push_front(struct list *list, item *item) {
    node *new_node = malloc(sizeof(node));
    new_node->item = item;
    new_node->next = list->head;
    new_node->prev = NULL;

    if (list->head != NULL)
        list->head->prev = new_node;

    list->head = new_node;
    if (!list->tail)
        list->tail = new_node;

    list->length++;
}

void push_back(struct list *list, item *item) {
    node *new_node = malloc(sizeof(node));
    new_node->item = item;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail != NULL)
        list->tail->next = new_node;

    list->tail = new_node;

    if (!list->head)
        list->head = new_node;

    list->length++;
}

void remove(struct list *list, node *node_to_remove) {
    if (node_to_remove == list->head) {
        list->head = node_to_remove->next;
        if (list->head != NULL)
            list->head->prev = NULL;
    } else if (node_to_remove == list->tail) {
        list->tail = node_to_remove->prev;
        if (list->tail != NULL)
            list->tail->next = NULL;
    } else {
        node_to_remove->prev->next = node_to_remove->next;
        node_to_remove->next->prev = node_to_remove->prev;
    }

    free(node_to_remove);
    list->length--;
}

item* get_cached_item(struct list *list, size_t index) {
    if (index >= list->capacity || !list->cache[index]) return NULL;
    return list->cache[index]->item;
}

void put_cached_item(struct list *list, item *item, size_t index) {
    if (index >= list->capacity) return;
    free(list->cache[index]);
    list->cache[index] = malloc(sizeof(node));
    list->cache[index]->item = item;
}

void traverse_and_print(struct list *list) {
    pthread_mutex_lock(&list->mutex);
    node *current = list->head;
    while (current != NULL) {
        printf("Index: %zu, Value: %.2f\n", current->item->index, current->item->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
```

This code defines a struct for `item`, a struct for `node`, and another for the linked list. The `init_list()` function initializes the linked list, with arguments specifying its maximum size and TTL for cached items. The `push_front()` and `push_back()` functions add elements to either end of the list, while the `remove()` function removes an element at a specified index. The `get_cached_item()` and `put_cached_item()` functions implement a caching mechanism for frequently accessed items. Finally, the `traverse_and_print()` function iterates through the linked list and prints the associated `struct item` values.

The code also implements mutex locking to ensure thread safety when accessing or modifying the linked list. The functions use a global variable `list` as their argument, which should be initialized outside this scope to allow for concurrent access from multiple threads.']

