struct mem_allocation_log {
    size_t failed_count;
    LTE_PHY_RX_CQI_MEASUREMENT *failed_elements[MAX_STRUCTURES];
};

void init_mutex(LTE_PHY_RX_CQI_MEASUREMENT *element) {
    pthread_mutex_init(&element->mutex, NULL);
}

size_t get_unique_rnti() {
    static uint32_t current_rnti = 1;
    return current_rnti++;
}

void generate_srs_id(uint8_t *srs_id) {
