}

LTE_PHY_RX_CQI_MEASUREMENT* allocate_element() {
    LTE_PHY_RX_CQI_MEASUREMENT* element = (LTE_PHY_RX_CQI_MEASUREMENT*) malloc(sizeof(LTE_PHY_RX_CQI_MEASUREMENT));
    if (!element) {
        return NULL;
    }

    init_mutex(element);
    element->rnti = get_unique_rnti();
    generate_srs_id(&element->phy_rx_srs_tag);

    return element;
}

void free_element(LTE_PHY_RX_CQI_MEASUREMENT *element) {
    if (element) {
        free(element);
    }
}

struct mem_allocation_log* init_array(size_t *num_elements, size_t max_elements) {
    struct mem_allocation_log *log = calloc(1, sizeof(*log));
    if (!log) {
        return NULL;
    }

    log->failed_count = 0;

    *num_elements = (max_elements > MAX_STRUCTURES) ? MAX_STRUCTURES : max_elements;
    LTE_PHY_RX_CQI_MEASUREMENT **array = calloc(*num_elements, sizeof(LTE_PHY_RX_CQI_MEASUREMENT*));
    if (!array) {
        free(log);
        return NULL;
    }

    size_t current_index = 0;
    LTE_PHY_RX_CQI_MEASUREMENT *current_element;
    while (current_index < *num_elements && (current_element = allocate_element())) {
        array[current_index] = current_element;
        current_index++;
    }

    if (current_index < *num_elements) {
        size_t new_max_elements = (*num_elements / GROWTH_FACTOR) + 1;
        struct mem_allocation_log *new_log = init_array(num_elements, new_max_elements);
        if (new_log) {
            free(log);
            return new_log;
        } else {
            log->failed_count += current_index;
            for (size_t i = 0; i < current_index; i++) {
                log->failed_elements[log->failed_count - 1] = array[i];
            }
            free(array);
            return log;
        }
    }

    *num_elements = current_index;
    return log;
}

void print_allocation_log(struct mem_allocation_log *log) {
    if (log->failed_count > 0) {
        printf("Failed allocations:\n");
        for (size_t i = 0; i < log->failed_count; i++) {
            printf("  - rnti: %u, harq_pid: %u, srs_id: %u\n",
                   log->failed_elements[i]->rnti,
                   log->failed_elements[i]->harq_pid,
                   log->failed_elements[i]->phy_rx_srs_tag);
        }
    }
}
