} Node;

struct List {
    Node* head;
    Node* tail;
    size_t capacity;
    size_t size;
    pthread_mutex_t list_mutex;
    bool logging_enabled;
};

void log(const char* message) {
    // Integrate with an external logging framework here.
}

void destroy_node(Node** node) {
    if (*node != NULL) {
        pthread_mutex_destroy(&(*node)->mutex);
        free(*node);
        *node = NULL;
    }
}

List* create_list(size_t capacity, bool logging_enabled) {
    List* list = malloc(sizeof(List));
    if (!list) {
        log("Memory allocation failed.");
        return NULL;
    }
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    list->logging_enabled = logging_enabled;
    pthread_mutex_init(&list->list_mutex, NULL);
    return list;
}

void push(List* list, LTE_PHY_RX_CQI_MEASUREMENT_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log("Memory allocation failed.");
        return;
    }
    new_node->data = data;
    pthread_mutex_init(&new_node->mutex, NULL);

    pthread_mutex_lock(&list->list_mutex);

    if (list->size >= list->capacity) {
        log("List is full.");
        destroy_node(&new_node);
        pthread_mutex_unlock(&list->list_mutex);
        return;
    }

    Node* temp = list->head;
    if (!temp) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = new_node;
        list->tail = new_node;
    }

    ++list->size;
    pthread_mutex_unlock(&list->list_mutex);

    if (list->logging_enabled) {
        log("Push successful.");
    }
}

LTE_PHY_RX_CQI_MEASUREMENT_T* pop(List* list) {
    pthread_mutex_lock(&list->list_mutex);
    if (list->size == 0) {
        pthread_mutex_unlock(&list->list_mutex);
        return NULL;
    }

    Node* temp = list->head;
    LTE_PHY_RX_CQI_MEASUREMENT_T* data = &temp->data;
    list->head = temp->next;
    destroy_node(&temp);

    --list->size;
    pthread_mutex_unlock(&list->list_mutex);

    return data;
}

