        !(ld->timestamps = malloc(items * sizeof(double))) ||
        !(ld->entries = calloc(items, sizeof(entry*))) ||
        !ld->log_service) {
        fprintf(stderr, "Allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

void log_data_init(struct log_data *ld, size_t capacity, int max_rate, void (*log_func)(const float, const double, const entry*)) {
    ld->capacity = capacity;
    ld->max_rate = max_rate;
    ld->log_service = log_func;

    check_alloc(ld, capacity);

    pthread_mutex_init(&ld->lock, NULL);
    pthread_cond_init(&ld->cond_full, NULL);
    pthread_cond_init(&ld->cond_empty, NULL);
}

void log_push(struct log_data *ld, float f_val, double timestamp, const char* msg, size_t len) {
    if (ld->head == ld->tail + 1 || (ld->tail + 1 >= ld->capacity && (ld->head != 0))) {
        pthread_mutex_lock(&ld->lock);
        while ((ld->head == ld->tail + 1 || (ld->tail + 1 >= ld->capacity && (ld->head != 0))) && ld->capacity < getpagesize() * getconf("SC_PAGE_SIZE") / 2) {
            pthread_cond_wait(&ld->cond_empty, &ld->lock);
        }
        if ((ld->head == ld->tail + 1 || (ld->tail + 1 >= ld->capacity && (ld->head != 0))) && ld->capacity >= getpagesize() * getconf("SC_PAGE_SIZE") / 2) {
            fprintf(stderr, "Memory allocation exceeded limit.\n");
        }
        pthread_mutex_unlock(&ld->lock);
    }

    entry* e = realloc(ld->entries[ld->tail], len + sizeof(entry));
    if (!e) {
        fprintf(stderr, "Reallocation failed.\n");
        exit(EXIT_FAILURE);
    }

    memcpy(e->msg, msg, len);
    e->key = (rand() % INT_MAX); // ensures uniqueness within the buffer
    e->len = len;

    ld->entries[ld->tail] = e;
    ld->timestamps[ld->tail] = timestamp;
    ld->f_vals[ld->tail] = 0.0f; // placeholder value for the float array
    ld->tail = (ld->tail + 1) % ld->capacity;

    if ((ld->head != ld->tail) && (gettimeofday().tv_sec - ld->log_service_last >= 1.0 / ld->max_rate)) {
        log_service(ld->f_vals[ld->head], ld->timestamps[ld->head], ld->entries[ld->head]);
        ld->log_service_last = gettimeofday().tv_sec;
        ld->head = (ld->head + 1) % ld->capacity;
    }
}
```

