class ExternalSource {
public:
    virtual ~ExternalSource() {}
    virtual auto GetUserParams(uint32_t user_id) = 0;
};

class Cache {
private:
    std::unordered_map<uint32_t, std::shared_ptr<std::vector<void*>>> cache_;
    mutable std::mutex mtx_;

public:
    auto GetOrFetch(const ExternalSource& source, uint32_t user_id) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto it = cache_.find(user_id);
        if (it != cache_.end()) {
            return it->second;
        }

        auto params = source.GetUserParams(user_id);
        std::vector<void*> data(params.begin(), params.end());
        std::shared_ptr<std::vector<void*>> sharedData(new std::vector<void*>(data));
        cache_[user_id] = sharedData;
        lock.unlock();
        return sharedData;
    }
};

