typedef struct _NFAPI_DYNAMIC_LIST_T {
    NFAPI_CRC_INDICATION_PDU** elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_DYNAMIC_LIST;

NFAPI_DYNAMIC_LIST* nfapi_dynamic_list_create(size_t initial_capacity) {
    NFAPI_DYNAMIC_LIST* list = malloc(sizeof(NFAPI_DYNAMIC_LIST));
    if (!list) {
        return NULL;
    }

    list->elements = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU*));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void nfapi_dynamic_list_destroy(NFAPI_DYNAMIC_LIST* list) {
    if (!list) {
        return;
    }

    for (size_t i = 0; i < list->size; ++i) {
        free(list->elements[i]);
    }

    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

NFAPI_CRC_INDICATION_PDU* nfapi_dynamic_list_push(NFAPI_DYNAMIC_LIST* list, const NFAPI_RX_UE_INFORMATION_TAG* rx_ue_information_tag, uint32_t rnti, CRC_INDICATION_REL8_TAG* crc_indication_rel8_tag) {
    if (!list || !rx_ue_information_tag || !crc_indication_rel8_tag || !(crc_indication_rel8_tag->crcflag = rand() % 2)) {
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU** new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU*));

        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return NULL;
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    memcpy(pdu, (void*)rx_ue_information_tag, sizeof(NFAPI_RX_UE_INFORMATION_TAG));
    pdu->rnti = rnti;
    memcpy(&pdu->crc_indication_rel8_tag, crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG));

    list->elements[list->size] = pdu;
    ++list->size;

    pthread_mutex_unlock(&list->mutex);
    return pdu;
}
