struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class MemoryPool {
public:
    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (freeList.empty()) {
            std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> newBlock(new NFAPI_CRC_INDICATION_PDU_T[capacity]);
            for (auto& el : newBlock.get()) {
                el.RX_UE_INFORMATION_TAG = rand();
                el.RNTI = rand();
                el.CRC_INDICATION_REL8_TAG = rand();
                el.CRCFLAG = false;
                occupiedList.push_back(el);
            }
            capacity *= 2;
        }
        auto result = freeList.front();
        freeList.pop_front();
        occupiedList.erase(std::remove(occupiedList.begin(), occupiedList.end(), result), occupiedList.end());
        return result;
    }

    void deallocate(NFAPI_CRC_INDICATION_PDU_T& obj) {
        if (freeList.size() >= capacity / 4 && std::find(occupiedList.begin(), occupiedList.end(), obj) != occupiedList.end()) {
            freeList.push_back(obj);
            occupiedList.erase(std::find(occupiedList.begin(), occupiedList.end(), obj));
        }
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> occupiedList;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> freeList;
    uint32_t capacity = 16;
};

void log(const char* msg) {
    static auto logFile = std::unique_ptr<std::ofstream>(new std::ofstream("log.txt", std::ios::app));
    if (logFile && *logFile) {
        *logFile << msg << '\n';
    }
}

void updateStructure(NFAPI_CRC_INDICATION_PDU_T& structure, int fieldToUpdate, int newValue) {
