        case 0: // RX_UE_INFORMATION_TAG
            structure.RX_UE_INFORMATION_TAG = newValue;
            break;
        case 1: // RNTI
            structure.RNTI = newValue;
            break;
        case 2: // CRC_INDICATION_REL8_TAG
            structure.CRC_INDICATION_REL8_TAG = newValue;
            break;
        case 3: // CRCFLAG
            structure.CRCFLAG = static_cast<bool>(newValue);
            break;
    }
}

void manageArray(int N, MemoryPool& pool, int updatesCount) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> array;
    if (N > 0) {
        for (size_t i = 0; i < N; ++i) {
            array.push_back(pool.allocate());
        }
    }

    std::mt19937 rng(std::chrono::high_resolution_clock::now().time_since_epoch().count());

    for (size_t i = 0; i < updatesCount; ++i) {
        int index = rng() % array.size();
        updateStructure(array[index], rand() % 4, rand());
        log(std::to_string(i) + ": Updated field " + std::to_string(rand() % 4) + " of structure at index " + std::to_string(index));
    }

    for (auto& el : array) {
        pool.deallocate(el);
    }
}

int main() {
    MemoryPool memPool;
    int N = 10;
    int updatesCount = 1000;

