    while (retries > 0) {
        sem_wait(&memory_sem); // Wait for memory resources to become available

        tmp_arr = (NFAPI_CRC_INDICATION_PDU_T*) malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

