void* memory_pool_allocate(size_t size, void **out) {
    pthread_mutex_lock(&memory_pool_mutex);
    if (allocated_elements + size > max_elements) {
        error_code = MEMORY_POOL_EXCEEDED;
        pthread_mutex_unlock(&memory_pool_mutex);
        return NULL;
    }
    void *block = calloc(size, sizeof(char));
    if (!block) {
        error_code = MEMORY_ALLOCATION_FAILURE;
        pthread_mutex_unlock(&memory_pool_mutex);
        return NULL;
    }
    allocated_elements += size;
    *out = block;
    pthread_mutex_unlock(&memory_pool_mutex);
    return block;
}

void memory_pool_free(void *block) {
