#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

struct DataStructure {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

void initialize_record(Record *record, int min, int max) {
    record->value = rand() % (max - min + 1) + min;
}

struct DataStructure* create_data_structure(size_t capacity) {
    struct DataStructure *ds = malloc(sizeof(struct DataStructure));
    if (!ds) return NULL;

    ds->offsets = calloc(capacity, sizeof(long));
    if (!ds->offsets) {
        free(ds);
        return NULL;
    }

    ds->keys = calloc(capacity, sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = malloc(capacity * sizeof(Record));
    if (!ds->records) {
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    ds->capacity = capacity;
    ds->length = 0;

    return ds;
}

void destroy_data_structure(struct DataStructure *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->mutex);
        free(ds);
    }
}

struct DataSource {
    // Add your data source implementation here
};

void periodically_update_data_structure(struct DataStructure *ds, struct DataSource *source) {
    // Implement periodic updates with data source here
}

int add_record(struct DataStructure *ds, int key, Record record) {
    if (!ds || ds->length == ds->capacity) return -1;

    pthread_mutex_lock(&ds->mutex);
    size_t i;
    for (i = 0; i < ds->length; ++i) {
        if (ds->keys[i] == key) {
            pthread_mutex_unlock(&ds->mutex);
            return -1;
        }
    }

    if (ds->length) {
        ds->offsets[ds->length] = ds->offsets[ds->length - 1] + sizeof(Record);
    } else {
        ds->offsets[0] = 0;
    }

    ds->keys[ds->length] = key;
    memcpy((void *)(ds->offsets[ds->length]), &record, sizeof(Record));

    ds->length++;
    pthread_mutex_unlock(&ds->mutex);

    return 0;
}

int remove_record(struct DataStructure *ds, int key) {
    if (!ds || ds->length == 0) return -1;

    pthread_mutex_lock(&ds->mutex);
    size_t i;
    for (i = 0; i < ds->length; ++i) {
        if (ds->keys[i] == key) {
            break;
        }
    }

    if (i == ds->length) {
        pthread_mutex_unlock(&ds->mutex);
        return -1;
    }

    memmove(ds->keys + i, ds->keys + i + 1, (ds->length - i - 1) * sizeof(int));
    memmove((void *)ds->offsets + ds->offsets[i], (void *)(ds->offsets + ds->offsets[i+1]), (ds->length - i - 1) * sizeof(long));

    ds->length--;
    pthread_mutex_unlock(&ds->mutex);

    return 0;
}
