/* Define the necessary structures */
typedef struct {
    uint32_t rnti;
    uint16_t crc_flag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    size_t file_size;
    size_t pos;
    size_t chunk_size;
    char *buffer;
    CURL *curl;
    FILE *file;
} FileContext;

/* Function prototypes */
void *hash_chunk(void *arg);
void generate_crc_indications(const char *filename, size_t num_pdu, NFAPI_CRC_INDICATION_PDU_T *pdus, FILE *log_file);

/* Main function */
int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <filename> <number_of_pdus> <output_prefix>\n", argv[0]);
        return 1;
    }

    generate_crc_indications(argv[1], atoi(argv[2]), (NFAPI_CRC_INDICATION_PDU_T *)calloc(atoi(argv[2]), sizeof(NFAPI_CRC_INDICATION_PDU_T)), fopen(argv[3], "w"));
    return 0;
}

/* Function to generate CRC indications */
void generate_crc_indications(const char *filename, size_t num_pdu, NFAPI_CRC_INDICATION_PDU_T *pdus, FILE *log_file) {
    FileContext file_context = {0};
    CURLcode res;

    /* Initialize file context and curl handle */
    file_context.chunk_size = 1024 * 64; // Optimal chunk size for performance
    file_context.pos = -1;
    file_context.file_size = get_file_size(filename);
    file_context.buffer = malloc(file_context.chunk_size);
    file_context.curl = curl_easy_init();

    /* Set up curl options */
    curl_easy_setopt(file_context.curl, CURLOPT_URL, filename);
    curl_easy_setopt(file_context.curl, CURLOPT_WRITEFUNCTION, NULL); // Read data as chunks
    curl_easy_setopt(file_context.curl, CURLOPT_PROGRESSFUNCTION, progress_callback);
    curl_easy_setopt(file_context.curl, CURLFLOW_TIMEOUT_CONTINUE_ON_ERROR, 1L); // Continue on errors for retries

    /* Initialize thread pool */
    pthread_t threads[numsystemaffinity_cpus()];

    /* Calculate number of threads based on CPU count and file size */
    size_t num_threads = (file_context.file_size > (1024 * 1024 * 16)) ? numsystemaffinity_cpus() : 1;

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, &hash_chunk, &file_context);
    }

    /* Wait for threads to finish */
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    /* Clean up and log results */
    curl_easy_cleanup(file_context.curl);
    free(file_context.buffer);
    fclose(log_file);
}

/* Function to hash a file chunk using multiple threads */
void *hash_chunk(void *arg) {
    FileContext *file_context = arg;
    char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;

    /* Calculate the hash in chunks and store it */
    while (true) {
        size_t read = fread(file_context->buffer, 1, file_context->chunk_size, file_context->file);
        if (read <= 0) break; // End of file

        MD5_Init(&ctx);
        MD5_Update(&ctx, file_context->buffer, read);
        MD5_Final(digest, &ctx);

        /* Generate CRC indications for the current chunk */
        for (size_t i = file_context->pos; i < num_pdu + file_context->pos; ++i) {
            pdus[i].rnti = i; // Use the index as RNTI
            pdus[i].crc_flag = digest[i % MD5_DIGEST_LENGTH] > 127 ? 1 : 0; // Set CRC flag based on the hash value
        }

        file_context->pos += read;
    }

    pthread_exit(NULL);
}
