#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <dlfcn.h> // For logging framework integration (assuming it's a shared library)
#include <sys/mman.h> // For POSIX memory-mapping

typedef struct {
    pthread_mutex_t lock;
    dl_list* messages;
    size_t max_payload_size;
} MessageList;

// Custom message structure (adjust field names and types based on your needs)
typedef struct CustomMessage {
    int sessionID;
    time_t timestamp;
    char* payload; // Dynamically allocated payload
    size_t payload_len;
};

// Function to read data from a network stream using a custom parser
char* parseNetworkData(void);

// Function to free resources for a single message
void freeMessage(CustomMessage* msg) {
    if (msg->payload != NULL) {
        free(msg->payload);
    }
    free(msg);
}

// Function to initialize and return a new CustomMessage instance
CustomMessage* createMessage() {
    CustomMessage* msg = malloc(sizeof(CustomMessage));
    if (!msg) return NULL;

    msg->sessionID = -1;
    msg->timestamp = 0;
    msg->payload = NULL;
    msg->payload_len = 0;
    return msg;
}

// Function to handle memory allocation failures gracefully when adding messages
CustomMessage* ensureCapacity(MessageList* list, size_t capacity) {
    if (list->messages == NULL || dl_length(list->messages) >= capacity) {
        dl_append(list->messages, createMessage());
        if (!list->messages) return NULL;
    }
    return dl_get(list->messages, dl_length(list->messages) - 1);
}

// Function to initialize the message list with a given maximum payload size
void initMessageList(MessageList* list, size_t maxPayloadSize) {
    list->max_payload_size = maxPayloadSize;
    list->messages = dl_create();
    if (!list->messages) {
        fprintf(stderr, "Failed to initialize message list\n");
        exit(1);
    }
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new CustomMessage into the message list, handling concurrent access
void addMessage(MessageList* list, CustomMessage* msg) {
    if (pthread_mutex_trylock(&list->lock)) return; // Return if lock cannot be acquired immediately

    char* networkData = parseNetworkData();
    if (!networkData) {
        freeMessage(msg);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    msg->payload = mmap(NULL, strlen(networkData), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (msg->payload == MAP_FAILED) {
        freeMessage(msg);
        pthread_mutex_unlock(&list->lock);
        free(networkData);
        return;
    }

    memcpy(msg->payload, networkData, strlen(networkData));
    msg->payload_len = strlen(networkData);
    CustomMessage* newMsg = ensureCapacity(list, 1 + list->messages->length);
    if (!newMsg) {
        munmap(msg->payload, msg->payload_len);
        freeMessage(msg);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *newMsg = *msg;
    freeMessage(msg); // Free the original message instance after copying data

    pthread_mutex_unlock(&list->lock);
}

// Function to free all resources when the list is no longer needed
void destroyMessageList(MessageList* list) {
    if (!list || !list->messages) return;

    dl_foreach(list->messages, node, msg) {
        freeMessage(*msg);
    }

    dl_destroy(list->messages);
    pthread_mutex_destroy(&list->lock);
}
