#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

#define HEADER_SIZE 4
#define ALIGNMENT 16

typedef struct record {
    int key;
    pthread_mutex_t mutex; // Thread-safe random number initialization
    bool in_use;
    char buffer[0]; // Variable-length buffer with header prepended
} Record;

// Function to initialize the record structure with a random key and an empty buffer
void init_record(Record* record, int min_value, int max_value) {
    record->key = (rand() % (max_value - min_value + 1)) + min_value;
    record->in_use = false;
}

// Function to allocate and initialize the record array with given parameters
Record* init_record_array(size_t num_records, size_t buffer_size, int min_value, int max_value) {
    Record* records = (Record*) malloc(num_records * sizeof(Record));
    if (!records) return NULL;

    // Allocate and initialize the buffer for each record
    void* base_ptr = mmap(NULL, num_records * buffer_size + num_records * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (base_ptr == MAP_FAILED) {
        free(records);
        return NULL;
    }

    size_t aligned_buffer_size = ALIGNMENT > buffer_size ? ((ALIGNMENT + buffer_size - 1) / ALIGNMENT) * ALIGNMENT : buffer_size;
    char* buffer_ptr = (char*) base_ptr + num_records * sizeof(Record);

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = ((Record*)base_ptr) + i;
        init_record(record, min_value, max_value);

        // Set up the buffer's header and alignment
        record->buffer[0] = (char)(aligned_buffer_size - buffer_size);
        record->buffer[1] = (char)((aligned_buffer_size - buffer_size) >> 8);
        record->buffer[2] = (char)((aligned_buffer_size - buffer_size) >> 16);
        record->buffer[3] = (char)((aligned_buffer_size - buffer_size) >> 24);
    }

    return records;
}

// Clean up and deallocate resources when the program terminates
void destroy_record_array(Record* records, void* base_ptr) {
    munmap((char*)base_ptr, num_records * buffer_size + num_records * sizeof(Record));
    free(records);
}
