['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

static pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t total_records = 0;

// Function to generate a random number within the specified range
int random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* initialize_records(size_t num_records) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    pthread_mutex_lock(&records_mutex);
    total_records += num_records;
    pthread_mutex_unlock(&records_mutex);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = (long)random(0, LLONG_MAX);
        records[i].key = random(0, INT_MAX);
        records[i].value = random(INT_MIN, INT_MAX);
    }

    return records;
}

size_t populate_records(Record **records_ptr, size_t num_records) {
    size_t successfully_initialized = 0;
    *records_ptr = initialize_records(num_records);
    if (*records_ptr) {
        successfully_initialized += num_records;
    } else {
        fprintf(stderr, "Error: Out of memory\n");
        // Log additional error details if available
    }
    return successfully_initialized;
}

void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

#if defined(_OPENMP) || defined(__TBB__) // Enable parallelization using OpenMP or TBB
#include <omp.h>

size_t populate_records_parallel(Record **records_ptr, size_t num_records) {
    size_t successfully_initialized = 0;
    *records_ptr = initialize_records(num_records);
    if (*records_ptr) {
        #pragma omp parallel for reduction(+:successfully_initialized)
        for (size_t i = 0; i < num_records; ++i) {
            Record &record = *(*records_ptr + i);
            record.offset = (long)random(0, LLONG_MAX);
            record.key = random(0, INT_MAX);
            record.value = random(INT_MIN, INT_MAX);

            if (successfully_initialized < i && atomic_load(&total_records) == i) {
                successfully_initialized += 1;
            }
        }
    } else {
        log_error("Error: Out of memory");
        // Log additional error details if available
    }
    return successfully_initialized;
}
#endif
```

