// Constants for memory allocation buffer and data range limits
#define BUFFER_SIZE 1024
#define MAX_STRING_LEN 256
#define MIN_INT 0
#define MAX_INT 100000

// Custom malloc implementation with error checking
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to generate a random string of characters
char* generateRandomString(int length) {
    char* str = custom_malloc(length + 1);
    for (int i = 0; i < length; ++i) {
        str[i] = rand() % 26 + 'a'; // Generates lowercase alphabet characters
    }
    str[length] = '\0';
    return str;
}

// Function to initialize and populate memory for the given data structures
void initDataStructures(size_t numEntries, size_t* offsets, int* keys, struct Entry** entries) {
    // Allocate memory for offsets, keys, and entries
    offsets = custom_malloc((numEntries + 1) * sizeof(size_t));
    keys = custom_malloc(numEntries * sizeof(int));
    struct Entry** entryBuffers = custom_malloc(BUFFER_SIZE * sizeof(struct Entry*));

    // Initialize offset array
    offsets[0] = 0;

    // Populate entry buffers using a circular buffer approach to minimize memory fragmentation
    int entryBufferIndex = 0;
    for (size_t i = 1; i <= numEntries; ++i) {
        struct Entry* currentEntryBuffer = &entryBuffers[entryBufferIndex];
        if (!currentEntryBuffer->buffer || (i % BUFFER_SIZE) == 0) {
            // Reallocate the current buffer or allocate a new one if it's empty
            size_t bufferSize = i < BUFFER_SIZE ? i : BUFFER_SIZE;
            currentEntryBuffer->buffer = custom_malloc(bufferSize * sizeof(char));
            currentEntryBuffer->value = custom_malloc(bufferSize * sizeof(int));
        }

        // Populate the current buffer with a random string and value
        char* randomString = generateRandomString(rand() % MAX_STRING_LEN + 1);
        int randomValue = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
        memcpy(currentEntryBuffer->buffer + offsets[i - 1], randomString, strlen(randomString) + 1);
        currentEntryBuffer->value[offsets[i - 1] / sizeof(int)] = randomValue;

        // Update the offset and keep track of the total number of entries
        offsets[i] = offsets[i - 1] + strlen(randomString) + sizeof(int);
    }

    // Create a dynamic array of Entry structures, copying the populated buffer into it
    *entries = custom_malloc(numEntries * sizeof(struct Entry));
    for (size_t i = 0; i < numEntries; ++i) {
        (*entries)[i].buffer = entryBuffers[entryBufferIndex]->buffer + offsets[i];
        (*entries)[i].value = &entryBuffers[entryBufferIndex]->value[offsets[i] / sizeof(int)];
    }

    // Free the entry buffer and initialize the buffer index for future use
    free(entryBuffers);
    entryBufferIndex = 0;
}

int main() {
    srand(time(NULL));
    size_t numEntries = 10000;
    size_t* offsets = NULL;
    int* keys = NULL;
    struct Entry** entries = NULL;

    initDataStructures(numEntries, &offsets[0], &keys[0], &entries);

    // Access the data structures for debugging and testing purposes
    for (size_t i = 0; i < numEntries; ++i) {
        printf("Entry %zu: String = %s, Value = %d\n", i, entries[i]->buffer, *entries[i]->value);
    }

    free(offsets);
    free(keys);
    for (size_t i = 0; i < numEntries; ++i) {
        free(entries[i]->buffer);
    }
    free(entries);

    return 0;
}
