typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_NRTI 10000
#define SEED 123456

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
static size_t num_structures = 0;
static size_t min_RNTI = 1;
static size_t max_RNTI = MAX_NRTI;
static double crc_probability = 0.5;

void generate_structures(size_t N) {
    if (N > MAX_NRTI || N == 0) {
        printf("Invalid number of structures\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    if (num_structures + N > MAX_NRTI) {
        printf("Insufficient memory for the requested number of structures\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_structures + N));
    if (!structures) {
        printf("Memory allocation failure\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    num_structures += N;
    struct timespec ts = {0, SEED};
    for (size_t i = num_structures - N; i < num_structures; ++i) {
        structures[i].RX_UE_INFORMATION_TAG = i;
        structures[i].RNTI = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;
        struct timespec_get(&ts, TIME_UTC);
        if (rand_r(&ts.tv_seed) < crc_probability * RAND_MAX) {
            structures[i].CRC_INDICATION_REL8_TAG = 1;
        } else {
            structures[i].CRC_INDICATION_REL8_TAG = 0;
        }
    }

    pthread_mutex_unlock(&mutex);
}
