['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

// Define the structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp; // Store the creation time for LRU implementation
    struct node *prev;
    struct node *next;
} Node;

typedef struct {
    unsigned int max_size;
    unsigned int size;
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

// LRU implementation helper function to add a node at the beginning
void lru_add_begin(List *list, Node* new_node) {
    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->next = list->head;
        list->head->prev = new_node;
        list->head = new_node;
    }
}

// LRU implementation helper function to remove the node from the list
void lru_remove(List *list, Node* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
}

// Function to manage the list of structures
List* create_list(unsigned int max_size) {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;

    list->max_size = max_size < 1 ? 1 : max_size;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&(list->lock), NULL);

    return list;
}

// Function to add a new structure to the list
int add_structure(List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->size >= list->max_size) {
        lru_remove(list, list->head); // Remove the oldest structure
        list->size--;
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = *data;
    new_node->timestamp = time(NULL);
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&(list->lock));
    lru_add_begin(list, new_node);
    list->size++;
    pthread_mutex_unlock(&(list->list->lock));

    return 0;
}

// Function to clean up the list (call periodically to manage memory)
void cleanup(List* list) {
    pthread_mutex_lock(&(list->lock));

    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
        list->size--;
    }

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&(list->lock));
}
```

This code defines a doubly-linked list to store the structures, along with an LRU (Least Recently Used) implementation to manage the oldest elements when the maximum size is reached. The function `create_list()` initializes the list and manages thread safety using a mutex. The `add_structure()` function adds new structures to the list while removing old ones as needed, and the `cleanup()` function periodically frees unused memory. The code is scalable, modular, well-documented, and integrates with existing components of the system.']

