void log(VerboseLevel level, const char *message) {
    // Implement a logging mechanism here based on the given verbosity levels and message.
}

CRC_INDICATION_PDU* generate_list(size_t num_pdus) {
    RNTI rntis[MAX_LIST_SIZE];
    CRC_INDICATION_PDU *list = malloc(num_pdus * sizeof(CRC_INDICATION_PDU));
    if (!list) {
        log(WARN, "Out of memory error");
        return NULL;
    }

    // Initialize RNTI pool with unused RNTIs.
    for (size_t i = 0; i < MAX_LIST_SIZE; ++i) {
        rntis[i].value = i;
        rntis[i].in_use = false;
    }

    size_t used_rntis = 0;
    for (size_t pdu_index = 0; pdu_index < num_pdus; ++pdu_index) {
        // Try to find an available RNTI in the pool.
        for (size_t rnti_index = 0; rnti_index < used_rntis; ++rnti_index) {
            if (!rntis[rnti_index].in_use) {
                rntis[rnti_index].in_use = true;
                list[pdu_index].rnti = rntis[rnti_index];
                break;
            }
        }

        // If no available RNTIs were found in the pool, resize it and continue.
        if (rnti_index == used_rntis) {
            size_t new_size = used_rntis * 2;
            CRC_INDICATION_PDU *temp_list = realloc(list, new_size * sizeof(CRC_INDICATION_PDU));
            if (!temp_list) {
                log(WARN, "Out of memory error");
                free(list);
                return NULL;
            }
            list = temp_list;
            RNTI *new_rntis = realloc(rntis, new_size * sizeof(RNTI));
            if (!new_rntis) {
                log(WARN, "Out of memory error");
                free(list);
                return NULL;
            }
            rntis = new_rntis;
            for (size_t i = used_rntis; i < new_size; ++i) {
                rntis[i].value = i;
                rntis[i].in_use = false;
            }
        }
    }

    // Set random CRCFLAG for each CRC_INDICATION_REL8_TAG in the list.
    for (size_t pdu_index = 0; pdu_index < num_pdus; ++pdu_index) {
        list[pdu_index].crc_indication.CRCFLAG = rand() % 2 == 1;
    }

    return list;
}
