typedef struct _UE_INFO_MEMORY_POOL {
    unsigned int size_limit;
    NFAPI_CRC_INDICATION_PDU **list;
    unsigned int count;
    pthread_mutex_t lock;
} UE_INFO_MEMORY_POOL;

UE_INFO_MEMORY_POOL* create_memory_pool(unsigned int size_limit) {
    UE_INFO_MEMORY_POOL *pool = malloc(sizeof(UE_INFO_MEMORY_POOL));
    if (!pool) return NULL;

    pool->size_limit = size_limit;
    pool->list = calloc((size_t) size_limit, sizeof(NFAPI_CRC_INDICATION_PDU*));
    if (!pool->list) {
        free(pool);
        return NULL;
    }

    pool->count = 0;

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

NFAPI_CRC_INDICATION_PDU* allocate_ue_info(UE_INFO_MEMORY_POOL *pool) {
    for (int i = 0; i < pool->size_limit; ++i) {
        if (!pool->list[i]) {
            pool->list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            if (!pool->list[i]) return NULL;

            NFAPI_CRC_INDICATION_PDU* ue_info = pool->list[i];
            ue_info->rx_ue_info = RX_UE_INFORMATION_TAG(); // fill with valid tag data
            ue_info->rnti = get_valid_rnti(); // replace this with your RNTI validation logic
            ue_info->crc_indication.crcflag = rand() % 2; // random CRC flag

            pthread_mutex_init(&ue_info->mutex, NULL);
            return ue_info;
        }
    }

    return NULL;
}

void deallocate_ue_info(UE_INFO_MEMORY_POOL *pool, NFAPI_CRC_INDICATION_PDU *ue_info) {
    pthread_mutex_lock(&ue_info->mutex);
    pthread_mutex_unlock(&ue_info->mutex);

    free(ue_info);
}

void add_ue_info(UE_INFO_MEMORY_POOL *pool, NFAPI_CRC_INDICATION_PDU *ue_info) {
    pthread_mutex_lock(&pool->lock);

    if (++pool->count > pool->size_limit) {
        // Gracefully degrade system's performance by increasing memory usage and reducing concurrency
        printf("Error: Reached maximum size limit. Dropping UE information.\n");
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    int i = 0;
    for (; i < pool->size_limit && pool->list[i]; ++i) {}
    if (i == pool->size_limit) {
        // Reallocate list and move existing elements, increasing size limit when needed
        UE_INFO_MEMORY_POOL tmp = *pool;
        tmp.list = realloc(tmp.list, (size_t) (2*tmp.size_limit)*sizeof(NFAPI_CRC_INDICATION_PDU*));
        if (!tmp.list) {
            // Handle failure case gracefully and unlock mutex to allow other operations
            pool->count--;
            pthread_mutex_unlock(&pool->lock);
            return;
        }

        for (i = 0; i < tmp.size_limit; ++i) {
            if (tmp.list[i]) pool->list[2*i] = tmp.list[i];
        }
        pool->size_limit *= 2;
    }

    pool->list[i] = ue_info;
    pthread_mutex_unlock(&pool->lock);
}

void remove_ue_info(UE_INFO_MEMORY_POOL *pool, uint16_t rnti) {
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < pool->size_limit; ++i) {
        if (!pool->list[i]) continue;

        NFAPI_CRC_INDICATION_PDU *ue_info = pool->list[i];
        if (ue_info->rnti == rnti) {
            pool->count--;
            deallocate_ue_info(pool, ue_info);
            memmove(pool->list + i, pool->list + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU*) * (pool->size_limit - i - 1));
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
