#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <semaphore.h>

typedef struct record {
    int key;
    char str[21];
    double metric;
} Record;

typedef struct memory_manager {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    sem_t semaphore;
} MemoryManager;

MemoryManager* create_memory_manager() {
    MemoryManager *mm = malloc(sizeof(MemoryManager));
    mm->records = NULL;
    mm->capacity = 0;
    mm->size = 0;
    pthread_mutex_init(&mm->lock, NULL);
    sem_init(&mm->semaphore, 0, 1);
    return mm;
}

void destroy_memory_manager(MemoryManager *mm) {
    if (mm->records) free(mm->records);
    free(mm);
}

int extend_capacity(MemoryManager *mm, size_t new_capacity) {
    if (new_capacity > 50000) return -1; // Maximum capacity limit reached
    Record *tmp = realloc(mm->records, sizeof(Record) * new_capacity);
    if (!tmp) return -1; // Memory allocation failure
    mm->records = tmp;
    mm->capacity = new_capacity;
    return 0;
}

int push_record(MemoryManager *mm, Record r) {
    int ret = extend_capacity(mm, mm->size + 1);
    if (ret < 0) return -1; // Memory allocation failure
    memcpy(&mm->records[mm->size], &r, sizeof(Record));
    mm->size++;
    sem_post(&mm->semaphore); // Notify that space is available
    return 0;
}

Record pop_record(MemoryManager *mm) {
    if (mm->size == 0) return (Record){0}; // Empty result
    Record ret = mm->records[0];
    memcpy(&mm->records[0], &mm->records[mm->size - 1], sizeof(Record));
    mm->size--;
    sem_wait(&mm->semaphore); // Wait for space to become available
    return ret;
}

MemoryManager* stack_allocator(size_t initial_size) {
    MemoryManager *mm = create_memory_manager();
    if (initial_size > 0) mm->records = malloc(sizeof(Record) * initial_size);
    return mm;
}

MemoryManager* heap_allocator(size_t initial_capacity, size_t growth_factor) {
    MemoryManager *mm = create_memory_manager();
    if (initial_capacity > 0) mm->records = malloc(sizeof(Record) * initial_capacity);
    return mm;
}

// Unit tests
void test_memory_manager() {
    MemoryManager *mm = heap_allocator(10, 2);
    for (size_t i = 0; i < 50000; ++i) push_record(mm, (Record){i, "test", (double)i});
    Record record;
    for (size_t i = 0; i < 50000; ++i) {
        record = pop_record(mm);
        if (record.key != i || strcmp(record.str, "test") || fabs(record.metric - i) > 0.01) {
            fprintf(stderr, "Error: Incorrect record after pop.\n");
            return;
        }
    }
    destroy_memory_manager(mm);
}
```

