    int value;
} record;

struct user {
    int id;
    char name[256];
    char email[256];
    char password[256];
};

static record* records = NULL;
static size_t capacity = 0;
static size_t count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_fd;
static char log_filename[256];

void log(const char* message, const char* user_id) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fd, "[%s] [%s]: %s\n", timestamp, user_id, message);
}

void resize() {
    record* new_records = realloc(records, sizeof(record) * (capacity * 2));
    if (!new_records) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }
    records = new_records;
    capacity *= 2;
}

void create(int id, int min, int max) {
    pthread_mutex_lock(&mutex);
    if (count == capacity) resize();
    records[count].id = id;
    records[count].value = rand() % (max - min + 1) + min;
    count++;
    log( "Created record with ID", itoa(id));
    pthread_mutex_unlock(&mutex);
}

void update(int id, const char* field, const char* value) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < count; ++i) {
        if (records[i].id == id) {
            strncpy(getattr(records[i], field), value, sizeof(records[i]->field));
            log("Updated ", field, " for record with ID", itoa(id));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void remove(int id) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < count; ++i) {
        if (records[i].id == id) {
            memmove(&records[i], &records[i + 1], sizeof(record) * (count - i - 1));
            --count;
            log("Deleted record with ID", itoa(id));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

char* list() {
    json_t* root = json_object();
    for (size_t i = 0; i < count; ++i) {
        json_t* record = json_pack("{si,si,si}", "id", records[i].id, "value", records[i].value);
        json_object_set_new(root, "", record);
    }
    char* json_str = json_dumps(root, JSON_ENCODE_ANY);
    json_decref(root);
    return json_str;
}

void save() {
    pthread_mutex_lock(&mutex);
    int fd = open(log_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("open failed");
        pthread_mutex_unlock(&mutex);
        return;
    }
    char* json_str = list();
    if (write(fd, json_str, strlen(json_str)) == -1) {
        perror("write failed");
    }
    close(fd);
    free(json_str);
    pthread_mutex_unlock(&mutex);
}

