typedef struct {
    char TCP_SOURCE_IP[INET6_ADDRSTRLEN];
    char TCP_DEST_IP[INET6_ADDRSTRLEN];
    uint32_t TCP_SEQ_NUMBER;
} TCP_CONNECTION_INFO;

typedef struct connection_pool {
    sem_t mutex;
    TCP_CONNECTION_INFO* connections;
    size_t capacity;
    size_t size;
} ConnectionPool;

ConnectionPool* create_connection_pool(size_t initial_capacity) {
    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->connections = calloc(initial_capacity, sizeof(TCP_CONNECTION_INFO));
    if (!pool->connections) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;

    sem_init(&pool->mutex, 0, 1);

    return pool;
}

void add_connection(ConnectionPool* pool, const char* source_ip, const char* dest_ip, uint32_t seq_number) {
    size_t index = __sync_add_and_fetch(&pool->size, 1) % pool->capacity;

    sem_wait(&pool->mutex);
    if (pool->connections[index].TCP_SEQ_NUMBER == 0 || !(seq_number >= pool->connections[index].TCP_SEQ_NUMBER)) {
        strcpy(pool->connections[index].TCP_SOURCE_IP, source_ip);
        strcpy(pool->connections[index].TCP_DEST_IP, dest_ip);
        pool->connections[index].TCP_SEQ_NUMBER = seq_number;
    } else {
        uint32_t new_seq = find_valid_seq_number(pool);
        add_connection(pool, source_ip, dest_ip, new_seq);
    }
    sem_post(&pool->mutex);
}

