typedef struct {
    void* state;
    int parent;
} STATE_INFO;

void* custom_malloc(size_t size) {
    // Custom allocator implementation goes here
}

void custom_free(void* ptr) {
    // Custom free implementation goes here
}

int find(STATE_INFO* nodes, int n, int i) {
    if (nodes[i].parent != i)
        nodes[i].parent = find(nodes, n, nodes[nodes[i].parent]);
    return nodes[i].parent;
}

void union_set(STATE_INFO* nodes, int n, int a, int b) {
    int root_a = find(nodes, n, a);
    int root_b = find(nodes, n, b);
    if (root_a != root_b)
        nodes[root_a].parent = root_b;
}

void log_performance(double time_taken) {
    // Performance logging implementation goes here
}

LTE_PHY_RX_CQI_MEASUREMENT_T* initialize_array(int* states, int num_states, const FSA* fsa, int last_state) {
    int i;
    LTE_PHY_RX_CQI_MEASUREMENT_T* array = NULL;
    STATE_INFO* nodes = (STATE_INFO*)custom_malloc((num_states + 1) * sizeof(STATE_INFO));
    double start_time, end_time;

    for (i = 0; i <= last_state; ++i) {
        nodes[i].parent = i;
        nodes[i].state = NULL;
    }

    array = (LTE_PHY_RX_CQI_MEASUREMENT_T*)custom_malloc((num_states + 1) * sizeof(LTE_PHY_RX_CQI_MEASUREMENT_T));
    if (!array) {
        custom_free(nodes);
        return NULL;
    }

    start_time = clock();
    for (i = 0; i <= last_state; ++i) {
        int rnti = states[i];
        array[i].rnti = rnti;
        array[i].harq_pid = fsa->states[rnti]->harq_pid;
        array[i].srs_id = rand() % 1024 + 1; // Generate SRS_ID within range [1, 1024]

        int a = find(nodes, num_states + 1, rnti);
        for (int j = 0; j <= last_state; ++j) {
            if (array[j].rnti == rnti && j != i) {
                custom_free(array);
                custom_free(nodes);
                return NULL;
            }
        }
        nodes[rnti].state = &array[i];
    }
    end_time = clock();
    log_performance(end_time - start_time);

    for (int j = 0; j <= last_state; ++j) {
        for (int k = j + 1; k <= last_state; ++k) {
            if (fsa->transitions[states[j]][states[k]] != -1) {
                int a = find(nodes, num_states + 1, states[j]);
                int b = find(nodes, num_states + 1, states[k]);
                if (a != b) {
                    union_set(nodes, num_states + 1, a, b);
                    end_time = clock();
                    log_performance(end_time - start_time);
                }
            }
        }
    }

    for (i = 0; i <= last_state; ++i) {
        array[i].srs_id = ((STATE_INFO*)nodes[states[i].rnti].state)->srs_id;
    }

    custom_free(nodes);
    return array;
}
