#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
    char str[256];
    int ref;
} Record;

typedef unsigned long Hash;
const unsigned int CAPACITY_THRESHOLD = 1000;

Hash hash(int key) {
    return (Hash)(key % CAPACITY_THRESHOLD);
}

void rehash(Record** table, unsigned int newCapacity) {
    Record* newTable = malloc(newCapacity * sizeof(Record));
    if (!newTable) {
        fprintf(stderr, "Memory allocation failure\n");
        return;
    }

    unsigned int currentIndex = 0;
    for (unsigned int i = 0; i < CAPACITY_THRESHOLD; ++i) {
        if (table[i] != NULL) {
            Record* currentRecord = table[i];
            Hash newHash = hash(currentRecord->key);
            unsigned int newIndex = newHash % newCapacity;
            while (newTable[newIndex] != NULL) ++newIndex;
            newTable[newIndex] = currentRecord;
            currentIndex++;
        }
    }

    free(table);
    CAPACITY_THRESHOLD = newCapacity;
    table = newTable;
}

int add_record(Record** table, long offset, int key, double value, const char* str, int ref) {
    if (CAPACITY_THRESHOLD == 0) {
        rehash(table, 16);
    }

    Hash hashKey = hash(key);
    unsigned int index = hashKey;

    while (table[index] != NULL && table[index]->key == key) {
        ++index %= CAPACITY_THRESHOLD;
        if ((CAPACITY_THRESHOLD * 2) <= table_size(table)) {
            rehash(table, (CAPACITY_THRESHOLD * 2));
            index = hashKey;
        }
    }

    Record* newRecord = malloc(sizeof(Record));
    if (!newRecord) {
        fprintf(stderr, "Memory allocation failure\n");
        return -1;
    }

    memset(newRecord, 0, sizeof(Record));
    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = value;
    strncpy(newRecord->str, str, sizeof(newRecord->str));
    newRecord->ref = ref;
    table[index] = newRecord;

    return 1;
}

unsigned int table_size(const Record* table) {
    unsigned int count = 0;
    for (unsigned int i = 0; i < CAPACITY_THRESHOLD; ++i) {
        if (table[i] != NULL) ++count;
    }
    return count;
}
