#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000
#define ARRAY_SIZE 10000

typedef struct Record {
    int key;
    char* str;
} Record;

void log(const char* message, bool enable_logging) {
    if (enable_logging) {
        printf("%s\n", message);
    }
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        log("Failed to allocate memory for Record", true);
        exit(EXIT_FAILURE);
    }
    record->str = NULL;
    return record;
}

char* create_string(size_t size, bool* success) {
    char* str = malloc(size + 1);
    if (!str) {
        *success = false;
        log("Failed to allocate memory for string", true);
        exit(EXIT_FAILURE);
    }
    memset(str, '\0', size + 1);
    *success = true;
    return str;
}

void init_data_pipeline(size_t num_records, int min_value, int max_value, bool enable_logging) {
    int* offsets = malloc(ARRAY_SIZE * sizeof(int));
    if (!offsets) {
        log("Failed to allocate memory for offset array", true);
        exit(EXIT_FAILURE);
    }
    int* keys = malloc(ARRAY_SIZE * sizeof(int));
    if (!keys) {
        log("Failed to allocate memory for key array", true);
        free(offsets);
        exit(EXIT_FAILURE);
    }
    Record** records = calloc(num_records, sizeof(Record*));
    if (!records) {
        log("Failed to allocate memory for record array", true);
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    size_t index = 0;
    int current_offset = 0, current_key = 1;

    for (size_t i = 0; i < ARRAY_SIZE && index < num_records; ++i) {
        if (!index % 100 || i == ARRAY_SIZE - 1) {
            log(("Indexed up to: " + std::to_string(index)).c_str(), enable_logging);
        }
        offsets[i] = current_offset++;
        keys[i] = current_key++;

        Record* record = create_record();
        records[index++] = record;

        record->key = rand() % (max_value - min_value + 1) + min_value;

        bool success;
        char* str = create_string(rand() % 40 + 5, &success);
        if (!success) {
            log("Failed to allocate memory for record string", true);
            free(str);
            exit(EXIT_FAILURE);
        }
        record->str = str;
    }

    if (index < num_records) {
        log("Number of records exceeded the limit. Allocated: " + std::to_string(index), true);
    }

    for (size_t i = 0; i < index; ++i) {
        log(("Record[" + std::to_string(i) + "]: {" + std::to_string(records[i]->key) + ", \"" + records[i]->str + "\")").c_str(), enable_logging);
    }

    // Log memory usage and performance information when logging is enabled.
    if (enable_logging) {
        log("Memory usage:", true);
        size_t total = 0;
        for (size_t i = 0; i < index; ++i) {
            total += strlen(records[i]->str) + sizeof(int) * 2 + sizeof(Record*);
        }
        log("Total memory usage: " + std::to_string(total), true);
    }
}

void free_data_pipeline(size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}
