['Here's a C++ solution using a resizable array with dynamic memory allocation and a custom hash table (using open addressing) to manage records efficiently. The code utilizes the `std::vector` for the resizable array and `std::hash` for hashing, which are part of the Standard Template Library (STL).

```cpp
#include <iostream>
#include <vector>
#include <initializer_list>
#include <cstdlib>
#include <functional>
#include <utility>
#include <algorithm>
#include <memory>

constexpr size_t MAX_RECORDS = 10000;
constexpr size_t MEMORY_LIMIT = 2 * 1024 * 1024; // 2 MB

struct Record {
    long offset;
    int key;
    int value;

    explicit Record(long offset_, int key_, int value_)
        : offset(offset_), key(key_), value((std::rand() % (MAX - MIN + 1)) + MIN) {}
};

class DynamicCollection {
public:
    explicit DynamicCollection(size_t seed = std::random_device{}());

    void add(const Record& record);

    size_t size() const;

    size_t memoryUsage() const;

    void clear();

private:
    static constexpr size_t BUCKET_COUNT = 1024;
    std::vector<std::unique_ptr<Record[]>> records_;
    std::hash<int> hasher_;
    std::function<size_t(size_t)> rehashStrategy_;

    size_t getBucketIndex(int key) const;
    bool tryInsert(size_t index, const Record& record);
};

DynamicCollection::DynamicCollection(size_t seed)
    : hasher_(std::hash<int>{})
{
    rehashStrategy_ = [this](size_t oldSize) { return (oldSize << 1) < MEMORY_LIMIT ? (oldSize << 1) : MEMORY_LIMIT; };
    records_.reserve(BUCKET_COUNT);
}

void DynamicCollection::add(const Record& record) {
    size_t index = getBucketIndex(record.key);
    if (!tryInsert(index, record)) {
        resize();
        if (!tryInsert(index, record)) {
            std::cerr << "Failed to add record due to memory allocation failure.\n";
        }
    }
}

size_t DynamicCollection::size() const { return records_.empty() ? 0 : records_.back()->size(); }

size_t DynamicCollection::memoryUsage() const {
    size_t totalBytes = 0;
    for (const auto& bucket : records_) {
        if (!bucket) continue;
        totalBytes += sizeof(Record*) * bucket->size() + bucket->data()[0]->size();
    }
    return totalBytes;
}

void DynamicCollection::clear() {
    for (auto& bucket : records_) {
        if (!bucket) continue;
        bucket.reset();
    }
}

size_t DynamicCollection::getBucketIndex(int key) const {
    return hasher_(key) % BUCKET_COUNT;
}

bool DynamicCollection::tryInsert(size_t index, const Record& record) {
    auto* current = records_[index].get();
    if (!current || current[record.key] == nullptr) {
        current[record.key] = std::make_unique<Record[]>(rehashStrategy_(records_.size()));
        current[record.key]->at(0) = std::move(record);
        return true;
    }
    return false;
}

void DynamicCollection::resize() {
    if (memoryUsage() >= MEMORY_LIMIT)
        throw std::runtime_error("Memory limit exceeded.");

    auto newRecords = records_.empty() ? std::vector<std::unique_ptr<Record[]>>(BUCKET_COUNT * 2)
                                       : std::vector<std::unique_ptr<Record[]>>(rehashStrategy_(records_.size()));

    for (const auto& bucket : records_) {
        if (!bucket) continue;
        for (size_t i = 0; i < bucket->size(); ++i) {
            auto record = std::move(*(bucket->begin() + i));
            size_t index = getBucketIndex(record.key);
            newRecords[index].reset(new Record*[rehashStrategy_(records_.size())]);
            if (newRecords[index]) {
                newRecords[index][record.key] = std::make_unique<Record>(std::move(record));
            }
        }
    }

    records_ = std::move(newRecords);
}
```

You can use this `DynamicCollection` class in your code as follows:

```cpp
