    std::cout << "Number of records: " << dc.size() << "\n";
    std::cout << "Memory usage: " << dc.memoryUsage() << " bytes\n";

    // Clear the collection and check memory usage again
    dc.clear();
    std::cout << "Memory usage after clearing: " << dc.memoryUsage() << " bytes\n";
}
```']

