int generateCRCFlag() {
    return rand() % 10 == 0 ? 1 : 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node* node) {
    pthread_mutex_lock(&list_mutex);
    if (head == NULL) {
        head = tail = node;
    } else {
        // Ensure no two consecutive nodes have the same RNTI or RX_UE_INFORMATION_TAG
        while ((node->data.RNTI == (tail->data.RNTI)) || ((node->data.RX_UE_INFORMATION_TAG) == (tail->data.RX_UE_INFORMATION_TAG))) {
            node = create_node(node->data);
        }

        // Insert at the end of the list
        tail->next = node;
        node->prev = tail;
        tail = node;
    }
    list_size++;
    if (list_size > max_list_size) {
        // Trim the list when it exceeds the maximum size
        Node* temp = head;
        while (list_size > max_list_size) {
            head = head->next;
            free(temp);
            list_size--;
            temp = head;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void cleanup() {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
    head = tail = NULL;
    list_size = 0;
}

int report() {
    int unique_RTNIs = 0;
    int crcFlagsCount = 0;

    pthread_mutex_lock(&list_mutex);
    Node* temp = head;
    while (temp != NULL) {
        if ((temp->data.RX_UE_INFORMATION_TAG.signalStrength > threshold) && (temp->data.RNTI != temp->next->data.RNTI) && (temp->data.RX_UE_INFORMATION_TAG.tagValue != temp->next->data.RX_UE_INFORMATION_TAG.tagValue)) {
            unique_RTNIs++;
            if (temp->data.CRC_INDICATION_REL8_TAG.crcFlag) {
                crcFlagsCount++;
            }
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&list_mutex);

    double crcPercentage = (double)crcFlagsCount / list_size * 100.0;
    printf("Number of unique RNTIs: %d\n", unique_RTNIs);
