typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char crcflag; // 1 byte, can be either 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ALLOCATION 1024
#define RX_UE_INFORMATION_TAG_MIN 0x0001
#define RX_UE_INFORMATION_TAG_MAX 0xFFFF
#define RNTI_MIN 0x0000
#define RNTI_MAX 0xFFFF

enum ErrorCode {
    ERR_SUCCESS = 0,
    ERR_ALLOCATION_FAILURE = -1,
    ERR_DATA_SOURCE_FAILURE = -2,
    ERR_OUT_OF_RANGE = -3,
    ERR_MEMORY_LIMIT_EXCEEDED = -4,
};

int get_random_byte() {
    return rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t *length) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    size_t current_allocation = 0;

    while (current_allocation < *length && current_allocation + sizeof(NFAPI_CRC_INDICATION_PDU_T) <= MAX_ALLOCATION) {
        pdus = realloc(pdus, current_allocation + *length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            perror("realloc");
            return NULL;
        }

        memset(&pdus[current_allocation], 0, *length * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        for (size_t i = current_allocation; i < current_allocation + *length; ++i) {
            pdus[i].tag = (RX_UE_INFORMATION_TAG)(rand() % (RX_UE_INFORMATION_TAG_MAX - RX_UE_INFORMATION_TAG_MIN + 1)) + RX_UE_INFORMATION_TAG_MIN;
            pdus[i].rnti = (RNTI)(rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;
            pdus[i].crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG)rand();
            pdus[i].crcflag = get_random_byte();
        }

        current_allocation += *length;
    }

    if (current_allocation < *length) {
        perror("Failed to allocate enough memory");
        return NULL;
    }

    *length = current_allocation / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t length) {
    if (pdus) {
        free(pdus);
    }
}
